from __future__ import annotations

import json
import mimetypes
import uuid
from contextlib import asynccontextmanager
from datetime import datetime
from pathlib import Path
from typing import Any

from fastapi import Depends, FastAPI, File, Header, HTTPException, Query, UploadFile
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, StreamingResponse

from .auth import CurrentUser, create_test_session, current_user, require_admin
from .config import settings
from .database import PlanningStateConflict, ProtectedSettingsChange, all_app_updates, all_feedback, app_update_record, connection, demand_import_history, feedback_record, init_database, now_iso, order_details, planning_state, planning_state_history, production_archive_history, revisions, save_demand_import_history, save_orders, save_planning_state, scenario_record, scenario_summaries, scenarios
from .data_package import DataPackageError, MAX_DATA_PACKAGE_BYTES, SCOPE_LABELS, build_data_package, parse_data_package
from .delivery_plan import DeliveryPlanError, build_delivery_plan
from .models import AppUpdateCreate, CalendarEventExportPayload, CommentCreate, CommentUpdate, DataPackagePayload, DeliveryPlanPayload, DemandImportHistoryPayload, FeedbackCreate, FeedbackUpdate, LoginRequest, OverviewExportPayload, PlanningStatePayload, ProductionArchiveExportPayload, RevisionPayload, ScenarioPayload
from .calendar_export import build_calendar_event_workbook
from .overview_export import build_overview_workbook
from .order_import import MAX_XLSX_BYTES, OrderImportError, parse_order_xlsx
from .production_archive_export import build_production_archive_workbook
from .production_sync import production_snapshot, production_sync_status_payload, pull_production_state
from .ravi.routes import router as ravi_router


@asynccontextmanager
async def lifespan(_: FastAPI):
    init_database()
    yield


app = FastAPI(title="Selsa Planlama API", version="1.0.0", lifespan=lifespan)
app.include_router(ravi_router)
app.add_middleware(CORSMiddleware, allow_origins=list(settings.cors_origins), allow_credentials=True, allow_methods=["*"], allow_headers=["*"])


def require_feedback(db, feedback_id: str) -> dict[str, Any]:
    record = feedback_record(db, feedback_id)
    if record is None:
        raise HTTPException(status_code=404, detail="Geri bildirim bulunamadı")
    return record


@app.get("/health")
def health() -> dict[str, str]:
    return {"status": "ok"}


if settings.app_env == "test" and settings.auth_test_mode:
    @app.post("/api/auth/login")
    def login(payload: LoginRequest):
        return {"token": create_test_session(payload.password), "name": "Test Yöneticisi"}


@app.get("/api/me")
def me(user: CurrentUser = Depends(current_user)):
    return {"id": user.id, "name": user.name, "email": user.email, "role": user.role}


@app.get("/api/app-updates")
def get_app_updates(_: CurrentUser = Depends(current_user)):
    return all_app_updates()


@app.post("/api/app-updates", status_code=201)
def create_app_update(payload: AppUpdateCreate, _: CurrentUser = Depends(require_admin)):
    title = payload.title.strip()
    bullets = [bullet.strip() for bullet in payload.bullets if bullet.strip()]
    if not title or not bullets:
        raise HTTPException(status_code=422, detail="Başlık ve en az bir değişiklik maddesi gerekli")
    if any(len(bullet) > 500 for bullet in bullets):
        raise HTTPException(status_code=422, detail="Değişiklik maddeleri 500 karakteri geçemez")
    update_id, timestamp = str(uuid.uuid4()), now_iso()
    with connection() as db:
        db.execute(
            "INSERT INTO app_updates(id,title,bullets_json,created_at,seen_at) VALUES(?,?,?,?,NULL)",
            (update_id, title, json.dumps(bullets, ensure_ascii=False), timestamp),
        )
        return app_update_record(db, update_id)


@app.post("/api/app-updates/{update_id}/seen")
def mark_app_update_seen(update_id: str, _: CurrentUser = Depends(current_user)):
    with connection() as db:
        record = app_update_record(db, update_id)
        if record is None:
            raise HTTPException(status_code=404, detail="Güncelleme bulunamadı")
        if record["seen_at"] is None:
            db.execute("UPDATE app_updates SET seen_at=? WHERE id=?", (now_iso(), update_id))
        return app_update_record(db, update_id)


@app.get("/api/orders")
def get_orders(_: CurrentUser = Depends(current_user)):
    return order_details()


@app.put("/api/orders")
def put_orders(payload: list[dict[str, Any]], _: CurrentUser = Depends(current_user)):
    save_orders(payload)
    return {"ok": True}


@app.post("/api/order-imports/preview")
async def preview_order_import(file: UploadFile = File(...), _: CurrentUser = Depends(current_user)):
    if not file.filename or not file.filename.lower().endswith(".xlsx"):
        raise HTTPException(status_code=422, detail="Yalnızca .xlsx dosyası yükleyebilirsiniz.")
    content = await file.read(MAX_XLSX_BYTES + 1)
    try:
        preview = parse_order_xlsx(content)
    except OrderImportError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    return {"fileName": Path(file.filename).name, **preview}


@app.get("/api/order-imports/history")
def get_order_import_history(_: CurrentUser = Depends(current_user)):
    return demand_import_history()


@app.post("/api/order-imports/history", status_code=201)
def post_order_import_history(payload: DemandImportHistoryPayload, _: CurrentUser = Depends(current_user)):
    return save_demand_import_history(payload.model_dump())


@app.post("/api/delivery-plan/export")
def export_delivery_plan(payload: DeliveryPlanPayload, _: CurrentUser = Depends(current_user)):
    template_path = Path(__file__).resolve().parents[1] / "teslimat_plani.xlsx"
    try:
        content = build_delivery_plan(template_path, payload.model_dump())
    except DeliveryPlanError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    filename = f"Teslimat_Plani_{payload.startDate}_{payload.endDate}.xlsx"
    return StreamingResponse(
        iter([content]),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@app.post("/api/general-overview/export")
def export_general_overview(payload: OverviewExportPayload, _: CurrentUser = Depends(current_user)):
    content = build_overview_workbook(payload.model_dump())
    process_name = {"turning": "Torna", "drilling": "Delme", "deburring": "Capak_Alma", "gkm": "GKM"}.get(payload.selectedProcess or "")
    if process_name and payload.printRange:
        filename = f"{process_name}_Saha_Plani_Siradaki_10_Is.xlsx" if payload.printRange.mode == "next-jobs" else f"{process_name}_Saha_Plani_{payload.printRange.startDate}_{payload.printRange.endDate}.xlsx"
    else:
        filename = f"{process_name}_Genel_Plani_{datetime.now().date().isoformat()}.xlsx" if process_name else f"Genel_Plan_Operasyonlar_{datetime.now().date().isoformat()}.xlsx"
    return StreamingResponse(
        iter([content]),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@app.post("/api/calendar-events/export")
def export_calendar_events(payload: CalendarEventExportPayload, _: CurrentUser = Depends(current_user)):
    content = build_calendar_event_workbook(payload.model_dump())
    filename = f"Bakim_Mesai_Vardiya_Detayi_{datetime.now().date().isoformat()}.xlsx"
    return StreamingResponse(
        iter([content]),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@app.post("/api/production-archive/export")
def export_production_archive(payload: ProductionArchiveExportPayload, _: CurrentUser = Depends(current_user)):
    content = build_production_archive_workbook(payload.model_dump())
    filename = f"Uretim_Arsivi_{datetime.now().date().isoformat()}.xlsx"
    return StreamingResponse(
        iter([content]),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@app.post("/api/data-packages/export")
def export_data_package(payload: DataPackagePayload, user: CurrentUser = Depends(current_user)):
    if payload.scope == "settings" and not user.is_admin:
        raise HTTPException(status_code=403, detail="Ayarlar paketlerine yalnızca yöneticiler erişebilir")
    content = build_data_package(payload.scope, payload.data)
    filename = f"Selsa_{SCOPE_LABELS[payload.scope]}_{datetime.now().date().isoformat()}.xlsx"
    return StreamingResponse(
        iter([content]),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@app.post("/api/data-packages/{scope}/import")
async def import_data_package(scope: str, file: UploadFile = File(...), user: CurrentUser = Depends(current_user)):
    if scope not in SCOPE_LABELS:
        raise HTTPException(status_code=404, detail="Veri paketi kapsamı bulunamadı.")
    if scope == "settings" and not user.is_admin:
        raise HTTPException(status_code=403, detail="Ayarlar paketlerini yalnızca yöneticiler içe aktarabilir")
    if not file.filename or not file.filename.lower().endswith(".xlsx"):
        raise HTTPException(status_code=422, detail="Yalnızca .xlsx dosyası yükleyebilirsiniz.")
    content = await file.read(MAX_DATA_PACKAGE_BYTES + 1)
    try:
        data = parse_data_package(content, scope)
    except DataPackageError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    return {"fileName": Path(file.filename).name, "scope": scope, "data": data}


@app.get("/api/planning-state")
def get_planning_state(_: CurrentUser = Depends(current_user)):
    return planning_state()


@app.get("/api/planning-state/history")
def get_planning_state_history(_: CurrentUser = Depends(current_user)):
    return planning_state_history()


@app.get("/api/production-archive/history")
def get_production_archive_history(_: CurrentUser = Depends(current_user)):
    return production_archive_history()


