.archive-remainder label small { color:var(--muted); font-size:7px; line-height:1.35; }
.data-package-actions > button:disabled { opacity:.48; cursor:not-allowed; }
@media (max-width:720px) { .archive-allocation-grid,.archive-remainder,.archive-remainder > div { grid-template-columns:1fr; }.archive-status-tabs button { min-width:170px; } }

/* Manual plan impact against the last automatic run */
