.automatic-comparison-head { flex:0 0 auto; padding:19px 22px 17px; display:grid; grid-template-columns:42px minmax(0,1fr) 28px; gap:12px; align-items:start; border-bottom:1px solid var(--line); }
.automatic-comparison-icon { background:#e6f2eb; color:#287052; }
