.automatic-summary-table > div > span:first-child { text-align:left; }
.automatic-summary-table .row > span:first-child { display:flex; flex-direction:column; gap:2px; }
.automatic-summary-table .row > span:first-child strong { font-size:8px; }
.automatic-summary-table .row > span:first-child small { color:var(--muted); font-size:7px; }
.automatic-summary-table .improved,.automatic-order-table em.improved { color:#287052; font-weight:800; }
.automatic-summary-table .worse,.automatic-order-table em.worse { color:#b14841; font-weight:800; }
.automatic-summary-table .neutral,.automatic-order-table em.neutral { color:#7b8580; }
