.comparison-order-filter button { min-height:26px; padding:0 9px; border:0; background:transparent; color:#68736d; font-size:7px; font-weight:750; cursor:pointer; }
.comparison-order-filter button.selected { background:#fff; color:#287052; box-shadow:0 1px 4px rgba(24,32,29,.08); }
