/* Staged ISO-week planning: plan, review, then append the next range */
.plan-sequence-bar { min-height:76px; margin:-9px 30px 15px; padding:11px 12px 11px 15px; display:grid; grid-template-columns:minmax(210px,.9fr) minmax(330px,1.45fr) auto; gap:16px; align-items:center; border-left:3px solid #d76a3b; background:#fff8f2; box-shadow:inset 0 0 0 1px #f0ddd0; animation:guide-reveal .18s ease-out; }
.plan-sequence-bar.complete { border-left-color:#287052; background:#f1f8f4; box-shadow:inset 0 0 0 1px #d5e7dc; }
.plan-sequence-copy { min-width:0; display:flex; flex-direction:column; gap:3px; }
.plan-sequence-copy > span { color:#b95731; font-size:7px; font-weight:850; letter-spacing:.11em; }
.plan-sequence-bar.complete .plan-sequence-copy > span { color:#287052; }
.plan-sequence-copy strong { overflow:hidden; font-size:9px; text-overflow:ellipsis; white-space:nowrap; }
.plan-sequence-copy small { color:#6f756f; font-size:7px; line-height:1.42; }
.plan-sequence-track { min-width:0; display:flex; align-items:stretch; gap:4px; overflow:auto; }
.plan-sequence-track > span { position:relative; min-width:112px; min-height:43px; padding:6px 7px 6px 27px; display:flex; flex-direction:column; justify-content:center; gap:2px; border:1px solid #e0e4df; background:#fff; color:#6c746f; }
.plan-sequence-track > span i { position:absolute; top:8px; left:8px; display:grid; place-items:center; color:#7b847f; font-style:normal; }
.plan-sequence-track > span b { font-size:7px; white-space:nowrap; }
.plan-sequence-track > span small { color:#87908b; font-size:6px; }
.plan-sequence-track > span.reviewing { border-color:#df9c77; background:#fff4ea; color:#9d482a; }
.plan-sequence-track > span.reviewing i,.plan-sequence-track > span.reviewing small { color:#ba5a35; }
.plan-sequence-track > span.completed { border-color:#a9cfb8; background:#eef8f2; color:#276849; }
.plan-sequence-track > span.completed i,.plan-sequence-track > span.completed small { color:#287052; }
.plan-sequence-track > span.next { border-color:#8bbeb8; background:#f0f8f7; color:#116d68; }
.plan-sequence-track > span.next i,.plan-sequence-track > span.next small { color:#087a78; }
.plan-next-range-action { min-height:43px; padding:0 12px; display:flex; align-items:center; gap:7px; border:0; border-radius:7px; background:#d95f2d; color:#fff; cursor:pointer; box-shadow:0 5px 14px rgba(185,75,32,.16); }
.plan-next-range-action > span { display:flex; flex-direction:column; align-items:flex-start; gap:2px; font-size:8px; font-weight:800; white-space:nowrap; }
.plan-next-range-action small { color:#ffe8dc; font-size:6px; font-weight:600; }
.plan-next-range-action:disabled { opacity:.48; cursor:not-allowed; box-shadow:none; }
.plan-sequence-bar + .planning-tools { margin-top:0; }
@media (max-width:1100px) {
  .plan-sequence-bar { margin-inline:18px; grid-template-columns:1fr auto; }
  .plan-sequence-track { grid-column:1 / -1; grid-row:2; }
}
@media (max-width:720px) {
  .plan-sequence-bar { grid-template-columns:1fr; gap:10px; }
  .plan-sequence-track { grid-column:1; grid-row:auto; }
  .plan-next-range-action { width:100%; justify-content:center; }
}

/* Compact planning workspace and live weekly delivery context */
.metrics { padding-bottom:8px; }
.metric { min-height:46px; padding-block:0; }
.metric strong { font-size:17px; }
.planning-tools { margin-bottom:8px; }
.planning-tools > .plan-sequence-bar { min-height:64px; margin:0; border-top:1px solid #e2e7e3; box-shadow:none; }
.planning-tools > .planning-quick-actions { justify-content:flex-start; }
.workspace { transition:grid-template-columns .18s ease; }
.weekly-demand-ribbon { position:relative; z-index:8; min-height:72px; padding:8px 12px; display:grid; grid-template-columns:255px minmax(0,1fr); gap:12px; align-items:stretch; overflow:visible; border-bottom:1px solid var(--line); background:#f8faf7; }
