.weekly-demand-kicker .weekly-demand-guide { padding:14px 15px 13px; display:grid; gap:0; border:1px solid #d6e1dc; background:#fff; color:#26332d; box-shadow:0 16px 38px rgba(24,41,34,.2); font-family:var(--font-body),sans-serif; }
