.calendar-detail-toolbar select,.calendar-detail-toolbar input { width:100%; min-width:0; height:32px; padding:0 7px; border:1px solid #dbe0da; border-radius:6px; background:#fff; color:var(--ink); font-size:8px; }
.calendar-excel-export { min-height:32px; padding:0 10px; display:flex; align-items:center; gap:5px; border:1px solid #a9cbc2; border-radius:6px; background:#edf7f4; color:#087a78; font-size:8px; font-weight:800; cursor:pointer; }
.calendar-excel-export:disabled { opacity:.55; cursor:wait; }
.calendar-detail-summary { min-height:34px; padding:0 10px; display:flex; align-items:center; gap:18px; border-bottom:1px solid var(--line); color:var(--muted); font-size:8px; }
.calendar-detail-summary strong { color:var(--ink); font-size:11px; }
.calendar-event-list.detail-list { max-height:420px; margin-top:0; }
.calendar-event-list.detail-list article { grid-template-columns:28px minmax(0,1fr) 110px auto; padding:9px 7px; }
.calendar-event-list article.completed { background:#f7f8f6; opacity:.78; }
.calendar-event-list article.completed .calendar-event-icon { background:#e2e7e3; color:#68746d; }
.maintenance-complete-toggle { min-height:28px; padding:0 8px; display:flex; flex-direction:row; align-items:center; gap:5px; border:1px solid #b7d6c3; border-radius:6px; background:#f1f8f3; color:#287052; font-size:7px; font-weight:800; cursor:pointer; white-space:nowrap; }
.maintenance-complete-toggle input { accent-color:#287052; }
.calendar-auto-complete { min-height:27px; padding:0 8px; display:inline-flex; align-items:center; gap:5px; border-radius:6px; background:#eaf5ee; color:#287052; font-size:7px; font-weight:800; white-space:nowrap; }

@media (max-width:1250px) {
  .calendar-detail-toolbar { grid-template-columns:repeat(3,minmax(120px,1fr)); }
  .process-plan-layout { grid-template-columns:minmax(0,1fr) 235px; }
  .journey-layout { grid-template-columns:300px minmax(0,1fr); }
  .wip-layout { grid-template-columns:minmax(0,1fr) 310px; }
  .process-summary-line > span { min-width:158px; }
}
@media (max-width:820px) { .journey-layout { grid-template-columns:1fr; }.journey-index { border-right:0; border-bottom:1px solid var(--line); }.journey-job-list { max-height:230px; }.process-workspace-head { align-items:flex-start; flex-direction:column; }.process-summary-line { overflow:auto; } }
.settings-tabs { display:flex; gap:4px; overflow-x:auto; border-bottom:1px solid var(--line); background:#f8faf7; padding:6px 12px 0; }
.settings-tabs button { flex:0 0 auto; padding:12px 18px; border:0; border-bottom:2px solid transparent; background:transparent; color:var(--muted); font:inherit; cursor:pointer; }
.settings-tabs button.active { border-bottom-color:#087a78; background:#fff; color:#075f5c; font-weight:700; }
.settings-tabs button:focus-visible { outline:2px solid #087a78; outline-offset:-3px; }
.settings-page [hidden] { display:none!important; }
.settings-page .settings-tab-workspace { grid-template-columns:minmax(0,1fr); }
.process-start-help { margin:8px 0; color:var(--muted); font-size:11px; line-height:1.5; }

.settings-month-calendar { padding:22px; background:#fff; border-top:3px solid #087a78; }
.settings-month-heading { display:flex; align-items:center; justify-content:space-between; gap:16px; margin-bottom:20px; }
.settings-month-heading > div > span { font-size:9px; letter-spacing:.1em; font-weight:800; color:#087a78; }
.settings-month-heading h3 { margin:5px 0; font:700 24px var(--font-display); text-transform:capitalize; }
.settings-month-heading p { margin:0; font-size:11px; color:var(--muted); }
.settings-month-navigation { display:flex; align-items:center; gap:6px; }
.settings-month-navigation input,.settings-month-filters select { min-height:34px; padding:6px 9px; border:1px solid var(--line); border-radius:5px; background:#fff; color:var(--ink); font:inherit; font-size:11px; }
.settings-month-filters { display:flex; align-items:end; gap:12px; padding:12px 0 18px; }
.settings-month-filters label { display:grid; gap:5px; min-width:135px; color:var(--muted); font-size:10px; }
.settings-month-filters p { max-width:310px; margin:0 0 4px auto; color:var(--muted); font-size:10px; line-height:1.5; }
.settings-month-layout { display:grid; grid-template-columns:minmax(0,1fr) 260px; border:1px solid var(--line); }
.settings-month-scroll { min-width:0; overflow-x:auto; }
.settings-month-grid { display:grid; grid-template-columns:repeat(7,minmax(0,1fr)); min-width:590px; }
.settings-weekday { padding:11px; background:#f4f7f3; color:var(--muted); font-size:10px; font-weight:700; border-bottom:1px solid var(--line); text-align:center; }
.settings-day { min-width:0; min-height:116px; padding:8px 5px; display:flex; flex-direction:column; gap:5px; border:0; border-right:1px solid #e9ede7; border-bottom:1px solid #e9ede7; background:#fff; text-align:left; cursor:pointer; color:var(--ink); }
.settings-day.sunday { background:#f8f8f4; }
.settings-day.outside { background:#f7f8f6; color:#98a19b; }
.settings-day.selected { background:#edf7f5; box-shadow:inset 0 0 0 2px #087a78; }
.settings-day:hover { background:#f1f7f5; }
.settings-day:focus-visible { outline:2px solid #087a78; outline-offset:-3px; }
.settings-day-number { display:flex; align-items:center; gap:5px; padding:0 3px; font-size:12px; font-weight:700; }
.settings-day-number.today { color:#087a78; }
.settings-day-number small { font-size:8px; font-weight:600; }
.settings-calendar-chip { display:flex; align-items:center; gap:5px; padding:4px 5px; border-radius:3px; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; width:100%; font-size:9px; line-height:1.3; border-left:3px solid; }
.settings-calendar-chip.holiday,.settings-calendar-kind.holiday { color:#795409; background:#fff1bf; border-color:#bd890f; }
.settings-calendar-chip.maintenance,.settings-calendar-kind.maintenance { color:#8e3737; background:#fbe1df; border-color:#c55450; }
.settings-calendar-chip.overtime,.settings-calendar-kind.overtime { color:#205d41; background:#dcefe2; border-color:#39865b; }
.settings-calendar-chip.shift-change,.settings-calendar-kind.shift-change { color:#284f86; background:#ddeafa; border-color:#4b78b5; }
.settings-calendar-chip.completed { opacity:.55; }
.settings-day-more { padding:0 4px; color:#087a78; font-size:9px; font-weight:700; }
.settings-day-details { padding:18px; border-left:1px solid var(--line); background:#fafbf9; max-height:740px; overflow-y:auto; }
.settings-day-details > svg { color:#087a78; }
.settings-day-details h4 { margin:9px 0 4px; font-size:16px; }
.settings-day-details > p { margin:0 0 18px; color:var(--muted); font-size:11px; }
.settings-day-details article { display:flex; flex-direction:column; gap:7px; padding:14px 0; border-top:1px solid var(--line); }
.settings-day-details article > div { display:flex; justify-content:space-between; align-items:center; gap:5px; }
.settings-day-details article strong { font-size:12px; overflow-wrap:anywhere; }
.settings-day-details article > span,.settings-day-details article small { font-size:10px; color:var(--muted); line-height:1.5; }
.settings-day-details article button { align-self:flex-start; margin-top:4px; }
.settings-calendar-kind { display:inline-block; padding:4px 7px; border-radius:3px; font-size:9px; font-weight:700; }
.settings-day-empty { padding:18px 0; font-size:11px; color:var(--muted); line-height:1.7; }
.settings-calendar-legend { display:flex; flex-wrap:wrap; align-items:center; gap:8px; padding:0 0 16px; }
.settings-calendar-legend small { margin-left:auto; color:var(--muted); font-size:10px; }
@media(max-width:1100px) { .settings-month-layout { grid-template-columns:minmax(0,1fr); }.settings-day-details { border-left:0; border-top:1px solid var(--line); max-height:360px; }.settings-month-filters { flex-wrap:wrap; }.settings-month-filters p { margin-left:0; } }
@media(max-width:700px) { .settings-month-calendar { padding:12px; }.settings-month-heading { align-items:flex-start; flex-direction:column; }.settings-month-filters label { min-width:100px; flex:1; }.settings-month-navigation { flex-wrap:wrap; } }

.settings-calendar-chip > svg { flex:0 0 16px; }
.settings-chip-copy { display:flex; flex-direction:column; min-width:0; gap:2px; }
.settings-chip-copy > b,.settings-chip-copy > span { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.settings-chip-copy > b { font-size:9px; font-weight:750; }
.settings-chip-copy > span { font-size:9px; }
.settings-day-details .settings-entry-process { display:flex; align-items:center; gap:6px; color:var(--ink); font-weight:700; }
.settings-legend-group { display:flex; flex-wrap:wrap; align-items:center; gap:8px; }
.settings-legend-group > strong { margin-right:2px; color:var(--muted); font-size:10px; font-weight:600; }
.settings-legend-group + .settings-legend-group { margin-left:12px; }
.settings-process-key { display:inline-flex; align-items:center; gap:4px; color:var(--ink); font-size:10px; }
.settings-process-key svg { flex-shrink:0; }
@media(max-width:1100px) { .settings-legend-group + .settings-legend-group { margin-left:0; }.settings-calendar-legend { gap:12px; } }

/* Downstream placement: requested anchor and calculated reservation are distinct. */
.process-drop-request { position:absolute; inset-block:0; border-left:2px dashed #9b5d22; z-index:15; pointer-events:none; }
.process-drop-placement { position:absolute; top:7px; bottom:7px; border:3px solid #087a78; background:repeating-linear-gradient(135deg,#d9f3edcc 0 7px,#ffffffcc 7px 14px); z-index:14; pointer-events:none; }
.process-drop-placement > span { position:absolute; left:0; top:-20px; padding:3px 6px; background:#075f5d; color:white; font-size:10px; font-weight:750; white-space:nowrap; }
.process-placement-dialog { width:min(780px,calc(100vw - 32px)); max-height:90vh; overflow:auto; padding:26px; background:#fff; border-top:4px solid #087a78; box-shadow:0 18px 70px #132f3440; }
.process-placement-dialog > svg { color:#087a78; }.process-placement-dialog h2 { margin:8px 0 14px; }.process-placement-dialog p { font-size:13px; line-height:1.6; }
.process-placement-dialog > dl { display:grid; gap:8px; padding:14px; background:#f2f7f5; }.process-placement-dialog > dl > div { display:flex; flex-wrap:wrap; justify-content:space-between; gap:8px; }.process-placement-dialog dt { font-size:12px; color:var(--muted); }.process-placement-dialog dd { margin:0; font-size:13px; font-weight:750; }
.placement-adjustment { padding:10px; background:#fff3de; border-left:3px solid #b67623; }
.placement-impact-list { max-height:clamp(180px,38vh,360px); overflow:auto; scrollbar-gutter:stable; border-top:1px solid var(--line); }
.placement-impact-viewport { position:relative; }
.placement-impact-viewport.has-more-below::after { content:""; position:absolute; bottom:0; left:0; right:0; height:30px; background:linear-gradient(transparent,#fff); pointer-events:none; }
.placement-impact-list:focus-visible { outline:2px solid #087a78; outline-offset:2px; }
.placement-scroll-guide { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px; padding:9px 12px; border:1px solid #d5e5df; border-radius:0 0 6px 6px; background:#f0f7f4; color:#4d655b; font-size:11px; }
.placement-scroll-guide button { display:inline-flex; align-items:center; gap:6px; padding:5px 8px; border:1px solid #b3d4c7; border-radius:5px; background:white; color:#086b5d; font-size:12px; font-weight:750; cursor:pointer; }
.placement-scroll-guide button:hover { background:#e2f2eb; border-color:#087a78; }
.placement-scroll-guide button:focus-visible { outline:2px solid #087a78; outline-offset:2px; }
.placement-impact-list article { padding:16px 0; display:grid; gap:10px; font-size:12px; border-bottom:1px solid var(--line); }
.placement-impact-title { display:flex; align-items:center; gap:6px; font-size:13px; }
.placement-impact-title svg { flex-shrink:0; }
.placement-comparison { display:grid; grid-template-columns:minmax(0,1fr) 18px minmax(0,1fr); align-items:center; gap:10px; }
.placement-version { min-width:0; padding:12px; border:1px solid #dfe5e2; border-radius:8px; background:#f5f6f5; }
.placement-version header { display:flex; align-items:center; gap:8px; margin-bottom:12px; color:#606b65; font-size:11px; }
.placement-version-label { padding:3px 7px; border-radius:4px; background:#e2e7e4; color:#47544d; font-size:11px; font-weight:800; }
.placement-version-after { background:#edf8f5; border-color:#abd4c8; }
.placement-version-after header { color:#356c5d; }
.placement-version-after .placement-version-label { color:#fff; background:#087a68; }
.placement-comparison-arrow { color:#738b81; }
.process-placement-dialog .placement-version-details { display:grid; gap:8px; padding:0; margin:0; background:none; }
.placement-version-details > div { display:grid; grid-template-columns:60px minmax(0,1fr); align-items:baseline; gap:6px; }
.process-placement-dialog .placement-version-details dt { font-size:11px; color:#5a6860; }
.process-placement-dialog .placement-version-details dd { font-size:12px; font-weight:600; font-variant-numeric:tabular-nums; overflow-wrap:anywhere; }
.process-placement-dialog .placement-version-details .placement-value-changed { color:#056b58; font-weight:800; }
.placement-resource-change { display:inline-block; margin-left:6px; font-size:10px; font-weight:600; }
@media (max-width:580px) {
  .process-placement-dialog { padding:18px; }
  .placement-comparison { grid-template-columns:minmax(0,1fr); gap:8px; }
  .placement-comparison-arrow { justify-self:center; transform:rotate(90deg); }
}

.process-gantt-batch.just-moved { outline:3px solid #7f3ca6; outline-offset:3px; box-shadow:0 0 0 6px #e6d5f3; }
@media (prefers-reduced-motion:reduce) { .process-gantt-batch.just-moved { animation:none; } }
/* Feedback must not move the drop target underneath a captured pointer. */
.gantt-drag-preview.process-move-notice { position:fixed; left:24px; right:24px; bottom:18px; z-index:90; margin:0; padding:14px 18px; box-shadow:0 8px 28px #132f3426; pointer-events:none; }
.gantt-drag-preview.process-move-notice button { pointer-events:auto; }.gantt-drag-preview.process-move-notice span { font-size:12px; line-height:1.5; }.gantt-drag-preview.process-move-notice strong { font-size:13px; }

/* Delivery reporting shares one restrained surface with the working table. */
.delivery-summary { margin:16px 0; padding:20px 22px; background:#fff; border:1px solid var(--line); border-radius:10px; }
.data-surface > .delivery-summary { margin:0; border:0; border-bottom:1px solid var(--line); border-radius:0; }
.delivery-report-scope { display:flex; flex-wrap:wrap; gap:12px; align-items:center; }
.delivery-report-scope > div { margin-right:auto; }
.delivery-report-scope > div > strong { font-size:14px; font-weight:750; }
.delivery-report-scope small { display:block; color:var(--muted); font-size:11px; line-height:1.5; margin-top:3px; }
.delivery-report-scope label { display:grid; gap:4px; color:var(--muted); font-size:10px; font-weight:600; }
.delivery-report-scope input { height:34px; width:136px; padding:6px 9px; color:var(--ink); background:#fff; border:1px solid var(--line); border-radius:5px; font-size:12px; }
.delivery-report-metrics { display:grid; grid-template-columns:repeat(7,minmax(0,1fr)); margin-top:22px; }
.delivery-report-metrics > div { min-width:0; display:flex; flex-direction:column; gap:6px; padding:0 14px; border-left:1px solid var(--line); }
.delivery-report-metrics > div:first-child { padding-left:0; border-left:0; }
.delivery-report-metrics > div:last-child { padding-right:0; }
.delivery-report-metrics strong { font-size:24px; line-height:1.15; font-weight:700; letter-spacing:-.035em; font-variant-numeric:tabular-nums; }
.delivery-report-metrics small { min-height:30px; font-size:11px; line-height:1.4; color:#53615a; }
.delivery-report-metrics span { font-size:10px; line-height:1.5; color:var(--muted); }
.delivery-report-metrics .metric-5 strong { color:#b04c3f; }
.delivery-report-metrics .metric-6 strong { color:#187057; }
.delivery-summary p { padding:10px 12px; background:#fff8ec; border-left:2px solid #b68532; color:#79531e; font-size:12px; line-height:1.5; }
.planning-production-summary { color:#526c62; font-size:12px; margin:12px 0; }
.delivery-report-scope input:focus-visible, .journey-filters select:focus-visible { outline:2px solid #087a78; outline-offset:2px; }
@media (max-width:1199px) {
  .delivery-report-metrics { grid-template-columns:repeat(12,minmax(0,1fr)); row-gap:18px; }
  .delivery-report-metrics > div { grid-column:span 3; }
  .delivery-report-metrics > div:nth-child(n+5) { grid-column:span 4; padding-top:14px; border-top:1px solid var(--line); }
  .delivery-report-metrics > div:nth-child(5) { border-left:0; padding-left:0; }
  .delivery-report-metrics small { min-height:0; }
  .delivery-report-scope > div { flex-basis:100%; }
}
@media (max-width:600px) {
  .delivery-summary { padding:16px; }
  .delivery-report-scope { gap:10px; }
  .delivery-report-scope label { flex:1; }
  .delivery-report-scope input { width:100%; min-width:0; }
  .delivery-report-scope > small { flex-basis:100%; }
  .delivery-report-metrics { grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px 0; margin-top:18px; }
  .delivery-report-metrics > div, .delivery-report-metrics > div:nth-child(n+5) { grid-column:span 1; padding:0 12px; border-top:0; }
  .delivery-report-metrics > div:nth-child(odd) { padding-left:0; border-left:0; }
  .delivery-report-metrics > div:last-child { grid-column:span 2; padding-top:14px; border-top:1px solid var(--line); }
  .delivery-report-metrics strong { font-size:23px; }
}

.journey-filters { display:grid; grid-template-columns:1fr 1fr; gap:10px; padding:12px; }
.journey-filters label { display:grid; min-width:0; gap:6px; font-size:10px; font-weight:600; color:#617069; }
.journey-filters select { width:100%; min-width:0; height:34px; padding:6px; font-size:11px; color:var(--ink); background:#fff; border:1px solid var(--line); border-radius:5px; }
.journey-filter-count { grid-column:1/-1; display:flex; flex-wrap:wrap; align-items:baseline; justify-content:space-between; gap:4px; padding-top:4px; }
.journey-filter-count strong { font-size:12px; font-weight:650; font-variant-numeric:tabular-nums; }
.journey-filter-count small, .journey-history-notice { color:#687770; font-size:10px; line-height:1.5; }
.journey-missing-plan { position: absolute; top: 6px; left: 8px; font-size: 11px; color: #687770; }
.journey-color-legend { display:flex; flex-wrap:wrap; gap:14px; padding:12px; font-size:12px; }
.journey-color-legend span::before { content:""; display:inline-block; width:10px; height:10px; margin-right:5px; background:var(--process-color); border-radius:2px; }
.journey-color-legend .turning, .journey-all-flow-track .planned.turning { --process-color:#2563eb; }
.journey-color-legend .drilling, .journey-all-flow-track .planned.drilling { --process-color:#c2410c; }
.journey-color-legend .deburring, .journey-all-flow-track .planned.deburring { --process-color:#9333ea; }
.journey-color-legend .gkm, .journey-all-flow-track .planned.gkm { --process-color:#0e7490; }
.journey-color-legend .waiting { --process-color:#eab308; }
.journey-color-legend .actual { --process-color:#15803d; }
.journey-all-flow-track .journey-flow-bar.planned { background:var(--process-color); border-color:var(--process-color); color:#fff; }
.journey-all-flow-track .journey-flow-bar.planned strong, .journey-all-flow-track .journey-flow-bar.planned small { color:#fff; }
.journey-all-flow-track .journey-flow-wait { background:#fde047; color:#594a00; z-index:2; }

/* Dialogs own their actions; the assistant remains behind modal feedback. */
.feedback-overlay { z-index: 100; }
.feedback-composer { max-width:100vw; min-height:0; overflow-y:auto; }
.feedback-composer > textarea { min-height:100px; }
.feedback-composer .composer-actions { flex-shrink:0; flex-wrap:wrap; }
.feedback-image-open { border:0; padding:0; background:transparent; cursor:zoom-in; width:100%; text-align:left; }
.feedback-image-open > span { display:block; padding:6px; color:#087a78; }
.feedback-image-dialog { width:min(1400px,95vw); max-height:92dvh; padding:16px; border:1px solid #cad5d0; border-radius:12px; }
.feedback-image-dialog::backdrop { background:#142922b3; }
.feedback-image-dialog > div { display:flex; align-items:center; gap:16px; margin-bottom:12px; }
.feedback-image-dialog > div strong { margin-right:auto; overflow-wrap:anywhere; }
.feedback-image-dialog img { display:block; width:100%; height:auto; max-height:none; object-fit:contain; }
/* Keep account actions and navigation on deliberate, independent rows. */
.topbar { height:auto; min-height:86px; display:grid; grid-template-columns:auto minmax(0,1fr); gap:8px 20px; padding:10px 28px 0; }
.topbar .brand { width:auto; }
.topbar > nav { grid-column:1/-1; grid-row:2; display:flex; min-width:0; height:36px; flex-wrap:nowrap; overflow-x:auto; scrollbar-width:thin; }
.topbar .nav-item { flex-shrink:0; padding:0 14px; transition:background .15s,color .15s; }
.topbar .nav-item:hover { background:#f3f6f3; }
.topbar .top-actions { grid-column:2; grid-row:1; justify-content:flex-end; min-width:0; max-width:100%; flex-wrap:wrap; gap:8px; }
.topbar .account-control { flex-shrink:0; }
.journey-color-legend { gap:14px; padding:12px 0; color:#647169; font-size:10px; }
.journey-all-flow-track .journey-flow-bar.planned { background:color-mix(in srgb,var(--process-color) 12%,white); border-color:color-mix(in srgb,var(--process-color) 45%,white); border-left:3px solid var(--process-color); }
.journey-all-flow-track .journey-flow-bar.planned strong, .journey-all-flow-track .journey-flow-bar.planned small { color:color-mix(in srgb,var(--process-color) 75%,black); }
.journey-all-flow-track .journey-flow-wait { background:#fff0a8; border-color:#d9b945; color:#665019; }
.feedback-image-open > span { padding:8px 0; font-size:11px; }
.feedback-image-open:hover > span { text-decoration:underline; }
.feedback-image-dialog { padding:0; overflow:auto; box-shadow:0 24px 80px #0d241f40; }
.feedback-image-dialog > div { position:sticky; top:0; z-index:1; padding:12px 16px; margin:0; border-bottom:1px solid var(--line); background:#fff; font-size:12px; }
.feedback-image-dialog > div a, .feedback-image-dialog > div button { display:inline-flex; align-items:center; justify-content:center; min-height:32px; padding:6px 10px; border:1px solid var(--line); border-radius:5px; background:#fff; color:#246b59; text-decoration:none; }
.feedback-image-dialog img { padding:12px; background:#f2f4f2; }
@media (max-width:700px) {
  .topbar { padding-inline:12px; gap:8px; }
  .topbar .brand { font-size:14px; }
  .topbar .top-actions { gap:6px; }
  .topbar .top-actions .advice-launch span, .topbar .top-actions .archive-global-launch span { display:none; }
  .topbar .top-actions .production-pull { max-width:140px; }
  .topbar .nav-item { padding-inline:12px; }
}
@media (prefers-reduced-motion:reduce) { .topbar .nav-item { transition:none; } }
/* Let wide working tables scroll locally without pushing the account menu offscreen. */
.app-shell { min-width:0; }
.order-context-line small { font-size:8px; letter-spacing:.03em; }
.order-context-line strong { font-size:11px; }
.order-entry-toolbar { flex-wrap:wrap; }
.order-context-summary { flex-basis:100%; min-width:0; }
.order-toolbar-actions { width:100%; justify-content:flex-start; }
.order-toolbar-actions .search { margin-left:auto; }
@media (max-width:820px) {
  .data-surface, .process-workspace { margin-inline:12px; }
  .order-context-line { flex-wrap:wrap; gap:10px 0; }
  .order-context-line > span { flex:1 1 140px; }
