  .order-toolbar-actions .search { margin-left:0; }
}
@media (max-width:600px) {
  .process-workspace { padding:14px; }
  .journey-detail { min-width:0; }
  .journey-color-legend { gap:10px; }
}
.order-entry-table td { font-size:11px; }
.order-entry-table th { font-size:9px; line-height:1.4; }
.order-toolbar-actions .secondary, .order-toolbar-actions .danger-outline { font-size:10px; }
