.metric strong { font-size:16px; }
.planning-status-toast { position:fixed; left:24px; bottom:24px; z-index:60; max-width:min(480px,calc(100vw - 140px)); display:flex; align-items:center; gap:16px; padding:12px 14px; border:1px solid #cedbd3; border-radius:8px; background:#fff; box-shadow:0 5px 24px #193c2420; font-size:12px; line-height:1.5; }
.planning-status-toast button { display:grid; place-items:center; flex-shrink:0; width:28px; height:28px; padding:0; background:transparent; border:0; border-radius:4px; cursor:pointer; }
