/* Freeze order identity while delivery and planning columns scroll. */
.order-entry-table { --order-sequence-width:72px; isolation:isolate; }
.order-entry-table table { border-collapse:separate; border-spacing:0; }
.order-entry-table tr > :first-child { width:var(--order-sequence-width); min-width:var(--order-sequence-width); max-width:var(--order-sequence-width); position:sticky; left:0; }
.order-entry-table tr > :nth-child(2) { position:sticky; left:var(--order-sequence-width); box-shadow:1px 0 0 #d8e1db,5px 0 8px -6px #263c3040; }
.order-entry-table tbody tr > :nth-child(-n+2) { z-index:3; background:#fff; }
