"use client";

import { Buildings, Cylinder, Drop, Ruler, Sparkle, type IconProps } from "@phosphor-icons/react";
import type { ComponentType } from "react";
import type { ProductionProcess } from "@/lib/planning";

function DrillBit({ size = 16, className }: IconProps) {
  return <svg width={size} height={size} className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M7 3h10v5H7zM9 8v10l3 3 3-3V8M9 11l6-2M9 15l6-2M9 18l6-2" /></svg>;
}

// The only process → icon mapping. Change a process icon here for every screen.
const PROCESS_ICONS: Record<ProductionProcess | "all" | "unknown", ComponentType<IconProps>> = {
  turning: Cylinder,
  drilling: DrillBit,
  deburring: Sparkle,
  washing: Drop,
  gkm: Ruler,
  all: Buildings,
  unknown: Buildings,
};

/** Decorative: always pair with a visible process name or an accessible action label.
 * Historical/imported process strings fall back to the work-center icon.
 */
export function ProcessIcon({ process, size = 16, className = "" }: { process: string; size?: number; className?: string }) {
  const key = Object.hasOwn(PROCESS_ICONS, process) ? process as keyof typeof PROCESS_ICONS : "unknown";
  const Icon = PROCESS_ICONS[key];
  return <Icon size={size} weight="bold" className={`process-icon ${className}`.trim()} aria-hidden="true" focusable="false" />;
}

frontend/components/ProcessParametersEdi.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { useMemo, useState } from "react";
import { CaretDown, CaretUp, CheckCircle, MagnifyingGlass, Plus, Warning, X } from "@phosphor-icons/react";
import type { PlanningSeed } from "@/lib/planning";
import {
  processLabel,
  processProductGroup,
  type DownstreamProcess,
  type ProcessPlanningStrategy,
  type ProcessProduct,
  type ProcessResource,
  type ProductProcessParameter,
} from "@/lib/process-master-data";
import { parameterForProcess, validateProcessMasterData } from "@/lib/process-planning";
import { formatInteger } from "@/lib/number-format";

function normalizedGroup(value: string): string {
  return value.trim().toLocaleLowerCase("tr-TR");
}

function strategyLabel(strategy: ProcessPlanningStrategy): string {
  return strategy === "campaign" ? "Aynı tip / setup kampanyası" : "En erken hazır işi al";
}

function familyLabel(family: ProcessProduct["family"]): string {
  return family === "piston" ? "Piston" : "Center Pin";
}

type ProcessParameterDraft = {
  productGroup: string;
  setupKey: string;
  waitWorkdaysBefore: string;
  resourcePriority: string[];
  unitsPerShift: Record<string, string>;
};

function parameterDraft(product: ProcessProduct, parameter: ProductProcessParameter): ProcessParameterDraft {
  return {
    productGroup: processProductGroup(product),
    setupKey: parameter.setupKey,
    waitWorkdaysBefore: String(parameter.waitWorkdaysBefore),
    resourcePriority: [...parameter.resourcePriority],
    unitsPerShift: Object.fromEntries(Object.entries(parameter.unitsPerShift).map(([resourceId, units]) => [resourceId, String(units)])),
  };
}

function ProcessParameterRow({ product, parameter, resources, process, updateSeed }: {
  product: ProcessProduct;
  parameter: ProductProcessParameter;
  resources: ProcessResource[];
  process: DownstreamProcess;
  updateSeed: (mutator: (seed: PlanningSeed) => void) => void;
}) {
  const original = parameterDraft(product, parameter);
  const [draft, setDraft] = useState<ProcessParameterDraft>(original);
  const [saved, setSaved] = useState(false);
  const changed = JSON.stringify(draft) !== JSON.stringify(original);
  const wait = Math.max(0, Math.trunc(Number(draft.waitWorkdaysBefore) || 0));
  const invalid = !draft.productGroup.trim() || !draft.setupKey.trim() || !draft.resourcePriority.length || draft.resourcePriority.some((resourceId) => !(Number(draft.unitsPerShift[resourceId]) > 0));

  function change(patch: Partial<ProcessParameterDraft>) {
    setSaved(false);
    setDraft((current) => ({ ...current, ...patch }));
  }

  function moveResource(index: number, direction: -1 | 1) {
    const target = index + direction;
    if (target < 0 || target >= draft.resourcePriority.length) return;
    const resourcePriority = [...draft.resourcePriority];
    [resourcePriority[index], resourcePriority[target]] = [resourcePriority[target], resourcePriority[index]];
    change({ resourcePriority });
  }

  function addResource(resourceId: string) {
    if (draft.resourcePriority.includes(resourceId)) return;
    change({
      resourcePriority: [...draft.resourcePriority, resourceId],
      unitsPerShift: { ...draft.unitsPerShift, [resourceId]: draft.unitsPerShift[resourceId] || "1" },
    });
  }

  function removeResource(resourceId: string) {
    const unitsPerShift = { ...draft.unitsPerShift };
    delete unitsPerShift[resourceId];
    change({ resourcePriority: draft.resourcePriority.filter((id) => id !== resourceId), unitsPerShift });
  }

  function save() {
    if (invalid) return;
    const normalizedDraft: ProcessParameterDraft = {
      ...draft,
      productGroup: draft.productGroup.trim(),
      setupKey: draft.setupKey.trim(),
      waitWorkdaysBefore: String(wait),
      unitsPerShift: Object.fromEntries(draft.resourcePriority.map((resourceId) => [resourceId, String(Math.max(1, Math.trunc(Number(draft.unitsPerShift[resourceId]) || 1)))])),
    };
    updateSeed((seedDraft) => {
      const targetProduct = seedDraft.processMasterData?.products.find((item) => item.product === product.product);
      const targetParameter = targetProduct ? parameterForProcess(targetProduct, process) : undefined;
      if (!targetProduct || !targetParameter) return;
      targetProduct.productGroup = normalizedDraft.productGroup;
      targetParameter.setupKey = normalizedDraft.setupKey;
      targetParameter.waitWorkdaysBefore = Number(normalizedDraft.waitWorkdaysBefore);
      targetParameter.resourcePriority = [...normalizedDraft.resourcePriority];
      targetParameter.unitsPerShift = Object.fromEntries(normalizedDraft.resourcePriority.map((resourceId) => [resourceId, Number(normalizedDraft.unitsPerShift[resourceId])]));
    });
    setDraft(normalizedDraft);
    setSaved(true);
  }

  return <>
    <tr className={invalid && changed ? "parameter-row invalid" : "parameter-row"}>
      <td><strong>{product.product}</strong><small className="process-product-family">{familyLabel(product.family)}</small></td>
      <td><input className={`cell-input wide ${!draft.productGroup.trim() ? "invalid" : ""}`} value={draft.productGroup} onChange={(event) => change({ productGroup: event.target.value })} /></td>
      <td className={`machine-priority-cell process-priority-cell ${!draft.resourcePriority.length ? "invalid" : ""}`}>
        <div className="machine-priority-list">{draft.resourcePriority.map((resourceId, index) => {
          const resource = resources.find((item) => item.id === resourceId);
          return <div className="machine-priority-item" key={resourceId}>
            <span>{index + 1}</span>
            <div className="machine-priority-identity"><strong>{resourceId}</strong><small>{resource?.name ?? "Tanımsız iş merkezi"}</small></div>
            <small className="machine-priority-role">{index === 0 ? "Ana merkez" : `${index + 1}. tercih`}</small>
            <div className="machine-daily-rate editing"><small>Adet / vardiya</small><span><input type="number" min="1" step="1" value={draft.unitsPerShift[resourceId] ?? ""} onChange={(event) => change({ unitsPerShift: { ...draft.unitsPerShift, [resourceId]: event.target.value } })} /></span></div>
            <button disabled={index === 0} onClick={() => moveResource(index, -1)} aria-label={`${resourceId} önceliğini yükselt`}><CaretUp size={11} /></button>
            <button disabled={index === draft.resourcePriority.length - 1} onClick={() => moveResource(index, 1)} aria-label={`${resourceId} önceliğini düşür`}><CaretDown size={11} /></button>
            <button className="remove" onClick={() => removeResource(resourceId)} aria-label={`${resourceId} seçimini kaldır`}><X size={11} /></button>
          </div>;
        })}</div>
        <details className="machine-priority-picker"><summary><Plus size={12} /> İş merkezi seç</summary><div><p>Seçim sırası planlama önceliğidir. Kodun altında iş merkezinin tam adı gösterilir.</p><div className="machine-option-grid">{resources.map((resource) => {
          const rank = draft.resourcePriority.indexOf(resource.id);
          return <button key={resource.id} className={rank >= 0 ? "selected" : ""} disabled={rank >= 0} onClick={() => addResource(resource.id)}><span>{rank >= 0 ? rank + 1 : "+"}</span><b><strong>{resource.id}</strong><small>{resource.name}</small></b></button>;
        })}</div></div></details>
      </td>
      <td><input className={`cell-input wide ${!draft.setupKey.trim() ? "invalid" : ""}`} value={draft.setupKey} onChange={(event) => change({ setupKey: event.target.value })} /></td>
      <td className="numeric"><input className="cell-input compact numeric" type="number" min="0" step="1" value={draft.waitWorkdaysBefore} onChange={(event) => change({ waitWorkdaysBefore: event.target.value })} /></td>
      <td><button className="parameter-save" disabled={invalid || !changed} onClick={save}>{changed ? "Kaydet" : "Güncel"}</button></td>
    </tr>
    {(invalid && changed || saved) && <tr className="parameter-feedback-row"><td colSpan={6}>{invalid && changed ? <><span className="error">Eksik parametre</span>Ürün grubu, setup ve en az bir pozitif kapasite girin.</> : <><span className="success">Kaydedildi</span>{product.product} için {processLabel(process).toLocaleLowerCase("tr-TR")} parametreleri güncellendi.</>}</td></tr>}
  </>;
}

function DownstreamParameterTable({ seed, updateSeed, process }: {
  seed: PlanningSeed;
  updateSeed: (mutator: (seed: PlanningSeed) => void) => void;
  process: DownstreamProcess;
}) {
  const [query, setQuery] = useState("");
  const [groupFilter, setGroupFilter] = useState("");
  useRaviScreenContext("process-parameters", { query, groupFilter, process });
  const master = seed.processMasterData!;
  const resources = master.resources.filter((resource) => resource.process === process);
  const strategy = master.planningStrategies?.[process] ?? (process === "drilling" ? "campaign" : "earliest-ready");
  const allProducts = master.products.filter((product) => parameterForProcess(product, process));
  const groups = [...new Set(allProducts.map(processProductGroup).filter(Boolean))].sort((left, right) => left.localeCompare(right, "tr"));
  const normalizedQuery = query.trim().toLocaleUpperCase("tr-TR");
  const products = allProducts.filter((product) => (!groupFilter || normalizedGroup(processProductGroup(product)) === normalizedGroup(groupFilter)) && (!normalizedQuery || `${product.product} ${processProductGroup(product)} ${familyLabel(product.family)}`.toLocaleUpperCase("tr-TR").includes(normalizedQuery)));
  const warnings = validateProcessMasterData(master);
  const title = process === "drilling" ? "Ürün, matkap çapı, iş merkezi önceliği ve üretim hızı" : "Ürün, setup, iş merkezi önceliği ve üretim hızı";

  return <section className="data-surface downstream-parameter-surface">
    <div className="turning-parameter-heading"><span><ProcessIcon process={process} size={14} /> {processLabel(process).toLocaleUpperCase("tr-TR")} PARAMETRELERİ</span><strong>{title}</strong><small>İş merkezi kodlarının altında tam adları gösterilir.</small></div>
    <div className="surface-toolbar parameter-toolbar"><div><strong>{products.length === allProducts.length ? formatInteger(allProducts.length) : `${formatInteger(products.length)} / ${formatInteger(allProducts.length)}`} ürün parametresi</strong><span>Değişiklikler yalnızca “Kaydet” ile uygulanır; öncelik sırası planlama motorunda doğrudan kullanılır.</span></div><div className="data-toolbar-actions">
      <label className="parameter-diameter-filter"><span>Planlama yöntemi</span><select aria-label={`${processLabel(process)} planlama yöntemi`} value={strategy} onChange={(event) => updateSeed((draft) => { if (draft.processMasterData) draft.processMasterData.planningStrategies = { ...draft.processMasterData.planningStrategies, [process]: event.target.value as ProcessPlanningStrategy }; })}><option value="campaign">{strategyLabel("campaign")}</option><option value="earliest-ready">{strategyLabel("earliest-ready")}</option></select></label>
      <label className={`parameter-diameter-filter ${groupFilter ? "active" : ""}`}><span>Ürün grubu</span><select aria-label="Ürün grubuna göre filtrele" value={groupFilter} onChange={(event) => setGroupFilter(event.target.value)}><option value="">Tüm gruplar</option>{groups.map((group) => <option key={group} value={group}>{group === "piston" ? "Piston" : group === "center-pin" ? "Center Pin" : group}</option>)}</select></label>
      <div className="search"><MagnifyingGlass size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ürün ara" /></div>
    </div></div>
    {warnings.length > 0 && <div className="process-editor-warning"><Warning size={16} weight="fill" /><span>{formatInteger(warnings.length)} ana veri uyarısı · {warnings[0].message}</span></div>}
    <div className="table-scroll"><table className="downstream-parameter-table"><thead><tr><th>Ürün</th><th>Ürün grubu</th><th>İş merkezi önceliği ve adet / vardiya</th><th>{process === "drilling" ? "Matkap çapı" : "Setup grubu"}</th><th className="numeric">Ön bekleme</th><th>Durum</th></tr></thead><tbody>
      {products.map((product) => <ProcessParameterRow key={`${process}-${product.product}`} product={product} parameter={parameterForProcess(product, process)!} resources={resources} process={process} updateSeed={updateSeed} />)}
      {!products.length && <tr className="parameter-empty-row"><td colSpan={6}><strong>Eşleşen ürün bulunamadı</strong><span>Ürün aramasını veya ürün grubu filtresini değiştirin.</span><button onClick={() => { setQuery(""); setGroupFilter(""); }}>Filtreleri temizle</button></td></tr>}
    </tbody></table></div>
  </section>;
}

export function ProcessParametersEditor({ seed, updateSeed, process, selectedResourceId, resourcesOnly = false }: {
  seed: PlanningSeed;
  updateSeed: (mutator: (seed: PlanningSeed) => void) => void;
  process: DownstreamProcess;
  selectedResourceId?: string;
  resourcesOnly?: boolean;
}) {
  const master = seed.processMasterData;
  const resources = (master?.resources ?? []).filter((resource) => resource.process === process);
  const selectedResource = resources.find((resource) => resource.id === selectedResourceId) ?? resources[0];
  const visibleResources = selectedResourceId ? (selectedResource ? [selectedResource] : []) : resources;
  const groups = useMemo(() => [...new Set((master?.products ?? []).map(processProductGroup).filter(Boolean))].sort((left, right) => left.localeCompare(right, "tr")), [master?.products]);
  const warnings = master ? validateProcessMasterData(master) : [];

  function editResource(resourceId: string, patch: Partial<ProcessResource>) {
    updateSeed((draft) => {
      const resource = draft.processMasterData?.resources.find((item) => item.id === resourceId);
      if (resource) Object.assign(resource, patch);
    });
  }

  function setResourceGroup(resource: ProcessResource, group: string, enabled: boolean) {
    const current = resource.eligibleProductGroups ?? groups;
    const target = normalizedGroup(group);
    const next = enabled ? [...new Set([...current, group])] : current.filter((item) => normalizedGroup(item) !== target);
    editResource(resource.id, { eligibleProductGroups: next });
  }

  if (!master) return <section className="process-parameter-editor embedded missing"><Warning size={18} weight="fill" /><div><strong>Proses ana verisi bulunamadı</strong><span>{processLabel(process)} ayarları yüklenemedi.</span></div></section>;
  if (!resourcesOnly) return <DownstreamParameterTable seed={seed} updateSeed={updateSeed} process={process} />;

  return <section className="process-parameter-editor embedded resources-only">
    {warnings.length > 0 && <div className="process-editor-warning"><Warning size={16} weight="fill" /><span>{formatInteger(warnings.length)} ana veri uyarısı · {warnings[0].message}</span></div>}
    <div className="process-resource-editor">
      <div className="process-editor-section-title"><div><span>{selectedResourceId ? "SEÇİLİ TEZGAH" : "İŞ MERKEZLERİ"}</span><strong><ProcessIcon process={process} /> {selectedResourceId ? (selectedResource ? `${selectedResource.id} · ${selectedResource.name}` : `${processLabel(process)} tezgahı bulunamadı`) : "Aktiflik, vardiya ve ürün grubu"}</strong></div><small>{resources.length} tanımlı · {resources.filter((resource) => resource.active && resource.defaultShifts > 0).length} planlamada</small></div>
      <div className="process-resource-cards">{visibleResources.map((resource) => {
        const usable = resource.active && resource.defaultShifts > 0;
        const eligibleGroups = resource.eligibleProductGroups ?? groups;
        return <article key={resource.id} className={usable ? "active" : "passive"}>
          <div className="process-resource-card-head"><span className={`status ${usable ? "on" : "off"}`} /><div><strong>{resource.id}</strong><small>{resource.operationName} · {resource.erpWorkCenterCode}</small></div><label className="switch-label compact"><input type="checkbox" checked={resource.active} onChange={(event) => editResource(resource.id, { active: event.target.checked })} /><span className="switch" /> Aktif</label></div>
          <label>İş merkezi adı<input defaultValue={resource.name} key={`${resource.id}-${resource.name}`} onBlur={(event) => { const name = event.target.value.trim(); if (name && name !== resource.name) editResource(resource.id, { name }); }} /></label>
          <label>Normal vardiya<select value={resource.defaultShifts} onChange={(event) => editResource(resource.id, { defaultShifts: Number(event.target.value) as 0 | 1 | 2 | 3 })}>{[0, 1, 2, 3].map((count) => <option key={count} value={count}>{count} vardiya</option>)}</select></label>
          <fieldset><legend>Uygun ürün grupları</legend><div>{groups.map((group) => <label key={group}><input type="checkbox" checked={eligibleGroups.some((item) => normalizedGroup(item) === normalizedGroup(group))} onChange={(event) => setResourceGroup(resource, group, event.target.checked)} /><span>{group === "piston" ? "Piston" : group === "center-pin" ? "Center Pin" : group}</span></label>)}</div></fieldset>
        </article>;
      })}</div>
    </div>
    <footer><CheckCircle size={15} weight="fill" /><span>Değişiklikler ortak planlama durumuna kaydedilir ve sonraki planlamada doğrudan kullanılır.</span></footer>
  </section>;
}

