"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { useEffect, useMemo, useRef, useState } from "react";
import { Archive, CalendarBlank, CaretLeft, CaretRight, CornersOut, MagnifyingGlass, Minus, NotePencil, Plus, Warning, X } from "@phosphor-icons/react";
import { excelSerialToDate, formatExcelDate, type ChargeJourneyNote, type PlanningSeed, type ProductionProcess, type ScenarioResult, type WipStage } from "@/lib/planning";
import { buildDownstreamProcessPlan, type ProcessOperation, type RoutedProcessJob } from "@/lib/process-planning";
import { processLabel, type DownstreamProcess } from "@/lib/process-master-data";
import { wipOperationReadyAt, wipStageLabel, type WipOperationInput } from "@/lib/wip-ledger";
import { ganttPercent } from "@/lib/gantt-scale";
import { factoryDateInput } from "@/lib/factory-time";
import { journeyCurrentProcess, journeyVisibleQuantity, chargeJourneyStatusForJob, defaultJourneyOperation, deliveredChargeJourneyJobs, plannedJourneyRange } from "@/lib/charge-journey-status";
import { CompleteJobDialog } from "@/features/planning/machines/ProductionDialogs";
import type { ChargeJourneyNoteInput } from "@/lib/charge-journey-notes";
import { formatInteger as formatNumber } from "@/lib/number-format";

type WorkspaceMode = "wip" | "plan";
type JourneyListMode = "active" | "archive";
type JourneyNoteEditor = Omit<ChargeJourneyNoteInput, "note"> & { label: string };

const WIP_STAGE_OPTIONS: Array<{ id: WipStage; label: string }> = [
  { id: "unclassified", label: "Konumu doğrulanmalı" },
  { id: "quality-hold", label: "Kalite bekliyor" },
  { id: "drilling-queue", label: "Delme bekliyor" },
  { id: "deburring-queue", label: "Çapak alma bekliyor" },
  { id: "washing-buffer", label: "Yıkama tamponunda" },
  { id: "gkm-buffer", label: "GKM öncesi bekliyor" },
  { id: "gkm-queue", label: "GKM bekliyor" },
  { id: "delivery-ready", label: "Teslimata hazır" },
  { id: "on-hold", label: "Blokeli" },
];

function formatHours(value: number): string {
  return `${new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 1 }).format(value)} sa`;
}

function serialToInputDate(serial: number): string {
  return serial ? excelSerialToDate(Math.floor(serial)).toISOString().slice(0, 10) : "";
}

function inputDateToSerial(value: string): number {
  return value ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0;
}

function journeyDateTooltip(label: string, start: number, end: number, ongoing = false): string {
  const date = (value: number) => formatExcelDate(value, { day: "2-digit", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" });
  return `${label}\nBaşlangıç: ${date(start)}\n${ongoing ? `Bitiş: Henüz tamamlanmadı\nPlanlanan bitiş: ${date(end)}` : `Bitiş: ${date(end)}`}`;
}

function familyLabel(family: "piston" | "center-pin"): string {
  return family === "piston" ? "Piston" : "Center Pin";
}

function journeySourceHeading(source: "current-turning" | "turning-plan" | "wip", delivered = false): string {
  return delivered ? "SEVK EDİLEN ŞARJ" : source === "wip" ? "SAHADAKİ ŞARJ" : source === "current-turning" ? "TORNADA ÇALIŞAN ŞARJ" : "PLANLANAN ŞARJ";
}

function rangePosition(start: number, end: number, horizonStart: number, days: number): React.CSSProperties {
  const horizonEnd = horizonStart + days;
  if (end <= horizonStart || start >= horizonEnd) return { display: "none" };
  const visibleStart = Math.max(start, horizonStart);
  const visibleEnd = Math.min(end, horizonEnd);
  const left = (visibleStart - horizonStart) / days * 100;
  const width = Math.max(0.9, (visibleEnd - visibleStart) / days * 100);
  return { left: `${left}%`, width: `${width}%` };
}

function waitLabel(days: number): string {
  const hours = Math.max(0, Math.round(days * 24));
  if (hours === 0) return "Bekleme yok";
  const wholeDays = Math.floor(hours / 24);
  const remainingHours = hours % 24;
  return [wholeDays ? `${wholeDays} gün` : "", remainingHours ? `${remainingHours} sa` : ""].filter(Boolean).join(" ") + " bekleme";
}

function journeyChargeKey(job: RoutedProcessJob): string {
  return job.workOrder.trim() || job.batchId;
}

function delayLabel(days: number): string {
  const rounded = Math.max(1, Math.ceil(days));
  return `+${rounded} gün`;
}

export function ProcessPlanningView({ seed, result, dirty, focusJobId, onCompleteCurrentJob, onCompleteWipOperation, onCorrectWipStage, onReleaseWip, onSaveJourneyNote }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; focusJobId?: string; onCompleteCurrentJob: (machineId: string, completedAt: number, completedQuantity: number) => void; onCompleteWipOperation: (input: WipOperationInput) => boolean; onCorrectWipStage: (lotId: string, stage: WipStage, occurredAt: number) => void; onReleaseWip: (lotId: string, occurredAt: number) => void; onSaveJourneyNote: (input: ChargeJourneyNoteInput) => void }) {
  const [mode, setMode] = useState<WorkspaceMode>("plan");
  const [journeyListMode, setJourneyListMode] = useState<JourneyListMode>("active");
  const [query, setQuery] = useState("");
  const [journeyProcessFilter, setJourneyProcessFilter] = useState("");
  const [journeyStateFilter, setJourneyStateFilter] = useState("");
  const [wipStageFilter, setWipStageFilter] = useState<WipStage | "">("");
  const [selectedJobId, setSelectedJobId] = useState("");
  const [selectedOperationId, setSelectedOperationId] = useState("");
  const journeyListRef = useRef<HTMLDivElement>(null);
  const [selectedWipId, setSelectedWipId] = useState("");
  const [completionQuantity, setCompletionQuantity] = useState(0);
  const [completionDate, setCompletionDate] = useState("");
  const [stageDraft, setStageDraft] = useState<WipStage>("unclassified");
  const [stageDate, setStageDate] = useState("");
  const [journeyCompletionOpen, setJourneyCompletionOpen] = useState(false);
  const [turningCompletionOpen, setTurningCompletionOpen] = useState(false);
  const [journeyCompletionQuantity, setJourneyCompletionQuantity] = useState(0);
  const [journeyCompletionDate, setJourneyCompletionDate] = useState("");
  const [journeyCompletionResourceId, setJourneyCompletionResourceId] = useState("");
  const [journeyCompletionError, setJourneyCompletionError] = useState("");
  const [journeyNoteEditor, setJourneyNoteEditor] = useState<JourneyNoteEditor | null>(null);
  const [journeyNoteDraft, setJourneyNoteDraft] = useState("");
  const plan = useMemo(() => buildDownstreamProcessPlan(seed, result), [result, seed]);
  const journeyJobs = useMemo(() => [...plan.jobs, ...deliveredChargeJourneyJobs(seed)], [plan.jobs, seed]);
  const journeyStatusByJobId = useMemo(() => new Map(journeyJobs.map((job) => [job.batchId, chargeJourneyStatusForJob(job, seed)])), [journeyJobs, seed]);
  const todaySerial = inputDateToSerial(factoryDateInput());
  const [journeyViewStart, setJourneyViewStart] = useState(todaySerial);
  const [journeyViewDays, setJourneyViewDays] = useState(28);
  const normalizedQuery = query.trim().toLocaleUpperCase("tr-TR");
  const archivedJobCount = journeyJobs.filter((job) => journeyStatusByJobId.get(job.batchId)?.tone === "delivered").length;
  const activeJobCount = journeyJobs.length - archivedJobCount;
  const visibleJobs = journeyJobs
    .filter((job) => journeyListMode === "archive" ? journeyStatusByJobId.get(job.batchId)?.tone === "delivered" : journeyStatusByJobId.get(job.batchId)?.tone !== "delivered")
    .filter((job) => !journeyProcessFilter || journeyCurrentProcess(job, seed) === journeyProcessFilter)
    .filter((job) => !journeyStateFilter || journeyStatusByJobId.get(job.batchId)?.tone === journeyStateFilter)
    .filter((job) => !normalizedQuery || `${job.product} ${job.workOrder} ${job.batchId}`.toLocaleUpperCase("tr-TR").includes(normalizedQuery))
    .sort((left, right) => Number(journeyStatusByJobId.get(left.batchId)?.tone === "delivered") - Number(journeyStatusByJobId.get(right.batchId)?.tone === "delivered") || (left.operations[0]?.start ?? 0) - (right.operations[0]?.start ?? 0) || left.batchId.localeCompare(right.batchId));
  const visibleTypes = new Set(visibleJobs.map((job) => job.product)).size;
  const visibleQuantity = visibleJobs.reduce((sum, job) => sum + journeyVisibleQuantity(job, seed), 0);
  const selectedJob = visibleJobs.find((job) => job.batchId === selectedJobId) ?? visibleJobs[0];
  const selectedOperation = selectedJob?.operations.find((operation) => operation.id === selectedOperationId) ?? (selectedJob ? defaultJourneyOperation(selectedJob, seed) : undefined);
  useRaviScreenContext("processes", { mode, journeyListMode, query, wipStageFilter, journeyProcessFilter, journeyStateFilter, visibleTypes, visibleQuantity,
    selectedJob, selectedOperation, selectedWipId, journeyViewStart, journeyViewDays,
    visibleJobCount: visibleJobs.length, dialogs: { journeyCompletionOpen, turningCompletionOpen, noteEditor: Boolean(journeyNoteEditor) },
    calculationSource: "buildDownstreamProcessPlan / chargeJourneyStatusForJob" });
  const selectedTurningMachine = selectedJob?.source === "current-turning"
    ? seed.machines.find((machine) => machine.id === selectedJob.turningMachineId && machine.currentJob.quantity > 0 && machine.currentJob.product.toUpperCase() === selectedJob.product.toUpperCase())
    : undefined;
  const nextTurningBatch = selectedTurningMachine ? result.batches.filter((batch) => batch.status === "planned" && batch.machineId === selectedTurningMachine.id).sort((a, b) => a.planColumn - b.planColumn)[0] : undefined;
  const selectedJobLot = selectedJob?.wipLotId ? (seed.wipLots ?? []).find((lot) => lot.id === selectedJob.wipLotId) : undefined;
  const selectedJobDelivered = Boolean(selectedJob?.archivedDelivery || selectedJobLot?.stage === "delivered");
  const selectedChargeKey = selectedJob ? journeyChargeKey(selectedJob) : "";
  const selectedJourneyNotes = (seed.chargeJourneyNotes ?? []).filter((note) => note.chargeKey === selectedChargeKey);
  const selectedJourneyLot = selectedOperation?.wipLotId ? (seed.wipLots ?? []).find((lot) => lot.id === selectedOperation.wipLotId) : undefined;
  const selectedJourneyResources = selectedOperation && selectedOperation.process !== "turning"
    ? (() => {
        const product = seed.processMasterData?.products.find((item) => item.product.toUpperCase() === selectedOperation.product.toUpperCase());
        const parameter = product?.processes.find((item) => item.process === selectedOperation.process);
        return (seed.processMasterData?.resources ?? []).filter((resource) => resource.process === selectedOperation.process && parameter?.resourcePriority.includes(resource.id));
      })()
    : [];
  const selectedJourneyRealReadyAt = selectedJourneyLot ? wipOperationReadyAt(selectedJourneyLot) : 0;
  const selectedJourneyOperationCanComplete = Boolean(!selectedJobDelivered && selectedOperation && selectedOperation.process !== "turning" && !selectedOperation.actual && selectedJourneyLot?.nextProcess === selectedOperation.process && selectedJourneyLot.availableQuantity > 0 && selectedJourneyRealReadyAt <= todaySerial + 1);
  const selectedJourneyCompletionHint = selectedOperation && selectedJourneyLot?.nextProcess === selectedOperation.process && selectedJourneyRealReadyAt > todaySerial + 1
    ? `${processLabel(selectedOperation.process)} için yarı mamül ${formatExcelDate(selectedJourneyRealReadyAt)} tarihinde hazır olacak.`
    : selectedOperation ? `${processLabel(selectedOperation.process)} tamamlamak için önceki prosesin tamamlanması ve yarı mamülün hazır olması gerekir.` : "";
  const journeyMilestones = selectedJob ? (() => {
    const turning = selectedJob.operations.find((operation) => operation.process === "turning");
    const drilling = selectedJob.operations.find((operation) => operation.process === "drilling");
    const deburring = selectedJob.operations.find((operation) => operation.process === "deburring");
    const gkm = selectedJob.operations.find((operation) => operation.process === "gkm");
    return [
      turning ? { id: "turning", label: "Torna bitti", date: turning.end, detail: `${turning.resourceId} tamamlanma`, wait: 0 } : null,
      drilling ? { id: "drilling", label: "Delmeye hazır", date: drilling.readyAt, detail: `Başlangıç ${formatExcelDate(drilling.start, { day: "2-digit", month: "short" })}`, wait: drilling.start - drilling.readyAt } : null,
      deburring ? { id: "deburring", label: "Çapak almaya hazır", date: deburring.readyAt, detail: `Başlangıç ${formatExcelDate(deburring.start, { day: "2-digit", month: "short" })}`, wait: deburring.start - deburring.readyAt } : selectedJob.historyIncomplete ? null : { id: "deburring", label: "Çapak alma", date: 0, detail: "Center Pin rotasında yok", wait: 0, skipped: true },
      gkm ? { id: "gkm", label: "GKM'ye hazır", date: gkm.readyAt, detail: `Başlangıç ${formatExcelDate(gkm.start, { day: "2-digit", month: "short" })}`, wait: gkm.start - gkm.readyAt } : null,
      { id: "delivery", label: selectedJobDelivered ? "Sevk edildi" : "Teslimata hazır", date: selectedJob.deliveryReadyAt, detail: selectedJobDelivered ? "Üretim yolculuğu tamamlandı" : "GKM sonrası teslimat listesi", wait: gkm ? selectedJob.deliveryReadyAt - gkm.end : 0 },
    ].filter((milestone): milestone is { id: string; label: string; date: number; detail: string; wait: number; skipped?: boolean } => Boolean(milestone));
  })() : [];
  const journeyRows = selectedJob?.operations.map((operation, index, operations) => {
    const plannedRange = plannedJourneyRange(operation);
    const plannedStart = plannedRange?.start ?? operation.start;
    const plannedEnd = plannedRange?.end ?? operation.end;
    const actualStart = operation.actual || operation.current ? operation.start : 0;
    const actualEnd = operation.actual ? operation.end : operation.current ? Math.max(operation.start, Math.min(todaySerial, operation.end)) : 0;
    const previous = operations[index - 1];
    const previousEnd = previous?.actual ? previous.end : 0;
    const waitingEnd = operation.actual || operation.current
      ? operation.start
      : selectedJob.source === "wip" && previousEnd > 0 && todaySerial > previousEnd
        ? Math.min(todaySerial, operation.start)
        : 0;
    const waitStart = previousEnd > 0 && waitingEnd > previousEnd + 1 / 24 ? previousEnd : 0;
    const delayedUntil = operation.actual ? operation.end : selectedJob.source === "wip" ? todaySerial : 0;
    const delayStart = plannedRange && delayedUntil > plannedEnd + 1 / 24 ? plannedEnd : 0;
    const plannedTooltip = plannedRange ? journeyDateTooltip(`${processLabel(operation.process)} · ${operation.resourceId} · Planlanan`, plannedStart, plannedEnd) : `${processLabel(operation.process)} · Plan kaydı yok`;
    const actualTooltip = journeyDateTooltip(`${processLabel(operation.process)} · ${operation.resourceId} · Gerçekleşen`, actualStart, operation.current ? operation.end : actualEnd, Boolean(operation.current));
    return { plannedTooltip, actualTooltip, operation, hasRecordedPlan: plannedRange !== null, plannedStart, plannedEnd, actualStart, actualEnd, waitStart, waitEnd: waitStart ? waitingEnd : 0, delayStart, delayEnd: delayStart ? delayedUntil : 0 };
  }) ?? [];
  const routeStart = journeyRows.length ? Math.floor(Math.min(...journeyRows.flatMap((row) => [row.plannedStart, row.actualStart || row.plannedStart, row.waitStart || row.plannedStart]))) : todaySerial;
  const routeEnd = selectedJob ? Math.ceil(Math.max(selectedJob.deliveryReadyAt, ...journeyRows.flatMap((row) => [row.plannedEnd, row.actualEnd, row.delayEnd]), selectedJobDelivered ? 0 : todaySerial)) + 1 : routeStart + 7;
  const horizonStart = Math.floor(journeyViewStart);
  const horizonDays = Math.max(7, Math.ceil(journeyViewDays));
  const horizonEnd = horizonStart + horizonDays;
  const journeyIntervalTicks = useMemo(() => Array.from({ length: 5 }, (_, index) => ({
    serial: Math.round(horizonStart + horizonDays * index / 4),
    position: index * 25,
  })), [horizonDays, horizonStart]);
  const wipLots = (seed.wipLots ?? []).filter((lot) => lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped");
  const visibleWipLots = wipLots
    .filter((lot) => !wipStageFilter || lot.stage === wipStageFilter)
    .filter((lot) => !normalizedQuery || `${lot.product} ${lot.workOrder} ${lot.id}`.toLocaleUpperCase("tr-TR").includes(normalizedQuery))
    .sort((left, right) => left.readyAt - right.readyAt || left.createdAt.localeCompare(right.createdAt));
  const selectedWip = visibleWipLots.find((lot) => lot.id === selectedWipId) ?? visibleWipLots[0];
  const selectedWipOperation = selectedWip
    ? plan.operations.find((operation) => operation.wipLotId === selectedWip.id && !operation.actual && operation.process === selectedWip.nextProcess)
    : undefined;
  useEffect(() => {
    if (!focusJobId) return;
    const focusedJob = plan.jobs.find((job) => job.batchId === focusJobId);
    if (!focusedJob) return;
    setMode("plan");
    setQuery("");
    setSelectedJobId(focusedJob.batchId);
    setSelectedOperationId(defaultJourneyOperation(focusedJob, seed)?.id ?? "");
  }, [focusJobId, plan.jobs]);

  useEffect(() => {
    if (!selectedJob) return;
    setJourneyViewStart(routeStart);
    setJourneyViewDays(Math.max(7, routeEnd - routeStart));
  }, [selectedJob?.batchId, routeEnd, routeStart]);

  useEffect(() => {
    if (mode !== "plan" || !selectedJob) return;
    const frame = window.requestAnimationFrame(() => {
      const list = journeyListRef.current;
      const activeJob = list?.querySelector<HTMLButtonElement>("button.active");
      if (!list || !activeJob) return;
      const itemTop = activeJob.getBoundingClientRect().top - list.getBoundingClientRect().top + list.scrollTop;
      list.scrollTop = Math.max(0, itemTop - 4);
    });
    return () => window.cancelAnimationFrame(frame);
  }, [mode, selectedJob?.batchId]);

  useEffect(() => {
    if (!selectedWip) return;
    setSelectedWipId(selectedWip.id);
    setCompletionQuantity(selectedWip.availableQuantity);
    setCompletionDate(serialToInputDate(selectedWipOperation?.end ?? selectedWip.readyAt));
    setStageDraft(selectedWip.stage);
    setStageDate(serialToInputDate(selectedWip.readyAt));
  }, [selectedWip?.id, selectedWip?.availableQuantity, selectedWip?.stage, selectedWipOperation?.id]);

  function openJourneyCompletion() {
    if (!selectedOperation || !selectedJourneyLot) return;
    setJourneyCompletionQuantity(selectedJourneyLot.availableQuantity);
    setJourneyCompletionDate(serialToInputDate(Math.min(todaySerial, Math.max(selectedJourneyRealReadyAt, selectedOperation.end))));
    setJourneyCompletionResourceId(selectedJourneyResources.some((resource) => resource.id === selectedOperation.resourceId) ? selectedOperation.resourceId : selectedJourneyResources[0]?.id ?? "");
    setJourneyCompletionError("");
    setJourneyCompletionOpen(true);
  }

  function fitJourneyRoute() {
    setJourneyViewStart(routeStart);
    setJourneyViewDays(Math.max(7, routeEnd - routeStart));
  }

  function zoomJourney(direction: -1 | 1) {
    const levels = [7, 14, 28, 42, 70, 112];
    const nearest = levels.reduce((best, value, index) => Math.abs(value - journeyViewDays) < Math.abs(levels[best] - journeyViewDays) ? index : best, 0);
    setJourneyViewDays(levels[Math.max(0, Math.min(levels.length - 1, nearest + direction))]);
  }

  function journeyNote(segmentId: string): ChargeJourneyNote | undefined {
    return selectedJourneyNotes.find((note) => note.segmentId === segmentId);
  }

  function openJourneyNote(kind: "wait" | "delay", operation: ProcessOperation, start: number, end: number) {
    const segmentId = `${operation.process}:${kind}`;
    const existing = journeyNote(segmentId);
    setJourneyNoteEditor({
      chargeKey: selectedChargeKey,
      segmentId,
      kind,
      process: operation.process as ProductionProcess,
      start,
      end,
      label: `${processLabel(operation.process)} ${kind === "delay" ? "gecikmesi" : "beklemesi"}`,
    });
    setJourneyNoteDraft(existing?.note ?? "");
  }

  return <section className="process-workspace">
    <div className="process-workspace-head">
      <div>
        <span>TEK ŞARJ · TEK ZAMAN ÇİZGİSİ</span>
        <h2>Şarjın üretim yolculuğu</h2>
        <p>Bir şarj seçin; torna, delme, çapak alma, GKM ve modellenmeyen proses için korunan iş günlük tamponlarını aynı Gantt üzerinde izleyin.</p>
      </div>
      <div className="process-mode-tabs" role="tablist" aria-label="Proses çalışma alanı">
        <button className={mode === "wip" ? "active" : ""} onClick={() => setMode("wip")}>Yarı mamül</button>
        <button className={mode === "plan" ? "active" : ""} onClick={() => setMode("plan")}>Şarj yolculuğu</button>
      </div>
    </div>

    {mode === "wip" ? <>
      <div className="process-summary-line">
        <span><b>{formatNumber(wipLots.length)}</b> açık yarı mamül</span>
        <span><b>{formatNumber(wipLots.reduce((sum, lot) => sum + lot.availableQuantity, 0))}</b> bekleyen adet</span>
        <span><b>{wipLots.filter((lot) => lot.stage === "delivery-ready" && lot.readyAt < todaySerial).length}</b> teslimata hazır şarj</span>
        <span><b>{wipLots.filter((lot) => lot.stage === "on-hold" || lot.stage === "unclassified").length}</b> dikkat isteyen</span>
      </div>
      <div className="process-parameter-toolbar wip-toolbar">
        <div><strong>Operasyonların iş kaynağı</strong><small>Müşteri siparişi değil, sahadaki şarj ve iş emirleri</small></div>
        <label className="wip-stage-filter"><span>Mevcut operasyon</span><select value={wipStageFilter} onChange={(event) => setWipStageFilter(event.target.value as WipStage | "")}><option value="">Tüm konumlar</option>{WIP_STAGE_OPTIONS.map((stage) => <option key={stage.id} value={stage.id}>{stage.label}</option>)}</select></label>
        <label className="process-search"><MagnifyingGlass size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Şarj, iş emri veya ürün ara" /></label>
      </div>
      {wipLots.length ? <div className="wip-layout">
        <div className="wip-table-wrap">
          <table className="wip-table">
            <thead><tr><th>Şarj / iş emri</th><th>Ürün</th><th>Yarı mamül</th><th>Konum</th><th>Hazır olma</th><th>Sıradaki operasyon</th></tr></thead>
            <tbody>{visibleWipLots.map((lot) => {
              const ready = lot.readyAt < todaySerial;
              return <tr key={lot.id} className={`${selectedWip?.id === lot.id ? "selected" : ""} ${lot.rolledForwardFrom ? "carried-over" : ""}`} onClick={() => setSelectedWipId(lot.id)}>
                <td><strong>{lot.workOrder || "İş emri yok"}</strong><small>{lot.id}</small></td>
                <td><b>{lot.product}</b><small>{familyLabel(lot.family)}</small></td>
                <td>{formatNumber(lot.availableQuantity)} adet</td>
                <td><span className={`wip-stage ${lot.stage}`}>{wipStageLabel(lot.stage, ready)}</span></td>
                <td><strong>{formatExcelDate(lot.readyAt)}</strong>{lot.rolledForwardFrom && <small>Geçmişten devretti · önce {formatExcelDate(lot.rolledForwardFrom)}</small>}</td>
                <td>{lot.nextProcess ? <><ProcessIcon process={lot.nextProcess} size={14} /> {processLabel(lot.nextProcess)}</> : "—"}</td>
              </tr>;
            })}</tbody>
          </table>
          {!visibleWipLots.length && <div className="process-empty compact"><strong>Eşleşen yarı mamül yok</strong><p>Şarj, iş emri veya ürün aramasını değiştirin.</p></div>}
        </div>
        <aside className="wip-inspector">
          {selectedWip ? <>
            <div className="process-inspector-title"><span>YARI MAMÜL DETAYI</span><h3>{selectedWip.workOrder || selectedWip.product}</h3><p>{selectedWip.product} · {formatNumber(selectedWip.availableQuantity)} adet</p></div>
            <dl className="process-operation-detail wip-detail">
              <div><dt>Konum</dt><dd>{wipStageLabel(selectedWip.stage, selectedWip.readyAt < todaySerial)}</dd></div>
              <div><dt>Hazır olma</dt><dd>{formatExcelDate(selectedWip.readyAt)}</dd></div>
              {selectedWip.rolledForwardFrom && <div><dt>Devreden iş</dt><dd>Eski hazır tarihi {formatExcelDate(selectedWip.rolledForwardFrom)} · tamamlanmadığı için bugüne taşındı</dd></div>}
              <div><dt>Tamamlanan adım</dt><dd>{selectedWip.completedSteps.map((step) => processLabel(step.process === "washing" ? "gkm" : step.process)).join(" → ")}</dd></div>
            </dl>
            {selectedWipOperation && <form className="wip-action-card" onSubmit={(event) => {
              event.preventDefault();
              const completedDay = inputDateToSerial(completionDate) + 23 / 24;
              onCompleteWipOperation({
                lotId: selectedWip.id,
                process: selectedWipOperation.process as DownstreamProcess,
                resourceId: selectedWipOperation.resourceId,
                resourceName: selectedWipOperation.resourceName,
                quantity: completionQuantity,
                startedAt: Math.max(selectedWipOperation.start, selectedWip.readyAt),
                completedAt: completedDay,
                plannedStart: selectedWipOperation.start,
                plannedEnd: selectedWipOperation.end,
              });
            }}>
              <span>SIRADAKİ OPERASYON</span>
              <strong>{processLabel(selectedWipOperation.process)} · {selectedWipOperation.resourceId}</strong>
              <small>Planlanan {formatExcelDate(selectedWipOperation.start)} – {formatExcelDate(selectedWipOperation.end)}</small>
              <label>Fiili tamamlanan adet<input type="number" min={1} max={selectedWip.availableQuantity} step={1} value={completionQuantity} onChange={(event) => setCompletionQuantity(Number(event.target.value))} /></label>
              <label>Tamamlanma günü<input type="date" min={serialToInputDate(selectedWip.readyAt)} value={completionDate} onChange={(event) => setCompletionDate(event.target.value)} /></label>
              <button type="submit">Operasyonu tamamla</button>
            </form>}
            {!selectedWipOperation && selectedWip.stage !== "delivery-ready" && selectedWip.stage !== "on-hold" && <div className="process-inline-notice danger"><Warning size={16} weight="fill" /><span>Bu şarj için sıradaki operasyon planlanamadı. Konumu ve proses parametrelerini doğrulayın.</span></div>}
            <form className="wip-correction" onSubmit={(event) => { event.preventDefault(); onCorrectWipStage(selectedWip.id, stageDraft, inputDateToSerial(stageDate)); }}>
              <span>SAHA DOĞRULAMASI</span>
              <label>Gerçek konum<select value={stageDraft} onChange={(event) => setStageDraft(event.target.value as WipStage)}>{WIP_STAGE_OPTIONS.map((stage) => <option key={stage.id} value={stage.id}>{stage.label}</option>)}</select></label>
              <label>Geçerlilik günü<input type="date" value={stageDate} onChange={(event) => setStageDate(event.target.value)} /></label>
              {selectedWip.stage === "on-hold" ? <button type="button" onClick={() => onReleaseWip(selectedWip.id, inputDateToSerial(stageDate))}>Blokeyi kaldır</button> : <button type="submit">Konumu doğrula</button>}
            </form>
            <div className="wip-audit"><span>SON HAREKETLER</span>{(seed.wipMovements ?? []).filter((movement) => movement.lotId === selectedWip.id).slice(-4).reverse().map((movement) => <p key={movement.id}><b>{wipStageLabel(movement.toStage)}</b><small>{formatExcelDate(movement.occurredAt)} · {formatNumber(movement.quantity)} adet</small></p>)}</div>
          </> : <div className="process-empty compact"><strong>Yarı mamül seçin</strong></div>}
        </aside>
      </div> : <div className="process-empty"><strong>Henüz açık yarı mamül yok</strong><p>Bir torna işi tamamlandığında kalite beklemesiyle birlikte burada otomatik açılır.</p></div>}
    </> : <>
      <div className="process-summary-line">
        <span><b>{formatNumber(journeyJobs.length)}</b> rotalı şarj</span>
        <span><b>{journeyJobs.filter((job) => job.source === "wip" && journeyStatusByJobId.get(job.batchId)?.tone !== "delivered").length}</b> sahadaki yarı mamül</span>
        <span><b>{plan.jobs.filter((job) => job.source === "current-turning").length}</b> tornada çalışan</span>
        <span><b>{plan.operations.filter((operation) => operation.actual).length}</b> fiili operasyon</span>
        <span><b>{formatNumber(plan.gaps.length)}</b> açıklanan kapasite boşluğu</span>
        <span><b>{plan.deliveryCompletion ? formatExcelDate(plan.deliveryCompletion) : "—"}</b> son teslimata hazır tarih</span>
      </div>
      {dirty && <div className="process-inline-notice"><Warning size={17} weight="fill" /><span>Torna girdileri değişti. Proses rotası, ekrandaki son planlı şarjları gösteriyor; yeni torna planından sonra otomatik güncellenir.</span></div>}
      {plan.warnings.length > 0 && <div className="process-inline-notice danger"><Warning size={17} weight="fill" /><span>{formatNumber(plan.warnings.length)} rota uyarısı var. İlk uyarı: {plan.warnings[0].message}</span></div>}
      {plan.gaps.length > 0 && <details className="process-gap-explanations"><summary><Warning size={15} weight="fill" /><span>{formatNumber(plan.gaps.length)} plan boşluğunun nedenini göster</span></summary><div>{plan.gaps.map((gap) => <p key={gap.id}><strong>{gap.resourceId} · {formatExcelDate(gap.start, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}–{formatExcelDate(gap.end, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</strong><span>{gap.message}</span></p>)}</div></details>}
      {journeyJobs.length ? <div className="journey-layout">
        <aside className="journey-index">
          <div className="journey-index-head"><span>ŞARJ SEÇ</span><strong>{formatNumber(visibleJobs.length)} kayıt</strong></div>
          <div className="journey-list-tabs" role="tablist" aria-label="Şarj yolculuğu kayıtları"><button className={journeyListMode === "active" ? "active" : ""} onClick={() => { setJourneyListMode("active"); setJourneyStateFilter(""); setJourneyProcessFilter(""); }}>Aktif <b>{formatNumber(activeJobCount)}</b></button><button className={journeyListMode === "archive" ? "active" : ""} onClick={() => { setJourneyListMode("archive"); setJourneyStateFilter(""); setJourneyProcessFilter(""); }}><Archive size={13} /> Arşiv <b>{formatNumber(archivedJobCount)}</b></button></div>
          <div className="journey-filters">
            <label>Mevcut proses<select aria-label="Şarj yolculuğu mevcut proses" value={journeyProcessFilter} onChange={(e) => setJourneyProcessFilter(e.target.value)}><option value="">Tüm prosesler</option><option value="turning">Torna</option><option value="drilling">Delme</option><option value="deburring">Çapak Alma</option><option value="gkm">GKM</option><option value="delivery">Paketleme / Teslimat</option><option value="attention">Blokeli / Konumu belirsiz</option></select></label>
            <label>Durum<select aria-label="Şarj yolculuğu durum" value={journeyStateFilter} onChange={(e) => setJourneyStateFilter(e.target.value)}><option value="">Tüm durumlar</option><option value="waiting">Bekliyor</option><option value="running">Üretimde</option><option value="planned">Planlanan</option><option value="finishing">Paketleme & Final Kontrol</option><option value="delivered">Sevk edildi</option><option value="attention">Dikkat gerekiyor</option></select></label>
            <div className="journey-filter-count"><strong>{formatNumber(visibleTypes)} tip · {formatNumber(visibleQuantity)} adet</strong><small>{journeyListMode === "archive" ? "Filtrelenen sevk adedi" : "Filtrelenen kalan adet"}</small></div>
          </div>
          <label className="process-search journey-search"><MagnifyingGlass size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Şarj, iş emri veya ürün ara" /></label>
          <div className="journey-job-list" ref={journeyListRef}>
            {visibleJobs.map((job) => {
              const status = journeyStatusByJobId.get(job.batchId)!;
              return <button key={job.batchId} className={selectedJob?.batchId === job.batchId ? "active" : ""} onClick={() => { setSelectedJobId(job.batchId); setSelectedOperationId(defaultJourneyOperation(job, seed)?.id ?? ""); }}>
                <span><strong>{job.product}</strong><small>{familyLabel(job.family)} · {formatNumber(job.quantity)} adet · İş emri {job.workOrder || "yok"}</small></span>
                <em className={`journey-status-${status.tone}`}>{status.label}</em>
                <small>{formatExcelDate(job.deliveryReadyAt, { day: "2-digit", month: "short" })} {status.tone === "delivered" ? "sevk" : "hazır"}</small>
              </button>;
            })}
            {!visibleJobs.length && <div className="process-empty compact"><strong>Eşleşen şarj yok</strong><p>Aramayı değiştirin.</p></div>}
          </div>
        </aside>
        <section className="journey-canvas">
          {selectedJob ? <>
            <div className="journey-heading">
              <div><span>{journeySourceHeading(selectedJob.source, selectedJobDelivered)}</span><h3>{selectedJob.product}</h3><p><b className={`process-family ${selectedJob.family}`}>{familyLabel(selectedJob.family)}</b> · {formatNumber(selectedJob.quantity)} adet · İş emri {selectedJob.workOrder || "yok"}</p></div>
              <div className="journey-heading-actions">
                {selectedTurningMachine && <button className="journey-complete-action" onClick={() => setTurningCompletionOpen(true)}><ProcessIcon process="turning" /> Torna prosesini bitir</button>}
                {selectedJourneyOperationCanComplete && selectedOperation && <button className="journey-complete-action" onClick={openJourneyCompletion}><ProcessIcon process={selectedOperation.process} /> {processLabel(selectedOperation.process)} prosesini bitir</button>}
                {!selectedJourneyOperationCanComplete && selectedOperation && !selectedOperation.actual && selectedOperation.process !== "turning" && <small className="journey-complete-hint">{selectedJourneyCompletionHint}</small>}
                <div className="journey-ready"><span>{selectedJobDelivered ? "SEVK EDİLDİ" : "TESLİMATA HAZIR"}</span><strong>{formatExcelDate(selectedJob.deliveryReadyAt, { day: "2-digit", month: "long" })}</strong><small>{selectedJobDelivered ? "Üretim yolculuğu tamamlandı" : "Paketleme & Final Kontrol · 1 iş günü dahil"}</small></div>
              </div>
            </div>
            {selectedJob.historyIncomplete && <p className="journey-history-notice">Bu eski kayıtta yalnızca kaydedilmiş proses tarihleri gösterilir. Eksik proses geçmişi sonradan hesaplanmaz.</p>}
            <div className="journey-readiness-strip" aria-label="Şarj proses hazırlık tarihleri">{journeyMilestones.map((milestone) => <div key={milestone.id} title={journeyRows.filter((row) => row.operation.process === milestone.id).map((row) => [row.plannedTooltip, row.actualStart > 0 ? row.actualTooltip : ""].filter(Boolean).join("\n\n")).join("\n\n") || milestone.detail} className={`journey-readiness-step ${milestone.id} ${milestone.skipped ? "skipped" : ""}`}><span>{milestone.id === "delivery" ? "+1" : <ProcessIcon process={milestone.id} size={13} />}</span><div><small>{milestone.label}</small><strong>{milestone.skipped ? "Atlanır" : formatExcelDate(milestone.date, { day: "2-digit", month: "long" })}</strong><em>{milestone.detail}</em>{!milestone.skipped && milestone.id !== "turning" && <b className={milestone.wait > 0 ? "waiting" : "ready"}>{waitLabel(milestone.wait)}</b>}</div></div>)}</div>
            <div className="journey-color-legend"><span className="turning">Torna</span><span className="drilling">Delme</span><span className="deburring">Çapak Alma</span><span className="gkm">GKM</span><span className="waiting">Bekleme</span><span className="actual">Gerçekleşen</span></div>
            <div className="journey-gantt-controls" aria-label="Şarj yolculuğu tarih kontrolleri">
              <button onClick={() => setJourneyViewStart((current) => current - Math.max(1, Math.floor(horizonDays / 2)))} aria-label="Önceki tarihlere git"><CaretLeft size={14} /></button>
              <label><CalendarBlank size={14} /><input type="date" value={serialToInputDate(horizonStart)} onChange={(event) => setJourneyViewStart(inputDateToSerial(event.target.value))} aria-label="Şarj yolculuğu başlangıç tarihi" /></label>
              <button onClick={() => setJourneyViewStart((current) => current + Math.max(1, Math.floor(horizonDays / 2)))} aria-label="Sonraki tarihlere git"><CaretRight size={14} /></button>
              <button className="journey-text-control" onClick={() => setJourneyViewStart(todaySerial)}>Bugün</button>
              <button className="journey-text-control" onClick={fitJourneyRoute}><CornersOut size={14} /> Rotayı sığdır</button>
              <span className="journey-zoom-control"><button disabled={horizonDays >= 112} onClick={() => zoomJourney(1)} aria-label="Şarj yolculuğunu uzaklaştır"><Minus size={13} /></button><small>{horizonDays} gün</small><button disabled={horizonDays <= 7} onClick={() => zoomJourney(-1)} aria-label="Şarj yolculuğunu yakınlaştır"><Plus size={13} /></button></span>
            </div>
            <div className="journey-gantt journey-comparison-gantt fit-view interval-view" style={{ "--journey-days": horizonDays, "--journey-interval-count": 4 } as React.CSSProperties} aria-label={`${selectedJob.workOrder || selectedJob.product} planlanan ve gerçekleşen şarj yolculuğu`}>
              <div className="journey-axis"><span>PROSES / KAYNAK</span><div className="journey-interval-scale" aria-label={`${formatExcelDate(horizonStart)} ile ${formatExcelDate(horizonEnd)} arasındaki zaman aralıkları`}>{journeyIntervalTicks.map((tick, index) => <small key={`${tick.serial}-${index}`} className={index === 0 ? "first" : index === journeyIntervalTicks.length - 1 ? "last" : ""} style={{ left: `${tick.position}%` }}>{formatExcelDate(tick.serial, { day: "2-digit", month: "short" })}</small>)}</div></div>
              <div className="journey-gantt-row journey-all-flow-row">
                <div className="journey-row-label journey-all-flow-label"><i>Σ</i><span><strong>Tüm akış</strong><small>Tüm prosesler + teslimat</small></span><span className="journey-side-lanes"><em>PLANLANAN</em><em>GERÇEKLEŞEN</em></span></div>
                <div className="journey-track journey-all-flow-track journey-two-lane-track">
                  {todaySerial >= horizonStart && todaySerial < horizonEnd && <i className="journey-today-line" style={{ left: `${ganttPercent(todaySerial, horizonStart, horizonDays)}%` }} />}
                  {journeyRows.filter((row) => row.hasRecordedPlan).map((row) => <button key={`flow-plan-${row.operation.id}`} title={row.plannedTooltip} className={`journey-bar journey-flow-bar planned ${row.operation.process}`} style={rangePosition(row.plannedStart, row.plannedEnd, horizonStart, horizonDays)} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{processLabel(row.operation.process)}</strong><small>{row.operation.resourceId}</small></button>)}
                  {journeyRows.filter((row) => row.waitStart > 0).map((row) => <button key={`flow-wait-${row.operation.id}`} className="journey-wait-segment journey-flow-wait" style={rangePosition(row.waitStart, row.waitEnd, horizonStart, horizonDays)} title={`Bekleme · ${waitLabel(row.waitEnd - row.waitStart)}`} onClick={() => openJourneyNote("wait", row.operation, row.waitStart, row.waitEnd)}><strong>Bekleme</strong></button>)}
                  {journeyRows.filter((row) => row.actualStart && row.actualEnd >= row.actualStart).map((row) => <button key={`flow-actual-${row.operation.id}`} title={row.actualTooltip} className={`journey-bar journey-flow-bar actual ${row.operation.process}`} style={rangePosition(row.actualStart, Math.max(row.actualStart + 1 / 24, row.actualEnd), horizonStart, horizonDays)} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{processLabel(row.operation.process)}</strong><small>{row.operation.resourceId}</small></button>)}
                </div>
              </div>
              {journeyRows.map((row, index) => <div className="journey-gantt-row journey-comparison-row" key={row.operation.id}>
                <button title={[row.plannedTooltip, row.actualStart > 0 ? row.actualTooltip : ""].filter(Boolean).join("\n\n")} className={selectedOperation?.id === row.operation.id ? "active" : ""} onClick={() => setSelectedOperationId(row.operation.id)}><ProcessIcon process={row.operation.process} className={`journey-process-icon ${row.operation.process}`} /><span><strong>{index + 1}. {processLabel(row.operation.process)}</strong><small>{row.operation.resourceId} · {row.operation.resourceName}</small></span><span className="journey-side-lanes"><em>PLANLANAN</em><em>GERÇEKLEŞEN</em></span></button>
                <div className="journey-track journey-two-lane-track">
                  {todaySerial >= horizonStart && todaySerial < horizonEnd && <i className="journey-today-line" style={{ left: `${ganttPercent(todaySerial, horizonStart, horizonDays)}%` }} />}
                  {!row.hasRecordedPlan && <span className="journey-missing-plan">Plan kaydı yok</span>}
                  {row.hasRecordedPlan && <button title={row.plannedTooltip} className={`journey-bar planned ${row.operation.process} ${selectedOperation?.id === row.operation.id ? "selected" : ""}`} style={rangePosition(row.plannedStart, Math.max(row.plannedStart + 1 / 24, row.plannedEnd), horizonStart, horizonDays)} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{processLabel(row.operation.process)}</strong><small>{formatExcelDate(row.plannedStart, { day: "2-digit", month: "short" })} – {formatExcelDate(row.plannedEnd, { day: "2-digit", month: "short" })}</small></button>}
                  {row.waitStart > 0 && <button className={`journey-wait-segment ${journeyNote(`${row.operation.process}:wait`) ? "has-note" : ""}`} style={rangePosition(row.waitStart, row.waitEnd, horizonStart, horizonDays)} onClick={() => openJourneyNote("wait", row.operation, row.waitStart, row.waitEnd)} title={journeyNote(`${row.operation.process}:wait`)?.note || "Bekleme açıklaması ekle"}><strong>Bekleme</strong><small>{waitLabel(row.waitEnd - row.waitStart)}</small>{journeyNote(`${row.operation.process}:wait`) && <NotePencil size={12} weight="fill" />}</button>}
                  {row.actualStart > 0 && <button title={row.actualTooltip} className={`journey-bar actual ${row.operation.process} ${selectedOperation?.id === row.operation.id ? "selected" : ""}`} style={rangePosition(row.actualStart, Math.max(row.actualStart + 1 / 24, row.actualEnd), horizonStart, horizonDays)} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{processLabel(row.operation.process)}</strong><small>{formatExcelDate(row.actualStart, { day: "2-digit", month: "short" })} – {row.operation.current ? "devam ediyor" : formatExcelDate(row.actualEnd, { day: "2-digit", month: "short" })}</small></button>}
                  {row.delayStart > 0 && <button className={`journey-delay-segment ${journeyNote(`${row.operation.process}:delay`) ? "has-note" : ""}`} style={rangePosition(row.delayStart, row.delayEnd, horizonStart, horizonDays)} onClick={() => openJourneyNote("delay", row.operation, row.delayStart, row.delayEnd)} title={journeyNote(`${row.operation.process}:delay`)?.note || "Gecikme açıklaması ekle"}><strong>{delayLabel(row.delayEnd - row.delayStart)}</strong>{journeyNote(`${row.operation.process}:delay`) && <NotePencil size={12} weight="fill" />}</button>}
                </div>
              </div>)}
              <div className="journey-gantt-row journey-comparison-row buffer-row">
                <div className="journey-row-label"><i>{selectedJobDelivered ? "✓" : "+1"}</i><span><strong>{selectedJobDelivered ? "Paketleme & sevkiyat" : "Paketleme & Final Kontrol"}</strong><small>{selectedJobDelivered ? "Arşivde saklanan son aşama" : "1 iş günü"}</small></span><span className="journey-side-lanes"><em>PLANLANAN</em><em>GERÇEKLEŞEN</em></span></div>
                <div className="journey-track journey-two-lane-track">{todaySerial >= horizonStart && todaySerial < horizonEnd && <i className="journey-today-line" style={{ left: `${ganttPercent(todaySerial, horizonStart, horizonDays)}%` }} />}{!selectedJobDelivered && <div title={journeyDateTooltip("Paketleme & Final Kontrol · Planlanan", selectedJob.completion, selectedJob.deliveryReadyAt)} className="journey-buffer-bar planned" style={rangePosition(selectedJob.completion, selectedJob.deliveryReadyAt, horizonStart, horizonDays)}><strong>Teslimat</strong><small>{formatExcelDate(selectedJob.deliveryReadyAt, { day: "2-digit", month: "short" })}</small></div>}{selectedJobDelivered && <div title={journeyDateTooltip("Paketleme ve sevkiyat · Gerçekleşen", selectedJob.completion, selectedJob.deliveryReadyAt)} className="journey-buffer-bar actual" style={rangePosition(selectedJob.completion, Math.max(selectedJob.completion + 1 / 24, selectedJob.deliveryReadyAt), horizonStart, horizonDays)}><strong>Sevk edildi</strong><small>{formatExcelDate(selectedJob.deliveryReadyAt, { day: "2-digit", month: "short" })}</small></div>}</div>
              </div>
            </div>
            {selectedOperation && <div className="journey-detail-panel">
              <div><span>SEÇİLİ ADIM</span><strong><ProcessIcon process={selectedOperation.process} /> {processLabel(selectedOperation.process)} · {selectedOperation.resourceId}</strong><small>{selectedOperation.resourceName}</small></div>
              <dl className="process-operation-detail">
                <div><dt>Durum</dt><dd>{selectedOperation.actual ? "Fiili tamamlandı" : selectedOperation.current || (selectedOperation.process === "turning" && selectedTurningMachine) ? "Üretimde" : "Planlandı"}</dd></div>
                <div><dt>Planlanan başlangıç</dt><dd>{plannedJourneyRange(selectedOperation) ? formatExcelDate(plannedJourneyRange(selectedOperation)!.start) : "Plan kaydı yok"}</dd></div>
                <div><dt>Planlanan bitiş</dt><dd>{plannedJourneyRange(selectedOperation) ? formatExcelDate(plannedJourneyRange(selectedOperation)!.end) : "Plan kaydı yok"}</dd></div>
                <div><dt>Başlangıç</dt><dd>{formatExcelDate(selectedOperation.start, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</dd></div>
                <div><dt>Bitiş</dt><dd>{formatExcelDate(selectedOperation.end, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</dd></div>
                <div><dt>Vardiya kapasitesi</dt><dd>{selectedOperation.actual ? "Fiili kayıt" : selectedOperation.unitsPerShift > 0 ? `${formatNumber(selectedOperation.unitsPerShift)} adet` : "Torna planından"}</dd></div>
                <div><dt>Setup</dt><dd>{formatHours(selectedOperation.setupHours)}</dd></div>
                {selectedOperation.protectedSetupHoursAfter ? <div><dt>D-02 dönüş rezervi</dt><dd>{formatHours(selectedOperation.protectedSetupHoursAfter)}</dd></div> : null}
                <div><dt>Üretim yükü</dt><dd>{formatHours(selectedOperation.runHours)}</dd></div>
                <div><dt>Ön bekleme</dt><dd>{selectedOperation.waitWorkdaysBefore ? `${selectedOperation.waitWorkdaysBefore} iş günü` : "Bekleme yok"}</dd></div>
                {selectedOperation.transferBatchQuantity ? <div><dt>Akış partisi</dt><dd>{formatNumber(selectedOperation.transferBatchQuantity)} adet yarı mamül</dd></div> : null}
              </dl>
            </div>}
          </> : <div className="process-empty"><strong>Bir şarj seçin</strong><p>Aramadaki bir kaydı açarak üretim yolculuğunu görün.</p></div>}
        </section>
      </div> : <div className="process-empty"><strong>Henüz rotalı şarj yok</strong><p>Torna planı çalıştırıldığında şarj yolculukları burada oluşur.</p></div>}
    </>}
    {turningCompletionOpen && selectedTurningMachine && <CompleteJobDialog key={selectedJob?.batchId} machine={selectedTurningMachine} nextBatch={nextTurningBatch} onClose={() => setTurningCompletionOpen(false)} onConfirm={(completedAt, quantity) => { onCompleteCurrentJob(selectedTurningMachine.id, completedAt, quantity); setTurningCompletionOpen(false); }} />}
    {journeyNoteEditor && <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog journey-note-dialog" role="dialog" aria-modal="true" aria-label={`${journeyNoteEditor.label} açıklaması`}><button className="delete-button journey-completion-close" onClick={() => setJourneyNoteEditor(null)} aria-label="Açıklama penceresini kapat"><X size={15} /></button><NotePencil size={25} weight="fill" /><span>{journeyNoteEditor.kind === "delay" ? "GECİKME AÇIKLAMASI" : "BEKLEME AÇIKLAMASI"}</span><h2>{journeyNoteEditor.label}</h2><p><b>{selectedJob?.workOrder || selectedJob?.product}</b> · {formatExcelDate(journeyNoteEditor.start, { day: "2-digit", month: "short" })} – {formatExcelDate(journeyNoteEditor.end, { day: "2-digit", month: "short" })}</p><label className="field"><span>Nedenini yazın</span><textarea autoFocus value={journeyNoteDraft} onChange={(event) => setJourneyNoteDraft(event.target.value)} placeholder={journeyNoteEditor.kind === "delay" ? "Örn. Tezgâh arızası nedeniyle 1 gün gecikti" : "Örn. Kalite onayı beklendi"} /></label><small className="journey-note-help">Bu açıklama şarjın arşiv kaydında da korunur. Boş kaydederseniz mevcut açıklama kaldırılır.</small><div className="drawer-actions"><button className="secondary" onClick={() => setJourneyNoteEditor(null)}>Vazgeç</button><button className="primary" onClick={() => { const { label: _label, ...input } = journeyNoteEditor; onSaveJourneyNote({ ...input, note: journeyNoteDraft }); setJourneyNoteEditor(null); }}><NotePencil size={15} /> Açıklamayı kaydet</button></div></section></div>}
    {journeyCompletionOpen && selectedOperation && selectedJourneyLot && <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label={`${selectedOperation.workOrder || selectedOperation.product} prosesini bitir`}><button className="delete-button journey-completion-close" onClick={() => setJourneyCompletionOpen(false)} aria-label="İş bitir penceresini kapat"><X size={15} /></button><ProcessIcon process={selectedOperation.process} size={25} /><span>{processLabel(selectedOperation.process).toLocaleUpperCase("tr-TR")} TAMAMLAMA</span><h2>{selectedOperation.workOrder || selectedOperation.product}</h2><p>{selectedOperation.product} şarjının bu adımı seçtiğiniz gerçek tarih ve iş merkezinde tamamlanacak, ardından sıradaki prosese geçirilecek.</p><label className="field"><span>Fiili tamamlanan adet</span><input type="number" min={1} max={selectedJourneyLot.availableQuantity} step={1} value={journeyCompletionQuantity || ""} onChange={(event) => setJourneyCompletionQuantity(Number(event.target.value))} /></label><label className="field"><span>Fiili iş merkezi</span><select value={journeyCompletionResourceId} onChange={(event) => setJourneyCompletionResourceId(event.target.value)}>{selectedJourneyResources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select><small>Planlanan tezgahtan farklıysa sahada kullanılan iş merkezini seçin.</small></label><label className="field"><span>Gerçek tamamlanma tarihi</span><input type="date" min={serialToInputDate(selectedJourneyRealReadyAt)} max={factoryDateInput()} value={journeyCompletionDate} onChange={(event) => setJourneyCompletionDate(event.target.value)} /><small>Geçmiş bir tarih seçebilirsiniz. Tarih, önceki prosesin gerçek bitişinden önce olamaz.</small></label>{journeyCompletionError && <p className="form-error">{journeyCompletionError}</p>}<div className="drawer-actions"><button className="secondary" onClick={() => setJourneyCompletionOpen(false)}>Vazgeç</button><button className="primary" onClick={() => { try { if (!journeyCompletionDate) throw new Error("Tamamlanma tarihi zorunludur."); const actualResource = selectedJourneyResources.find((resource) => resource.id === journeyCompletionResourceId); if (!actualResource) throw new Error("Fiili iş merkezi seçilmelidir."); if (!Number.isInteger(journeyCompletionQuantity) || journeyCompletionQuantity <= 0 || journeyCompletionQuantity > selectedJourneyLot.availableQuantity) throw new Error("Fiili adet açık yarı mamül miktarını aşmayan pozitif tam sayı olmalıdır."); const completedAt = inputDateToSerial(journeyCompletionDate) + 23 / 24; const startedAt = Math.max(selectedJourneyRealReadyAt, Math.min(selectedOperation.start, completedAt)); const completed = onCompleteWipOperation({ lotId: selectedJourneyLot.id, process: selectedOperation.process as DownstreamProcess, resourceId: actualResource.id, resourceName: actualResource.name, quantity: journeyCompletionQuantity, startedAt, completedAt, plannedStart: selectedOperation.start, plannedEnd: selectedOperation.end }); if (completed === false) throw new Error("İş tamamlanamadı; ekrandaki uyarıyı kontrol edin."); setJourneyCompletionOpen(false); } catch (reason) { setJourneyCompletionError(reason instanceof Error ? reason.message : "Proses tamamlanamadı."); } }}><ProcessIcon process={selectedOperation.process} size={15} /> {processLabel(selectedOperation.process)} prosesini bitir</button></div></section></div>}
  </section>;
}

