"use client";

import { useEffect, useMemo, useState } from "react";
import { ArrowLeft, ArrowRight, Check, Info, X } from "@phosphor-icons/react";

export type AppView = "planning" | "processes" | "control" | "orders" | "machines" | "parameters" | "settings" | "scenarios" | "feedback";

export const PAGE_GUIDES: Record<AppView, { summary: string; title: string; features: string[] }> = {
  planning: { title: "Tezgah planını okuyun ve düzenleyin", summary: "C-01–C-17 üzerindeki planlı şarjları zaman çizelgesinde yönetin.", features: ["Bugünden başlayın; tarihi değiştirin, yakınlaştırın veya tüm planı sığdırın", "Şarjları sürükleyerek tezgah veya kuyruk sırasını değiştirin", "Tatil veya Pazar bandına tıklayıp 0–3 vardiya üretim açın"] },
  processes: { title: "Bir şarjın bütün üretim yolculuğunu izleyin", summary: "Seçili şarjın torna, delme, çapak alma, GKM ve 1 fabrika iş günlük teslim tamponunu tek zaman çizgisinde görün.", features: ["İş emri, şarj veya ürünle arayıp tek bir yolculuğa odaklanın", "Fiili ve planlanan operasyonları aynı Gantt üzerinde ayırt edin", "Yarı mamül hareketlerini ve proses ana verilerini ikincil sekmelerde yönetin"] },
  control: { title: "Tüm tezgah kuyruklarını tek ekranda görün", summary: "Excel Dashboard ve Dashboard 2 düzenindeki üretim bilgisini canlı plan özetiyle birlikte izleyin.", features: ["Üretimdeki işi ve sıradaki şarjları tezgah bazında tarayın", "Tezgah veya ürün arayın; aktif ve planı olan tezgahları filtreleyin", "Plan kontrolünü açarak ilgili sipariş veya tezgaha doğrudan gidin"] },
  orders: { title: "Siparişleri girin ve müşteri değişikliklerini yönetin", summary: "A2 ve Cpin tipleri için sipariş adedi ile termini doğrudan girin; sonucu planla karşılaştırın.", features: ["Excel sırasından satır satır sipariş ekleyin", "Hazır listeyi veya aynı kolon yapısındaki kendi .xlsx dosyanızı doğrulayarak yükleyin", "Aktif siparişin parçalı teslimat ve müşteri revizyonu detayını yönetin"] },
  machines: { title: "Tezgah kapasitesini ve kuyruğunu yönetin", summary: "Her tezgahın aktiflik, mevcut üretim, tarih, vardiya ve plan sırasını inceleyin.", features: ["Tezgah adlarını yönetin veya güvenli varsayılanlarla yeni tezgah ekleyin", "Mevcut işi seçerken eksik ürün × tezgah hızını tamamlayın", "Kuyruk, günlük vardiya ve planlı bakım işlemlerini yönetin"] },
  parameters: { title: "Ürün planlama parametrelerini doğrulayın", summary: "Şarj büyüklüğü, çap, sıralı tezgah öncelikleri ve tezgaha özel üretim hızlarını yönetin.", features: ["İlk seçilen tezgahı ana tezgah olarak belirleyin", "Her tezgahın günlük üretimini varsayılandan başlatıp gerektiğinde değiştirin", "Kaydedilmiş parametreleri sayfa yenilense de koruyun"] },
  settings: { title: "Üretim takvimini ve setup sürelerini yönetin", summary: "Tatil, bakım, vardiya, tip ve çap değişim sürelerini gerçek plan kapasitesine dahil edin.", features: ["Resmi tatilde üretimi 0–3 vardiya olarak belirleyin", "Tezgaha tarih aralıklı bakım veya vardiya istisnası ekleyin", "Aynı üründe 0, tip değişiminde 1 ve çap değişiminde 3 saatlik setup kuralını yönetin"] },
  scenarios: { title: "Alternatif planları karşılaştırın", summary: "İki kayıtlı senaryonun miktar, bitiş, setup ve tezgah etkisini yan yana değerlendirin.", features: ["İki senaryoyu seçip temel sonuçları kıyaslayın", "Toplam setup saatini ve kullanılan tezgah sayısını görün", "Değişen sipariş atamalarını inceleyin"] },
  feedback: { title: "Ürün hakkında geri bildirim paylaşın", summary: "Açık işler ve çözülen iyileştirmeleri tek bir çalışma alanında yönetin.", features: ["Açık ve çözülen kayıtları yan yana tarayın", "Duruma göre filtreleyin, notlarda arayın ve sıralayın", "Görsel, ekran görüntüsü veya sesli not ekleyin"] },
};

export function PageGuidePanel({ view, onClose }: { view: AppView; onClose: () => void }) {
  const guide = PAGE_GUIDES[view];
  return <section className="page-guide-panel"><div><Info size={18} weight="fill" /><span><strong>{guide.title}</strong><small>{guide.summary}</small></span></div><ul>{guide.features.map((feature) => <li key={feature}>{feature}</li>)}</ul><button onClick={onClose} aria-label="Sayfa rehberini kapat"><X size={16} /></button></section>;
}

const TOUR_STEPS: Array<{ view: AppView; eyebrow: string; title: string; body: string }> = [
  { view: "planning", eyebrow: "HOŞ GELDİNİZ", title: "Selsa Planlama", body: "Excel V51 planlama yaklaşımının web uygulamasına dönüşen ilk sürümü. Bu kısa tur ana çalışma alanlarını gösterir." },
  { view: "orders", eyebrow: "1 · SİPARİŞLER", title: "Ağustos siparişlerini hızlıca girin", body: "A2 ve Cpin tipleri için sipariş adedi ile termini satırdan kaydedin; hazır listeyi veya aynı formattaki kendi Excel’inizi yükleyin." },
  { view: "planning", eyebrow: "2 · PLANLAMA", title: "Tezgah zaman çizelgesini okuyun", body: "Şarjları taşıyın; tatil veya Pazar bandına tıklayarak seçili tezgah ya da tüm aktif tezgahlar için vardiya açın." },
  { view: "machines", eyebrow: "3 · TEZGAHLAR", title: "Kapasiteyi ve kuyrukları yönetin", body: "C-01–C-17 için aktiflik, tarih, vardiya sayısı ve plan kuyruğunu yönetin; kontrollü manuel şarj ekleyin." },
  { view: "settings", eyebrow: "4 · ÜRETİM TAKVİMİ", title: "Takvimi ve setup sürelerini yönetin", body: "Pazar, tatil, vardiya ve bakım istisnalarının yanında ürün değişim sürelerini de planın gerçek bitiş hesabına dahil edin." },
  { view: "control", eyebrow: "5 · GENEL BAKIŞ", title: "Fabrikanın planını tek ekranda tarayın", body: "Excel dashboard’larındaki gibi her tezgahın üretimdeki işini ve plan kuyruğunu görün; gerekirse alttaki plan kontrolünden ilgili kayda gidin." },
  { view: "scenarios", eyebrow: "6 · SENARYOLAR", title: "Alternatifleri yan yana değerlendirin", body: "Kaydettiğiniz iki planı talep karşılama, bitiş tarihi, toplam setup saati, tezgah kullanımı ve değişen atamalar açısından karşılaştırın." },
  { view: "feedback", eyebrow: "7 · GERİ BİLDİRİM", title: "Geliştirme sürecine doğrudan katılın", body: "Hata, özellik talebi veya fikir paylaşın. Ekran görüntüsünü metin alanına yapıştırabilir, görsel ya da sesli not ekleyebilirsiniz." },
];

export function ProductTour({ open, onClose, onNavigate, canManageSettings = true }: { open: boolean; onClose: () => void; onNavigate: (view: AppView) => void; canManageSettings?: boolean }) {
  const [index, setIndex] = useState(0);
  const steps = useMemo(() => canManageSettings ? TOUR_STEPS : TOUR_STEPS.filter((step) => step.view !== "settings"), [canManageSettings]);
  useEffect(() => { if (open) setIndex(0); }, [open]);
  useEffect(() => { if (index >= steps.length) setIndex(Math.max(steps.length - 1, 0)); }, [index, steps.length]);
  useEffect(() => { if (open && steps[index]) onNavigate(steps[index].view); }, [index, onNavigate, open, steps]);
  if (!open) return null;
  const step = steps[index];
  const finish = () => { window.localStorage.setItem("selsa-planlama-tour-seen", "1"); onClose(); };
  return <div className="tour-overlay" role="presentation"><section className="tour-card" role="dialog" aria-modal="false" aria-label="Selsa Planlama ürün turu"><div className="tour-progress">{steps.map((_, stepIndex) => <i key={stepIndex} className={stepIndex <= index ? "active" : ""} />)}</div><span>{step.eyebrow}</span><h2>{step.title}</h2><p>{step.body}</p><div className="tour-actions"><button className="tour-skip" onClick={finish}>Turu geç</button>{index > 0 && <button className="tour-back" onClick={() => setIndex((current) => current - 1)}><ArrowLeft size={15} /> Geri</button>}<button className="tour-next" onClick={() => index === steps.length - 1 ? finish() : setIndex((current) => current + 1)}>{index === steps.length - 1 ? <><Check size={15} /> Bitir</> : <>Sonraki <ArrowRight size={15} /></>}</button></div></section></div>;
}

frontend/components/ProductionProcessWor.source:
"use client";

import { ProcessIcon } from "@/components/ProcessIcon";

import type { PlanningSeed } from "@/lib/planning";
import type { ProcessKind } from "@/lib/process-master-data";
import {
  PRODUCTION_PROCESS_TABS,
  productionProcessResourceCount,
  productionResourceOptions,
} from "@/lib/production-process-workspace";

export function ProductionProcessTabs({ seed, value, onChange }: {
  seed: PlanningSeed;
  value: ProcessKind;
  onChange: (process: ProcessKind) => void;
}) {
  return <div className="production-process-tabs" role="tablist" aria-label="Üretim prosesi">
    {PRODUCTION_PROCESS_TABS.map((process) => <button
      key={process.id}
      type="button"
      role="tab"
      aria-selected={value === process.id}
      className={value === process.id ? "active" : ""}
      onClick={() => onChange(process.id)}
    >
      <strong><ProcessIcon process={process.id} /> {process.label}</strong>
      <small>{productionProcessResourceCount(seed, process.id)} tezgah</small>
    </button>)}
  </div>;
}

export function ProductionResourceStrip({ seed, process, selectedId, onSelect, plannedBatchCounts }: {
  seed: PlanningSeed;
  process: ProcessKind;
  selectedId: string;
  onSelect: (resourceId: string) => void;
  plannedBatchCounts?: Readonly<Record<string, number>>;
}) {
  const resources = productionResourceOptions(seed, process, plannedBatchCounts);

  return <div className="production-resource-strip" role="tablist" aria-label={`${PRODUCTION_PROCESS_TABS.find((item) => item.id === process)?.label} tezgahları`}>
    {resources.map((resource) => <button
      key={resource.id}
      type="button"
      role="tab"
      aria-selected={resource.id === selectedId}
      className={resource.id === selectedId ? "selected" : ""}
      onClick={() => onSelect(resource.id)}
    >
      <span className={`status ${resource.active ? "on" : "off"}`} />
      <span className="production-resource-identity">
        <strong>{resource.id}</strong>
        <small>{resource.name}</small>
      </span>
      <em>{resource.meta}</em>
    </button>)}
    {!resources.length && <div className="production-resource-empty">Bu proses için tanımlı tezgah yok.</div>}
  </div>;
}

