const dismissedAdviceKey = "selsa-planlama-dismissed-advice-v1";

type OperationalSnapshot = { seed: PlanningSeed; result: ScenarioResult; selectedBatchId: string; message: string; dirty: boolean };

type PlanningSyncStatus = "loading" | "saving" | "synced" | "offline" | "conflict";

type PlanningWriteMode = "planning" | "operational";

export function PlanningApplication() {
  const apiFetch = useApiFetch();
  const currentUser = useCurrentUser();
  const isAdmin = currentUser.role === "admin";
  const [seed, setSeed] = useState<PlanningSeed>(() => cloneSeed(originalSeed));
  const [result, setResult] = useState<ScenarioResult>(() => runOptimizedScenario(cloneSeed(originalSeed)));
  const [selectedBatchId, setSelectedBatchId] = useState<string>("scenario-1");
  const [focusedJourneyJobId, setFocusedJourneyJobId] = useState("");
  const [selectedMachineId, setSelectedMachineId] = useState("C-01");
  const [dirty, setDirty] = useState(false);
  const strategy: ScenarioStrategy = "optimized";
  const [notice, setNotice] = useState("Setup dahil optimize plan yüklendi");
  const { view, setView, changeView, entryPoint } = usePlanningNavigation(isAdmin, setNotice);
  const {
    scenarios, scenarioSummaries, scenarioListTotal, scenarioListLoading, scenarioListError,
    fetchScenarioPage, fetchScenarioDetail, addStoredScenario, replaceScenarioLibrary,
    deleteStoredScenario, updateStoredScenario, importStoredScenarios,
  } = useScenarioLibrary(apiFetch, setNotice);
  const [planningHistory, setPlanningHistory] = useState<PlanningStateRevision[]>([]);
  const [revisions, setRevisions] = useState<OrderRevision[]>([]);
  const [focusedOrderId, setFocusedOrderId] = useState<string | null>(null);
  const [pageGuideOpen, setPageGuideOpen] = useState(false);
  const [tourOpen, setTourOpen] = useState(false);
  const [historyPast, setHistoryPast] = useState<OperationalSnapshot[]>([]);
  const [historyFuture, setHistoryFuture] = useState<OperationalSnapshot[]>([]);
  const [historyMessage, setHistoryMessage] = useState("");
  const planningStateWriteRef = useRef<Promise<void>>(Promise.resolve());
  const remotePlanningStateUpdatedAtRef = useRef("");
  const [planningSyncStatus, setPlanningSyncStatus] = useState<PlanningSyncStatus>("loading");
  const [lastPlanningSyncAt, setLastPlanningSyncAt] = useState("");
  const [planningSyncConflict, setPlanningSyncConflict] = useState<PlanningStateRecord | null>(null);
  const [productionSyncInfo, setProductionSyncInfo] = useState<ProductionSyncInfo | null>(null);
  const [productionPullStatus, setProductionPullStatus] = useState<ProductionPullStatus>("idle");
  const [productionPullConfirmOpen, setProductionPullConfirmOpen] = useState(false);
  const [reportRangeOverride, setReportRange] = useState<DeliveryPlanRange | null>(null);
  const reportRange = reportRangeOverride ?? deliveryPlanSuggestedRange(seed, result);
  useEffect(() => { setReportRange(null); }, [result.createdAt]);
  const deliveryReport = useMemo(() => buildDeliveryReport(seed,
    result.state === "planned" && !dirty ? result : createEmptyResult(seed), reportRange),
    [seed, result, dirty, reportRange.startDate, reportRange.endDate]);

  const [operationAlert, setOperationAlert] = useState<{ id: number; message: string } | null>(null);
  const [adviceOpen, setAdviceOpen] = useState(false);
  const [adviceOrderId, setAdviceOrderId] = useState<string | null>(null);
  const [adviceMachineId, setAdviceMachineId] = useState<string | null>(null);
  const [dismissedAdviceIds, setDismissedAdviceIds] = useState<string[]>([]);
  const [quickManualProduct, setQuickManualProduct] = useState<string | null>(null);
  const [scenarioSaveOpen, setScenarioSaveOpen] = useState(false);
  const [scenarioLoadReport, setScenarioLoadReport] = useState<ScenarioLoadReport | null>(null);
  const [activeScenarioName, setActiveScenarioName] = useState("");
  const [archiveOpen, setArchiveOpen] = useState(false);
  const [planRunOpen, setPlanRunOpen] = useState(false);
  const [automaticComparisonOpen, setAutomaticComparisonOpen] = useState(false);

  const raviPlanningContext = useMemo(() => ({
    source: "current-browser", dirty, syncStatus: planningSyncStatus, lastSyncedAt: lastPlanningSyncAt,
    planState: result.state, calculatedAt: result.createdAt, summary: result.summary,
    activeScenarioName, scope: seed.customerDemand?.activeScope ?? seed.activePlanningScope,
    activePlanRun: result.planRun ?? seed.activePlanRun,
    orderSource: seed.customerDemand ? {
      sourceFile: seed.customerDemand.sourceFile, snapshotDate: seed.customerDemand.snapshotDate,
      importedAt: seed.customerDemand.importedAt, calculationModel: seed.customerDemand.calculationModel,
    } : seed.orderImport ?? { source: seed.orderCatalogName ?? "Manuel sipariş girişi" },
    orderCount: seed.orders.length, machineCount: seed.machines.length,
    selectedBatch: view === "planning" ? result.batches.find((batch) => batch.id === selectedBatchId) : undefined,
    openPanels: { archive: archiveOpen, advice: adviceOpen, planRun: planRunOpen, scenarioSave: scenarioSaveOpen,
      automaticComparison: automaticComparisonOpen, syncConflict: Boolean(planningSyncConflict) },
  }), [seed, result, view, dirty, planningSyncStatus, lastPlanningSyncAt, activeScenarioName, selectedBatchId,
    archiveOpen, adviceOpen, planRunOpen, scenarioSaveOpen, automaticComparisonOpen, planningSyncConflict]);

  function navigateFromRavi(id: string) {
    const target = raviTarget(id, isAdmin);
    if (!target) return;
    if (target.panel === "archive") setArchiveOpen(true);
    if (target.panel === "advice") openAdvice();
    if (target.view) { setPageGuideOpen(false); changeView(target.view); }
    if (target.focusId) {
      window.requestAnimationFrame(() => {
        const element = document.getElementById(target.focusId!);
        element?.scrollIntoView({ block: "center", behavior: "instant" });
        element?.focus({ preventScroll: true });
        element?.classList.add("ravi-highlight");
        window.setTimeout(() => element?.classList.remove("ravi-highlight"), 3500);
      });
    }
  }

  const {
    placeDownstreamQueueOperation, rescheduleDownstreamOperation, replanDownstreamProcess, saveCurrentJob, completeCurrentJob, changeProductionHistoryStatus, editProductionHistoryEntry, allocateProductionHistory, finishWipOperation, beginDownstreamCurrentJob, replaceDownstreamCurrentJob, saveDownstreamCurrentJob, finishDownstreamCurrentJob, changeWipStage, releaseHeldWip, saveJourneyNote
  } = createProductionActions({ seed, result, commitOperationalChange, setOperationAlert, setDirty, dirty });

  const planningAdvice = useMemo(() => buildPlanningAdvice(seed, result, { dirty }), [dirty, result, seed]);
  const visiblePlanningAdvice = planningAdvice.filter((item) => !dismissedAdviceIds.includes(item.id));
  const automaticComparisonAvailable = !dirty && hasManualPlanChanges(seed.lastAutomaticPlan, result);

  useEffect(() => {
    if (!window.localStorage.getItem("selsa-planlama-tour-seen")) setTourOpen(true);
    try {
      const stored = JSON.parse(window.localStorage.getItem(dismissedAdviceKey) ?? "[]");
      if (Array.isArray(stored)) setDismissedAdviceIds(stored.filter((item): item is string => typeof item === "string"));
    } catch {
      setDismissedAdviceIds([]);
    }
  }, []);

  useEffect(() => {
    void fetchScenarioPage(0, true);
    const localState = readLocalPlanningState();
    const localSeed = localState?.seed ?? null;
    if (localSeed) {
      const local = cloneSeed(localSeed);
      const restored = restoreManualResult(local);
      setSeed(local);
      setResult(restored ?? createEmptyResult(local));
      setSelectedBatchId(restored?.batches.find((batch) => batch.status === "planned")?.id ?? "");
      setDirty(!restored);
      setNotice(restored ? "Kaydedilmiş manuel plan geri yüklendi" : "Yerel parametreler yüklendi · planı yeniden çalıştırın");
    }
    Promise.all([
      apiFetch("/orders").then((response) => response.json()),
      apiFetch("/revisions").then((response) => response.json()),
      apiFetch("/planning-state").then((response) => response.ok ? response.json() : null),
      apiFetch("/planning-state/history").then((response) => response.ok ? response.json() : []),
      apiFetch("/production-sync/status").then((response) => response.ok ? response.json() : null).catch(() => null),
    ]).then(([details, storedRevisions, storedState, storedPlanningHistory, storedProductionSyncInfo]) => {
      const detailMap = new Map((details as Array<Partial<Order> & { id: string }>).map((detail) => [detail.id, detail]));
      const remoteState = isPlanningSeed(storedState?.seed)
        ? { seed: storedState.seed, updatedAt: String(storedState.updatedAt ?? "") }
        : null;
      remotePlanningStateUpdatedAtRef.current = remoteState?.updatedAt ?? "";
      setLastPlanningSyncAt(remoteState?.updatedAt ?? "");
      setPlanningSyncStatus(localState && newestPlanningState(localState, remoteState) === localState && localState.updatedAt !== remoteState?.updatedAt ? "offline" : "synced");
      const newestState = newestPlanningState(localState, remoteState);
      const persistedSeed = newestState?.seed ?? null;
      // A local planning draft may legitimately be newer than the server, but
      // the server remains authoritative for production/archive truth.
      const safePersistedSeed = persistedSeed && remoteState && newestState === localState
        ? mergeScenarioWithLiveOperations(persistedSeed, remoteState.seed)
        : persistedSeed;
      const base = cloneSeed(safePersistedSeed ?? originalSeed);
      if (!base.customerDemand) {
        base.orders = base.orders.map((order) => ({ ...order, ...(detailMap.get(order.id) ?? {}) }));
      }
      setSeed(base);
      const restored = restoreManualResult(base);
      const loadedResult = restored ?? (persistedSeed ? createEmptyResult(base) : runOptimizedScenario(base));
      setResult(loadedResult);
      setSelectedBatchId(loadedResult.batches.find((batch) => batch.status === "planned")?.id ?? "");
      setDirty(Boolean(persistedSeed && !restored));
      setPlanningHistory(storedPlanningHistory as PlanningStateRevision[]);
      setRevisions(storedRevisions as OrderRevision[]);
      setProductionSyncInfo(parseProductionSyncInfo(storedProductionSyncInfo));
      setNotice(persistedSeed ? (restoreManualResult(base) ? "Kaydedilmiş manuel plan geri yüklendi" : "Kaydedilmiş parametreler yüklendi · planı yeniden çalıştırın") : "Backend veritabanı hazır");
    }).catch(() => {
      setPlanningSyncStatus("offline");
      setNotice("Veritabanı açılamadı; uygulama bellekte çalışıyor");
    });
  }, [apiFetch]);

  useEffect(() => {
    function handleHistoryShortcut(event: KeyboardEvent) {
      if (!(event.ctrlKey || event.metaKey)) return;
      const target = event.target;
      if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement || (target instanceof HTMLElement && target.isContentEditable)) return;
      const key = event.key.toLowerCase();
      if (key === "z" && event.shiftKey) {
        if (!historyFuture.length) return;
        event.preventDefault();
        redoLastOperation();
      } else if (key === "z") {
        if (!historyPast.length) return;
        event.preventDefault();
        undoLastOperation();
      } else if (key === "y") {
        if (!historyFuture.length) return;
        event.preventDefault();
        redoLastOperation();
      }
    }
    window.addEventListener("keydown", handleHistoryShortcut);
    return () => window.removeEventListener("keydown", handleHistoryShortcut);
  }, [historyFuture, historyPast, result, seed, selectedBatchId, dirty]);

  useEffect(() => {
    if (!operationAlert) return;
    const timeout = window.setTimeout(() => setOperationAlert(null), 7_000);
    return () => window.clearTimeout(timeout);
  }, [operationAlert]);

  const selectedBatch = result.batches.find((batch) => batch.id === selectedBatchId)
    ?? result.batches.find((batch) => batch.status === "planned")
    ?? null;

  async function writePlanningStateToServer(next: PlanningSeed, options: { force?: boolean; expectedUpdatedAt?: string; mode?: PlanningWriteMode } = {}): Promise<PlanningStateRecord> {
    const expectedUpdatedAt = options.expectedUpdatedAt ?? remotePlanningStateUpdatedAtRef.current;
    const response = await apiFetch("/planning-state", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ seed: next, expectedUpdatedAt, force: options.force ?? false, mode: options.mode ?? "planning" }),
    });
    if (response.status === 409) {
      const body = await response.json().catch(() => ({})) as { detail?: { current?: PlanningStateRecord } };
      const current = body.detail?.current;
      if (current && isPlanningSeed(current.seed)) setPlanningSyncConflict(current);
      setPlanningSyncStatus("conflict");
      throw new Error("Ortak planlama verisi başka bir oturumda değişti.");
    }
    if (!response.ok) throw new Error("Planlama durumu ortak veritabanına kaydedilemedi.");
    const saved = await response.json() as PlanningStateRecord & { historyEntry?: PlanningStateRevision };
    remotePlanningStateUpdatedAtRef.current = saved.updatedAt;
    setLastPlanningSyncAt(saved.updatedAt);
    setPlanningSyncStatus("synced");
    if (saved.historyEntry) setPlanningHistory((current) => [saved.historyEntry!, ...current.filter((entry) => entry.id !== saved.historyEntry!.id)].slice(0, 20));
    return saved;
  }

  function persistPlanningState(next: PlanningSeed, options: { mode?: PlanningWriteMode } = {}) {
    const updatedAt = new Date().toISOString();
    window.localStorage.setItem(planningStateKey, JSON.stringify(next));
    window.localStorage.setItem(planningStateUpdatedAtKey, updatedAt);
    setPlanningSyncStatus("saving");
    planningStateWriteRef.current = planningStateWriteRef.current
      .then(async () => {
        await writePlanningStateToServer(next, { mode: options.mode ?? "planning" });
      })
      .catch(() => {
        setPlanningSyncStatus((current) => current === "conflict" ? current : "offline");
      });
  }

  async function pullProductionState() {
    setProductionPullStatus("pulling");
    try {
      await planningStateWriteRef.current;
      // Queued writes report errors in the UI; explicitly require this snapshot to be saved.
      await writePlanningStateToServer(seed, { mode: "operational" });
      const response = await apiFetch("/production-sync/pull", { method: "POST" });
      const payload = await response.json().catch(() => ({})) as {
        detail?: string;
        planningState?: { seed?: unknown; updatedAt?: unknown };
        sourceUpdatedAt?: unknown;
        importedAt?: unknown;
        sourceUrl?: unknown;
        historyEntry?: unknown;
        scenarios?: unknown;
      };
      if (!response.ok) {
        throw new Error(typeof payload.detail === "string" ? payload.detail : "Üretim verileri staging’e alınamadı.");
      }
      const planningRecord = payload.planningState;
      if (!planningRecord || !isPlanningSeed(planningRecord.seed) || typeof planningRecord.updatedAt !== "string") {
        throw new Error("Üretimden gelen planlama kaydı eksik; ekran değiştirilmedi.");
      }
      let productionScenarios: StoredScenario[];
      try {
        productionScenarios = importedScenarios(payload.scenarios);
      } catch {
        throw new Error("Üretimden gelen kayıtlı senaryolar eksik; staging değiştirilmedi.");
      }
      const next = cloneSeed(planningRecord.seed);
      const restored = restoreManualResult(next);
      setSeed(next);
      setResult(restored ?? createEmptyResult(next));
      setSelectedBatchId(restored?.batches.find((batch) => batch.status === "planned")?.id ?? "");
      setDirty(!restored);
      window.localStorage.setItem(planningStateKey, JSON.stringify(next));
      window.localStorage.setItem(planningStateUpdatedAtKey, planningRecord.updatedAt);
      remotePlanningStateUpdatedAtRef.current = planningRecord.updatedAt;
      setLastPlanningSyncAt(planningRecord.updatedAt);
      setPlanningSyncStatus("synced");
      replaceScenarioLibrary(productionScenarios);
      if (payload.historyEntry && typeof payload.historyEntry === "object") {
        const historyEntry = payload.historyEntry as PlanningStateRevision;
        if (typeof historyEntry.id === "string" && isPlanningSeed(historyEntry.seed) && typeof historyEntry.createdAt === "string") {
          setPlanningHistory((current) => [historyEntry, ...current.filter((entry) => entry.id !== historyEntry.id)].slice(0, 20));
        }
      }
      if (typeof payload.sourceUpdatedAt === "string" && typeof payload.importedAt === "string") {
        setProductionSyncInfo((current) => current ? {
          ...current,
          lastSync: {
            sourceUpdatedAt: payload.sourceUpdatedAt as string,
            importedAt: payload.importedAt as string,
            sourceUrl: typeof payload.sourceUrl === "string" ? payload.sourceUrl : current.lastSync?.sourceUrl ?? "production",
          },
        } : current);
      }
      setProductionPullConfirmOpen(false);
      setProductionPullStatus("idle");
      setNotice(`Yerel çalışma korundu · üretim verileri güncellendi · ${productionScenarios.length} kayıtlı senaryo`);
    } catch (reason) {
      setProductionPullStatus("error");
      setProductionPullConfirmOpen(false);
      setOperationAlert({ id: Date.now(), message: reason instanceof Error ? reason.message : "Üretim verileri staging’e alınamadı; staging değiştirilmedi." });
    }
  }

  function acceptRemotePlanningState() {
    if (!planningSyncConflict) return;
    const next = cloneSeed(planningSyncConflict.seed);
    const restored = restoreManualResult(next);
    setSeed(next);
    setResult(restored ?? createEmptyResult(next));
    setSelectedBatchId(restored?.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(!restored);
    window.localStorage.setItem(planningStateKey, JSON.stringify(next));
    window.localStorage.setItem(planningStateUpdatedAtKey, planningSyncConflict.updatedAt);
    remotePlanningStateUpdatedAtRef.current = planningSyncConflict.updatedAt;
    setLastPlanningSyncAt(planningSyncConflict.updatedAt);
    setPlanningSyncConflict(null);
    setPlanningSyncStatus("synced");
    setNotice("Ortak veritabanındaki daha yeni planlama durumu yüklendi");
  }

  async function forceLocalPlanningStateSync() {
    setPlanningSyncStatus("saving");
    try {
      await writePlanningStateToServer(seed, { force: true });
      const ordersResponse = await apiFetch("/orders", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(seed.orders) });
      if (!ordersResponse.ok) throw new Error("Siparişler ortak veritabanına aktarılamadı.");
      setPlanningSyncConflict(null);
      setNotice("Bu cihazdaki planlama durumu yeni ortak sürüm olarak yayınlandı");
    } catch (reason) {
      setPlanningSyncStatus((current) => current === "conflict" ? current : "offline");
      setOperationAlert({ id: Date.now(), message: reason instanceof Error ? reason.message : "Senkronizasyon tamamlanamadı." });
    }
  }

  function syncApiInBackground(path: string, init: RequestInit, label: string) {
    void apiFetch(path, init)
      .then((response) => {
        if (!response.ok) throw new Error(`${label} sunucuya kaydedilemedi.`);
      })
      .catch(() => {
        setNotice("Sunucu bağlantısı yok — uygulama bu cihazdaki verilerle çalışıyor");
        setOperationAlert({ id: Date.now(), message: `${label} bu cihazda korundu; ortak veritabanına aktarmak için backend bağlantısını kontrol edin.` });
      });
  }

  function operationalSeed(current: PlanningSeed, nextResult: ScenarioResult): PlanningSeed {
    const nextSeed = cloneSeed(current);
    nextSeed.manualBatches = nextResult.state === "planned" ? nextResult.batches.map((batch) => ({ ...batch })) : [];
    return nextSeed;
  }

  function commitOperationalChange(nextSeed: PlanningSeed, nextResult: ScenarioResult, successMessage: string, event?: Omit<PlanningEvent, "id" | "createdAt">, undoMessage = "Son işlem geri alınabilir") {
    const before: OperationalSnapshot = { seed: cloneSeed(seed), result: cloneResult(result), selectedBatchId, dirty, message: undoMessage };
    const committed = operationalSeed(nextSeed, nextResult);
    if (event) appendPlanningEvent(committed, event);
    setHistoryPast((current) => [...current, before].slice(-50));
    setHistoryFuture([]);
    setHistoryMessage(undoMessage);
    setSeed(committed);
    setResult(nextResult);
    persistPlanningState(committed, { mode: "operational" });
    setSelectedBatchId(nextResult.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(false);
    setNotice(successMessage);
  }

  function updateSeed(mutator: (draft: PlanningSeed) => void) {
    setSeed((current) => {
      const draft = cloneSeed(current);
      mutator(draft);
      draft.manualBatches = [];
      draft.lastAutomaticPlan = undefined;
      draft.planRunSequence = undefined;
      persistPlanningState(draft);
      syncApiInBackground("/orders", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(draft.orders) }, "Sipariş değişikliği");
      return draft;
    });
    setDirty(true);
    setNotice("Girdiler değişti — planı yeniden çalıştırın");
  }

  function applyCalendarChange(mutator: (draft: PlanningSeed) => void) {
    const nextSeed = cloneSeed(seed);
    mutator(nextSeed);
    nextSeed.lastAutomaticPlan = undefined;
    if (result.state !== "planned") {
      nextSeed.manualBatches = [];
      setSeed(nextSeed);
      persistPlanningState(nextSeed);
      setDirty(true);
      setNotice("Takvim güncellendi — planı çalıştırın");
      return;
    }
    try {
      const previousCompletion = Math.max(0, ...result.batches.filter((batch) => batch.status === "planned").map((batch) => batch.end));
      const nextResult = recalculateManualScenario(nextSeed, result.batches, { allowPlanEndOverflow: true });
      const nextCompletion = Math.max(0, ...nextResult.batches.filter((batch) => batch.status === "planned").map((batch) => batch.end));
      const previousBatches = new Map(result.batches.filter((batch) => batch.status === "planned").map((batch) => [batch.id, batch]));
      const changedBatches = nextResult.batches.filter((batch) => {
        const previous = previousBatches.get(batch.id);
        return batch.status === "planned" && previous && (previous.start !== batch.start || previous.end !== batch.end);
      });
      const changedMachines = [...new Set(changedBatches.map((batch) => batch.machineId))];
      const dayDelta = Math.round((nextCompletion - previousCompletion) * 10) / 10;
      const deltaText = dayDelta === 0 ? "genel bitiş değişmedi" : dayDelta < 0 ? `${Math.abs(dayDelta)} gün erkene geldi` : `${dayDelta} gün ötelendi`;
      const impactText = changedBatches.length ? `${changedBatches.length} şarj · ${changedMachines.join(", ")} güncellendi` : "etkilenen planlı şarj yok";
      commitOperationalChange(nextSeed, nextResult, `Takvim uygulandı · ${impactText} · plan bitişi ${formatExcelDate(nextCompletion)} · ${deltaText}`, undefined, "Takvim değişikliği geri alınabilir");
    } catch (error) {
      nextSeed.manualBatches = [];
      setSeed(nextSeed);
      persistPlanningState(nextSeed);
      setDirty(true);
      const message = error instanceof Error ? error.message : "Takvim değişikliği mevcut plana uygulanamadı.";
      setNotice("Takvim kaydedildi — planı yeniden çalıştırın");
      setOperationAlert({ id: Date.now(), message: `Takvim kaydedildi ancak mevcut kuyruk yeniden hesaplanamadı: ${message}` });
    }
  }

  function runScenario(request: PlanRunRequest) {
    const fixedBatches = result.batches.filter((batch) =>
      batch.status === "planned" && (request.appendToExistingPlan || batch.locked));
    const { prepared, result: next } = executePlanRun(seed, fixedBatches, request);
    const planningSeed = prepared.seed;
    const nextSeed = operationalSeed(planningSeed, next);
    nextSeed.lastAutomaticPlan = createAutomaticPlanSnapshot(next);
    setSeed(nextSeed);
    setResult(next);
    persistPlanningState(nextSeed);
    syncApiInBackground("/orders", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(nextSeed.orders) }, "Yeni planın sipariş durumu");
    setSelectedBatchId(next.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(false);
    setActiveScenarioName("");
    const completion = Math.max(0, ...next.batches.filter((batch) => batch.status === "planned").map((batch) => batch.end));
    const shortage = Math.max(0, next.summary.demand - next.summary.planned);
    const pendingRangeCount = Math.max(0, (prepared.sequence?.ranges.length ?? 1) - (prepared.sequence?.completedRangeCount ?? 1));
    setNotice(request.appendToExistingPlan
      ? pendingRangeCount > 0
        ? `Yeni aralığın ilki plana eklendi · ${prepared.scopeLabel} · manuel kontrolünüzden sonra ${pendingRangeCount} aralık daha eklenebilir · ${formatNumber(shortage)} eksik üretim`
        : `Planın devamı eklendi · ${prepared.scopeLabel} · mevcut düzen korundu · ${formatNumber(shortage)} eksik üretim · bitiş ${formatExcelDate(completion)}`
      : pendingRangeCount > 0
        ? `İlk aralık planlandı · ${prepared.scopeLabel} · manuel kontrolünüzden sonra ${pendingRangeCount} aralık daha eklenebilir · ${formatNumber(shortage)} eksik üretim`
        : `Plan tamamlandı · ${optimizationGoalLabel(request.optimizationGoal)} · ${prepared.scopeLabel} · ${next.summary.plannedBatchCount} şarj · ${formatNumber(shortage)} eksik üretim · bitiş ${formatExcelDate(completion)}`);
    setPlanRunOpen(false);
    setAutomaticComparisonOpen(false);
    setView("planning");
  }

  function previewPlanRuns(request: PlanRunRequest): PlanComparisonRow[] {
    const fixedBatches = result.batches.filter((batch) =>
      batch.status === "planned" && (request.appendToExistingPlan || batch.locked));
    return comparePlanRuns(seed, fixedBatches, request);
  }

  function runNextPlanRange() {
    try {
      const fixedBatches = result.batches.filter((batch) => batch.status === "planned");
      const next = executeNextPlanStage(seed, fixedBatches);
      next.seed.lastAutomaticPlan = createAutomaticPlanSnapshot(next.result);
      const rangeNumber = next.sequence.completedRangeCount;
      const completion = next.result.summary.completion;
      const shortage = Math.max(0, next.result.summary.demand - next.result.summary.planned);
      commitOperationalChange(
        next.seed,
        next.result,
        `${rangeNumber}. aralık plana eklendi · ${next.completedRange.label} · ${formatNumber(shortage)} eksik üretim · bitiş ${formatExcelDate(completion)}`,
        undefined,
        `${rangeNumber}. aralık ekleme işlemi geri alınabilir`,
      );
      syncApiInBackground("/orders", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(next.seed.orders) }, "Yeni planlama aralığının sipariş durumu");
      setAutomaticComparisonOpen(false);
      setView("planning");
    } catch (error) {
      const message = error instanceof Error ? error.message : "Sıradaki planlama aralığı eklenemedi.";
      setNotice(message);
      setOperationAlert({ id: Date.now(), message });
    }
  }

  function restoreLastAutomaticPlan() {
    const snapshot = seed.lastAutomaticPlan;
    if (!snapshot) {
      setOperationAlert({ id: Date.now(), message: "Geri dönülecek otomatik plan bulunamadı." });
      return;
    }
    const restoredResult = automaticPlanResult(snapshot);
    const restoredSeed = cloneSeed(seed);
    restoredSeed.activePlanRun = restoredResult.planRun ?? restoredSeed.activePlanRun;
    commitOperationalChange(
      restoredSeed,
      restoredResult,
      "Son otomatik plan geri yüklendi",
      undefined,
      "Otomatik plana dönüş geri alınabilir",
    );
    setAutomaticComparisonOpen(false);
  }

  function applyCustomerDemandImport(preview: ConfirmedOverviewPreview) {
    const comparison = compareCustomerDemandImport(seed.customerDemand, preview);
    const requestedScope = scopeForDemandReimport(seed.customerDemand, preview);
    const state = buildWeeklyPlanningState(preview, seed.orders, requestedScope, seed.customerOrderOverrides);
    const nextSeed = cloneSeed(seed);
    nextSeed.lastAutomaticPlan = undefined;
    nextSeed.planRunSequence = undefined;
    const planEnd = inputDateToSerial(state.planEndDate);
    nextSeed.orderCatalog = state.orderCatalog;
    nextSeed.orderCatalogName = preview.fileName;
    nextSeed.orders = state.orders;
    nextSeed.customerDemand = state.dataset;
    nextSeed.orderImport = orderImportMetadataForSeed({ customerDemand: state.dataset }) ?? undefined;
    nextSeed.orderImportGrossOrders = undefined;
    nextSeed.openingStock = {};
    nextSeed.demandTargets = undefined;
    for (const machine of nextSeed.machines) machine.planEnd = planEnd;
    if (seed.customerDemand) {
      const previousVersion = demandImportVersion(seed.customerDemand);
      syncApiInBackground("/order-imports/history", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(previousVersion) }, "Önceki sipariş Excel geçmişi");
    }
    const nextVersion = demandImportVersion(state.dataset);
    syncApiInBackground("/order-imports/history", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(nextVersion) }, "Yeni sipariş Excel geçmişi");

    const protectedBatches = protectedBatchesForDemandReimport(result);
    const scopeStart = state.dataset.weeks.find((week) => week.id === state.dataset.activeScope.startWeekId)?.label ?? state.dataset.activeScope.startWeekId;
    const scopeEnd = state.dataset.weeks.find((week) => week.id === state.dataset.activeScope.endWeekId)?.label ?? state.dataset.activeScope.endWeekId;
    const delta = comparison.requirementDelta;
    const deltaLabel = comparison.repeatImport ? ` · talep farkı ${delta > 0 ? "+" : ""}${formatNumber(delta)}` : "";

    if (result.state === "planned") {
      const nextResult = runOptimizedScenario(nextSeed, protectedBatches);
      commitOperationalChange(
        nextSeed,
        nextResult,
        `Müşteri Excel’i uzlaştırıldı · ${scopeStart}–${scopeEnd}${deltaLabel} · ${protectedBatches.length} korunan şarj`,
        undefined,
        "Müşteri Excel’i güncellemesi geri alınabilir",
      );
    } else {
      nextSeed.manualBatches = [];
      setSeed(nextSeed);
      setResult(createEmptyResult(nextSeed));
      setSelectedBatchId("");
      setDirty(true);
      persistPlanningState(nextSeed);
      setNotice(`Müşteri Excel’i uygulandı · ${scopeStart}–${scopeEnd}${deltaLabel} · planı çalıştırın`);
    }
    syncApiInBackground("/orders", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(nextSeed.orders) }, "İçe aktarılan siparişler");
  }

  function clearPlan() {
    const nextSeed = cloneSeed(seed);
    nextSeed.lastAutomaticPlan = undefined;
    nextSeed.planRunSequence = undefined;
    const locked = result.batches.filter((batch) => batch.status === "planned" && batch.locked).map((batch) => ({ ...batch }));
    if (!locked.length) {
      for (const machine of nextSeed.machines) {
        machine.availableStart = machine.operationalAvailableStart ?? machine.availableStart;
      }
    }
    let nextResult = createEmptyResult(nextSeed);
    if (locked.length) {
      try {
        nextResult = recalculateManualScenario(nextSeed, locked);
      } catch {
        nextResult = createEmptyResult(nextSeed);
      }
    }
    nextSeed.manualBatches = nextResult.state === "planned" ? nextResult.batches.map((batch) => ({ ...batch })) : [];
    setSeed(nextSeed);
    persistPlanningState(nextSeed);
    setResult(nextResult);
    setSelectedBatchId(nextResult.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(true);
    setActiveScenarioName("");
    setNotice(locked.length ? `Plan temizlendi — ${locked.length} kilitli şarj korundu` : "Plan temizlendi — girdiler korunuyor");
    setView("planning");
  }

  async function saveScenario(name: string, notes: string) {
    if (result.state !== "planned") {
      setNotice("Kaydetmeden önce planı çalıştırın");
      throw new Error("Kaydetmeden önce planı çalıştırın.");
    }
    const createdAt = new Date().toISOString();
    const scenario: StoredScenario = {
      id: crypto.randomUUID(),
      name: name.trim(),
      createdAt,
      notes: notes.trim(),
      seed: scenarioPlanningSeed(cloneSeed(seed)),
      result,
    };
    await addStoredScenario(scenario);
    setActiveScenarioName(scenario.name);
    await fetchScenarioPage(0, true);
    setNotice(`${scenario.name} veritabanına kaydedildi`);
    setScenarioSaveOpen(false);
  }

  function applyManualChange(action: () => ScenarioResult, successMessage: string, event?: Omit<PlanningEvent, "id" | "createdAt">) {
    try {
      const next = action();
      commitOperationalChange(seed, next, successMessage, event);
    } catch (error) {
      const message = error instanceof Error ? error.message : "Manuel plan değişikliği uygulanamadı";
      setNotice(message);
      setOperationAlert({ id: Date.now(), message });
    }
  }

  function undoLastOperation() {
    const previous = historyPast.at(-1);
    if (!previous) return;
    const current: OperationalSnapshot = { seed: cloneSeed(seed), result: cloneResult(result), selectedBatchId, dirty, message: previous.message };
    setHistoryPast((items) => items.slice(0, -1));
    setHistoryFuture((items) => [current, ...items].slice(0, 50));
    setSeed(previous.seed);
    setResult(previous.result);
    persistPlanningState(previous.seed, { mode: "operational" });
    setSelectedBatchId(previous.selectedBatchId || previous.result.batches.find((batch) => batch.status === "planned")?.id || "");
    setDirty(previous.dirty);
    setNotice("Son manuel işlem geri alındı");
    setHistoryMessage(`Geri alındı · ${previous.message}`);
  }

  function redoLastOperation() {
    const next = historyFuture[0];
    if (!next) return;
    const current: OperationalSnapshot = { seed: cloneSeed(seed), result: cloneResult(result), selectedBatchId, dirty, message: next.message };
    setHistoryPast((items) => [...items, current].slice(-50));
    setHistoryFuture((items) => items.slice(1));
    setSeed(next.seed);
    setResult(next.result);
    persistPlanningState(next.seed, { mode: "operational" });
    setSelectedBatchId(next.selectedBatchId || next.result.batches.find((batch) => batch.status === "planned")?.id || "");
    setDirty(next.dirty);
    setNotice("Manuel işlem yeniden uygulandı");
    setHistoryMessage(`Yeniden uygulandı · ${next.message}`);
  }

  function lockThrough(batch: PlannedBatch) {
    applyManualChange(() => lockQueueThrough(result, batch.machineId, batch.id), `${batch.machineId} kuyruğu ${queuePosition(batch.planColumn)}. işe kadar kilitlendi`, { type: "lock", machineId: batch.machineId, batchId: batch.id, message: `${batch.machineId} kuyruğu ${queuePosition(batch.planColumn)}. işe kadar kilitlendi.` });
  }

  function unlockQueue(machineId: string) {
    applyManualChange(() => unlockMachineQueue(result, machineId), `${machineId} kuyruk kilidi kaldırıldı`, { type: "unlock", machineId, message: `${machineId} kuyruk kilidi kaldırıldı.` });
  }

  function saveBatchWorkOrder(batch: PlannedBatch, workOrder: string) {
    applyManualChange(() => updateBatchWorkOrder(result, batch.id, workOrder), `${batch.product} iş emri kaydedildi`, { type: "work-order", machineId: batch.machineId, batchId: batch.id, message: `${batch.product} için iş emri ${workOrder || "boş"} olarak güncellendi.` });
  }

  function updateBatchQuantity(batch: PlannedBatch, quantity: number) {
    applyManualChange(() => updateBatchQuantityManually(seed, result, batch.id, quantity), `${batch.product} şarj adedi güncellendi`, { type: "quantity", machineId: batch.machineId, batchId: batch.id, message: `${batch.product} şarjı ${formatNumber(batch.quantity)} → ${formatNumber(quantity)} adet olarak güncellendi.` });
  }

  function loadScenario(scenario: StoredScenario) {
    // Normalize only the saved planning inputs. Inject live factory truth last
    // so loading a scenario can never roll or otherwise edit a current job.
    const scenarioSeed = mergeScenarioWithLiveOperations(cloneSeed(scenario.seed), seed);
    scenarioSeed.lastAutomaticPlan = undefined;
    let loadedResult: ScenarioResult;
    let overflows: ScenarioPlanOverflow[] = [];
    try {
      const rebased = rebaseScenarioPlan(scenarioSeed, scenario.result);
      loadedResult = rebased.result;
      overflows = rebased.overflows;
    } catch (error) {
      const message = error instanceof Error ? error.message : "Senaryo canlı üretim durumuna uygulanamadı.";
      setOperationAlert({ id: Date.now(), message });
      setNotice("Senaryo yüklenmedi · canlı işler korundu");
      return;
    }
    scenarioSeed.manualBatches = loadedResult.batches.map((batch) => ({ ...batch }));
    setSeed(scenarioSeed);
    persistPlanningState(scenarioSeed);
    setResult(loadedResult);
    setSelectedBatchId(loadedResult.batches[0]?.id ?? "");
    setDirty(false);
    setActiveScenarioName(scenario.name);
    setScenarioLoadReport(overflows.length ? { scenarioName: scenario.name, overflows } : null);
    setNotice(overflows.length ? `${scenario.name} yüklendi · ${overflows.length} iş plan penceresini aşıyor` : `${scenario.name} yüklendi`);
    setView("planning");
  }

  function restorePlanningRevision(revision: PlanningStateRevision) {
    const restoredSeed = mergeScenarioWithLiveOperations(cloneSeed(revision.seed), seed);
    const restoredResult = restoreManualResult(restoredSeed) ?? createEmptyResult(restoredSeed);
    const before: OperationalSnapshot = { seed: cloneSeed(seed), result: cloneResult(result), selectedBatchId, dirty, message: "Versiyon geri yükleme işlemi geri alınabilir" };
    setHistoryPast((current) => [...current, before].slice(-50));
    setHistoryFuture([]);
    setSeed(restoredSeed);
    setResult(restoredResult);
    setSelectedBatchId(restoredResult.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(!restoredSeed.manualBatches?.length);
    persistPlanningState(restoredSeed);
    setNotice(`${formatFactoryDateTime(revision.createdAt)} versiyonu geri yüklendi`);
    setView("planning");
  }

  async function approveOrderRevision(revision: OrderRevision) {
    const response = await apiFetch("/revisions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(revision) });
    if (!response.ok) throw new Error("Sipariş revizyonu kaydedilemedi.");
    const revisionSeed = mergeScenarioWithLiveOperations(cloneSeed(revision.seed), seed);
    revisionSeed.lastAutomaticPlan = undefined;
    revisionSeed.planRunSequence = undefined;
    revisionSeed.manualBatches = revision.result.batches.map((batch) => ({ ...batch }));
    setSeed(revisionSeed);
    persistPlanningState(revisionSeed);
    setResult(revision.result);
    setRevisions((current) => [revision, ...current]);
    setSelectedBatchId(revision.result.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(false);
    setNotice(`${revision.product} revizyonu onaylandı; dondurulmuş işler korundu`);
  }

  function navigateToFinding(target: AuditTarget) {
    if (target.orderId) setFocusedOrderId(target.orderId);
    if (target.machineId) setSelectedMachineId(target.machineId);
    if (target.batchId) setSelectedBatchId(target.batchId);
    setPageGuideOpen(false);
    changeView(target.view);
  }

  function openAdvice(orderId: string | null = null, machineId: string | null = null) {
    setAdviceOrderId(orderId);
    setAdviceMachineId(machineId);
    setAdviceOpen(true);
  }

  function dismissAdvice(id: string) {
    setDismissedAdviceIds((current) => {
      const next = [...new Set([...current, id])];
      window.localStorage.setItem(dismissedAdviceKey, JSON.stringify(next));
      return next;
    });
  }

  function restoreDismissedAdvice() {
    setDismissedAdviceIds([]);
    window.localStorage.removeItem(dismissedAdviceKey);
  }

  function applyAdvice(item: PlanningAdvice) {
    if (item.action.type === "pull-forward") {
      const action = item.action;
      applyManualChange(
        () => applyPullForwardAdvice(seed, result, action),
        `${item.product}, ${action.sourceWeekLabel} talebinden ${action.machineId} tezgahına öne çekildi`,
        { type: "pull-forward", machineId: action.machineId, message: `${item.product}, ${action.sourceWeekLabel} talebinden ${action.pulledIntoRangeLabel} kapasitesine öne çekildi.` },
      );
      return;
    }
    if (item.action.type === "move") {
      const action = item.action;
      applyManualChange(
        () => moveBatchManually(seed, result, action.batchId, action.toMachineId, action.position),
        `${item.product} tavsiyesi uygulandı · şarj ${action.toMachineId} tezgahına taşındı`,
        { type: "move", machineId: action.toMachineId, batchId: action.batchId, message: `${item.product}, tavsiye ile ${action.fromMachineId} → ${action.toMachineId} taşındı.` },
      );
      return;
    }
    if (item.action.type === "add-charge") {
      const action = item.action;
      applyManualChange(
        () => addBatchManually(seed, result, item.product, action.machineId, action.quantity, action.position),
        `${item.product} için önerilen şarj ${action.machineId} kuyruğuna eklendi`,
        { type: "add", machineId: action.machineId, message: `${item.product}, tavsiye ile ${action.machineId} kuyruğuna eklendi.` },
      );
      return;
    }
    const action = item.action;
    applyCalendarChange((draft) => replaceMachineShiftOverrides(draft, [action.machineId], action.start, action.end, action.shiftCount, `${item.product} termin önerisi`));
  }

  return (
    <RaviContextProvider view={view} planning={raviPlanningContext} entryPoint={entryPoint}><main className="app-shell">
      <Header isAdmin={isAdmin} view={view} setView={(next) => { setPageGuideOpen(false); if (next === "processes") setFocusedJourneyJobId(""); changeView(next); window.scrollTo(0, 0); }} notice={notice} adviceCount={visiblePlanningAdvice.length} onOpenAdvice={() => openAdvice()} onOpenArchive={() => setArchiveOpen(true)} productionSyncInfo={productionSyncInfo} productionPullStatus={productionPullStatus} onPullProduction={() => setProductionPullConfirmOpen(true)} />
      <section className="page-head">
        <div>
          <div className="eyebrow">{originalSeed.source} · Setup dahil optimize planlama</div>
          <h1>{pageTitle(view)}</h1>
          <p className="page-summary">{PAGE_GUIDES[view].summary}</p>
        </div>
        <div className="page-actions">
          {view !== "feedback" && <>
            <button className="secondary" onClick={clearPlan}><Trash size={16} /> Planı Temizle</button>
            <button className={`primary ${dirty ? "attention" : ""}`} onClick={() => setPlanRunOpen(true)}><Play size={16} weight="fill" /> Planı Çalıştır</button>
          </>}
          <details className="page-more-actions">
            <summary><span>Diğer işlemler</span><CaretDown size={14} /></summary>
            <div>
              <button onClick={() => setPageGuideOpen((open) => !open)}><Question size={15} /> Sayfa rehberi</button>
              <button onClick={() => setTourOpen(true)}><Question size={15} /> Tanıtımı başlat</button>
              {view !== "feedback" && <>
                <span className="page-more-history" aria-label="Plan değişikliği geçmişi">
                  <button disabled={!historyPast.length} onClick={undoLastOperation} title="Geri al (Ctrl/Cmd+Z)"><ArrowCounterClockwise size={15} /> Geri al</button>
                  <button disabled={!historyFuture.length} onClick={redoLastOperation} title="Yinele (Ctrl/Cmd+Y)"><ArrowClockwise size={15} /> Yinele</button>
                </span>
                <button onClick={() => result.state === "planned" ? setScenarioSaveOpen(true) : setNotice("Kaydetmeden önce planı çalıştırın")}><FloppyDisk size={15} /> Senaryoyu Kaydet</button>
              </>}
            </div>
          </details>
        </div>
      </section>
      {pageGuideOpen && <PageGuidePanel view={view} onClose={() => setPageGuideOpen(false)} />}

      {view === "planning" && (
        <PlanningView report={deliveryReport} reportRange={reportRange} onReportRangeChange={setReportRange}
          seed={seed}
          result={result}
          dirty={dirty}
          selectedBatch={selectedBatch}
          onSelectBatch={setSelectedBatchId}
          onMoveBatch={(batchId, machineId, position) => { const batch = result.batches.find((item) => item.id === batchId); applyManualChange(() => moveBatchManually(seed, result, batchId, machineId, position), "Şarj taşındı ve kuyruklar yeniden hesaplandı", { type: "move", machineId, batchId, message: `${batch?.product ?? "Şarj"}, ${machineId} kuyruğunda ${position + 1}. sıraya taşındı.` }); }}
          onRemoveBatch={(batchId) => { const batch = result.batches.find((item) => item.id === batchId); applyManualChange(() => removeBatchManually(seed, result, batchId), "Şarj plandan çıkarıldı", { type: "remove", machineId: batch?.machineId, batchId, message: `${batch?.product ?? "Şarj"} plandan çıkarıldı.` }); }}
          onLockThrough={lockThrough}
          onUnlockQueue={unlockQueue}
          onSaveWorkOrder={saveBatchWorkOrder}
          onUpdateBatchQuantity={updateBatchQuantity}
          onSaveCurrentJob={saveCurrentJob}
          onCompleteCurrentJob={completeCurrentJob}
          onOperationError={(message) => setOperationAlert({ id: Date.now(), message })}
          advice={visiblePlanningAdvice}
          onApplyAdvice={applyAdvice}
          onOpenMachineAdvice={(machineId) => openAdvice(null, machineId)}
          onOpenManualBatch={() => setQuickManualProduct("")}
          automaticComparisonAvailable={automaticComparisonAvailable}
          onOpenAutomaticComparison={() => setAutomaticComparisonOpen(true)}
          onPlanNextRange={runNextPlanRange}
          onReplanProcess={replanDownstreamProcess}
          onRescheduleProcess={rescheduleDownstreamOperation}
          updateSeed={applyCalendarChange}
          onOpenJourney={(jobId) => { setFocusedJourneyJobId(jobId); setView("processes"); window.scrollTo(0, 0); }}
        />
      )}
      {view === "processes" && <ProcessPlanningView seed={seed} result={result} dirty={dirty} focusJobId={focusedJourneyJobId} onCompleteCurrentJob={completeCurrentJob} onCompleteWipOperation={finishWipOperation} onCorrectWipStage={changeWipStage} onReleaseWip={releaseHeldWip} onSaveJourneyNote={saveJourneyNote} />}
      {view === "control" && <PlanControl seed={seed} result={result} dirty={dirty} onNavigate={navigateToFinding} />}
      {view === "orders" && <OrdersView report={deliveryReport} reportRange={reportRange} onReportRangeChange={setReportRange} seed={seed} result={result} dirty={dirty} activeScenarioName={activeScenarioName || scenarioSummaries.find((scenario) => scenario.planRun?.planId && scenario.planRun.planId === (result.planRun ?? seed.activePlanRun)?.planId)?.name || ""} revisions={revisions} focusOrderId={focusedOrderId} onApprove={approveOrderRevision} strategy={strategy} updateSeed={updateSeed} onApplyCustomerImport={applyCustomerDemandImport} onOpenAdvice={(orderId) => openAdvice(orderId)} onOpenManualBatch={(product) => setQuickManualProduct(product)} />}
      {view === "machines" && (
        <MachinesView
          seed={seed}
          result={result}
          dirty={dirty}
          selectedMachineId={selectedMachineId}
          setSelectedMachineId={setSelectedMachineId}
          updateSeed={updateSeed}
          updateCalendar={applyCalendarChange}
          onAddBatch={(product, machine, quantity, position) => applyManualChange(() => addBatchManually(seed, result, product, machine, quantity, position), "Manuel şarj eklendi", { type: "add", machineId: machine, message: `${product}, ${machine} kuyruğuna manuel eklendi.` })}
          onMoveBatch={(batchId, machineId, position) => { const batch = result.batches.find((item) => item.id === batchId); applyManualChange(() => moveBatchManually(seed, result, batchId, machineId, position), "Tezgah kuyruğu yeniden sıralandı", { type: "move", machineId, batchId, message: `${batch?.product ?? "Şarj"}, ${machineId} kuyruğunda ${position + 1}. sıraya taşındı.` }); }}
          onRemoveBatch={(batchId) => { const batch = result.batches.find((item) => item.id === batchId); applyManualChange(() => removeBatchManually(seed, result, batchId), "Şarj plandan çıkarıldı", { type: "remove", machineId: batch?.machineId, batchId, message: `${batch?.product ?? "Şarj"} plandan çıkarıldı.` }); }}
          onLockThrough={lockThrough}
          onUnlockQueue={unlockQueue}
          onSaveWorkOrder={saveBatchWorkOrder}
          onUpdateBatchQuantity={updateBatchQuantity}
          onSaveCurrentJob={saveCurrentJob}
          onCompleteCurrentJob={completeCurrentJob}
          onStartProcessCurrentJob={beginDownstreamCurrentJob}
          onReplanProcess={replanDownstreamProcess}
          onPlaceProcessQueue={placeDownstreamQueueOperation}
          onReplaceProcessCurrentJob={replaceDownstreamCurrentJob}
          onSaveProcessCurrentJob={saveDownstreamCurrentJob}
          onCompleteProcessCurrentJob={finishDownstreamCurrentJob}
          onCompleteWipOperation={finishWipOperation}
        />
      )}
      {view === "parameters" && <ParametersView seed={seed} updateSeed={updateSeed} />}
      {view === "settings" && isAdmin && <SettingsView seed={seed} updateSeed={applyCalendarChange} updatePlanningInputs={updateSeed} />}
      {view === "scenarios" && <ScenariosView scenarios={scenarioSummaries} loadedScenarios={scenarios} total={scenarioListTotal} loading={scenarioListLoading} error={scenarioListError} planningHistory={planningHistory} onFetchScenario={fetchScenarioDetail} onLoad={loadScenario} onLoadMore={() => fetchScenarioPage(scenarioSummaries.length)} onRetry={() => fetchScenarioPage(0, true)} onRestoreRevision={restorePlanningRevision} onDelete={deleteStoredScenario} onUpdate={updateStoredScenario} onImport={importStoredScenarios} />}
      <FeedbackFeature pagePath={pageTitle(view)} workspace={view === "feedback"} />
      {archiveOpen && <ProductionArchiveDrawer seed={seed} onClose={() => setArchiveOpen(false)} onStatusChange={changeProductionHistoryStatus} onEdit={editProductionHistoryEntry} onAllocate={allocateProductionHistory} />}
      {adviceOpen && <RecommendationCenter advice={visiblePlanningAdvice} allAdviceCount={planningAdvice.length} dismissedCount={dismissedAdviceIds.length} focusedOrderId={adviceOrderId} focusedMachineId={adviceMachineId} focusedProduct={seed.orders.find((order) => order.id === adviceOrderId)?.product ?? ""} currentPlan={result.state === "planned" && !dirty} onClose={() => setAdviceOpen(false)} onShowAll={() => { setAdviceOrderId(null); setAdviceMachineId(null); }} onApply={applyAdvice} onDismiss={dismissAdvice} onRestoreDismissed={restoreDismissedAdvice} onManual={(product) => { setQuickManualProduct(product); setAdviceOpen(false); }} />}
      {quickManualProduct !== null && <QuickManualBatchDialog key={quickManualProduct || "all"} seed={seed} result={result} initialProduct={quickManualProduct} onClose={() => setQuickManualProduct(null)} onSave={(product, machineId, quantity, position) => { applyManualChange(() => addBatchManually(seed, result, product, machineId, quantity, position), "Manuel şarj eklendi", { type: "add", machineId, message: `${product}, ${machineId} kuyruğuna manuel eklendi.` }); setQuickManualProduct(null); }} />}
      {planRunOpen && <PlanRunDialog seed={seed} existingPlanAvailable={result.state === "planned" && !dirty} existingPlannedBatchCount={result.batches.filter((batch) => batch.status === "planned").length} lockedBatchCount={result.batches.filter((batch) => batch.status === "planned" && batch.locked).length} onClose={() => setPlanRunOpen(false)} onCompare={previewPlanRuns} onRun={runScenario} />}
      {automaticComparisonOpen && seed.lastAutomaticPlan && automaticComparisonAvailable && <AutomaticPlanComparisonDialog seed={seed} snapshot={seed.lastAutomaticPlan} manualResult={result} onClose={() => setAutomaticComparisonOpen(false)} onRestore={restoreLastAutomaticPlan} />}
      {scenarioSaveOpen && <ScenarioSaveDialog sequence={nextScenarioNumber(scenarioSummaries)} onClose={() => setScenarioSaveOpen(false)} onSave={saveScenario} />}
      {scenarioLoadReport && <ScenarioLoadReportDialog report={scenarioLoadReport} onClose={() => setScenarioLoadReport(null)} />}
      {operationAlert && <div key={operationAlert.id} className="operation-alert-toast" role="alert" aria-live="assertive"><Warning size={21} weight="fill" /><div><strong>İşlem uygulanmadı</strong><p>{operationAlert.message}</p></div><button onClick={() => setOperationAlert(null)} aria-label="Operasyon uyarısını kapat"><X size={15} /></button><i /></div>}
      {historyMessage && <div className="operation-undo" role="status"><span><strong>İşlem geçmişi</strong><small>{historyMessage}</small></span><button disabled={!historyPast.length} onClick={undoLastOperation}><ArrowCounterClockwise size={14} /> Geri al</button><button disabled={!historyFuture.length} onClick={redoLastOperation}><ArrowClockwise size={14} /> Yinele</button><button className="operation-undo-close" onClick={() => setHistoryMessage("")} aria-label="İşlem geçmişi bildirimini kapat"><X size={14} /></button></div>}
      {planningSyncConflict && <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog sync-conflict-dialog" role="dialog" aria-modal="true" aria-label="Planlama verisi çakışması"><div className="operational-dialog-head"><span className="dialog-icon maintenance"><Warning size={20} weight="fill" /></span><div><span>SENKRONİZASYON ÇAKIŞMASI</span><h2>Ortak veri başka bir oturumda değişti</h2><p>Daha yeni ortak kayıt sessizce ezilmedi. Hangi sürümle devam edeceğinizi açıkça seçin.</p></div><button className="delete-button" onClick={() => setPlanningSyncConflict(null)} aria-label="Senkronizasyon uyarısını kapat"><X size={16} /></button></div><div className="sync-conflict-versions"><span><small>Bu cihazdaki son değişiklik</small><strong>{formatFactoryDateTime(window.localStorage.getItem(planningStateUpdatedAtKey) ?? "")}</strong></span><span><small>Ortak veritabanındaki sürüm</small><strong>{formatFactoryDateTime(planningSyncConflict.updatedAt)}</strong></span></div><div className="sync-conflict-note"><strong>Ortak veriyi yükle</strong><span>Bu cihazdaki henüz aktarılmamış değişikliklerin yerine diğer kullanıcının yeni sürümü gelir.</span><strong>Bu cihazı yayınla</strong><span>Ortak sürümün üzerine bu ekrandaki planlama ve üretim durumu açık onayınızla yazılır.</span></div><div className="drawer-actions"><button className="secondary" onClick={() => setPlanningSyncConflict(null)}>Şimdilik kapat</button><button className="secondary" onClick={acceptRemotePlanningState}>Ortak veriyi yükle</button><button className="primary" onClick={() => void forceLocalPlanningStateSync()}>Bu cihazı yeni sürüm olarak yayınla</button></div></section></div>}
      {productionPullConfirmOpen && <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog production-pull-dialog" role="dialog" aria-modal="true" aria-label="Üretim verilerini staging'e alma onayı"><div className="operational-dialog-head"><span className="dialog-icon shift"><ArrowClockwise size={20} /></span><div><span>STAGING VERİ YENİLEME</span><h2>Yerel çalışma korunarak üretim verileri güncellensin mi?</h2><p>Bu işlem üretimi yalnızca okur. Üretim ortamında hiçbir kayıt eklenmez, düzenlenmez veya silinmez.</p></div><button className="delete-button" onClick={() => setProductionPullConfirmOpen(false)} aria-label="Üretim verisi alma onayını kapat"><X size={16} /></button></div><div className="sync-conflict-note"><strong>Değişecek yer: staging</strong><span>Yerelde değişen plan, çalışan işler, proses ilerlemesi ve teslimatlar korunur. Son alınan üretim kopyasına göre yerelde değişmeyen veriler güncellenir. Aynı kayıtta farklılık varsa yerel çalışma önceliklidir; yerel senaryolar silinmez.</span><strong>Değişmeyecek yer: üretim</strong><span>Erdinç’in kullandığı üretim planlama sitesi kaynak olarak kalacak; staging’den üretime veri gönderilmeyecek.</span></div><div className="drawer-actions"><button className="secondary" onClick={() => setProductionPullConfirmOpen(false)}>Vazgeç</button><button className="primary" disabled={productionPullStatus === "pulling"} onClick={() => void pullProductionState()}><ArrowClockwise size={15} /> {productionPullStatus === "pulling" ? "Prod’dan alınıyor…" : "Prod verilerini staging’e al"}</button></div></section></div>}
      <ProductTour open={tourOpen} onClose={() => setTourOpen(false)} onNavigate={changeView} canManageSettings={isAdmin} />
      <RaviChat view={view} onNavigate={navigateFromRavi} />
    </main></RaviContextProvider>
  );
}

frontend/features/planning/advice/Recomm.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { Field } from "@/features/planning/shared/controls";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { type PlanningSeed, type ScenarioResult, diameterNumeric, isMachineEligibleForProduct } from "@/lib/planning";
import { type PlanningAdvice } from "@/lib/planning-advice";
import { productSetupFamilyLabel, resolvedProductSetupFamily } from "@/lib/setup-families";
import { CaretDown, CaretRight, CheckCircle, Lightbulb, Lock, Plus, Warning, Wrench, X } from "@phosphor-icons/react";
import { useEffect, useState } from "react";

export function RecommendationCenter({ advice, allAdviceCount, dismissedCount, focusedOrderId, focusedMachineId, focusedProduct, currentPlan, onClose, onShowAll, onApply, onDismiss, onRestoreDismissed, onManual }: { advice: PlanningAdvice[]; allAdviceCount: number; dismissedCount: number; focusedOrderId: string | null; focusedMachineId: string | null; focusedProduct: string; currentPlan: boolean; onClose: () => void; onShowAll: () => void; onApply: (item: PlanningAdvice) => void; onDismiss: (id: string) => void; onRestoreDismissed: () => void; onManual: (product: string) => void }) {
  const [kindFilter, setKindFilter] = useState<"all" | PlanningAdvice["kind"]>("all");
  useRaviScreenContext("advice", { kindFilter, focusedOrderId, focusedMachineId, focusedProduct, currentPlan,
    allAdviceCount, dismissedCount, recommendations: advice.slice(0, 8).map(({ id, title, detail, kind }) => ({ id, title, detail, kind })) });
  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [onClose]);
  const scopeAdvice = focusedOrderId
    ? advice.filter((item) => item.orderId === focusedOrderId)
    : focusedMachineId
      ? advice.filter((item) => item.machineId === focusedMachineId)
      : advice;
  const visible = kindFilter === "all" ? scopeAdvice : scopeAdvice.filter((item) => item.kind === kindFilter);
  const kindLabel = (kind: PlanningAdvice["kind"]) => kind === "move" ? "TEZGAH DEĞİŞİKLİĞİ" : kind === "overtime" ? "MESAİ" : kind === "pull-forward" ? "GELECEK HAFTADAN" : "EK ŞARJ";
  const heading = focusedProduct ? `${focusedProduct} tavsiyeleri` : focusedMachineId ? `${focusedMachineId} tezgah tavsiyeleri` : "Uygulanabilir tavsiyeler";
  return <div className="advice-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside className="advice-drawer" role="dialog" aria-modal="true" aria-label="Planlama tavsiyeleri"><header><div className="advice-title-icon"><Lightbulb size={19} weight="fill" /></div><div><span>PLANLAMA ASİSTANI</span><h2>{heading}</h2><p>Her öneri mevcut plan üzerinde denenmiş ve yalnızca ölçülebilir fayda sağlıyorsa gösterilmiştir.</p></div><button className="delete-button" onClick={onClose} aria-label="Tavsiyeleri kapat"><X size={16} /></button></header><div className="advice-scope"><span><strong>{visible.length}</strong> açık tavsiye</span><label className="advice-kind-filter"><small>Tavsiye tipi</small><select value={kindFilter} onChange={(event) => setKindFilter(event.target.value as "all" | PlanningAdvice["kind"])}><option value="all">Tüm tipler</option><option value="move">Tezgah değişikliği</option><option value="add-charge">Ek şarj</option><option value="pull-forward">Gelecek haftadan</option><option value="overtime">Mesai</option></select></label>{(focusedOrderId || focusedMachineId) && <button onClick={onShowAll}>Tüm tavsiyeleri göster</button>}{dismissedCount > 0 && <button onClick={onRestoreDismissed}>{dismissedCount} göz ardı edileni geri getir</button>}</div><div className="advice-list">{!currentPlan ? <div className="advice-empty"><Lightbulb size={25} /><strong>Güncel plan gerekli</strong><span>Tavsiyeleri hesaplamak için planı çalıştırın.</span></div> : visible.length ? visible.map((item) => <RecommendationAdviceCard key={item.id} item={item} kindLabel={kindLabel} onApply={onApply} onDismiss={onDismiss} />) : <div className="advice-empty"><CheckCircle size={25} weight="fill" /><strong>{scopeAdvice.length && kindFilter !== "all" ? "Bu tavsiye tipinde kayıt yok" : focusedProduct ? "Bu sipariş için açık tavsiye yok" : focusedMachineId ? `${focusedMachineId} için açık tavsiye yok` : "Açık tavsiye yok"}</strong><span>{scopeAdvice.length && kindFilter !== "all" ? "Başka bir tavsiye tipi seçin veya tüm tipleri gösterin." : allAdviceCount && dismissedCount ? "Tavsiyeler göz ardı edilmiş olabilir; üstteki geri getirme bağlantısını kullanabilirsiniz." : "Mevcut plan için ek şarj, taşıma, gelecek haftadan iş çekme veya mesai müdahalesi gerekmiyor."}</span>{scopeAdvice.length && kindFilter !== "all" ? <button className="secondary" onClick={() => setKindFilter("all")}>Tüm tipleri göster</button> : focusedProduct && <button className="secondary" onClick={() => onManual(focusedProduct)}><Plus size={14} /> Yine de manuel şarj aç</button>}</div>}</div>{focusedProduct && currentPlan && visible.length > 0 && <div className="advice-manual-fallback"><span><strong>Farklı bir çözüm mü gerekiyor?</strong><small>Tezgahı ve miktarı kendiniz seçerek manuel şarj açabilirsiniz.</small></span><button onClick={() => onManual(focusedProduct)}><Plus size={13} /> Manuel şarj</button></div>}</aside></div>;
}

function RecommendationAdviceCard({ item, kindLabel, onApply, onDismiss }: { item: PlanningAdvice; kindLabel: (kind: PlanningAdvice["kind"]) => string; onApply: (item: PlanningAdvice) => void; onDismiss: (id: string) => void }) {
  const addAction = item.action.type === "add-charge" ? item.action : null;
  const [pickerOpen, setPickerOpen] = useState(false);
  const [machineId, setMachineId] = useState(addAction?.machineId ?? "");
  const initialMachine = addAction?.machineOptions.find((option) => option.machineId === addAction.machineId);
  const [position, setPosition] = useState(addAction?.position ?? initialMachine?.queueLength ?? 0);
  const selectedMachine = addAction?.machineOptions.find((option) => option.machineId === machineId) ?? initialMachine;
  const allowedPositions = selectedMachine
    ? Array.from({ length: selectedMachine.queueLength - selectedMachine.lockedCount + 1 }, (_, index) => selectedMachine.lockedCount + index)
    : [];
  const selectedMachineId = selectedMachine?.machineId ?? item.machineId;

  useEffect(() => {
    if (selectedMachine && (position < selectedMachine.lockedCount || position > selectedMachine.queueLength)) setPosition(selectedMachine.queueLength);
  }, [position, selectedMachine?.lockedCount, selectedMachine?.queueLength]);

  function chooseMachine(nextMachineId: string) {
    const nextMachine = addAction?.machineOptions.find((option) => option.machineId === nextMachineId);
    setMachineId(nextMachineId);
    setPosition(nextMachine?.queueLength ?? 0);
  }

  function applySelected() {
    if (!addAction || !selectedMachine) {
      onApply(item);
      return;
    }
    onApply({
      ...item,
      machineId: selectedMachine.machineId,
      action: { ...addAction, machineId: selectedMachine.machineId, position },
    });
  }

  return <article className={`advice-item ${item.kind}`}>
    <div className="advice-item-head"><span>{kindLabel(item.kind)}{selectedMachineId ? ` · ${selectedMachineId}` : ""}</span><strong>{item.title}</strong></div>
    <p>{item.detail}</p>
    <div className="advice-benefit"><CheckCircle size={14} weight="fill" /><span>{item.benefit}</span></div>
    {addAction && pickerOpen && <div className="advice-machine-picker">
      <div className="advice-machine-picker-head"><span><strong>Parametrelerde izin verilen tezgahlar</strong><small>Tezgahı ve şarjın kuyrukta ekleneceği sırayı seçin.</small></span><b>{addAction.machineOptions.length} seçenek</b></div>
      <div className="advice-machine-options">{addAction.machineOptions.map((option) => {
        const hasMatchingJob = option.matchingPositions.length > 0;
        return <button key={option.machineId} className={option.machineId === selectedMachine?.machineId ? "selected" : ""} onClick={() => chooseMachine(option.machineId)} aria-pressed={option.machineId === selectedMachine?.machineId}>
          <span><strong>{option.machineId}</strong><small>{option.machineName}</small></span>
          <span className={hasMatchingJob ? "queue-match" : "queue-empty"}>{hasMatchingJob ? <CheckCircle size={12} weight="fill" /> : null}<small>{hasMatchingJob ? `Bu iş kuyrukta · ${option.matchingPositions.map((index) => `${index + 1}.`).join(", ")} sıra` : "Bu iş kuyrukta yok"}</small></span>
          <em>{option.queueLength}/14 şarj</em>
        </button>;
      })}</div>
      {selectedMachine && <label className="advice-position-picker"><span><small>Eklenecek sıra</small><strong>{selectedMachine.machineId} iş kuyruğu</strong></span><select value={position} onChange={(event) => setPosition(Number(event.target.value))}>{allowedPositions.map((queuePosition) => <option key={queuePosition} value={queuePosition}>{adviceQueuePositionLabel(selectedMachine.queue, queuePosition)}</option>)}</select></label>}
      {selectedMachine && selectedMachine.lockedCount > 0 && <p className="advice-locked-note"><Lock size={12} /> İlk {selectedMachine.lockedCount} şarj kilitli olduğu için yeni iş bunların arkasına eklenebilir.</p>}
    </div>}
    <footer>
      <button className="advice-dismiss" onClick={() => onDismiss(item.id)}>Göz ardı et</button>
      {addAction && <button className={`advice-machine-toggle ${pickerOpen ? "open" : ""}`} onClick={() => setPickerOpen((open) => !open)} aria-expanded={pickerOpen}><Wrench size={13} /> Tezgah seç <CaretDown size={11} /></button>}
      <button className="advice-apply" onClick={applySelected}>{item.actionLabel}<CaretRight size={13} /></button>
    </footer>
  </article>;
}

function adviceQueuePositionLabel(queue: Array<{ product: string }>, position: number): string {
  if (position >= queue.length) return `${position + 1}. sıra · Kuyruk sonu`;
  return `${position + 1}. sıra · ${queue[position].product} öncesi`;
}

export function QuickManualBatchDialog({ seed, result, initialProduct, onClose, onSave }: { seed: PlanningSeed; result: ScenarioResult; initialProduct: string; onClose: () => void; onSave: (product: string, machineId: string, quantity: number, position: number) => void }) {
  const activeProducts = seed.products.filter((product) => seed.orders.some((order) => order.quantity > 0 && order.product.toUpperCase() === product.product.toUpperCase()));
  const firstProduct = activeProducts.find((product) => product.product.toUpperCase() === initialProduct.toUpperCase()) ?? activeProducts[0];
  const [productCode, setProductCode] = useState(firstProduct?.product ?? "");
  const product = activeProducts.find((item) => item.product === productCode);
  const eligibleMachines = product ? seed.machines.filter((machine) => machine.active && (machine.rates[product.product.toUpperCase()] ?? 0) > 0 && isMachineEligibleForProduct(seed, machine.id, product.product)) : [];
  const [machineId, setMachineId] = useState(eligibleMachines[0]?.id ?? "");
  const [quantity, setQuantity] = useState(firstProduct?.batchSize ?? 0);
  const selectedMachine = eligibleMachines.find((machine) => machine.id === machineId) ?? eligibleMachines[0];
  const queueLength = selectedMachine ? result.batches.filter((batch) => batch.status === "planned" && batch.machineId === selectedMachine.id).length : 0;
  const [position, setPosition] = useState(queueLength);
  const chargeCount = product?.batchSize ? quantity / product.batchSize : 0;
  const validQuantity = Boolean(product?.batchSize && quantity > 0 && Number.isInteger(chargeCount));
  const valid = result.state === "planned" && Boolean(product && selectedMachine && validQuantity);

  useEffect(() => {
    const nextProduct = activeProducts.find((item) => item.product === productCode);
    if (nextProduct) setQuantity(nextProduct.batchSize);
  }, [productCode]);
  useEffect(() => {
    if (!eligibleMachines.some((machine) => machine.id === machineId)) setMachineId(eligibleMachines[0]?.id ?? "");
  }, [eligibleMachines.map((machine) => machine.id).join("|"), machineId]);
  useEffect(() => setPosition(queueLength), [machineId, queueLength]);

  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog quick-manual-dialog" role="dialog" aria-modal="true" aria-label="Planlama ekranından manuel şarj ekleme"><div className="operational-dialog-head"><span className="dialog-icon manual"><Plus size={20} /></span><div><span>HIZLI MANUEL PLANLAMA</span><h2>Tezgah kuyruğuna şarj ekle</h2><p>Sipariş ve Planlama ekranından ayrılmadan ürün, tezgah ve kuyruk sırasını seçin.</p></div><button className="delete-button" onClick={onClose} aria-label="Manuel şarj penceresini kapat"><X size={16} /></button></div>{activeProducts.length ? <div className="operational-dialog-form quick-manual-form"><Field label="Ürün"><select value={productCode} onChange={(event) => setProductCode(event.target.value)}>{activeProducts.map((item) => <option key={item.product} value={item.product}>{item.product} · {productSetupFamilyLabel(resolvedProductSetupFamily(item.product, item.setupFamily))} · Ø {new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 2 }).format(diameterNumeric(item.diameter))}</option>)}</select></Field><Field label="Tezgah"><select value={selectedMachine?.id ?? ""} onChange={(event) => setMachineId(event.target.value)}>{eligibleMachines.map((machine) => <option key={machine.id} value={machine.id}>{machine.id} · {machine.name}</option>)}</select></Field><Field label={`Miktar · ${formatNumber(product?.batchSize ?? 0)} katları`}><input type="number" min={product?.batchSize || 1} step={product?.batchSize || 1} value={quantity} onChange={(event) => setQuantity(Number(event.target.value))} /></Field><Field label="Kuyruk sırası"><select value={position} onChange={(event) => setPosition(Number(event.target.value))}>{Array.from({ length: queueLength + 1 }, (_, index) => <option key={index} value={index}>{index + 1}. sıra</option>)}</select></Field><div className="manual-batch-preview"><span><small>Standart şarj</small><strong>{formatNumber(product?.batchSize ?? 0)}</strong></span><span><small>Şarj sayısı</small><strong>{validQuantity ? formatNumber(chargeCount) : "—"}</strong></span><span><small>Tezgah kuyruğu</small><strong>{queueLength} planlı şarj</strong></span></div>{!eligibleMachines.length && <p className="form-error">Bu ürün için hızı tanımlı ve aktif tezgah bulunamadı.</p>}{quantity > 0 && !validQuantity && <p className="form-error">Miktar standart şarj büyüklüğünün tam katı olmalıdır.</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(product!.product, selectedMachine!.id, quantity, position)}><Plus size={14} /> Şarjı ekle</button></div></div> : <div className="quick-manual-empty"><Warning size={23} /><strong>Manuel şarja uygun aktif sipariş yok</strong><span>Önce Siparişler sayfasında adet girin ve planı çalıştırın.</span><button className="secondary" onClick={onClose}>Kapat</button></div>}</section></div>;
}

frontend/features/planning/archive/Produ.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { Field, SetupFamilyBadge } from "@/features/planning/shared/controls";
import { formatInputDate, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { useApiFetch } from "@/lib/api";
import { factoryDateInput, factoryDateTimeInput } from "@/lib/factory-time";
import { formatInteger as formatNumber } from "@/lib/number-format";
import {
  formatExcelDate,
  type PlanningSeed,
  type ProductionHistoryAllocationInput,
  type ProductionHistoryEntry,
  type ProductionInventoryStatus,
  productSetupFamily,
} from "@/lib/planning";
import { type ProcessKind, processLabel } from "@/lib/process-master-data";
import {
  productionArchiveDateLabel,
  productionArchiveEventDate,
  productionArchiveEventSerial,
  productionArchiveProcessSnapshot,
} from "@/lib/production-archive";
import { type ProductSetupFamily, productSetupFamilyLabel } from "@/lib/setup-families";
import { wipStageLabel } from "@/lib/wip-ledger";
import {
  Archive,
  ArrowCounterClockwise,
  CheckCircle,
  FileXls,
  FloppyDisk,
  MagnifyingGlass,
  PencilSimple,
  Trash,
  Warning,
  X,
} from "@phosphor-icons/react";
import { useEffect, useState } from "react";
import { productionProcessLabel } from "../shared/production";

export function ProductionArchiveDrawer({ seed, onClose, onStatusChange, onEdit, onAllocate }: { seed: PlanningSeed; onClose: () => void; onStatusChange: (entryId: string, status: ProductionInventoryStatus, actionDate?: string, reason?: string) => void; onEdit: (entryId: string, actualQuantity: number, completedAt: number) => boolean; onAllocate: (entryId: string, input: ProductionHistoryAllocationInput) => boolean }) {
  const apiFetch = useApiFetch();
  const entries = (seed.productionHistory ?? []).filter((entry) => entry.inventoryStatus !== "voided");
  const [activeStatus, setActiveStatus] = useState<Exclude<ProductionInventoryStatus, "voided">>("semi-finished");
  const [query, setQuery] = useState("");
  const [machineId, setMachineId] = useState("");
  const [product, setProduct] = useState("");
  const [familyFilter, setFamilyFilter] = useState<ProductSetupFamily | "">("");
  const [operationFilter, setOperationFilter] = useState<ProductionHistoryEntry["process"] | "">("");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [deliveryEntry, setDeliveryEntry] = useState<ProductionHistoryEntry | null>(null);
  const [deliveryDraft, setDeliveryDraft] = useState({ actualQuantity: 0, completedDate: "", deliveredQuantity: 0, deliveryDate: factoryDateTimeInput(), remainderAction: "keep" as "keep" | "scrap" });
  const [editEntry, setEditEntry] = useState<ProductionHistoryEntry | null>(null);
  const [editDraft, setEditDraft] = useState({ actualQuantity: 0, completedDate: "" });
  const [voidEntry, setVoidEntry] = useState<ProductionHistoryEntry | null>(null);
  const [restoreEntry, setRestoreEntry] = useState<ProductionHistoryEntry | null>(null);
  const [restoreReason, setRestoreReason] = useState("");
  const [restoreDate, setRestoreDate] = useState(factoryDateInput());
  const [exporting, setExporting] = useState(false);
  useRaviScreenContext("archive", { activeStatus, query, machineId, product, familyFilter, operationFilter, start, end,
    deliveryEntry, editEntry, voidEntry, restoreEntry });
  const [exportError, setExportError] = useState("");
  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      if (voidEntry) setVoidEntry(null);
      else if (restoreEntry) setRestoreEntry(null);
      else if (editEntry) setEditEntry(null);
      else if (deliveryEntry) setDeliveryEntry(null);
      else onClose();
    };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [deliveryEntry, editEntry, onClose, restoreEntry, voidEntry]);
  const archiveToday = inputDateToSerial(factoryDateInput()) + 1;
  const wipContextByEntryId = new Map(entries.map((entry) => {
    const sourceIds = new Set([entry.id, entry.sourceEntryId].filter(Boolean));
    const lots = (seed.wipLots ?? []).filter((lot) => sourceIds.has(lot.sourceHistoryEntryId) && lot.availableQuantity > 0);
    const snapshot = productionArchiveProcessSnapshot(seed, entry, archiveToday);
    const stages = [...new Set(lots.map((lot) => wipStageLabel(lot.stage, lot.readyAt < archiveToday)))];
    const currentOperation = snapshot.currentAssignments.map((assignment) => `${processLabel(assignment.process)} · ${assignment.resourceId}`).join(" · ");
    const nextOperation = snapshot.nextProcesses.map((process) => processLabel(process)).join(" · ");
    return [entry.id, {
      stage: stages.join(" · ") || (entry.inventoryStatus === "semi-finished" ? "Yarı mamül · konum kaydı yok" : ""),
      latestCompletedProcess: snapshot.latestCompletedProcess,
      currentOperation,
      nextOperation,
      operationCodes: [...new Set([snapshot.latestCompletedProcess, ...snapshot.currentProcesses, ...snapshot.nextProcesses])],
      lotIds: snapshot.lotIds,
      availableQuantity: snapshot.availableQuantity,
      deliveryReadyQuantity: snapshot.deliveryReadyQuantity,
    }] as const;
  }));
  const machineOptions = [...new Set(entries.map((entry) => entry.machineId))].sort((left, right) => left.localeCompare(right, "tr", { numeric: true }));
  const productOptions = [...new Set(entries.map((entry) => entry.product))].sort((left, right) => left.localeCompare(right));
  const startSerial = inputDateToSerial(start);
  const endSerial = inputDateToSerial(end);
  const normalizedQuery = query.trim().toLocaleLowerCase("tr-TR");
  const filteredEntries = (status: Exclude<ProductionInventoryStatus, "voided">) => entries
    .filter((entry) => (entry.inventoryStatus ?? "semi-finished") === status)
    .filter((entry) => !machineId || entry.machineId === machineId)
    .filter((entry) => !product || entry.product === product)
    .filter((entry) => !familyFilter || productSetupFamily(seed, entry.product) === familyFilter)
    .filter((entry) => !operationFilter || entry.process === operationFilter || wipContextByEntryId.get(entry.id)?.operationCodes.includes(operationFilter as Exclude<ProcessKind, "turning">))
    .filter((entry) => !startSerial || productionArchiveEventSerial(entry, status) >= startSerial)
    .filter((entry) => !endSerial || productionArchiveEventSerial(entry, status) <= endSerial)
    .filter((entry) => !normalizedQuery || `${entry.id} ${entry.sourceEntryId ?? ""} ${entry.product} ${productSetupFamilyLabel(productSetupFamily(seed, entry.product))} ${entry.workOrder} ${entry.machineId} ${entry.machineName} ${productionProcessLabel(entry.process)} ${wipContextByEntryId.get(entry.id)?.lotIds.join(" ") ?? ""} ${wipContextByEntryId.get(entry.id)?.stage ?? ""} ${wipContextByEntryId.get(entry.id)?.currentOperation ?? ""} ${wipContextByEntryId.get(entry.id)?.nextOperation ?? ""}`.toLocaleLowerCase("tr-TR").includes(normalizedQuery))
    .sort((left, right) => productionArchiveEventSerial(right, status) - productionArchiveEventSerial(left, status) || right.archivedAt.localeCompare(left.archivedAt));
  const statusEntries = entries.filter((entry) => (entry.inventoryStatus ?? "semi-finished") === activeStatus);
  const visible = filteredEntries(activeStatus);
  const totalQuantity = visible.reduce((sum, entry) => sum + (activeStatus === "semi-finished" ? wipContextByEntryId.get(entry.id)?.availableQuantity ?? entry.completedQuantity : entry.completedQuantity), 0);
  const visibleMachineCount = new Set(visible.map((entry) => entry.machineId)).size;
  const filtered = Boolean(query || machineId || product || familyFilter || operationFilter || start || end);
  const statusCount = (status: Exclude<ProductionInventoryStatus, "voided">) => entries.filter((entry) => (entry.inventoryStatus ?? "semi-finished") === status).length;

  function clearFilters() {
    setQuery("");
    setMachineId("");
    setProduct("");
    setFamilyFilter("");
    setOperationFilter("");
    setStart("");
    setEnd("");
  }

  function openDelivery(entry: ProductionHistoryEntry) {
    setDeliveryDraft({ actualQuantity: entry.completedQuantity, completedDate: serialToInputDate(entry.completedAt), deliveredQuantity: entry.completedQuantity, deliveryDate: factoryDateTimeInput(), remainderAction: "keep" });
    setDeliveryEntry(entry);
  }

  function openEdit(entry: ProductionHistoryEntry) {
    setEditDraft({ actualQuantity: entry.completedQuantity, completedDate: serialToInputDate(entry.completedAt) });
    setEditEntry(entry);
  }

  async function exportArchive() {
    setExporting(true);
    setExportError("");
    try {
      const statuses: Array<Exclude<ProductionInventoryStatus, "voided">> = ["semi-finished", "delivered", "scrapped"];
      const sections = statuses.map((status) => {
        const rows = filteredEntries(status);
        return {
          status,
          eventDateLabel: productionArchiveDateLabel(status),
          totalAvailable: entries.filter((entry) => (entry.inventoryStatus ?? "semi-finished") === status).length,
          rows: rows.map((entry) => ({
            completedAt: productionArchiveEventDate(entry, status),
            archivedAt: entry.archivedAt,
            machineId: entry.machineId,
            machineName: entry.machineName,
            workOrder: entry.workOrder,
            product: entry.product,
            setupFamily: productSetupFamily(seed, entry.product) ?? "",
            process: wipContextByEntryId.get(entry.id)?.latestCompletedProcess ?? entry.process,
            stage: status === "semi-finished" ? wipContextByEntryId.get(entry.id)?.stage ?? "" : "",
            currentOperation: status === "semi-finished" ? wipContextByEntryId.get(entry.id)?.currentOperation ?? "" : "",
            nextOperation: status === "semi-finished" ? wipContextByEntryId.get(entry.id)?.nextOperation ?? "" : "",
            completedQuantity: entry.completedQuantity,
            availableQuantity: status === "semi-finished" ? wipContextByEntryId.get(entry.id)?.availableQuantity ?? entry.completedQuantity : entry.completedQuantity,
            plannedStart: serialToInputDate(entry.start),
            plannedEnd: serialToInputDate(entry.plannedEnd),
            deliveryDate: entry.deliveredAt ?? "",
          })),
        };
      });
      if (!sections.some((section) => section.rows.length)) throw new Error("Excel’e aktarılacak arşiv kaydı bulunamadı.");
      const payload = {
        generatedAt: new Date().toISOString(),
        filtered,
        sections,
      };
      const response = await apiFetch("/production-archive/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
      if (!response.ok) {
        const body = await response.json().catch(() => ({})) as { detail?: string };
        throw new Error(body.detail || "Üretim arşivi Excel’i oluşturulamadı.");
      }
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? `Uretim_Arsivi_${new Date().toISOString().slice(0, 10)}.xlsx`;
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (reason) {
      setExportError(reason instanceof Error ? reason.message : "Üretim arşivi Excel’i oluşturulamadı.");
    } finally {
      setExporting(false);
    }
  }

  return <div className="archive-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside className="archive-drawer" role="dialog" aria-modal="true" aria-label="Üretim arşivi">
    <header className="archive-head"><div><span>TAMAMLANAN ÜRETİMLER</span><h2>Üretim arşivi</h2><p>Yarı mamulün son tamamlanan, şu anda çalışan ve sıradaki prosesini teslimata kadar izleyin.</p></div><div className="archive-head-actions"><button className="archive-export" disabled={exporting || !entries.length} onClick={() => void exportArchive()}><FileXls size={15} /> {exporting ? "Hazırlanıyor…" : "WIP + teslim + ıskarta Excel"}</button><button onClick={onClose} aria-label="Üretim arşivini kapat"><X size={17} /></button></div></header>
    <div className="archive-status-tabs" role="tablist" aria-label="Üretim arşivi durumu"><button role="tab" aria-selected={activeStatus === "semi-finished"} className={activeStatus === "semi-finished" ? "selected" : ""} onClick={() => setActiveStatus("semi-finished")}><span>Yarı mamuller</span><b>{statusCount("semi-finished")}</b><small>Siparişlerde mevcut üretime dahil</small></button><button role="tab" aria-selected={activeStatus === "delivered"} className={activeStatus === "delivered" ? "selected" : ""} onClick={() => setActiveStatus("delivered")}><span>Teslim edilenler</span><b>{statusCount("delivered")}</b><small>Planlama hesabının dışında</small></button><button role="tab" aria-selected={activeStatus === "scrapped"} className={activeStatus === "scrapped" ? "selected" : ""} onClick={() => setActiveStatus("scrapped")}><span>Iskartalar</span><b>{statusCount("scrapped")}</b><small>Seçilebilir ve izlenebilir kayıp</small></button></div>
    {exportError && <div className="archive-export-error" role="alert"><Warning size={14} weight="fill" /><span>{exportError}</span><button onClick={() => setExportError("")}>Kapat</button></div>}
    <div className="archive-filters"><label className="archive-search"><MagnifyingGlass size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Şarj no, ürün, proses, aşama veya tezgah ara" /></label><Field label="Tezgah / istasyon"><select value={machineId} onChange={(event) => setMachineId(event.target.value)}><option value="">Tüm tezgahlar</option>{machineOptions.map((id) => <option key={id} value={id}>{id} · {entries.find((entry) => entry.machineId === id)?.machineName || "İsimsiz"}</option>)}</select></Field><Field label="Ürün"><select value={product} onChange={(event) => setProduct(event.target.value)}><option value="">Tüm ürünler</option>{productOptions.map((code) => <option key={code} value={code}>{code} · {productSetupFamilyLabel(productSetupFamily(seed, code))}</option>)}</select></Field><Field label="Ürün ailesi"><select value={familyFilter} onChange={(event) => setFamilyFilter(event.target.value as ProductSetupFamily | "")}><option value="">Tüm aileler</option><option value="piston">Piston</option><option value="center-pin">Center Pin</option></select></Field><Field label="Operasyon"><select value={operationFilter} onChange={(event) => setOperationFilter(event.target.value as ProductionHistoryEntry["process"] | "")}><option value="">Tüm operasyonlar</option><option value="turning">Torna</option><option value="drilling">Delme</option><option value="deburring">Çapak alma</option><option value="gkm">GKM</option></select></Field><Field label="Başlangıç"><input type="date" value={start} onChange={(event) => setStart(event.target.value)} /></Field><Field label="Bitiş"><input type="date" min={start} value={end} onChange={(event) => setEnd(event.target.value)} /></Field>{filtered && <button className="archive-clear" onClick={clearFilters}><X size={13} /> Temizle</button>}</div>
    <div className="archive-summary"><span><small>{activeStatus === "semi-finished" ? "Yarı mamul iş" : activeStatus === "delivered" ? "Teslim edilen iş" : "Iskarta kaydı"}</small><strong>{formatNumber(visible.length)}</strong></span><span><small>{activeStatus === "semi-finished" ? "Toplam WIP" : activeStatus === "scrapped" ? "Toplam ıskarta" : "Toplam teslim"}</small><strong>{formatNumber(totalQuantity)} adet</strong></span><span><small>Tezgah</small><strong>{visibleMachineCount}</strong></span><em>{filtered ? `${formatNumber(statusEntries.length)} kaydın içinden filtrelendi` : activeStatus === "semi-finished" ? "Bu miktarlar siparişlerde “mevcut” sayılır" : activeStatus === "scrapped" ? "Bu miktarlar üretim kaybı olarak saklanır" : "Bu miktarlar yeni planı karşılamaz"}</em></div>
    <div className="archive-table"><table><thead><tr><th>{productionArchiveDateLabel(activeStatus)}</th><th>Tezgah</th><th>Şarj / iş emri</th><th>Ürün</th><th>Son tamamlanan</th><th>Güncel proses / aşama</th><th className="numeric">{activeStatus === "scrapped" ? "Iskarta" : activeStatus === "semi-finished" ? "WIP miktarı" : "Teslim edilen"}</th><th>Planlanan başlangıç</th><th>Planlanan bitiş</th><th>İşlem</th></tr></thead><tbody>{visible.map((entry) => { const context = wipContextByEntryId.get(entry.id); return <tr key={entry.id}><td><strong className="archive-key-date">{formatInputDate(productionArchiveEventDate(entry, activeStatus))}</strong>{activeStatus !== "semi-finished" && <small>Üretim {formatExcelDate(entry.completedAt)} tamamlandı</small>}<small>{new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short" }).format(new Date(entry.archivedAt))} arşivlendi</small>{entry.deliveredAt && <small className="archive-delivery-date">{entry.deliveredAtTime ? new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short", timeZone: "Europe/Istanbul" }).format(new Date(entry.deliveredAtTime)) : formatInputDate(entry.deliveredAt)} teslim</small>}{entry.statusChangeReason && <small>{entry.statusChangedBy || "Planlama oturumu"}: {entry.statusChangeReason}</small>}</td><td><b>{entry.machineId}</b><small>{entry.machineName}</small></td><td><strong className="tracking-number">{entry.workOrder || "—"}</strong></td><td><strong>{entry.product}</strong><SetupFamilyBadge family={productSetupFamily(seed, entry.product)} /></td><td><span className="archive-process"><ProcessIcon process={context?.latestCompletedProcess ?? entry.process} size={13} /> {productionProcessLabel(context?.latestCompletedProcess ?? entry.process)}</span></td><td>{activeStatus === "semi-finished" ? <><span className={`archive-wip-stage ${context?.currentOperation ? "running" : ""}`}>{context?.currentOperation || context?.stage || "Konum kaydı yok"}</span>{context?.currentOperation ? <small>Aşama: {context.stage}</small> : context?.nextOperation ? <small>Sıradaki: {context.nextOperation}</small> : null}</> : <span className="archive-wip-stage">—</span>}</td><td className="numeric"><strong className="archive-key-quantity">{formatNumber(activeStatus === "semi-finished" ? context?.availableQuantity ?? entry.completedQuantity : entry.completedQuantity)}</strong></td><td>{formatExcelDate(entry.start)}</td><td>{formatExcelDate(entry.plannedEnd)}</td><td><div className="archive-row-actions">{activeStatus === "semi-finished" ? <button className="archive-deliver" disabled={(context?.deliveryReadyQuantity ?? 0) <= 0} title={(context?.deliveryReadyQuantity ?? 0) > 0 ? `${formatNumber(context?.deliveryReadyQuantity ?? 0)} adet teslimata hazır` : "Rota ve GKM sonrası teslimat tamponu tamamlanmadı"} onClick={() => openDelivery(entry)}><CheckCircle size={13} /> Teslim / parçala</button> : <button className="archive-restore" onClick={() => { setRestoreEntry(entry); setRestoreReason(""); setRestoreDate(factoryDateInput()); }}><ArrowCounterClockwise size={13} /> Yarı mamule geri al</button>}<button className="archive-edit" onClick={() => openEdit(entry)}><PencilSimple size={13} /> Adet / tarih</button><button className="archive-delete" onClick={() => setVoidEntry(entry)}><Trash size={13} /> Kaydı sil</button></div></td></tr>; })}</tbody></table>{visible.length === 0 && <div className="archive-empty"><Archive size={28} /><strong>{statusEntries.length ? "Bu filtrelerle kayıt bulunamadı" : activeStatus === "semi-finished" ? "Bekleyen yarı mamul yok" : activeStatus === "scrapped" ? "Henüz ıskarta kaydı yok" : "Henüz teslim edilen kayıt yok"}</strong><span>{statusEntries.length ? "Tarih veya diğer filtreleri değiştirin." : activeStatus === "semi-finished" ? "Tezgah ekranında “İş tamamlandı” işlemi yapıldığında kayıtlar burada birikecek." : activeStatus === "scrapped" ? "Teslimat sırasında kalan miktarı ıskartaya ayırdığınızda burada izlenir." : "Yarı mamul listesindeki teslimat işlemleri burada saklanacak."}</span>{filtered && <button className="secondary" onClick={clearFilters}>Filtreleri temizle</button>}</div>}</div>
  </aside>
    {deliveryEntry && <div className="archive-action-backdrop" role="presentation"><section className="completion-dialog archive-action-dialog archive-allocation-dialog" role="dialog" aria-modal="true" aria-label={`${deliveryEntry.product} teslimat ve ıskarta ayrımı`}><CheckCircle size={24} /><span>FİİLİ ÜRETİM VE TESLİMAT</span><h2>{deliveryEntry.product}</h2><p>Gerçek tamamlanan adedi girin. Teslim edilen kısmı ayırın; kalan miktarı yarı mamulde tutun veya ıskartaya çevirin.</p><div className="archive-allocation-grid"><Field label="Fiili tamamlanan adet"><input type="number" min="1" step="1" value={deliveryDraft.actualQuantity || ""} onChange={(event) => setDeliveryDraft({ ...deliveryDraft, actualQuantity: Number(event.target.value), deliveredQuantity: Math.min(deliveryDraft.deliveredQuantity, Number(event.target.value)) })} /></Field><Field label="Gerçek tamamlanma tarihi"><input type="date" value={deliveryDraft.completedDate} onChange={(event) => setDeliveryDraft({ ...deliveryDraft, completedDate: event.target.value })} /></Field><Field label="Teslim edilen adet"><input type="number" min="0" max={deliveryDraft.actualQuantity} step="1" value={deliveryDraft.deliveredQuantity} onChange={(event) => setDeliveryDraft({ ...deliveryDraft, deliveredQuantity: Number(event.target.value) })} /></Field><Field label="Teslim tarihi ve saati"><input type="datetime-local" disabled={deliveryDraft.deliveredQuantity === 0} value={deliveryDraft.deliveryDate} onChange={(event) => setDeliveryDraft({ ...deliveryDraft, deliveryDate: event.target.value })} /></Field></div><div className="archive-remainder"><span><small>Kalan miktar</small><strong>{formatNumber(Math.max(0, deliveryDraft.actualQuantity - deliveryDraft.deliveredQuantity))} adet</strong></span>{deliveryDraft.actualQuantity > deliveryDraft.deliveredQuantity && <div role="radiogroup" aria-label="Kalan miktar işlemi"><label><input type="radio" name="remainder-action" checked={deliveryDraft.remainderAction === "keep"} onChange={() => setDeliveryDraft({ ...deliveryDraft, remainderAction: "keep" })} /><span><strong>Yarı mamulde bırak</strong><small>Sonraki teslimatta kullanılabilir</small></span></label><label className="scrap-choice"><input type="radio" name="remainder-action" checked={deliveryDraft.remainderAction === "scrap"} onChange={() => setDeliveryDraft({ ...deliveryDraft, remainderAction: "scrap" })} /><span><strong>Iskartaya ayır</strong><small>Iskartalar listesinde izlenir</small></span></label></div>}</div><div className="drawer-actions"><button className="secondary" onClick={() => setDeliveryEntry(null)}>Vazgeç</button><button className="primary" disabled={!deliveryDraft.actualQuantity || !deliveryDraft.completedDate || deliveryDraft.deliveredQuantity > deliveryDraft.actualQuantity || (deliveryDraft.deliveredQuantity === 0 && deliveryDraft.remainderAction === "keep") || (deliveryDraft.deliveredQuantity > 0 && !deliveryDraft.deliveryDate)} onClick={() => { const saved = onAllocate(deliveryEntry.id, { actualQuantity: deliveryDraft.actualQuantity, completedAt: inputDateToSerial(deliveryDraft.completedDate), deliveredQuantity: deliveryDraft.deliveredQuantity, deliveryDate: deliveryDraft.deliveryDate, remainderAction: deliveryDraft.remainderAction }); if (saved) { setDeliveryEntry(null); setActiveStatus(deliveryDraft.deliveredQuantity > 0 ? "delivered" : "scrapped"); } }}><CheckCircle size={15} /> Teslimat ayrımını kaydet</button></div></section></div>}
    {editEntry && <div className="archive-action-backdrop" role="presentation"><section className="completion-dialog archive-action-dialog" role="dialog" aria-modal="true" aria-label={`${editEntry.product} fiili üretim düzenleme`}><PencilSimple size={24} /><span>FİİLİ ÜRETİMİ DÜZENLE</span><h2>{editEntry.product}</h2><p>Planlanan değerleri değiştirmeden, sahada gerçekleşen tamamlanma adedi ve tarihini düzeltin.</p><Field label="Fiili tamamlanan adet"><input type="number" min="1" step="1" value={editDraft.actualQuantity || ""} onChange={(event) => setEditDraft({ ...editDraft, actualQuantity: Number(event.target.value) })} /></Field><Field label="Gerçek tamamlanma tarihi"><input type="date" value={editDraft.completedDate} onChange={(event) => setEditDraft({ ...editDraft, completedDate: event.target.value })} /></Field><div className="drawer-actions"><button className="secondary" onClick={() => setEditEntry(null)}>Vazgeç</button><button className="primary" disabled={!editDraft.actualQuantity || !editDraft.completedDate} onClick={() => { if (onEdit(editEntry.id, editDraft.actualQuantity, inputDateToSerial(editDraft.completedDate))) setEditEntry(null); }}><FloppyDisk size={15} /> Değişiklikleri kaydet</button></div></section></div>}
    {restoreEntry && <div className="archive-action-backdrop" role="presentation"><section className="completion-dialog archive-action-dialog" role="dialog" aria-modal="true" aria-label={`${restoreEntry.product} yarı mamule geri alma onayı`}><ArrowCounterClockwise size={24} /><span>TERS HAREKET ONAYI</span><h2>Yarı mamule geri alınsın mı?</h2><p>{restoreEntry.product} · {formatNumber(restoreEntry.completedQuantity)} adet, teslimata hazır yarı mamül durumuna dönecek. Miktar yalnızca bir kez geri eklenecek ve işlem denetim geçmişine yazılacak.</p><Field label="Geçerlilik tarihi"><input type="date" value={restoreDate} onChange={(event) => setRestoreDate(event.target.value)} /></Field><Field label="Geri alma nedeni"><textarea value={restoreReason} onChange={(event) => setRestoreReason(event.target.value)} placeholder="Örn. yanlış şarj teslim edildi olarak işaretlendi" /></Field><div className="drawer-actions"><button className="secondary" onClick={() => setRestoreEntry(null)}>Vazgeç</button><button className="primary" disabled={!restoreDate || !restoreReason.trim()} onClick={() => { onStatusChange(restoreEntry.id, "semi-finished", restoreDate, restoreReason); setRestoreEntry(null); }}><ArrowCounterClockwise size={15} /> Onayla ve geri al</button></div></section></div>}
    {voidEntry && <div className="archive-action-backdrop" role="presentation"><section className="reset-dialog archive-action-dialog" role="dialog" aria-modal="true" aria-label={`${voidEntry.product} arşiv kaydını silme onayı`}><Warning size={24} weight="fill" /><span>KAYIT SİLİNECEK</span><h2>Kaydı silmeyi onaylıyor musunuz?</h2><p>{voidEntry.product} · {formatNumber(voidEntry.completedQuantity)} adet kayıt listeden kaldırılacak ve planlama hesabına katılmayacak. İşlem geçmişi güvenlik için korunur.</p><div className="drawer-actions"><button className="secondary" onClick={() => setVoidEntry(null)}>Vazgeç</button><button className="danger-confirm" onClick={() => { onStatusChange(voidEntry.id, "voided"); setVoidEntry(null); }}><Trash size={15} /> Evet, kaydı sil</button></div></section></div>}
  </div>;
}

