"use client";

import { NumberHelp } from "@/features/planning/shared/controls";
import { formatHours, formatInputDate, signedNumber } from "@/features/planning/shared/format";
import { compareWithAutomaticPlan, type PlanOutcomeMetrics } from "@/lib/automatic-plan-comparison";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { formatExcelDate, type AutomaticPlanSnapshot, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { ArrowCounterClockwise, ArrowsLeftRight, CheckCircle, Warning, X } from "@phosphor-icons/react";
import { useMemo, useState } from "react";

export function AutomaticPlanComparisonDialog({ seed, snapshot, manualResult, onClose, onRestore }: { seed: PlanningSeed; snapshot: AutomaticPlanSnapshot; manualResult: ScenarioResult; onClose: () => void; onRestore: () => void }) {
  const comparison = useMemo(() => compareWithAutomaticPlan(seed, snapshot, manualResult), [manualResult, seed, snapshot]);
  const [showAllOrders, setShowAllOrders] = useState(false);
  const [restoreConfirmation, setRestoreConfirmation] = useState(false);
  const visibleOrders = showAllOrders ? comparison.orders : comparison.orders.filter((order) => order.changed);
  const automaticCreatedAt = new Intl.DateTimeFormat("tr-TR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(snapshot.createdAt));
  const metricRows: Array<{ label: string; detail: string; key: keyof PlanOutcomeMetrics; format: (value: number | null, metrics: PlanOutcomeMetrics) => string; direction: "higher" | "lower" | "neutral"; date?: boolean; hours?: boolean }> = [
    { label: "Termin gününe kadar hazır", detail: "Delme, çapak alma, GKM ve korunan +1 iş günü dahil", key: "readyByDue", format: (value) => formatNumber(value ?? 0), direction: "higher" },
    { label: "Eksik üretim", detail: "Planda hiç karşılanmayan adet", key: "shortage", format: (value) => formatNumber(value ?? 0), direction: "lower" },
    { label: "Geciken miktar", detail: "Planlı fakat terminden sonra hazır", key: "lateQuantity", format: (value) => formatNumber(value ?? 0), direction: "lower" },
    { label: "İlk teslimata hazır", detail: "İlk hazır üretim tarihi", key: "firstReadyAt", format: formatComparisonDate, direction: "lower", date: true },
    { label: "Son teslimata hazır", detail: "Son hazır üretim tarihi", key: "lastReadyAt", format: formatComparisonDate, direction: "lower", date: true },
    { label: "En kötü termin sapması", detail: "Siparişler içindeki en geç sonuç", key: "dueDeltaDays", format: (value, metrics) => formatDueTiming(value, metrics.shortage), direction: "lower" },
    { label: "Plan bitişi", detail: "Tezgâhlardaki son üretim bitişi", key: "planCompletion", format: formatComparisonDate, direction: "lower", date: true },
    { label: "Setup saati", detail: "Tüm planlı şarjların toplamı", key: "setupHours", format: (value) => formatHours(value ?? 0), direction: "lower", hours: true },
  ];
  return (
    <div className="confirmation-backdrop automatic-comparison-backdrop" role="presentation">
      <section className="automatic-comparison-dialog" role="dialog" aria-modal="true" aria-label="Otomatik ve manuel plan karşılaştırması">
        <header className="automatic-comparison-head">
          <span className="dialog-icon automatic-comparison-icon"><ArrowsLeftRight size={20} /></span>
          <div>
            <span>MANUEL PLAN ETKİSİ</span>
            <h2>Otomatik planla karşılaştır</h2>
            <p>Manuel plandaki teslimat ve termin sonuçları, {automaticCreatedAt} tarihinde çalıştırılan son otomatik planla karşılaştırılıyor.</p>
          </div>
          <button className="delete-button" onClick={onClose} aria-label="Karşılaştırmayı kapat"><X size={17} /></button>
        </header>

        <div className="automatic-comparison-body">
          <section className="automatic-comparison-summary">
            <div className="automatic-comparison-section-title">
              <div><span>GENEL SONUÇ</span><strong>Manuel değişikliklerin toplam etkisi</strong></div>
              <small>Yeşil iyileşme, kırmızı olumsuz değişim gösterir.</small>
            </div>
            <div className="automatic-summary-table">
              <div className="head"><span>Ölçüt</span><span>Otomatik</span><span>Manuel</span><span>Fark</span></div>
              {metricRows.map((row) => {
                const automatic = comparison.automatic[row.key];
                const manual = comparison.manual[row.key];
                const delta = row.date
                  ? dateDelta(automatic, manual)
                  : automatic === null || manual === null ? null : manual - automatic;
                const description = `${row.label}: ${row.detail}.`;
                return <div className="row" key={row.key}><span><strong>{row.label}</strong><small>{row.detail}</small></span><span><NumberHelp description={description}>{row.format(automatic, comparison.automatic)}</NumberHelp></span><span><NumberHelp description={description}>{row.format(manual, comparison.manual)}</NumberHelp></span><span className={comparisonDeltaTone(delta, row.direction)}><NumberHelp description="Manuel sonuç ile otomatik sonuç arasındaki değişim.">{formatComparisonDelta(delta, row.date, row.hours)}</NumberHelp></span></div>;
              })}
            </div>
          </section>

          <section className="automatic-order-impact">
            <div className="automatic-comparison-section-title">
              <div><span>SİPARİŞ BAZINDA</span><strong>{comparison.changedOrderCount ? `${formatNumber(comparison.changedOrderCount)} siparişin sonucu değişti` : "Sipariş sonucu değişmedi"}</strong></div>
              <div className="comparison-order-filter"><button className={!showAllOrders ? "selected" : ""} onClick={() => setShowAllOrders(false)}>Değişenler · {formatNumber(comparison.changedOrderCount)}</button><button className={showAllOrders ? "selected" : ""} onClick={() => setShowAllOrders(true)}>Tümü · {formatNumber(comparison.orders.length)}</button></div>
            </div>
            {visibleOrders.length ? <div className="automatic-order-table"><table><thead><tr><th>Sipariş</th><th>Termin hazır</th><th>Eksik</th><th>Geciken</th><th>İlk hazır</th><th>Son hazır</th><th>Termin sapması</th></tr></thead><tbody>{visibleOrders.map((order) => <tr key={order.orderId}><td><strong>{order.product}</strong><small>{formatInputDate(order.dueDate)} termin · {formatNumber(order.quantity)} adet</small></td><ComparisonOrderCell automatic={formatNumber(order.automatic.readyByDue)} manual={formatNumber(order.manual.readyByDue)} delta={order.manual.readyByDue - order.automatic.readyByDue} direction="higher" /><ComparisonOrderCell automatic={formatNumber(order.automatic.shortage)} manual={formatNumber(order.manual.shortage)} delta={order.manual.shortage - order.automatic.shortage} direction="lower" /><ComparisonOrderCell automatic={formatNumber(order.automatic.lateQuantity)} manual={formatNumber(order.manual.lateQuantity)} delta={order.manual.lateQuantity - order.automatic.lateQuantity} direction="lower" /><ComparisonOrderCell automatic={formatComparisonDate(order.automatic.firstReadyAt)} manual={formatComparisonDate(order.manual.firstReadyAt)} delta={dateDelta(order.automatic.firstReadyAt, order.manual.firstReadyAt)} direction="lower" date /><ComparisonOrderCell automatic={formatComparisonDate(order.automatic.lastReadyAt)} manual={formatComparisonDate(order.manual.lastReadyAt)} delta={dateDelta(order.automatic.lastReadyAt, order.manual.lastReadyAt)} direction="lower" date /><ComparisonOrderCell automatic={formatDueTiming(order.automatic.dueDeltaDays, order.automatic.shortage)} manual={formatDueTiming(order.manual.dueDeltaDays, order.manual.shortage)} delta={nullableDelta(order.automatic.dueDeltaDays, order.manual.dueDeltaDays)} direction="lower" date /></tr>)}</tbody></table></div> : <div className="automatic-order-empty"><CheckCircle size={18} weight="fill" /><span>Manuel değişiklikler siparişlerin termin, eksik veya geciken miktar sonuçlarını değiştirmedi.</span></div>}
          </section>
        </div>

        <footer className="automatic-comparison-actions">
          {restoreConfirmation ? <div className="automatic-restore-confirmation"><Warning size={17} weight="fill" /><span><strong>Manuel değişiklikler kaldırılsın mı?</strong><small>Son otomatik plan geri yüklenecek. Bu işlem daha sonra “Geri al” ile tersine çevrilebilir.</small></span><button className="secondary" onClick={() => setRestoreConfirmation(false)}>Vazgeç</button><button className="danger-confirm" onClick={onRestore}><ArrowCounterClockwise size={14} /> Otomatik plana dön</button></div> : <><button className="secondary" onClick={onClose}>Kapat</button><button className="automatic-restore-action" onClick={() => setRestoreConfirmation(true)}><ArrowCounterClockwise size={14} /> Otomatik plana dön</button></>}
        </footer>
      </section>
    </div>
  );
}

function ComparisonOrderCell({ automatic, manual, delta, direction, date = false }: { automatic: string; manual: string; delta: number | null; direction: "higher" | "lower" | "neutral"; date?: boolean }) {
  return <td><strong>{manual}</strong><small>Otomatik · {automatic}</small><em className={comparisonDeltaTone(delta, direction)}>{formatComparisonDelta(delta, date)}</em></td>;
}

function formatComparisonDate(value: number | null) { return value ? formatExcelDate(value, { day: "2-digit", month: "short", year: "numeric" }) : "—"; }

function formatDueTiming(value: number | null, shortage: number) {
  if (value === null) return shortage > 0 ? "Tamamlanmıyor" : "—";
  if (value === 0) return "Termin günü";
  return `${Math.abs(value)} gün ${value < 0 ? "erken" : "geç"}`;
}

function nullableDelta(automatic: number | null, manual: number | null) { return automatic === null || manual === null ? null : manual - automatic; }

function dateDelta(automatic: number | null, manual: number | null) { return automatic === null || manual === null ? null : Math.floor(manual) - Math.floor(automatic); }

function formatComparisonDelta(value: number | null, date = false, hours = false) {
  if (value === null) return "—";
  if (Math.abs(value) < 0.000001) return "Değişmedi";
  if (date) return `${Math.abs(Math.round(value))} gün ${value < 0 ? "önce" : "sonra"}`;
  if (hours) return `${value > 0 ? "+" : "−"}${new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 1 }).format(Math.abs(value))} sa`;
  return signedNumber(value);
}

function comparisonDeltaTone(value: number | null, direction: "higher" | "lower" | "neutral") {
  if (value === null || Math.abs(value) < 0.000001 || direction === "neutral") return "neutral";
  const improved = direction === "higher" ? value > 0 : value < 0;
  return improved ? "improved" : "worse";
}

frontend/features/planning/board/Capacit.source:
"use client";

import { ProcessIcon } from "@/components/ProcessIcon";

import { Field, NumberHelp } from "@/features/planning/shared/controls";
import { formatPercent, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { buildCapacityReport, suggestedCapacityRange, type MachineCapacity } from "@/lib/capacity-analytics";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { excelSerialToDate, formatExcelDate, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { processLabel } from "@/lib/process-master-data";
import { Clock, X } from "@phosphor-icons/react";
import { useMemo, useState } from "react";

export function CapacityDrawer({ seed, result, onClose }: { seed: PlanningSeed; result: ScenarioResult; onClose: () => void }) {
  const suggested = useMemo(() => suggestedCapacityRange(seed, result), [result, seed]);
  const planEnd = Math.ceil(Math.max(suggested.end, result.summary.completion || suggested.end));
  const [start, setStart] = useState(suggested.start);
  const [end, setEnd] = useState(suggested.end);
  const report = useMemo(() => buildCapacityReport(seed, result, start, end, { includeDownstream: true }), [end, result, seed, start]);
  const [selectedMachineId, setSelectedMachineId] = useState(report.machines[0]?.machineId ?? "");
  const selected = report.machines.find((machine) => machine.machineId === selectedMachineId) ?? report.machines[0];
  const overtimeMachineCount = report.machines.filter((machine) => machine.overtimeCapacityHours > 0).length;

  function setQuickRange(days: number | "plan") {
    setEnd(days === "plan" ? planEnd : start + days - 1);
  }

  return <div className="capacity-backdrop" role="presentation"><aside className="capacity-drawer" role="dialog" aria-modal="true" aria-label="Tezgah dolulukları">
    <header className="capacity-head"><div><span>KAPASİTE ANALİZİ</span><h2>Tüm proseslerin dolulukları</h2><p>Torna, delme, çapak alma ve GKM iş merkezlerini seçilen tarihlerdeki gerçek vardiya kapasitesiyle karşılaştırır.</p></div><button onClick={onClose} aria-label="Tezgah doluluklarını kapat"><X size={17} /></button></header>
    <div className="capacity-filters">
      <Field label="Başlangıç"><input type="date" value={serialToInputDate(start)} onChange={(event) => { const next = inputDateToSerial(event.target.value); setStart(next); if (next > end) setEnd(next); }} /></Field>
      <Field label="Bitiş"><input type="date" min={serialToInputDate(start)} value={serialToInputDate(end)} onChange={(event) => setEnd(Math.max(start, inputDateToSerial(event.target.value)))} /></Field>
      <div className="capacity-presets"><span>Hızlı aralık</span><div><button onClick={() => setQuickRange(7)}>7 gün</button><button onClick={() => setQuickRange(30)}>30 gün</button><button onClick={() => setQuickRange("plan")}>Tüm plan</button></div></div>
      <div className="capacity-scope"><strong><NumberHelp description="Kapasite analizine dahil edilen toplam takvim günü.">{report.dayCount} gün</NumberHelp></strong><span>{formatExcelDate(report.start)} – {formatExcelDate(report.end)}</span></div>
    </div>
    <div className="capacity-summary">
      <span><small>Genel doluluk</small><strong><NumberHelp description="Planlanan setup ve üretim saatlerinin kullanılabilir toplam vardiya saatlerine oranı.">{formatPercent(report.utilization)}</NumberHelp></strong><em>{formatNumber(report.plannedHours)} / {formatNumber(report.availableHours)} saat</em></span>
      <span><small>Boş kapasite</small><strong><NumberHelp description="Seçili tarihlerde aktif tezgâhlarda henüz kullanılmayan normal çalışma saati.">{formatNumber(report.idleHours)} sa</NumberHelp></strong><em>Seçili aralıkta kullanılabilir</em></span>
      <span className="overtime"><small>Mesai kapasitesi</small><strong><NumberHelp description="Normal vardiyanın üzerine tanımlanmış toplam ek çalışma saati.">{formatNumber(report.overtimeCapacityHours)} sa</NumberHelp></strong><em>{overtimeMachineCount} tezgahta · kullanılan {formatNumber(report.overtimeLoadHours)} sa</em></span>
      <span><small>Kapalı kapasite</small><strong><NumberHelp description="Bakım, tatil veya vardiya azaltımı nedeniyle üretime kapalı toplam saat.">{formatNumber(report.downtimeHours)} sa</NumberHelp></strong><em>Bakım veya vardiya azaltımı</em></span>
    </div>
    <div className="capacity-body">
      <section className="capacity-ranking"><div className="capacity-section-head"><div><strong>Tezgah karşılaştırması</strong><span>Oran, planlanan saatin kullanılabilir saate bölümüdür.</span></div><div className="capacity-legend"><i className="normal" /> Normal yük <i className="overtime" /> Mesai yükü</div></div>
        <div className="capacity-machine-list">{report.machines.map((machine) => <button key={machine.machineId} className={selected?.machineId === machine.machineId ? "selected" : ""} onClick={() => setSelectedMachineId(machine.machineId)}>
          <span className="capacity-machine-name"><strong>{machine.machineId}</strong><small><ProcessIcon process={machine.process} size={13} /> {processLabel(machine.process)} · {machine.machineName}</small></span>
          <span className="capacity-bar" aria-label={`${machine.machineId} doluluk ${formatPercent(machine.utilization)}`}><i className="normal" style={{ width: `${Math.min(100, machine.availableHours ? machine.regularLoadHours / machine.availableHours * 100 : 0)}%` }} /><i className="overtime" style={{ width: `${Math.min(100, machine.availableHours ? machine.overtimeLoadHours / machine.availableHours * 100 : 0)}%` }} /></span>
          <span className="capacity-machine-value"><strong><NumberHelp focusable={false} description="Bu tezgâhtaki planlı saatin kullanılabilir saate oranı.">{formatPercent(machine.utilization)}</NumberHelp></strong><small>{formatNumber(machine.plannedHours)} / {formatNumber(machine.availableHours)} sa</small></span>
          {machine.overtimeCapacityHours > 0 ? <em className="has-overtime">+{formatNumber(machine.overtimeCapacityHours)} sa mesai</em> : <em>{formatNumber(machine.idleHours)} sa boş</em>}
        </button>)}</div>
      </section>
      {selected && <CapacityMachineDetail machine={selected} />}
    </div>
  </aside></div>;
}

function CapacityMachineDetail({ machine }: { machine: MachineCapacity }) {
  return <section className="capacity-detail"><div className="capacity-detail-head"><div><span><ProcessIcon process={machine.process} size={14} /> {processLabel(machine.process).toLocaleUpperCase("tr-TR")} · GÜNLÜK DAĞILIM</span><h3>{machine.machineId} · {machine.machineName}</h3></div><strong><NumberHelp description="Seçili tezgâhtaki planlı saatin kullanılabilir saate oranı.">{formatPercent(machine.utilization)} dolu</NumberHelp></strong></div>
    <div className="capacity-detail-stats"><span><small>Planlanan</small><strong><NumberHelp description="Bu tezgâhta setup ve üretim için ayrılan toplam saat.">{formatNumber(machine.plannedHours)} sa</NumberHelp></strong></span><span><small>Boş</small><strong><NumberHelp description="Bu tezgâhta seçili aralıkta kullanılabilir kalan normal çalışma saati.">{formatNumber(machine.idleHours)} sa</NumberHelp></strong></span><span className="overtime"><small>Mesai kullanımı</small><strong><NumberHelp description="Planın bu tezgâhta normal vardiya dışından kullandığı toplam saat.">{formatNumber(machine.overtimeLoadHours)} sa</NumberHelp></strong></span></div>
    <div className="capacity-day-scroll"><div className="capacity-days">{machine.days.map((day) => {
      const tone = day.availableHours === 0 ? "closed" : day.overtimeCapacityHours > 0 ? "overtime" : day.utilization >= .85 ? "full" : day.utilization > 0 ? "loaded" : "empty";
      return <div key={day.serial} className={`capacity-day ${tone}`} title={`${formatExcelDate(day.serial)} · ${day.label} · ${formatNumber(day.plannedHours)} / ${formatNumber(day.availableHours)} saat`}>
        <span>{new Intl.DateTimeFormat("tr-TR", { weekday: "short" }).format(excelSerialToDate(day.serial)).slice(0, 2)}</span><strong>{excelSerialToDate(day.serial).getUTCDate()}</strong><i style={{ height: `${Math.max(day.plannedHours > 0 ? 8 : 0, Math.min(100, day.utilization * 100))}%` }} />{day.overtimeCapacityHours > 0 && <em>+{formatNumber(day.overtimeCapacityHours)}</em>}
      </div>;
    })}</div></div>
    <div className="capacity-detail-note"><Clock size={15} /><span><strong>Mesai ayrı hesaplanır.</strong> Turuncu günlerde normal vardiyanın üzerindeki kapasite ve bu kapasitede kullanılan saatler ayrıca gösterilir.</span></div>
  </section>;
}

frontend/features/planning/board/Inspect.source:
"use client";

import { ProcessIcon } from "@/components/ProcessIcon";

import { NumberHelp, SetupFamilyBadge } from "@/features/planning/shared/controls";
import { formatHours } from "@/features/planning/shared/format";
import { queuePosition } from "@/features/planning/shared/production";
import { type PlanningOperations } from "@/features/planning/shared/types";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { formatExcelDate, type Machine, type PlannedBatch, type PlanningSeed, productSetupFamily } from "@/lib/planning";
import { processLabel } from "@/lib/process-master-data";
import { type ProcessOperation, type RoutedProcessJob } from "@/lib/process-planning";
import { plannedBatchDemandOrigin } from "@/lib/weekly-plan-status";
import { ArrowsLeftRight, CheckCircle, Lightbulb, Lock, LockOpen, PencilSimple, Play, Trash, Warning } from "@phosphor-icons/react";
import { useEffect, useState } from "react";
import { BatchQuantityDialog } from "../machines/ProductionDialogs";

export function JourneyInspector({ job, operation, onSelectOperation, onOpenJourney }: { job: RoutedProcessJob; operation: ProcessOperation; onSelectOperation: (operationId: string) => void; onOpenJourney: () => void }) {
  return <aside className="inspector journey-inspector">
    <div className="inspector-kicker">ŞARJ YOLCULUĞU</div>
    <div className="inspector-title"><div><h2>{job.workOrder || job.product}</h2><span>{job.product} · {job.family === "piston" ? "Piston" : "Center Pin"} · {formatNumber(job.quantity)} adet</span></div></div>
    <div className={`status-callout journey-${operation.process}`}><span>Seçili adım</span><strong><ProcessIcon process={operation.process} /> {processLabel(operation.process)} · {operation.resourceId}</strong></div>
    <div className="journey-inspector-route" aria-label={`${job.workOrder || job.product} üretim rotası`}>
      {job.operations.map((step, index) => <button key={step.id} className={`${step.process} ${step.id === operation.id ? "active" : ""}`} onClick={() => onSelectOperation(step.id)}>
        <i>{step.actual ? <CheckCircle size={12} weight="fill" /> : index + 1}</i>
        <span><strong><ProcessIcon process={step.process} size={14} /> {processLabel(step.process)}</strong><small>{step.resourceId} · {formatExcelDate(step.start, { day: "2-digit", month: "short" })} – {formatExcelDate(step.end, { day: "2-digit", month: "short" })}</small></span>
      </button>)}
      <div className="journey-inspector-buffer"><i>+1</i><span><strong>Teslimat tamponu</strong><small>{formatExcelDate(job.deliveryReadyAt, { day: "2-digit", month: "short" })} teslimata hazır</small></span></div>
    </div>
    <button className="journey-open-action" onClick={onOpenJourney}>Tam yolculuk Gantt’ını aç <span>→</span></button>
    <dl className="details journey-operation-facts">
      <div><dt>Durum</dt><dd>{operation.actual ? "Fiili tamamlandı" : "Planlandı"}</dd></div>
      <div><dt>Setup</dt><dd>{formatHours(operation.setupHours)}</dd></div>
      {operation.protectedSetupHoursAfter ? <div><dt>D-02 dönüş rezervi</dt><dd>{formatHours(operation.protectedSetupHoursAfter)}</dd></div> : null}
      <div><dt>Üretim yükü</dt><dd>{formatHours(operation.runHours)}</dd></div>
      <div><dt>Vardiya kapasitesi</dt><dd>{operation.actual ? "Fiili kayıt" : operation.unitsPerShift > 0 ? `${formatNumber(operation.unitsPerShift)} adet` : "Torna planından"}</dd></div>
    </dl>
  </aside>;
}

export function BatchInspector({ seed, batch, currentMachine, machines, queueLength, onMove, onRemove, onLockThrough, onUnlockQueue, onSaveWorkOrder, onUpdateBatchQuantity }: { seed: PlanningSeed; batch: PlannedBatch | null; currentMachine: Machine | null; machines: Machine[]; queueLength: number; onMove: (batchId: string, machineId: string, position: number) => void; onRemove: (batchId: string) => void; onLockThrough: PlanningOperations["onLockThrough"]; onUnlockQueue: PlanningOperations["onUnlockQueue"]; onSaveWorkOrder: PlanningOperations["onSaveWorkOrder"]; onUpdateBatchQuantity: PlanningOperations["onUpdateBatchQuantity"] }) {
  const [targetMachine, setTargetMachine] = useState(batch?.machineId ?? "C-01");
  const [targetPosition, setTargetPosition] = useState(Math.max(0, (batch?.planColumn ?? 13) - 13));
  const [workOrder, setWorkOrder] = useState(batch?.workOrder ?? "");
  const [quantityOpen, setQuantityOpen] = useState(false);
  useEffect(() => {
    setTargetMachine(batch?.machineId ?? "C-01");
    setTargetPosition(Math.max(0, (batch?.planColumn ?? 13) - 13));
    setWorkOrder(batch?.workOrder ?? "");
    setQuantityOpen(false);
  }, [batch?.id, batch?.machineId, batch?.planColumn]);
  if (currentMachine) {
    const current = currentMachine.currentJob;
    return <aside className="inspector"><div className="inspector-kicker">SEÇİLİ MEVCUT İŞ</div><div className="inspector-title"><div><h2>{current.product}</h2><span>{currentMachine.id} · {currentMachine.name}</span></div></div><div className="status-callout"><span>Üretimde</span><strong><Play size={12} weight="fill" /> {currentMachine.id}</strong></div><dl className="details"><div><dt>İş emri</dt><dd>{current.workOrder || "—"}</dd></div><div><dt>Ürün ailesi</dt><dd><SetupFamilyBadge family={productSetupFamily(seed, current.product)} /></dd></div><div><dt>Orijinal miktar</dt><dd><NumberHelp description="Şarj tezgâhta başladığında girilen toplam üretim adedi.">{formatNumber(current.originalQuantity ?? current.quantity)}</NumberHelp></dd></div><div><dt>Kalan miktar</dt><dd><NumberHelp description="Seçili kayıt tarihine göre tezgâhta üretilmesi beklenen kalan adet.">{formatNumber(current.remainingQuantity ?? current.quantity)}</NumberHelp></dd></div><div><dt>Başlangıç</dt><dd>{formatExcelDate(current.start)}</dd></div><div><dt>Tahmini bitiş</dt><dd>{formatExcelDate(current.end)}</dd></div><div><dt>Hesaplanan hız</dt><dd><NumberHelp description="Mevcut işin girilen süre ve miktarından hesaplanan günlük üretim kapasitesi.">{formatNumber(current.dailyRate)} / gün</NumberHelp></dd></div><div><dt>Çap</dt><dd><NumberHelp description="Mevcut ürünün parametre kartındaki parça çapı.">{current.diameter || "—"}</NumberHelp></dd></div></dl><div className="explanation"><div className="explanation-head"><span className="spark">●</span><strong>Devam eden üretim</strong></div><p>Bu kayıt tezgahın halen üretimde olan işidir; planlı kuyruktaki yeni bir şarj değildir. Kuyruğun ilk işi bunun tahmini bitişinden sonra başlar.</p></div></aside>;
  }
  if (!batch) return <aside className="inspector empty-state">Plan boş. Girdileri düzenleyip “Planı Çalıştır” düğmesine basın.</aside>;
  const demandOrigin = plannedBatchDemandOrigin(seed, batch);
  const statusLabel = batch.rolledForwardFrom
    ? `${batch.locked ? "Kilitli · " : ""}Gecikmiş plan`
    : batch.locked
      ? "Kilitli plan"
      : batch.pullForward
        ? `${batch.pullForward.sourceWeekLabel}’den öne çekildi`
        : batch.manuallyPlaced
          ? "Manuel plan"
          : "Planlandı";
  return (<>
    <aside className="inspector">
      <div className="inspector-kicker">SEÇİLİ ŞARJ</div>
      <div className="inspector-title"><div><h2>{batch.product}</h2><span>Kuyrukta {queuePosition(batch.planColumn)}. sıra</span></div></div>
      <div className={`status-callout ${batch.locked ? "locked" : ""} ${batch.pullForward ? "pulled-forward" : ""} ${batch.rolledForwardFrom ? "delayed-plan" : ""}`}><span>{statusLabel}</span><strong>{batch.pullForward ? <Lightbulb size={12} weight="fill" /> : batch.locked ? <Lock size={12} weight="fill" /> : null} {batch.machineId}</strong></div>
      <dl className="details">
        <div><dt>Miktar</dt><dd><NumberHelp description="Bu planlı şarjda üretilecek toplam adet.">{formatNumber(batch.quantity)}</NumberHelp></dd></div>
        <div><dt>Ürün ailesi</dt><dd><SetupFamilyBadge family={productSetupFamily(seed, batch.product)} /></dd></div>
        <div><dt>Başlangıç</dt><dd>{formatExcelDate(batch.start)}</dd></div>
        <div><dt>Bitiş</dt><dd>{formatExcelDate(batch.end)}</dd></div>
        <div><dt>Hesaplanan hız</dt><dd><NumberHelp description="Ürün–tezgâh parametresinden gelen günlük üretim kapasitesi.">{formatNumber(batch.dailyRate)} / gün</NumberHelp></dd></div>
        <div><dt>Setup</dt><dd><NumberHelp description="Önceki şarjdan bu şarja geçiş için plana eklenen hazırlık süresi.">{formatHours(batch.setupHours)}</NumberHelp></dd></div>
        <div><dt>Üretim süresi</dt><dd><NumberHelp description="Setup hariç, bu şarjın miktar ve hızına göre hesaplanan çalışma süresi.">{formatHours(batch.runHours)}</NumberHelp></dd></div>
        <div><dt>Çap</dt><dd><NumberHelp description="Planlanan ürünün parametre kartındaki parça çapı.">Ø {batch.diameter}</NumberHelp></dd></div>
        <div><dt>İş emri</dt><dd>{batch.workOrder || "—"}</dd></div>
        <div><dt>Talep haftası / tarihi</dt><dd>{demandOrigin?.label ?? "Talep haftası bağlı değil"}</dd></div>
        {batch.rolledForwardFrom && <div><dt>Plan durumu</dt><dd>Henüz üretime başlamadı · eski plan başlangıcı {formatExcelDate(batch.rolledForwardFrom)}</dd></div>}
        {batch.pullForward && <div><dt>Kaynak aralık</dt><dd>{batch.pullForward.sourceRangeLabel}</dd></div>}
      </dl>
      <div className="explanation"><div className="explanation-head"><span className="spark">✦</span><strong>Neden bu tezgah?</strong></div><p>{batch.explanation}</p><ul><li>Ürün–tezgah kısıtı sağlandı</li><li>Bitiş müsaitlik penceresi içinde</li><li>{batch.pullForward ? "Müşteri termini değişmeden normal boş kapasite kullanıldı" : batch.demandDueDate ? "En erken açık haftalık hedef önceliklendirildi" : "Setup dahil en erken bitiş değerlendirildi"}</li></ul></div>
      {batch.reason && <div className="risk-note"><Warning size={18} weight="fill" /><div><strong>Şarj yuvarlama</strong><p>{batch.reason}</p></div></div>}
      <div className="manual-controls">
        <div><strong>Manuel planlama</strong><span>Taşıma sonrası kapasite ve tarihler yeniden kontrol edilir.</span></div>
        <label>İş emri / izlenebilirlik<div className="inline-save"><input value={workOrder} onChange={(event) => setWorkOrder(event.target.value)} placeholder="320-…" /><button disabled={workOrder.trim() === (batch.workOrder ?? "")} onClick={() => onSaveWorkOrder(batch, workOrder)}>Kaydet</button></div></label>
        <label>Hedef tezgah<select value={targetMachine} onChange={(event) => setTargetMachine(event.target.value)}>{machines.filter((machine) => machine.active).map((machine) => <option key={machine.id} value={machine.id}>{machine.id}</option>)}</select></label>
        <label>Kuyruk sırası<select value={targetPosition} onChange={(event) => setTargetPosition(Number(event.target.value))}>{Array.from({ length: Math.max(1, queueLength) }, (_, index) => <option key={index} value={index}>{index + 1}. sıra</option>)}</select></label>
        <button className="wide-secondary quantity-action" disabled={batch.locked} onClick={() => setQuantityOpen(true)}><PencilSimple size={15} /> Adedi düzenle</button>
        <button className="wide-secondary" disabled={batch.locked} onClick={() => onMove(batch.id, targetMachine, targetPosition)}><ArrowsLeftRight size={15} /> Taşı / yeniden sırala</button>
        {batch.locked ? <button className="wide-secondary lock-action" onClick={() => onUnlockQueue(batch.machineId)}><LockOpen size={15} /> Tezgah kuyruğu kilidini kaldır</button> : <button className="wide-secondary lock-action" onClick={() => onLockThrough(batch)}><Lock size={15} /> Bu sıraya kadar kilitle</button>}
        <button className="danger-button" disabled={batch.locked} onClick={() => onRemove(batch.id)}><Trash size={15} /> Şarjı plandan çıkar</button>
      </div>
    </aside>
    {quantityOpen && <BatchQuantityDialog batch={batch} setupFamily={productSetupFamily(seed, batch.product)} onClose={() => setQuantityOpen(false)} onSave={(quantity) => { onUpdateBatchQuantity(batch, quantity); setQuantityOpen(false); }} />}
  </>);
}

frontend/features/planning/board/PlanBoa.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessPlacementReview, placementDate } from "@/features/planning/shared/ProcessPlacementReview";

import { ProcessIcon } from "@/components/ProcessIcon";

import { WeeklyDemandRibbon } from "@/features/planning/board/WeeklyDemandRibbon";
import { ShiftOptions } from "@/features/planning/machines/CalendarDialogs";
import { CompleteJobDialog, CurrentJobEditor } from "@/features/planning/machines/ProductionDialogs";
import { Field, NumberHelp } from "@/features/planning/shared/controls";
import { formatHours, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { clampShiftCount, queuePosition } from "@/features/planning/shared/production";
import { type PlanningOperations } from "@/features/planning/shared/types";
import { buildOvertimeEntries } from "@/lib/capacity-analytics";
import { factoryDateInput } from "@/lib/factory-time";
import { buildGanttCalendar, ganttDropStart, ganttPercent } from "@/lib/gantt-scale";
import { buildMachineDiagnostics } from "@/lib/machine-diagnostics";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { buildOperationWorkloads } from "@/lib/operation-workload";
import { buildOperationalMetrics } from "@/lib/operational-metrics";
import {
  type Machine,
  type PlannedBatch,
  type PlanningSeed,
  type ScenarioResult,
  type ShiftCount,
  diameterNumeric,
  formatExcelDate,
  machineDayCapacity,
  moveBatchManually,
  productSetupFamily,
  removeMachineShiftOverrides,
  replaceMachineShiftOverrides,
} from "@/lib/planning";
import { type PlanningAdvice } from "@/lib/planning-advice";
import { compatibleMachineIdsForBatch, machineMatchesPlanningQuery } from "@/lib/planning-search";
import { type ProcessKind, processLabel } from "@/lib/process-master-data";
import {
  type ProcessOperation,
  buildDownstreamProcessPlan,
  clearProcessOperationReschedule,
  previewProcessOperationReschedule, processPlacementSignature,
} from "@/lib/process-planning";
import { productSetupFamilyLabel } from "@/lib/setup-families";
import { batchSplitInsight, buildWeeklyPlanStatus, plannedBatchDemandOrigin } from "@/lib/weekly-plan-status";
import {
  ArrowCounterClockwise,
  ArrowsLeftRight,
  CalendarBlank,
  CaretDown,
  CaretLeft,
  CaretRight,
  CheckCircle,
  Clock,
  DotsSixVertical,
  Lightbulb,
  Lock,
  LockOpen,
  MagnifyingGlass,
  Minus,
  PencilSimple,
  Play,
  Plus,
  Trash,
  Warning,
  Wrench,
  X,
} from "@phosphor-icons/react";
import { useEffect, useMemo, useRef, useState } from "react";

const GANTT_PROCESS_TABS: Array<{ id: ProcessKind; label: string }> = [
  { id: "turning", label: "Torna" },
  { id: "drilling", label: "Delme" },
  { id: "deburring", label: "Çapak Alma" },
  { id: "gkm", label: "GKM" },
];

export function PlanBoard({ seed, result, dirty, advice, selectedBatch, selectedCurrentMachineId, selectedProcessOperationId, onSelectProcessOperation, onSelectBatch, onSelectCurrentJob, onMoveBatch, onLockThrough, onUnlockQueue, onApplyAdvice, onOpenMachineAdvice, onSaveCurrentJob, onCompleteCurrentJob, onOperationError, updateSeed, onRescheduleProcess, onReplanProcess }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; advice: PlanningAdvice[]; selectedBatch: PlannedBatch | null; selectedCurrentMachineId: string | null; selectedProcessOperationId: string; onSelectProcessOperation: (operationId: string) => void; onSelectBatch: (id: string) => void; onSelectCurrentJob: (machineId: string) => void; onMoveBatch: (batchId: string, machineId: string, position: number) => void; onLockThrough: PlanningOperations["onLockThrough"]; onUnlockQueue: PlanningOperations["onUnlockQueue"]; onApplyAdvice: (item: PlanningAdvice) => void; onOpenMachineAdvice: (machineId: string) => void; onSaveCurrentJob: PlanningOperations["onSaveCurrentJob"]; onCompleteCurrentJob: PlanningOperations["onCompleteCurrentJob"]; onOperationError: (message: string) => void; onRescheduleProcess: (operationId: string, resourceId: string, requestedStart: number, signature: string) => import("@/lib/process-planning").ProcessOperation; onReplanProcess: (process: "drilling" | "deburring" | "gkm") => boolean; updateSeed: (mutator: (seed: PlanningSeed) => void) => void }) {
  const [query, setQuery] = useState("");
  const [ganttProcess, setGanttProcess] = useState<ProcessKind>("turning");
  const [diagnosticMachineId, setDiagnosticMachineId] = useState<string | null>(null);
  const [draggedBatchId, setDraggedBatchId] = useState<string | null>(null);
  const [dropTarget, setDropTarget] = useState<{ machineId: string; position: number } | null>(null);
  const [lastDropError, setLastDropError] = useState("");
  const [jobEditorMachineId, setJobEditorMachineId] = useState<string | null>(null);
  const [completeMachineId, setCompleteMachineId] = useState<string | null>(null);
  const [calendarSelection, setCalendarSelection] = useState<{ resourceId: string; process: ProcessKind; serial: number } | null>(null);
  const [recentMovedBatchId, setRecentMovedBatchId] = useState<string | null>(null);
  const [recentMovedProcessOperationId, setRecentMovedProcessOperationId] = useState<string | null>(null);
  const [draggedProcessOperationId, setDraggedProcessOperationId] = useState<string | null>(null);
  const [pendingProcessMove, setPendingProcessMove] = useState<{ operationId: string; resourceId: string; requestedStart: number } | null>(null);
  const [lastAppliedProcessMove, setLastAppliedProcessMove] = useState<ProcessOperation | null>(null);
  const [processMoveSequence, setProcessMoveSequence] = useState(0);
  const [processMoveFeedback, setProcessMoveFeedback] = useState("");
  const movedElementRef = useRef<HTMLButtonElement | null>(null);
  const [processDragOffset, setProcessDragOffset] = useState({ x: 0, y: 0 });
  const [processDropTarget, setProcessDropTarget] = useState<{ resourceId: string; requestedStart: number } | null>(null);
  const todaySerial = inputDateToSerial(factoryDateInput());
  const [viewStart, setViewStart] = useState(todaySerial);
  const [viewDays, setViewDays] = useState(42);
  const turningViewportRef = useRef({ start: todaySerial, days: 42 });
  const gestureRef = useRef<{ batchId: string; startX: number; startY: number; active: boolean; element: HTMLButtonElement } | null>(null);
  const processGestureRef = useRef<{ operationId: string; startX: number; startY: number; active: boolean; grabOffsetDays: number } | null>(null);
  const processDropTargetRef = useRef<{ resourceId: string; requestedStart: number } | null>(null);
  const suppressProcessClickRef = useRef(false);
  const dropTargetRef = useRef<{ machineId: string; position: number } | null>(null);
  const suppressBatchClickRef = useRef(false);
  const plannedBatches = result.batches.filter((batch) => batch.status === "planned");
  const activeMachines = seed.machines.filter((machine) => machine.active);
  const downstreamPlan = useMemo(() => buildDownstreamProcessPlan(seed, result), [result, seed]);
  useEffect(() => {
    if (!lastAppliedProcessMove) return;
    const current = downstreamPlan.operations.find((item) => item.id === lastAppliedProcessMove.id);
    if (!current || current.start !== lastAppliedProcessMove.start || current.end !== lastAppliedProcessMove.end || current.resourceId !== lastAppliedProcessMove.resourceId) {
      setProcessMoveFeedback(""); setRecentMovedProcessOperationId(null); setLastAppliedProcessMove(null);
    }
  }, [downstreamPlan, lastAppliedProcessMove]);
  const compatibleDropMachineIds = useMemo(() => {
    if (!draggedBatchId) return new Set<string>();
    const batch = result.batches.find((item) => item.id === draggedBatchId);
    if (!batch) return new Set<string>();
    return compatibleMachineIdsForBatch(seed, batch);
  }, [draggedBatchId, result.batches, seed]);
  const customerDemand = seed.customerDemand;
  const activeDemandScope = customerDemand?.activeScope;
  const demandStartWeek = customerDemand?.weeks.find((week) => week.id === activeDemandScope?.startWeekId);
  const demandEndWeek = customerDemand?.weeks.find((week) => week.id === activeDemandScope?.endWeekId);
  const diameterHues = useMemo(() => buildDiameterHues(seed, result), [result, seed]);
  const operationWorkloads = useMemo(() => buildOperationWorkloads(seed, result), [result, seed]);
  const selectedWorkload = operationWorkloads[ganttProcess];
  useRaviScreenContext("plan-board", { query, ganttProcess, viewStart, viewDays, diagnosticMachineId,
    jobEditorMachineId, completeMachineId, calendarSelection, selectedWorkload, lastDropError });
  useEffect(() => {
    if (!recentMovedBatchId) return;
    const timeout = window.setTimeout(() => setRecentMovedBatchId(null), 900);
    return () => window.clearTimeout(timeout);
  }, [recentMovedBatchId]);
  useEffect(() => {
    if (!recentMovedProcessOperationId) return;
    const timeout = window.setTimeout(() => setRecentMovedProcessOperationId(null), 4500);
    return () => window.clearTimeout(timeout);
  }, [recentMovedProcessOperationId, processMoveSequence]);
  useEffect(() => {
    if (ganttProcess !== "turning") return;
    if (!demandStartWeek || !demandEndWeek) return;
    const start = inputDateToSerial(demandStartWeek.weekStart);
    const end = inputDateToSerial(demandEndWeek.weekEnd);
    setViewStart(start);
    setViewDays(Math.max(14, Math.min(112, end - start + 1)));
  }, [demandEndWeek?.id, demandStartWeek?.id]);
  const diagnostics = useMemo(() => buildMachineDiagnostics(seed, result, { dirty }), [dirty, result, seed]);
  const adviceByMachine = useMemo(() => {
    const map = new Map<string, PlanningAdvice[]>();
    for (const item of advice) {
      if (!item.machineId) continue;
      map.set(item.machineId, [...(map.get(item.machineId) ?? []), item]);
    }
    return map;
  }, [advice]);
  const selectedDiagnostic = diagnosticMachineId ? diagnostics[diagnosticMachineId] : null;
  const selectedDiagnosticMachine = seed.machines.find((machine) => machine.id === diagnosticMachineId);
  const selectedDiagnosticBatches = diagnosticMachineId ? plannedBatches.filter((batch) => batch.machineId === diagnosticMachineId) : [];
  const selectedLastCharge = [...selectedDiagnosticBatches].sort((left, right) => right.end - left.end || right.planColumn - left.planColumn)[0];
  const selectedMachineAdvice = diagnosticMachineId ? adviceByMachine.get(diagnosticMachineId) ?? [] : [];
  const selectedPullForwardAdvice = selectedMachineAdvice.find((item) => item.kind === "pull-forward");
  const downstreamOperations = downstreamPlan.operations.filter((operation) => !operation.actual && operation.process === ganttProcess);
  const processSetupHues = useMemo(() => buildProcessSetupHues(downstreamPlan.operations), [downstreamPlan.operations]);
  const planStart = ganttProcess === "turning"
    ? plannedBatches.length ? Math.min(...plannedBatches.map((batch) => batch.start)) : Math.min(...activeMachines.map((machine) => machine.availableStart))
    : downstreamOperations.length ? Math.min(...downstreamOperations.map((operation) => operation.start)) : todaySerial;
  const planEnd = ganttProcess === "turning"
    ? Math.max(...activeMachines.map((machine) => machine.planEnd), ...plannedBatches.map((batch) => batch.end))
    : downstreamOperations.length ? Math.max(...downstreamOperations.map((operation) => operation.end)) : todaySerial + 14;
  const horizonStart = Math.floor(viewStart);
  const horizon = Math.max(1, Math.ceil(viewDays));
  const horizonEnd = horizonStart + horizon;
  const operationalMetrics = useMemo(() => buildOperationalMetrics(seed, result, { start: horizonStart, end: horizonEnd - 1 }), [horizonEnd, horizonStart, result, seed]);
  const overtimeEntries = useMemo(() => buildOvertimeEntries(seed, horizonStart, horizonEnd - 1), [horizonEnd, horizonStart, seed]);
  const overtimeEntryKeys = useMemo(() => new Set(overtimeEntries.map((entry) => entry.id)), [overtimeEntries]);
  const overtimeMachineIds = useMemo(() => new Set(overtimeEntries.map((entry) => entry.machineId)), [overtimeEntries]);
  const machineBatchesById = useMemo(() => {
    const map = new Map(seed.machines.map((machine) => [machine.id, [] as PlannedBatch[]]));
    for (const batch of plannedBatches) map.get(batch.machineId)?.push(batch);
    return map;
  }, [plannedBatches, seed.machines]);
  const calendarBandsByMachine = useMemo(() => new Map(activeMachines.map((machine) => [
    machine.id,
    Array.from({ length: horizon }, (_, index) => horizonStart + index)
      .map((serial) => ({ serial, capacity: machineDayCapacity(seed, machine, serial) }))
      .filter(({ capacity }) => capacity.kind !== "normal"),
  ])), [activeMachines, horizon, horizonStart, seed]);
  const processCalendarBandsByResource = useMemo(() => new Map(
    (seed.processMasterData?.resources ?? []).filter((resource) => resource.active && resource.process !== "turning").map((resource) => {
      const calendarSeed = resource.id.startsWith("B-01-S")
        ? {
          ...seed,
          calendarEvents: [
            ...(seed.calendarEvents ?? []),
            ...(seed.calendarEvents ?? []).filter((event) => event.machineId === "B-01").map((event) => ({ ...event, id: `${event.id}-${resource.id}`, machineId: resource.id })),
          ],
        }
        : seed;
      return [resource.id, Array.from({ length: horizon }, (_, index) => horizonStart + index)
        .map((serial) => ({ serial, capacity: machineDayCapacity(calendarSeed, { id: resource.id, shiftFactor: resource.defaultShifts }, serial) }))
        .filter(({ capacity }) => capacity.kind !== "normal")] as const;
    }),
  ), [horizon, horizonStart, seed]);
  const selectedProcessCalendarResource = calendarSelection?.process !== "turning"
    ? seed.processMasterData?.resources.find((resource) => resource.id === calendarSelection?.resourceId)
    : undefined;
  const calendarCapacityTarget: Pick<Machine, "id" | "shiftFactor"> | undefined = calendarSelection?.process === "turning"
    ? seed.machines.find((machine) => machine.id === calendarSelection.resourceId)
    : selectedProcessCalendarResource
      ? { id: selectedProcessCalendarResource.id, shiftFactor: selectedProcessCalendarResource.defaultShifts }
      : undefined;
  const visibleMachines = activeMachines.filter((machine) => machineMatchesPlanningQuery(machine, plannedBatches, query));
  const normalizedProcessQuery = query.trim().toLocaleUpperCase("tr-TR");
  const processResources = (seed.processMasterData?.resources ?? [])
    .filter((resource) => resource.active && resource.process === ganttProcess)
    .map((resource) => ({
      resource,
      gaps: normalizedProcessQuery ? [] : downstreamPlan.gaps.filter((gap) => gap.resourceId === resource.id),
      operations: downstreamOperations
        .filter((operation) => operation.resourceId === resource.id)
        .filter((operation) => !normalizedProcessQuery || `${operation.product} ${operation.workOrder} ${operation.batchId}`.toLocaleUpperCase("tr-TR").includes(normalizedProcessQuery))
        .sort((left, right) => left.start - right.start || left.id.localeCompare(right.id)),
    }))
    .filter(({ resource, operations }) => !normalizedProcessQuery || operations.length > 0 || `${resource.id} ${resource.name}`.toLocaleUpperCase("tr-TR").includes(normalizedProcessQuery));
  const selectedProcessOperation = downstreamOperations.find((operation) => operation.id === selectedProcessOperationId);
  const selectedProcessJob = selectedProcessOperation ? downstreamPlan.jobs.find((job) => job.batchId === selectedProcessOperation.batchId) : undefined;
  const ganttCalendar = useMemo(() => buildGanttCalendar(horizonStart, horizon), [horizon, horizonStart]);
  const demandMonthOptions = useMemo(() => {
    if (!customerDemand?.weeks.length) return [];
    const first = new Date(`${customerDemand.weeks[0].weekStart}T00:00:00Z`);
    const last = new Date(`${customerDemand.weeks.at(-1)!.weekEnd}T00:00:00Z`);
    const months: Array<{ id: string; label: string; start: string; dayCount: number }> = [];
    const cursor = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth(), 1));
    while (cursor <= last) {
      const year = cursor.getUTCFullYear();
      const month = cursor.getUTCMonth();
      const start = `${year}-${String(month + 1).padStart(2, "0")}-01`;
      months.push({
        id: start.slice(0, 7),
        label: new Intl.DateTimeFormat("tr-TR", { month: "long", year: "numeric", timeZone: "UTC" }).format(cursor),
        start,
        dayCount: new Date(Date.UTC(year, month + 1, 0)).getUTCDate(),
      });
      cursor.setUTCMonth(cursor.getUTCMonth() + 1);
    }
    return months;
  }, [customerDemand]);
  const visibleMonthId = serialToInputDate(horizonStart).slice(0, 7);
  const holidaySerials = useMemo(() => new Set(seed.holidays.map((holiday) => Math.floor(holiday.serial))), [seed.holidays]);
  const dayWidth = horizon <= 14 ? 44 : horizon <= 28 ? 30 : horizon <= 42 ? 24 : horizon <= 70 ? 18 : 16;
  const timelineStyle = { "--gantt-days": horizon, "--gantt-min-width": `${Math.max(680, horizon * dayWidth)}px` } as React.CSSProperties;
  const dropPreview = useMemo(() => {
    if (!draggedBatchId || !dropTarget) return null;
    try {
      const preview = moveBatchManually(seed, result, draggedBatchId, dropTarget.machineId, dropTarget.position);
      const moved = preview.batches.find((batch) => batch.id === draggedBatchId);
      return moved ? { valid: true as const, moved, result: preview } : { valid: false as const, reason: "Taşıma önizlemesi oluşturulamadı." };
    } catch (error) {
      return { valid: false as const, reason: error instanceof Error ? error.message : "Bu konuma taşınamaz." };
    }
  }, [draggedBatchId, dropTarget, result, seed]);
  const processDropPreview = useMemo(() => {
    if (!draggedProcessOperationId || !processDropTarget) return null;
    try {
      const preview = previewProcessOperationReschedule(seed, result, draggedProcessOperationId, processDropTarget.resourceId, processDropTarget.requestedStart);
      return { valid: true as const, operation: preview.operation, preview };
    } catch (error) {
      return { valid: false as const, reason: error instanceof Error ? error.message : "Bu downstream yerleşimi uygulanamaz." };
    }
  }, [draggedProcessOperationId, processDropTarget, result, seed]);
  const pendingProcessPreview = useMemo(() => {
    if (!pendingProcessMove) return null;
    try { return { valid: true as const, preview: previewProcessOperationReschedule(seed, result, pendingProcessMove.operationId, pendingProcessMove.resourceId, pendingProcessMove.requestedStart) }; }
    catch (error) { return { valid: false as const, reason: error instanceof Error ? error.message : "Taşıma uygulanamaz." }; }
  }, [pendingProcessMove, seed, result]);
  useRaviScreenContext("process-placement", { pendingProcessMove, preview: pendingProcessPreview?.valid ? {
    operation: pendingProcessPreview.preview.operation, adjustments: pendingProcessPreview.preview.adjustments,
    affectedOperations: pendingProcessPreview.preview.affectedOperations,
  } : pendingProcessPreview, draggedProcessOperationId, processDropTarget, processMoveFeedback, lastDropError, dirty });
  useEffect(() => {
    if (!recentMovedProcessOperationId) return;
    const frame = requestAnimationFrame(() => movedElementRef.current?.scrollIntoView({ block: "center", inline: "center", behavior: "instant" }));
    return () => cancelAnimationFrame(frame);
  }, [recentMovedProcessOperationId, processMoveSequence]);
  useEffect(() => {
    const cancel = (event: KeyboardEvent) => { if (event.key === "Escape") { cancelProcessPointerMove(); setPendingProcessMove(null); } };
    window.addEventListener("keydown", cancel);
    return () => window.removeEventListener("keydown", cancel);
  }, []);
  const evaluatedResult = dropPreview?.valid ? dropPreview.result : result;
  const evaluatedSelectedBatch = selectedBatch ? evaluatedResult.batches.find((batch) => batch.id === selectedBatch.id) ?? selectedBatch : null;
  const evaluatedDownstreamPlan = useMemo(() => buildDownstreamProcessPlan(seed, evaluatedResult), [evaluatedResult, seed]);
  const selectedBatchDeliveryReadyAt = evaluatedSelectedBatch
    ? evaluatedDownstreamPlan.jobs.find((job) => job.batchId === evaluatedSelectedBatch.id)?.deliveryReadyAt
    : undefined;
  const weeklyPlanStatus = useMemo(() => buildWeeklyPlanStatus(seed, evaluatedResult).filter((row) => !row.excludedFromPlan), [evaluatedResult, seed]);
  const selectedSplitInsight = useMemo(() => batchSplitInsight(evaluatedResult.batches, evaluatedSelectedBatch), [evaluatedResult.batches, evaluatedSelectedBatch]);

  function setPointerDropTarget(batchId: string, clientX: number, clientY: number) {
    const target = document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(".track[data-machine-id]");
    if (!target) return;
    const machineId = target.dataset.machineId;
    if (!machineId) return;
    const rect = target.getBoundingClientRect();
    const serial = horizonStart + Math.max(0, Math.min(1, (clientX - rect.left) / rect.width)) * horizon;
    const queue = plannedBatches.filter((batch) => batch.machineId === machineId && batch.id !== batchId).sort((left, right) => left.start - right.start);
    const nextTarget = { machineId, position: queue.filter((batch) => batch.start < serial).length };
    dropTargetRef.current = nextTarget;
    setDropTarget(nextTarget);
  }

  function beginPointerMove(event: React.PointerEvent<HTMLButtonElement>, batch: PlannedBatch) {
    if (event.button !== 0 || batch.locked) return;
    gestureRef.current = { batchId: batch.id, startX: event.clientX, startY: event.clientY, active: false, element: event.currentTarget };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continuePointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = gestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY) < 6) return;
    gesture.active = true;
    suppressBatchClickRef.current = true;
    setDraggedBatchId(gesture.batchId);
    setLastDropError("");
    setPointerDropTarget(gesture.batchId, event.clientX, event.clientY);
  }

  function endPointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = gestureRef.current;
    if (!gesture) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    if (gesture.active) {
      const target = dropTargetRef.current;
      if (target) {
        try {
          moveBatchManually(seed, result, gesture.batchId, target.machineId, target.position);
          onMoveBatch(gesture.batchId, target.machineId, target.position);
          setLastDropError("");
          setRecentMovedBatchId(gesture.batchId);
        } catch (error) {
          const message = error instanceof Error ? error.message : "Bu konuma taşınamaz.";
          setLastDropError(message);
          onOperationError(message);
        }
      } else {
        const message = "Şarjı geçerli bir tezgah zaman çizgisine bırakın.";
        setLastDropError(message);
        onOperationError(message);
      }
    }
    gestureRef.current = null;
    finishDrag();
  }

  function setProcessPointerDropTarget(clientX: number, clientY: number) {
    const target = document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(".process-resource-track[data-process-resource-id]");
    if (!target?.dataset.processResourceId) {
      processDropTargetRef.current = null;
      setProcessDropTarget(null);
      return;
    }
    const resourceId = target.dataset.processResourceId;
    const rect = target.getBoundingClientRect();
    const pointerRatio = (clientX - rect.left) / rect.width;
    const requestedStart = ganttDropStart(pointerRatio, horizonStart, horizon, processGestureRef.current?.grabOffsetDays ?? 0);
    const nextTarget = { resourceId, requestedStart };
    if (processDropTargetRef.current?.resourceId === resourceId && processDropTargetRef.current.requestedStart === requestedStart) return;
    processDropTargetRef.current = nextTarget;
    setProcessDropTarget(nextTarget);
  }

  function beginProcessPointerMove(event: React.PointerEvent<HTMLButtonElement>, operation: ProcessOperation) {
    if (event.button !== 0) return;
    if (operation.actual || operation.current) { setLastDropError("Çalışan ve tamamlanan işler sabittir; yalnızca kuyruktaki planlı işleri taşıyabilirsiniz."); return; }
    processDropTargetRef.current = null;
    setProcessDropTarget(null);
    const track = event.currentTarget.closest<HTMLElement>(".process-resource-track");
    const trackRect = track?.getBoundingClientRect();
    const pointerSerial = trackRect ? horizonStart + (event.clientX - trackRect.left) / trackRect.width * horizon : operation.start;
    processGestureRef.current = {
      operationId: operation.id,
      startX: event.clientX,
      startY: event.clientY,
      active: false,
      grabOffsetDays: Math.max(0, pointerSerial - operation.start),
    };
    setProcessDragOffset({ x: 0, y: 0 });
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continueProcessPointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = processGestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY) < 6) return;
    gesture.active = true;
    suppressProcessClickRef.current = true;
    setDraggedProcessOperationId(gesture.operationId);
    setProcessDragOffset({ x: event.clientX - gesture.startX, y: event.clientY - gesture.startY });
    setLastDropError("");
    setProcessPointerDropTarget(event.clientX, event.clientY);
  }

  function cancelProcessPointerMove() {
    processGestureRef.current = null;
    processDropTargetRef.current = null;
    setDraggedProcessOperationId(null);
    setProcessDropTarget(null);
    setProcessDragOffset({ x: 0, y: 0 });
  }

  function endProcessPointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = processGestureRef.current;
    if (!gesture) return;
    if (gesture.active) {
      // Resolve the actual release location; never reuse a previously hovered row.
      setProcessPointerDropTarget(event.clientX, event.clientY);
      const target = processDropTargetRef.current;
      try {
        if (!target) throw new Error("İşi geçerli bir proses istasyonu zaman çizgisine bırakın. Taşıma uygulanmadı.");
        previewProcessOperationReschedule(seed, result, gesture.operationId, target.resourceId, target.requestedStart);
