      setProcessMoveSequence((value) => value + 1);
      setProcessMoveFeedback(`${processLabel(moved.process)} · ${moved.workOrder || moved.product} → ${moved.resourceId} · ${placementDate(moved.start)} – ${placementDate(moved.end)}. Üst çubuktaki Geri al ile geri alınabilir.`);
      setLastDropError("");
      setPendingProcessMove(null);
    } catch (error) { setLastDropError(error instanceof Error ? error.message : "Taşıma uygulanamadı."); }
  }

  function zoom(direction: -1 | 1) {
    const levels = [14, 28, 42, 70, 112, 182, 365];
    const current = levels.indexOf(viewDays);
    const next = levels[Math.max(0, Math.min(levels.length - 1, (current < 0 ? 2 : current) + direction))];
