        <span><small>{ganttProcess === "turning" ? "Torna kuyruğunda" : `${processLabel(ganttProcess)} bekleyen / planlı`}</small><strong>{formatNumber(selectedWorkload.waitingQuantity)} adet</strong><em>{formatNumber(selectedWorkload.waitingJobCount)} iş</em></span>
        <span className="total"><small>Toplam operasyon yükü</small><strong>{formatNumber(selectedWorkload.totalQuantity)} adet</strong><em>{formatNumber(selectedWorkload.totalJobCount)} iş</em></span>
