        {ganttProcess === "turning" ? <div className="legend"><span><i className="dot running" /> Mevcut üretim</span><span><i className="dot planned" /> Süre = genişlik</span><span><i className="diameter-key" /> Renk ve kalınlık = çap</span><span><i className="calendar-key shutdown" /> Tatil / Pazar · tıklayıp çalıştır</span><span><i className="calendar-key overtime" /> Mesai</span><span><Lock size={11} /> Kilitli</span></div> : <div className="legend process-legend"><span><ProcessIcon process={ganttProcess} size={13} /> {processLabel(ganttProcess)}</span><span><i className="planned-outline" /> Planlanan</span><span><i className="actual-outline" /> Fiili</span><span><i className="calendar-key shutdown" /> Tatil / Pazar · tıklayıp çalıştır</span>{ganttProcess === "drilling" ? [...processSetupHues.entries()].slice(0, 8).map(([setupKey, hue]) => <span key={setupKey}><i className="process-setup-key" style={{ backgroundColor: `hsl(${hue} 82% 88%)`, borderColor: `hsl(${hue} 48% 48%)` }} /> {setupKey}</span>) : <span>GKM sonrası +1 iş günü tampon</span>}</div>}
