      {processMoveFeedback && !lastDropError && !draggedProcessOperationId && <div className="gantt-drag-preview valid process-move-notice" role="status"><CheckCircle size={18} /><div><strong>Yerleşim uygulandı</strong><span>{processMoveFeedback}</span></div><button onClick={() => setProcessMoveFeedback("")} aria-label="Yerleşim bildirimini kapat"><X size={14} /></button></div>}
      {ganttProcess === "turning" && lastDropError && !draggedBatchId && <div className="gantt-drag-preview invalid"><Warning size={16} weight="fill" /><div><strong>Taşıma uygulanmadı</strong><span>{lastDropError}</span></div><button onClick={() => setLastDropError("")} aria-label="Taşıma uyarısını kapat"><X size={14} /></button></div>}
      {ganttProcess !== "turning" && lastDropError && !draggedProcessOperationId && <div className="gantt-drag-preview invalid process-move-notice" role="alert"><Warning size={16} weight="fill" /><div><strong>{processLabel(ganttProcess)} taşıması uygulanmadı</strong><span>{lastDropError}</span></div><button onClick={() => setLastDropError("")} aria-label="Taşıma uyarısını kapat"><X size={14} /></button></div>}
