} from "@/lib/weekly-demand";
import { ArrowClockwise, CalendarBlank, ChartBar, FileXls, Lock, Play, Plus, Question, Warning, X } from "@phosphor-icons/react";
import { useEffect, useState } from "react";

export function PlanRunDialog({ seed, existingPlanAvailable, existingPlannedBatchCount, lockedBatchCount, onClose, onCompare, onRun }: { seed: PlanningSeed; existingPlanAvailable: boolean; existingPlannedBatchCount: number; lockedBatchCount: number; onClose: () => void; onCompare: (request: PlanRunRequest) => PlanComparisonRow[]; onRun: (request: PlanRunRequest) => void }) {
  const customerDemand = seed.customerDemand;
  const availableWeeks = customerDemand?.weeks ?? [];
  const replaceWeekRanges = customerDemand
    ? planningWeekRangesForScope(customerDemand.activeScope)
    : [];
  const activeEndWeekIndex = customerDemand
    ? availableWeeks.findIndex((week) => week.id === customerDemand.activeScope.endWeekId)
    : -1;
  const sequencePending = Boolean(seed.planRunSequence && seed.planRunSequence.completedRangeCount < seed.planRunSequence.ranges.length);
  const continuationWeek = availableWeeks[activeEndWeekIndex + 1];
  const appendAvailable = Boolean(
    customerDemand
    && existingPlanAvailable
    && seed.activePlanRun?.scope.kind === "customer-weeks"
    && !sequencePending
    && continuationWeek,
  );
  const continuationWeekRanges = continuationWeek
    ? [{ startWeekId: continuationWeek.id, endWeekId: continuationWeek.id }]
    : [];
  const completedRangeCount = seed.activePlanRun?.scope.ranges?.length
    ?? (seed.activePlanRun?.scope.kind === "customer-weeks" ? 1 : 0);
  const existingOptimizationGoal = seed.planRunSequence?.optimizationGoal
    ?? seed.activePlanRun?.optimizationGoal
    ?? "earliest-finish";
  const existingIncludePriorBacklog = seed.planRunSequence?.includePriorBacklog
    ?? seed.activePlanRun?.includePriorBacklog
    ?? true;
  const existingAllowProductionBeforeScope = seed.planRunSequence?.allowProductionBeforeScope
    ?? seed.activePlanRun?.allowProductionBeforeScope
    ?? true;
  const orderImport = orderImportMetadataForSeed(seed);
  const existingDeliveryFilter = seed.planRunSequence?.deliveryDeductionFilter
    ?? seed.activePlanRun?.deliveryDeduction?.filter;
  const activeMachines = seed.machines.filter((machine) => machine.active);
  const initialStart = Math.min(...activeMachines.map((machine) => machine.availableStart).filter((value) => value > 0));
  const initialEnd = Math.max(0, ...activeMachines.map((machine) => machine.planEnd));
  const [appendToExistingPlan, setAppendToExistingPlan] = useState(appendAvailable);
  const [weekRanges, setWeekRanges] = useState<PlanningWeekRange[]>(appendAvailable ? continuationWeekRanges : replaceWeekRanges);
  const [productionStartDate, setProductionStartDate] = useState(Number.isFinite(initialStart) ? excelSerialToDate(initialStart).toISOString().slice(0, 10) : "");
  const [productionEndDate, setProductionEndDate] = useState(initialEnd ? excelSerialToDate(initialEnd).toISOString().slice(0, 10) : "");
  const [optimizationGoal, setOptimizationGoal] = useState<OptimizationGoal>(appendAvailable ? existingOptimizationGoal : "earliest-finish");
  const [includePriorBacklog, setIncludePriorBacklog] = useState(appendAvailable ? existingIncludePriorBacklog : false);
  const [allowProductionBeforeScope, setAllowProductionBeforeScope] = useState(appendAvailable ? existingAllowProductionBeforeScope : false);
  const [deductDeliveries, setDeductDeliveries] = useState(existingDeliveryFilter?.enabled ?? Boolean(orderImport));
  const [deliveryStartDateTime, setDeliveryStartDateTime] = useState(() => factoryDateTimeInput(existingDeliveryFilter?.startAt ?? orderImport?.importedAt ?? new Date()));
  const [includeDeliveryStart, setIncludeDeliveryStart] = useState(existingDeliveryFilter?.includeStart ?? true);
  const [error, setError] = useState("");
  const [comparison, setComparison] = useState<PlanComparisonRow[]>([]);
  const [comparing, setComparing] = useState(false);
  useRaviScreenContext("plan-run-dialog", { appendToExistingPlan, weekRanges, productionStartDate, productionEndDate,
    optimizationGoal, includePriorBacklog, allowProductionBeforeScope, deductDeliveries, deliveryStartDateTime, includeDeliveryStart, comparison, error });
  let resolvedWeekRanges: ReturnType<typeof resolvePlanningWeekRanges> = [];
  let rangeValidationError = "";
  if (customerDemand) {
    try {
      resolvedWeekRanges = resolvePlanningWeekRanges(customerDemand.weeks, weekRanges);
    } catch (reason) {
      rangeValidationError = reason instanceof Error ? reason.message : "Hafta aralıklarını kontrol edin.";
    }
  }
  const scopeRangeValid = customerDemand
    ? resolvedWeekRanges.length === weekRanges.length && !rangeValidationError
    : Boolean(productionStartDate && productionEndDate && productionStartDate <= productionEndDate);
  const firstResolvedRange = resolvedWeekRanges[0];
  const deliveryPreviewRange = customerDemand && firstResolvedRange
    ? {
        startWeekId: appendToExistingPlan && seed.activePlanRun?.scope.kind === "customer-weeks"
          ? seed.activePlanRun.scope.startWeekId ?? firstResolvedRange.startWeekId
          : firstResolvedRange.startWeekId,
        endWeekId: firstResolvedRange.endWeekId,
      }
    : null;
  const demandSummary = customerDemand && firstResolvedRange
    ? weeklyScopeDemandSummary(previewFromDataset(customerDemand), {
        startWeekId: firstResolvedRange.startWeekId,
        endWeekId: firstResolvedRange.endWeekId,
      })
    : null;
  let deliveryPreview: DeliveryDeductionPreview | null = null;
  let deliveryPreviewError = "";
  if (orderImport && scopeRangeValid) {
    try {
      const startAt = factoryDateTimeToIso(deliveryStartDateTime);
      if (!startAt) throw new Error("Teslimat başlangıç tarihini ve saatini kontrol edin.");
      const grossOrders = customerDemand && deliveryPreviewRange
        ? buildWeeklyPlanningState(
            previewFromDataset(customerDemand),
            seed.orders,
            deliveryPreviewRange,
            seed.customerOrderOverrides,
            { includePriorBacklog },
          ).orders
        : seed.orderImportGrossOrders ?? seed.orders;
      deliveryPreview = calculateDeliveryDeduction({
        orders: grossOrders,
        productionHistory: seed.productionHistory,
        orderImport,
        importProducts: customerDemand?.products.map((product) => product.product) ?? seed.orderCatalog ?? seed.orders.map((order) => order.product),
        filter: {
          enabled: deductDeliveries,
          startAt,
          includeStart: includeDeliveryStart,
          endAt: appendToExistingPlan && existingDeliveryFilter ? existingDeliveryFilter.endAt : new Date().toISOString(),
        },
      });
    } catch (reason) {
      deliveryPreviewError = reason instanceof Error ? reason.message : "Teslimatlar ihtiyaçtan düşülemedi.";
    }
  }
  const dateRangeValid = scopeRangeValid && !deliveryPreviewError;
  const weekRangeSignature = weekRanges.map((range) => `${range.startWeekId}:${range.endWeekId}`).join("|");
  const lastSelectedWeekIndex = customerDemand && weekRanges.length
    ? availableWeeks.findIndex((week) => week.id === weekRanges.at(-1)?.endWeekId)
    : -1;
  const coarsePlanning = optimizationGoal === "coarse";
  const canAddWeekRange = Boolean(customerDemand && lastSelectedWeekIndex >= 0 && lastSelectedWeekIndex < availableWeeks.length - 1);
  const goals: Array<{ id: OptimizationGoal; title: string; detail: string }> = [
    { id: "coarse", title: "Standart planlama", detail: "Her aralığın toplam talebini tek üretim penceresinde ürün ve çap kampanyalarıyla planlar." },
    { id: "balanced", title: "Dengeli planlama", detail: "Aynı ürün ve çap kampanyalarını korurken uygun alternatiflerde kapasite yükünü dengeler." },
    { id: "earliest-finish", title: "En erken bitiş", detail: "Her şarjı setup dahil en erken tamamlayan uygun tezgahı seçer." },
    { id: "minimum-setup", title: "Setup’ı azalt", detail: "Aynı ürün ve çap kampanyalarını koruyarak tezgah değişim süresini azaltır." },
  ];
  useEffect(() => {
    setComparison([]);
    setError("");
  }, [weekRangeSignature, productionStartDate, productionEndDate, includePriorBacklog, allowProductionBeforeScope, deductDeliveries, deliveryStartDateTime, includeDeliveryStart]);

  function selectPlanMode(append: boolean) {
    setAppendToExistingPlan(append);
    setWeekRanges(append ? continuationWeekRanges : replaceWeekRanges);
    setOptimizationGoal(append ? existingOptimizationGoal : "earliest-finish");
    setIncludePriorBacklog(append ? existingIncludePriorBacklog : false);
    setAllowProductionBeforeScope(append ? existingAllowProductionBeforeScope : false);
    const filter = append ? existingDeliveryFilter : undefined;
    setDeductDeliveries(filter?.enabled ?? Boolean(orderImport));
    setDeliveryStartDateTime(factoryDateTimeInput(filter?.startAt ?? orderImport?.importedAt ?? new Date()));
    setIncludeDeliveryStart(filter?.includeStart ?? true);
    setComparison([]);
    setError("");
  }

  function updateWeekRange(index: number, field: keyof PlanningWeekRange, value: string) {
    setWeekRanges((current) => {
      const next = current.map((range) => ({ ...range }));
      next[index] = { ...next[index], [field]: value };
      const startIndex = availableWeeks.findIndex((week) => week.id === next[index].startWeekId);
      const endIndex = availableWeeks.findIndex((week) => week.id === next[index].endWeekId);
      if (startIndex >= 0 && (endIndex < startIndex || endIndex < 0)) next[index].endWeekId = next[index].startWeekId;
      for (let cursor = index + 1; cursor < next.length; cursor += 1) {
        const previousEnd = availableWeeks.findIndex((week) => week.id === next[cursor - 1].endWeekId);
        const requiredStart = availableWeeks[previousEnd + 1];
        if (!requiredStart) break;
        next[cursor].startWeekId = requiredStart.id;
        const currentEnd = availableWeeks.findIndex((week) => week.id === next[cursor].endWeekId);
        if (currentEnd < previousEnd + 1) next[cursor].endWeekId = requiredStart.id;
      }
      return next;
    });
  }

  function addWeekRange() {
    if (!canAddWeekRange) return;
    const nextWeek = availableWeeks[lastSelectedWeekIndex + 1];
    setWeekRanges((current) => [...current, { startWeekId: nextWeek.id, endWeekId: nextWeek.id }]);
  }

  function selectOptimizationGoal(goal: OptimizationGoal) {
    setOptimizationGoal(goal);
    if (goal === "coarse") setAllowProductionBeforeScope(false);
    setComparison([]);
    setError("");
  }

  function removeWeekRange(index: number) {
    setWeekRanges((current) => {
      const next = current.filter((_, currentIndex) => currentIndex !== index).map((range) => ({ ...range }));
      for (let cursor = Math.max(1, index); cursor < next.length; cursor += 1) {
        const previousEnd = availableWeeks.findIndex((week) => week.id === next[cursor - 1].endWeekId);
        const requiredStart = availableWeeks[previousEnd + 1];
        if (!requiredStart) break;
        next[cursor].startWeekId = requiredStart.id;
        const currentEnd = availableWeeks.findIndex((week) => week.id === next[cursor].endWeekId);
        if (currentEnd < previousEnd + 1) next[cursor].endWeekId = requiredStart.id;
      }
      return next;
    });
  }

  function request(): PlanRunRequest {
    return {
      optimizationGoal,
      appendToExistingPlan: customerDemand ? appendToExistingPlan : undefined,
      includePriorBacklog: customerDemand ? includePriorBacklog : undefined,
      allowProductionBeforeScope: customerDemand ? allowProductionBeforeScope : undefined,
      weekRanges: customerDemand ? weekRanges : undefined,
      productionStartDate: customerDemand ? undefined : productionStartDate,
      productionEndDate: customerDemand ? undefined : productionEndDate,
      deliveryDeduction: orderImport ? {
        enabled: deductDeliveries,
        startAt: factoryDateTimeToIso(deliveryStartDateTime),
        includeStart: includeDeliveryStart,
      } : undefined,
    };
  }

  function submit() {
    setError("");
    try {
      if (!dateRangeValid) throw new Error("Geçerli bir planlama kapsamı seçin.");
      onRun(request());
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Plan çalıştırılamadı.");
    }
  }

  function runComparison() {
    if (!dateRangeValid) return;
    setComparing(true);
    setError("");
    window.setTimeout(() => {
      try {
        setComparison(onCompare(request()));
      } catch (reason) {
        setError(reason instanceof Error ? reason.message : "Seçenekler karşılaştırılamadı.");
      } finally {
        setComparing(false);
      }
    }, 0);
  }

  return (
    <div className="confirmation-backdrop plan-run-backdrop" role="presentation">
      <section className="operational-dialog plan-run-dialog" role="dialog" aria-modal="true" aria-label="Planı çalıştır">
        <div className="operational-dialog-head">
          <span className="dialog-icon plan-run"><Play size={20} weight="fill" /></span>
          <div>
            <span>PLAN OLUŞTUR</span>
            <h2>Kapsamı ve optimizasyon hedefini seçin</h2>
            <p>{customerDemand ? `${customerDemand.sourceFile} · talepler ISO hafta Cumartesi terminine göre kapsama alınır.` : "Siparişler seçilen üretim tarihleri içinde uygun tezgahlara yerleştirilir."}</p>
          </div>
          <button className="delete-button" onClick={onClose} aria-label="Plan çalıştırma penceresini kapat"><X size={16} /></button>
        </div>
        <div className="plan-run-body">
          {appendAvailable && <section className="plan-run-mode">
            <div><strong>Mevcut plan bulundu</strong><span>Yeni haftaları mevcut Gantt’ın devamına ekleyebilir veya planı baştan oluşturabilirsiniz.</span></div>
            <div className="plan-run-mode-actions">
              <button type="button" className={appendToExistingPlan ? "selected" : ""} onClick={() => selectPlanMode(true)}><Plus size={14} /><span><strong>Planın devamına ekle</strong><small>Mevcut, manuel ve öne çekilmiş şarjlar korunur</small></span></button>
              <button type="button" className={!appendToExistingPlan ? "selected replace" : ""} onClick={() => selectPlanMode(false)}><ArrowClockwise size={14} /><span><strong>Planı baştan oluştur</strong><small>Yalnızca kilitli şarjlar korunur</small></span></button>
            </div>
          </section>}
          <section className="plan-run-scope">
            <div className="plan-run-section-title"><CalendarBlank size={17} /><div><strong>{customerDemand ? appendToExistingPlan ? "Eklenecek planlama aralıkları" : "Planlama aralıkları" : "Üretim tarihleri"}</strong><span>{customerDemand ? appendToExistingPlan ? "İlk yeni aralık mevcut planın hemen arkasından başlar; varsa diğerleri kontrol sonrasında eklenir." : "Önce ilk aralık planlanır; diğerleri manuel kontrolünüzden sonra tek tek eklenir." : "Tezgahların yeni plan için ortak başlangıç ve bitiş penceresi."}</span></div></div>
            {customerDemand
              ? <div className="plan-run-week-ranges">
                  {weekRanges.map((range, index) => {
                    const startIndex = availableWeeks.findIndex((week) => week.id === range.startWeekId);
                    const rangeNumber = appendToExistingPlan ? completedRangeCount + index + 1 : index + 1;
                    return <div className="plan-run-week-range" key={`${index}-${range.startWeekId}`}>
                      <div className="plan-run-week-range-head"><strong>{rangeNumber}. Aralık</strong>{index > 0 && <button type="button" onClick={() => removeWeekRange(index)} aria-label={`${rangeNumber}. planlama aralığını kaldır`}><X size={13} /></button>}</div>
                      <div className="plan-run-fields">
                        <Field label="Başlangıç haftası"><select value={range.startWeekId} disabled={appendToExistingPlan || index > 0} onChange={(event) => updateWeekRange(index, "startWeekId", event.target.value)}>{availableWeeks.map((week) => <option key={week.id} value={week.id}>{formatPlanningWeek(week.isoWeek, week.isoYear)}</option>)}</select></Field>
                        <Field label="Bitiş haftası"><select value={range.endWeekId} onChange={(event) => updateWeekRange(index, "endWeekId", event.target.value)}>{availableWeeks.slice(Math.max(0, startIndex)).map((week) => <option key={week.id} value={week.id}>{formatPlanningWeek(week.isoWeek, week.isoYear)}</option>)}</select></Field>
                      </div>
                    </div>;
                  })}
                  <button type="button" className="plan-run-add-range" disabled={!canAddWeekRange} onClick={addWeekRange}><Plus size={14} /> Aralık ekle</button>
                </div>
              : <div className="plan-run-fields"><Field label="Plan başlangıcı"><input type="date" value={productionStartDate} onChange={(event) => setProductionStartDate(event.target.value)} /></Field><Field label="Plan bitişi"><input type="date" value={productionEndDate} onChange={(event) => setProductionEndDate(event.target.value)} /></Field></div>}
            <div className={`plan-run-scope-preview ${dateRangeValid ? "" : "invalid"}`}>
              {customerDemand && dateRangeValid
                ? <>{resolvedWeekRanges.map((range, index) => <span className="plan-run-scope-line" key={range.startWeekId}><b>{appendToExistingPlan ? completedRangeCount + index + 1 : index + 1}</b><span><strong>{range.label}</strong><small>{formatInputDate(range.startDate)}–{formatInputDate(range.endDate)}</small></span></span>)}<em><NumberHelp description="Seçilen hafta aralıklarında ilk kez oluşan toplam müşteri talebi; önceki haftaların açığı bu sayıya eklenmez.">{formatNumber(demandSummary?.selectedDemand ?? 0)} adet yeni hafta talebi</NumberHelp>. {coarsePlanning ? weekRanges.length > 1 ? "Şimdi 1. aralık tek toplam olarak planlanır; diğerleri kontrolünüzden sonra sırayla eklenir." : "Seçilen aralığın talebi tek toplam olur ve yalnızca bu tarih penceresine yerleştirilir." : appendToExistingPlan ? weekRanges.length > 1 ? "İlk yeni aralık şimdi eklenir; diğerleri kontrolden sonra planlanır." : "Seçilen aralık mevcut planın arkasına eklenecek." : weekRanges.length > 1 ? "Şimdi yalnızca 1. aralık planlanır; diğerleri kontrolden sonra eklenir." : "Seçilen hafta aralığı planlanır."}</em></>
                : <><strong>{dateRangeValid ? `${formatInputDate(productionStartDate)}–${formatInputDate(productionEndDate)}` : "Kapsam seçilemedi"}</strong><span>{customerDemand ? rangeValidationError : `${activeMachines.length} aktif tezgah`}</span></>}
            </div>
          </section>
          <section className="plan-run-goals">
            <div className="plan-run-section-title"><ChartBar size={17} /><div><strong>Optimizasyon hedefi</strong><span>{appendToExistingPlan ? "Devam planı, mevcut planla aynı optimizasyon hedefini kullanır." : coarsePlanning ? "Standart planlama haftalık teslimat koruması vermez; her aralığı kendi üretim penceresinde toplu olarak planlar." : "Termin sırası her seçenekte korunur; seçenek tezgah dağılımını değiştirir."}</span></div></div>
            <div className={`plan-run-goal-list ${appendToExistingPlan ? "fixed" : ""}`}>{goals.map((goal) => <label key={goal.id} className={optimizationGoal === goal.id ? "selected" : ""}><input type="radio" name="optimization-goal" value={goal.id} checked={optimizationGoal === goal.id} disabled={appendToExistingPlan} onChange={() => selectOptimizationGoal(goal.id)} /><span><strong>{goal.title}</strong><small>{goal.detail}</small></span></label>)}</div>
          </section>
          {orderImport && <section className="plan-run-delivery-deduction">
            <header>
              <div><FileXls size={17} /><span><small>KULLANILAN SİPARİŞ EXCEL’İ</small><strong>{orderImport.sourceFile}</strong><em>{formatFactoryDateTime(orderImport.importedAt)} yüklendi</em></span></div>
              <label className={deductDeliveries ? "selected" : ""}><input type="checkbox" checked={deductDeliveries} disabled={appendToExistingPlan} onChange={(event) => setDeductDeliveries(event.target.checked)} /><span><strong>Teslimatları ihtiyaçtan düş</strong><small>Aynı Excel ile yeniden üretimi engeller</small></span></label>
            </header>
            <div className="delivery-deduction-controls">
              <Field label="Teslimat başlangıç tarihi ve saati"><input type="datetime-local" value={deliveryStartDateTime} disabled={appendToExistingPlan || !deductDeliveries} onChange={(event) => setDeliveryStartDateTime(event.target.value)} /></Field>
              <label className="delivery-boundary-option"><input type="checkbox" checked={includeDeliveryStart} disabled={appendToExistingPlan || !deductDeliveries} onChange={(event) => setIncludeDeliveryStart(event.target.checked)} /><span><strong>Başlangıç anını dahil et</strong><small>{includeDeliveryStart ? "Tam bu anda kaydedilen teslimat hesaba katılır." : "Hesap başlangıç anından hemen sonra başlar."}</small></span></label>
              {appendToExistingPlan && <p><Lock size={13} /> Mevcut planın Excel sürümü ve teslimat filtresi korunuyor.</p>}
            </div>
            {deliveryPreview && <>
              <div className="delivery-deduction-summary">
                <span><small>Excel ihtiyacı</small><strong>{formatNumber(deliveryPreview.snapshot.grossDemand)}</strong></span>
                <b>−</b>
                <span className="deducted"><small>Düşülecek teslimat</small><strong>{formatNumber(deliveryPreview.snapshot.deductedQuantity)}</strong></span>
                <b>=</b>
                <span className="planned"><small>Planlanacak miktar</small><strong>{formatNumber(deliveryPreview.snapshot.plannedDemand)}</strong></span>
              </div>
              {deliveryPreview.snapshot.excessDeliveryQuantity > 0 && <div className="delivery-deduction-alert excess"><Warning size={15} weight="fill" /><span><strong>İhtiyaçtan fazla teslimat var</strong><small>{formatNumber(deliveryPreview.snapshot.excessDeliveryQuantity)} adet ihtiyaçtan düşülmedi; planlanacak miktar sıfırın altına inmedi.</small></span></div>}
              {deliveryPreview.unmatchedItems.length > 0 && <div className="delivery-deduction-alert unmatched"><Warning size={15} weight="fill" /><span><strong>{deliveryPreview.unmatchedItems.length} teslimat Excel ile eşleşmedi</strong><small>{deliveryPreview.unmatchedItems.map((item) => `${item.product}${item.workOrder ? ` · ${item.workOrder}` : ""}`).join(" · ")}</small></span></div>}
              <details className="delivery-deduction-details">
                <summary><Question size={14} /> Ürün ve teslimat hesabını göster <b>{deliveryPreview.snapshot.items.length}</b></summary>
                <div>
                  <section className="delivery-deduction-products" aria-label="Ürün bazında teslimat hesabı">
                    <header><strong>Ürün bazında hesap</strong><span>Excel ihtiyacı</span><span>Düşülen</span><span>Kalan</span></header>
                    {deliveryPreview.products.map((row) => <article key={row.product}>
                      <strong>{row.product}</strong>
                      <span>{formatNumber(row.grossDemand)}</span>
                      <span>{formatNumber(row.deductedQuantity)}</span>
                      <span>{formatNumber(row.plannedDemand)}</span>
                    </article>)}
                  </section>
                  <section className="delivery-deduction-items" aria-label="Teslimat kayıtları">
                    <header><strong>Teslimat kayıtları</strong><span>{deliveryPreview.snapshot.items.length} kayıt</span></header>
                    {deliveryPreview.snapshot.items.length ? deliveryPreview.snapshot.items.map((item) => <article key={item.entryId} className={item.status}>
                      <span><strong>{item.product}</strong><small>{item.workOrder || "İş emri yok"}</small></span>
                      <span><strong>{formatNumber(item.quantity)} adet</strong><small>{formatFactoryDateTime(item.deliveredAt)}</small></span>
                      <span><strong>{item.status === "unmatched" ? "Eşleşmedi" : item.status === "outside-scope" ? "Bu aralığın dışında" : `${formatNumber(item.deductedQuantity)} düşüldü`}</strong><small>{item.excessQuantity > 0 ? `${formatNumber(item.excessQuantity)} adet fazla` : item.matchedOrderIds.length ? `Talep: ${item.matchedOrderIds.join(", ")}` : "İhtiyaçtan düşülmedi"}</small></span>
                    </article>) : <p>Seçilen zaman aralığında teslimat bulunmuyor.</p>}
                  </section>
                </div>
              </details>
            </>}
            {deliveryPreviewError && <p className="form-error">{deliveryPreviewError}</p>}
          </section>}
          {coarsePlanning && <div className="coarse-plan-warning"><Warning size={17} weight="fill" /><span><strong>Haftalık teslimat kontrolü kapalı</strong><small>{firstResolvedRange ? `${formatInputDate(firstResolvedRange.startDate)}–${formatInputDate(firstResolvedRange.endDate)} arasında tüm talep tek toplamdır. Aynı ürün ve çaplar daha uzun kampanyalar halinde tutulur; üretim pencere dışına taşamaz.` : "Seçilen aralık tek üretim penceresi olarak kullanılır."}</small></span></div>}
          <div className="plan-run-protection"><Lock size={16} /><span><strong>{appendToExistingPlan ? `${existingPlannedBatchCount} mevcut şarj korunacak` : `${lockedBatchCount} kilitli şarj korunacak`}</strong><small>{appendToExistingPlan ? "Manuel düzenlemeler ve öne çekilmiş üretimler dahil mevcut Gantt değişmeden kalır; yalnızca kalan ihtiyaç arkasına eklenir." : "Mevcut çalışan işler ve kilitli kuyruk önekleri yeni planın önünde sabit kalır."}</small></span></div>
          {comparison.length > 0 && <section className="plan-run-comparison">
            <header><div><span>SEÇENEK ÖNİZLEMESİ</span><strong>{customerDemand && weekRanges.length > 1 ? "Yalnızca ilk aralık için hesaplandı" : "Aynı kapsam ve kilitlerle hesaplandı"}</strong></div><small>Öneri önce eksik ve termin riskini, sonra bitiş ve setup’ı azaltır.</small></header>
            <div className="plan-run-comparison-table">
              <div className="head"><span>Hedef</span><span>Termin eksiği</span><span>Planlanamayan</span><span>Yük farkı</span><span>Setup</span><span>Bitiş</span></div>
              {comparison.map((row) => <button key={row.goal} className={`${optimizationGoal === row.goal ? "selected" : ""} ${row.recommended ? "recommended" : ""}`} onClick={() => setOptimizationGoal(row.goal)}>
                <span><strong>{optimizationGoalLabel(row.goal)}</strong>{row.recommended && <small>Önerilen</small>}</span>
                <span><NumberHelp focusable={false} description="Seçilen termin günlerine kadar hazır olmayacak toplam adet.">{formatNumber(row.onTimeShortage)}</NumberHelp></span>
                <span><NumberHelp focusable={false} description="Kapasite veya uygun tezgâh bulunamadığı için plana yerleşemeyen şarj sayısı.">{row.result.summary.unplannedBatchCount}</NumberHelp></span>
                <span><NumberHelp focusable={false} description="En dolu ve en boş kullanılan tezgâhların yük oranları arasındaki fark; düşük olması daha dengeli dağılım demektir.">{formatPercent(row.loadSpread)}</NumberHelp></span>
                <span><NumberHelp focusable={false} description="Bu seçenekle oluşan tüm şarj geçişlerinin toplam setup süresi.">{formatHours(row.result.summary.totalSetupHours)}</NumberHelp></span>
                <span><NumberHelp focusable={false} description="Bu seçenek uygulandığında Gantt üzerindeki son planlı işin bitiş tarihi.">{formatExcelDate(row.result.summary.completion, { day: "2-digit", month: "short" })}</NumberHelp></span>
              </button>)}
            </div>
          </section>}
          {error && <p className="form-error" role="alert">{error}</p>}
        </div>
        <div className="drawer-actions plan-run-actions">
          <button className="secondary" onClick={onClose}>Vazgeç</button>
          {!appendToExistingPlan && !coarsePlanning && <button className="secondary plan-compare-action" disabled={!dateRangeValid || comparing} onClick={runComparison}><ChartBar size={15} /> {comparing ? "Karşılaştırılıyor…" : "Seçenekleri karşılaştır"}</button>}
          <button className="primary" disabled={!dateRangeValid || comparing} onClick={submit}><Play size={15} weight="fill" /> {appendToExistingPlan ? weekRanges.length > 1 ? "İlk yeni aralığı ekle" : "Aralığı plana ekle" : customerDemand && weekRanges.length > 1 ? "İlk aralığı planla" : "Planı oluştur"}</button>
        </div>
      </section>
    </div>
  );
}

frontend/features/planning/board/Plannin.source:
"use client";

import { type DeliverySummaryProps } from "@/features/planning/shared/DeliverySummary";
import { useRaviScreenContext } from "@/features/ravi/context";

import { CapacityDrawer } from "@/features/planning/board/CapacityDrawer";
import { BatchInspector, JourneyInspector } from "@/features/planning/board/Inspectors";
import { PlanBoard } from "@/features/planning/board/PlanBoard";
import { Metric } from "@/features/planning/shared/controls";
import { formatPercent } from "@/features/planning/shared/format";
import { type PlanningOperations } from "@/features/planning/shared/types";
import { buildOrderDeliveryResults } from "@/lib/delivery-readiness";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { buildPlanCoverageMetrics } from "@/lib/plan-coverage";
import { type PlannedBatch, type PlanningSeed, type PlanRunSequence, type ScenarioResult } from "@/lib/planning";
import { type PlanningAdvice } from "@/lib/planning-advice";
import { buildDownstreamProcessPlan } from "@/lib/process-planning";
import {
  ArrowsLeftRight,
  CaretDown,
  CaretLeft,
  CaretRight,
  ChartBar,
  CheckCircle,
  Clock,
  PencilSimple,
  Play,
  Plus,
} from "@phosphor-icons/react";
import { useMemo, useState } from "react";

export function PlanningView({ report, reportRange, onReportRangeChange, seed, result, dirty, selectedBatch, onSelectBatch, onMoveBatch, onRemoveBatch, onLockThrough, onUnlockQueue, onSaveWorkOrder, onUpdateBatchQuantity, onSaveCurrentJob, onCompleteCurrentJob, onOperationError, advice, onApplyAdvice, onOpenMachineAdvice, onOpenManualBatch, automaticComparisonAvailable, onOpenAutomaticComparison, onPlanNextRange, updateSeed, onRescheduleProcess, onReplanProcess, onOpenJourney }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; selectedBatch: PlannedBatch | null; onSelectBatch: (id: string) => void; onOperationError: (message: string) => void; advice: PlanningAdvice[]; onApplyAdvice: (item: PlanningAdvice) => void; onOpenMachineAdvice: (machineId: string) => void; onOpenManualBatch: () => void; automaticComparisonAvailable: boolean; onOpenAutomaticComparison: () => void; onPlanNextRange: () => void; onRescheduleProcess: (operationId: string, resourceId: string, requestedStart: number, signature: string) => import("@/lib/process-planning").ProcessOperation; onReplanProcess: (process: "drilling" | "deburring" | "gkm") => boolean; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; onOpenJourney: (jobId: string) => void } & PlanningOperations & Omit<DeliverySummaryProps, "hasPlan">) {
  const coverage = buildPlanCoverageMetrics({ ...result, orders: buildOrderDeliveryResults(seed, result) });
  const active = seed.machines.filter((machine) => machine.active).length;
  const hasPlan = result.state === "planned";
  const stagedSequence = seed.planRunSequence;
  const hasPendingPlanRange = Boolean(
    stagedSequence && stagedSequence.completedRangeCount < stagedSequence.ranges.length,
  );
  const [selectedCurrentMachineId, setSelectedCurrentMachineId] = useState<string | null>(null);
  const [selectedProcessOperationId, setSelectedProcessOperationId] = useState("");
  const [capacityOpen, setCapacityOpen] = useState(false);
  const [inspectorOpen, setInspectorOpen] = useState(false);
  const selectedCurrentMachine = seed.machines.find((machine) => machine.id === selectedCurrentMachineId && machine.currentJob.product) ?? null;
  const downstreamPlan = useMemo(() => buildDownstreamProcessPlan(seed, result), [result, seed]);
  const selectedProcessOperation = downstreamPlan.operations.find((operation) => operation.id === selectedProcessOperationId);
  const selectedProcessJob = selectedProcessOperation ? downstreamPlan.jobs.find((job) => job.batchId === selectedProcessOperation.batchId) : undefined;
  useRaviScreenContext("planning", { selectedCurrentMachine, selectedProcessOperation, selectedProcessJob,
    capacityOpen, inspectorOpen, coverage, deliveryReport: report, reportRange, calculationSource: { coverageRate: "Teslimat Planı Excel", productionMetrics: "buildPlanCoverageMetrics(buildOrderDeliveryResults)" } });
  const selectBatch = (id: string) => { setSelectedCurrentMachineId(null); setSelectedProcessOperationId(""); setInspectorOpen(true); onSelectBatch(id); };
  const selectCurrentJob = (machineId: string) => { setSelectedProcessOperationId(""); setSelectedCurrentMachineId(machineId); setInspectorOpen(true); };
  const selectProcessOperation = (operationId: string) => { setSelectedCurrentMachineId(null); setSelectedProcessOperationId(operationId); if (operationId) setInspectorOpen(true); };
  return (
    <>
      <section className="metrics" aria-label="Plan summary">
        <Metric label="Toplam sipariş" value={formatNumber(result.summary.demand)} detail={`${seed.orders.filter((order) => order.quantity > 0).length} aktif sipariş · ${hasPlan ? `${formatNumber(result.summary.planned)} üretim kapsamında` : "plan bekliyor"}`} description="Seçili planlama kapsamındaki toplam net ihtiyaç. Alt satır planda bulunan toplam üretim miktarını ayrıca gösterir." />
        <Metric label="Karşılama oranı" value={report.payload && report.coverage != null ? new Intl.NumberFormat("tr-TR", { style: "percent", minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(report.coverage) : "—"} detail={report.payload ? `${reportRange.startDate} – ${reportRange.endDate} · Teslimat Planı` : "Teslimat raporu hesaplanamadı"} tone={report.payload && report.shortage! < 0 ? "warning" : "default"} description="Siparişler ile aynı Teslimat Planı döneminde, ürün bazındaki eksik miktarın sipariş miktarından düşülmesiyle hesaplanır. Ürün fazlaları başka ürünün açığını kapatmaz." />
        <Metric label="Termin sonrası" value={hasPlan ? formatNumber(coverage.lateCovered) : "—"} detail={hasPlan ? coverage.lateCovered > 0 ? "Planda var, termininden sonra hazır" : "Geciken planlı miktar yok" : "Plan sonrası hesaplanır"} tone={hasPlan && coverage.lateCovered > 0 ? "warning" : "default"} description="Üretim planında bulunan fakat ilgili sipariş terminine yetişmeyen miktar. Bu miktar kaybolmaz; zamanında karşılama oranına dahil edilmez." />
        <Metric label="Açık kalan" value={hasPlan ? formatNumber(coverage.uncovered) : "—"} detail={hasPlan ? coverage.uncovered > 0 ? `${result.summary.unplannedBatchCount} planlanamayan şarj` : "Tüm ihtiyaç planda mevcut" : "Plan sonrası hesaplanır"} tone={hasPlan && coverage.uncovered > 0 ? "danger" : "default"} description="Ne termininde ne de daha sonraki üretim planında karşılığı bulunan ihtiyaç miktarı." />
        <Metric label="Aktif tezgah" value={`${formatNumber(active)} / ${formatNumber(seed.machines.length)}`} detail={hasPlan ? `${formatNumber(result.summary.plannedBatchCount)} yeni şarj` : "Plan boş"} description="Soldaki sayı planlamaya açık tezgahları, sağdaki sayı sistemde tanımlı tüm tezgahları gösterir." />
      </section>
      {stagedSequence && hasPendingPlanRange && <PlanRunSequenceBar sequence={stagedSequence} disabled={!hasPlan || dirty} onNext={onPlanNextRange} />}
      <details className="planning-tools">
        <summary><span><strong>Planlama araçları</strong><small>{seed.planRunSequence ? "Aralıklar, doluluk, karşılaştırma ve manuel işlemler" : "Doluluk, karşılaştırma ve manuel şarj"}</small></span><CaretDown size={14} /></summary>
        {stagedSequence && !hasPendingPlanRange && <PlanRunSequenceBar sequence={stagedSequence} disabled={!hasPlan || dirty} onNext={onPlanNextRange} />}
        <div className="planning-quick-actions">{automaticComparisonAvailable && <button className="secondary automatic-compare-action" onClick={onOpenAutomaticComparison}><ArrowsLeftRight size={14} /> Otomatik planla karşılaştır</button>}<button className="secondary capacity-inline-action" disabled={!hasPlan || dirty} onClick={() => setCapacityOpen(true)}><ChartBar size={14} /> Tezgah dolulukları</button><button className="secondary" disabled={!hasPlan || dirty} onClick={onOpenManualBatch}><Plus size={14} /> Manuel şarj</button></div>
      </details>
      <section className={`workspace ${inspectorOpen ? "" : "inspector-collapsed"}`}>
        <PlanBoard seed={seed} result={result} dirty={dirty} advice={advice} selectedBatch={selectedCurrentMachine ? null : selectedBatch} selectedCurrentMachineId={selectedCurrentMachineId} selectedProcessOperationId={selectedProcessOperationId} onSelectProcessOperation={selectProcessOperation} onSelectBatch={selectBatch} onSelectCurrentJob={selectCurrentJob} onMoveBatch={onMoveBatch} onLockThrough={onLockThrough} onUnlockQueue={onUnlockQueue} onApplyAdvice={onApplyAdvice} onOpenMachineAdvice={onOpenMachineAdvice} onSaveCurrentJob={onSaveCurrentJob} onCompleteCurrentJob={onCompleteCurrentJob} onOperationError={onOperationError} updateSeed={updateSeed} onReplanProcess={onReplanProcess} onRescheduleProcess={onRescheduleProcess} />
        {inspectorOpen ? <div className="inspector-shell"><button className="inspector-toggle" onClick={() => setInspectorOpen(false)} aria-label="Seçili şarj panelini daralt" title="Paneli daralt"><CaretRight size={15} /></button>{selectedProcessOperation && selectedProcessJob ? <JourneyInspector job={selectedProcessJob} operation={selectedProcessOperation} onSelectOperation={selectProcessOperation} onOpenJourney={() => onOpenJourney(selectedProcessJob.batchId)} /> : <BatchInspector seed={seed} batch={selectedCurrentMachine ? null : selectedBatch} currentMachine={selectedCurrentMachine} machines={seed.machines} queueLength={selectedBatch ? result.batches.filter((batch) => batch.status === "planned" && batch.machineId === selectedBatch.machineId).length : 0} onMove={onMoveBatch} onRemove={onRemoveBatch} onLockThrough={onLockThrough} onUnlockQueue={onUnlockQueue} onSaveWorkOrder={onSaveWorkOrder} onUpdateBatchQuantity={onUpdateBatchQuantity} />}</div> : <button className="inspector-rail" onClick={() => setInspectorOpen(true)} aria-label="Seçili şarj panelini aç" title="Seçili şarj ayrıntılarını aç"><CaretLeft size={15} /><span>{selectedProcessOperation ? "Şarj yolculuğu" : selectedCurrentMachine ? "Mevcut iş" : "Seçili şarj"}</span></button>}
      </section>
      {capacityOpen && <CapacityDrawer seed={seed} result={result} onClose={() => setCapacityOpen(false)} />}
    </>
  );
}

function PlanRunSequenceBar({ sequence, disabled, onNext }: { sequence: PlanRunSequence; disabled: boolean; onNext: () => void }) {
  const completed = Math.min(sequence.completedRangeCount, sequence.ranges.length);
  const nextRange = sequence.ranges[completed];
  const currentRange = sequence.ranges[Math.max(0, completed - 1)];
  const complete = completed >= sequence.ranges.length;
  return (
    <section className={`plan-sequence-bar ${complete ? "complete" : ""}`} aria-label="Aşamalı planlama durumu">
      <div className="plan-sequence-copy">
        <span>{complete ? "ARALIKLAR TAMAMLANDI" : "MANUEL KONTROL ADIMI"}</span>
        <strong>{complete ? `${sequence.ranges.length} aralığın tamamı planlandı` : `${completed}. aralık planlandı · ${currentRange.label}`}</strong>
        <small>{complete ? "Planlanan tüm aralıklar aynı Gantt üzerinde birleşik olarak korunuyor." : `Mevcut planı düzenleyip doğrulayın; hazır olduğunuzda ${nextRange.label} aralığını arkasına ekleyin.`}</small>
      </div>
      <div className="plan-sequence-track">
        {sequence.ranges.map((range, index) => {
          const isReviewing = !complete && index === completed - 1;
          const isCompleted = index < completed && !isReviewing;
          const isNext = index === completed;
          const status = isReviewing ? "Kontrol ediliyor" : isCompleted || complete ? "Tamamlandı" : isNext ? "Sıradaki" : "Bekliyor";
          return <span key={`${range.startWeekId}-${range.endWeekId}`} className={isReviewing ? "reviewing" : isCompleted || complete ? "completed" : isNext ? "next" : "pending"}><i>{isCompleted || complete ? <CheckCircle size={13} weight="fill" /> : isReviewing ? <PencilSimple size={13} /> : <Clock size={13} />}</i><b>{index + 1}. {range.label}</b><small>{status}</small></span>;
        })}
      </div>
      {!complete && <button className="plan-next-range-action" disabled={disabled} onClick={onNext}><Play size={14} weight="fill" /><span>Sıradaki aralığı planla<small>{nextRange.label}</small></span></button>}
    </section>
  );
}

frontend/features/planning/board/WeeklyD.source:
"use client";

import { formatInputDate, serialToInputDate } from "@/features/planning/shared/format";
import { turningDeliveryReadyAt } from "@/lib/delivery-calendar";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { type PlannedBatch, formatExcelDate } from "@/lib/planning";
import { type BatchSplitInsight, type WeeklyPlanStatus, selectedBatchWeeklyStatus } from "@/lib/weekly-plan-status";
import { Question } from "@phosphor-icons/react";

export function WeeklyDemandRibbon({ rows, selectedBatch, selectedReadyAt, splitInsight, previewing, coarsePlanning, onFocusWeek }: { rows: WeeklyPlanStatus[]; selectedBatch: PlannedBatch | null; selectedReadyAt?: number; splitInsight: BatchSplitInsight | null; previewing: boolean; coarsePlanning: boolean; onFocusWeek: (dueDate: string) => void }) {
  const selected = selectedBatchWeeklyStatus(rows, selectedBatch);
  const readyDate = selectedBatch ? serialToInputDate(selectedReadyAt ?? turningDeliveryReadyAt(selectedBatch.end)) : "";
  const selectedOnTime = Boolean(selectedBatch?.demandDueDate && readyDate <= selectedBatch.demandDueDate);
  if (!rows.length) return <section className="weekly-demand-ribbon empty"><div className="weekly-demand-empty-state"><span>HAFTALIK TERMİN</span><strong>Haftalık talep bulunmuyor</strong><small>Müşteri sipariş haftaları içe aktarıldığında termin etkisi burada görünür.</small></div></section>;
  return (
    <section className={`weekly-demand-ribbon ${previewing ? "previewing" : ""}`} aria-label="Haftalık talep ve termin durumu">
      <div className="weekly-demand-context">
        <span className="weekly-demand-kicker">{previewing ? "TAŞIMA ÖNİZLEMESİ" : coarsePlanning ? "STANDART PLANLAMA" : "HAFTALIK TERMİN"}<WeeklyDemandHelp coarsePlanning={coarsePlanning} /></span>
        <strong>{coarsePlanning ? "Tek toplam talep · tek üretim penceresi" : selected ? `${selected.product.product} · ${selected.week.label} hedefi` : "Talep ile plan aynı çizgide"}</strong>
        <small>{coarsePlanning
          ? selected
            ? `Bu şarj tornayı ${formatExcelDate(selectedBatch?.end ?? 0)} tarihinde tamamlar. Haftalık termin yerine pencere sonundaki toplam üretim kontrol edilir.`
            : "Haftalık teslim tarihleri bu deneyde değerlendirilmez; seçili aralığın toplam talebi pencere sonuna kadar tornada tamamlanır."
          : selected
            ? `Bu şarj ${formatInputDate(readyDate)} tarihinde teslimata hazır olur. ${formatNumber(selected.product.ready)} / ${formatNumber(selected.product.required)} adet yetişiyor${selectedOnTime ? "." : `; ${formatNumber(selected.product.shortage)} adet açık kalıyor.`}`
            : "Her hafta yeni talep ile o tarihe kadar teslimata hazır miktarı gösterir. Bir şarjı taşıdığınızda sonuç anında güncellenir."}</small>
        {!coarsePlanning && splitInsight && <em className={splitInsight.justifiedByDeadline ? "justified" : "review"}>{splitInsight.justifiedByDeadline
          ? `Kampanya bölündü: ${splitInsight.interveningProduct}, ${formatInputDate(splitInsight.interveningDueDate)} terminine önce yetişmeli.`
          : `Kampanya bölünmüş; aradaki ${splitInsight.interveningProduct} için daha erken termin görünmüyor. İncelemeye değer.`}</em>}
      </div>
      <div className="weekly-demand-weeks">
        {rows.map((row) => {
          const selectedWeek = selectedBatch?.demandDueDate === row.dueDate;
          return <button key={row.id} className={`${row.excludedFromPlan ? "backlog" : row.shortage > 0 ? "risk" : "ready"} ${selectedWeek ? "selected" : ""}`} onClick={() => onFocusWeek(row.dueDate)} title={`${row.excludedFromPlan ? "Plan dışında · " : `${formatInputDate(row.dueDate)} · `}${formatNumber(row.required)} gerekli · ${formatNumber(row.ready)} hazır`}>
            <span>{row.label}<small>{row.excludedFromPlan ? formatNumber(row.newDemand) : `+${formatNumber(row.newDemand)}`}</small></span>
            <strong>{formatNumber(row.ready)} / {formatNumber(row.required)}</strong>
            <em>{row.excludedFromPlan ? `${formatNumber(row.shortage)} açık · plan dışında` : coarsePlanning ? row.shortage > 0 ? `${formatNumber(row.shortage)} pencereye sığmadı` : "Pencereye sığdı" : row.shortage > 0 ? `${formatNumber(row.shortage)} eksik · ${formatNumber(row.riskProductCount)} tip` : "Termin tamam"}</em>
          </button>;
        })}
      </div>
    </section>
  );
}

function WeeklyDemandHelp({ coarsePlanning }: { coarsePlanning: boolean }) {
  const description = coarsePlanning
    ? "Standart planlama kartlarında yeni talep, pencere içinde tamamlanan miktar, toplam ihtiyaç ve pencereye sığmayan miktar açıklanır."
    : "Haftalık termin kartlarında yeni talep, teslimata hazır miktar, toplam ihtiyaç ve termin eksiği açıklanır.";
  return <span className="number-help-trigger general-help-trigger" tabIndex={0} aria-label={description}><Question size={10} weight="bold" aria-hidden="true" /><span role="tooltip" className="weekly-demand-guide">
    <span className="weekly-demand-guide-eyebrow">KART OKUMA REHBERİ</span>
    <strong>{coarsePlanning ? "Üretim penceresi nasıl okunur?" : "Haftalık termin nasıl okunur?"}</strong>
    <span className="weekly-demand-guide-rows">
      <span><b>+ Yeni talep</b><small>O haftada siparişe eklenen üretim ihtiyacı.</small></span>
      <span><b>{coarsePlanning ? "Tamamlanan" : "Hazır"}</b><small>{coarsePlanning ? "Pencere bitimine kadar üretimi tamamlanan adet; karttaki sol sayı." : "Termin tarihine kadar teslimata hazır olacak adet; karttaki sol sayı."}</small></span>
      <span><b>Toplam ihtiyaç</b><small>{coarsePlanning ? "Seçili pencerenin sonuna kadarki toplam talep; karttaki sağ sayı." : "O termin tarihine kadarki birikmiş ihtiyaç; karttaki sağ sayı."}</small></span>
      <span><b>{coarsePlanning ? "Sığmayan" : "Eksik · tip"}</b><small>{coarsePlanning ? "Pencere bitimine kadar üretilemeyen adet." : "Termine yetişmeyen adet ve bundan etkilenen ürün tipi sayısı."}</small></span>
    </span>
    <span className="weekly-demand-guide-rule"><i />{coarsePlanning ? "Sol sayı sağ sayıdan küçükse üretim pencereye sığmıyor." : "Sol sayı sağ sayıdan küçükse termin riski vardır."}</span>
  </span></span>;
}

frontend/features/planning/machines/Cale.source:
"use client";

import { Field } from "@/features/planning/shared/controls";
import { dateAfterDays, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { clampShiftCount } from "@/features/planning/shared/production";
import { type Machine, type MachineCalendarEvent, type ShiftCount, formatExcelDate } from "@/lib/planning";
import { Clock, PencilSimple, Trash, Wrench, X } from "@phosphor-icons/react";
import { useState } from "react";

export function MachineShiftDialog({ machine, events = [], initialEvent, onClose, onSave, onDelete }: { machine: Machine; events?: MachineCalendarEvent[]; initialEvent?: MachineCalendarEvent; onClose: () => void; onSave: (name: string, start: number, end: number, shifts: ShiftCount, editingId?: string) => void; onDelete?: (eventId: string) => void }) {
  const defaultShifts = clampShiftCount(machine.shiftFactor) || 1;
  const emptyDraft = { name: "Vardiya değişikliği", start: dateAfterDays(1), end: dateAfterDays(1), shifts: defaultShifts };
  const eventDraft = initialEvent ? { name: initialEvent.name, start: serialToInputDate(initialEvent.start), end: serialToInputDate(initialEvent.end), shifts: clampShiftCount(initialEvent.shiftCount) } : emptyDraft;
  const [editingId, setEditingId] = useState<string | undefined>(initialEvent?.id);
  const [draft, setDraft] = useState<{ name: string; start: string; end: string; shifts: ShiftCount }>(eventDraft);
  const start = inputDateToSerial(draft.start);
  const end = inputDateToSerial(draft.end);
  const valid = Boolean(draft.name.trim() && start && end && end >= start);
  const shiftEvents = [...events].filter((event) => event.kind === "shift").sort((left, right) => left.start - right.start);

  function edit(event: MachineCalendarEvent) {
    setEditingId(event.id);
    setDraft({ name: event.name, start: serialToInputDate(event.start), end: serialToInputDate(event.end), shifts: clampShiftCount(event.shiftCount) });
  }

  function reset() {
    setEditingId(undefined);
    setDraft(emptyDraft);
  }

  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog shift-manager-dialog" role="dialog" aria-modal="true" aria-label={`${machine.id} günlük vardiya ayarı`}><div className="operational-dialog-head"><span className="dialog-icon shift"><Clock size={20} /></span><div><span>TEZGAH TAKVİMİ</span><h2>{machine.id} için günlük vardiya</h2><p>Yeni bir istisna ekleyin veya daha önce girilmiş vardiya değişikliklerini düzenleyin.</p></div><button className="delete-button" onClick={onClose} aria-label="Günlük vardiya penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Açıklama"><input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></Field><div className="dialog-date-range"><Field label="Başlangıç"><input type="date" value={draft.start} onChange={(event) => setDraft({ ...draft, start: event.target.value, end: event.target.value > draft.end ? event.target.value : draft.end })} /></Field><Field label="Bitiş"><input type="date" min={draft.start} value={draft.end} onChange={(event) => setDraft({ ...draft, end: event.target.value })} /></Field></div><Field label="Çalışılacak vardiya"><select value={draft.shifts} onChange={(event) => setDraft({ ...draft, shifts: clampShiftCount(Number(event.target.value)) })}><ShiftOptions /></select></Field><div className="calendar-impact-note"><strong>{editingId ? "Kayıt düzenleniyor" : draft.shifts === 0 ? "Bu tarihlerde üretim duracak" : `${draft.shifts} vardiya kapasite uygulanacak`}</strong><span>Kaydettiğinizde mevcut kuyruk korunur ve başlangıç/bitiş tarihleri hemen yeniden hesaplanır.</span></div><div className="drawer-actions">{editingId && <button className="secondary" onClick={reset}>Yeni kayıt</button>}<button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(draft.name.trim(), start, end, draft.shifts, editingId)}>{editingId ? "Değişikliği kaydet" : "Uygula ve hesapla"}</button></div></div>{shiftEvents.length > 0 && <div className="shift-manager-records"><div><span>MEVCUT VARDİYA DEĞİŞİKLİKLERİ</span><small>{shiftEvents.length} kayıt</small></div>{shiftEvents.map((event) => <article key={event.id} className={editingId === event.id ? "editing" : ""}><span><strong>{event.name}</strong><small>{formatExcelDate(event.start)}{event.end !== event.start ? ` – ${formatExcelDate(event.end)}` : ""} · {event.shiftCount} vardiya</small></span><button onClick={() => edit(event)}><PencilSimple size={13} /> Düzenle</button>{onDelete && <button className="delete-button" onClick={() => { onDelete(event.id); if (editingId === event.id) reset(); }} aria-label={`${event.name} vardiya kaydını sil`}><Trash size={14} /></button>}</article>)}</div>}</section></div>;
}

export function MachineMaintenanceDialog({ machine, events = [], initialEvent, onClose, onSave, onDelete }: { machine: Machine; events?: MachineCalendarEvent[]; initialEvent?: MachineCalendarEvent; onClose: () => void; onSave: (name: string, start: number, end: number, editingId?: string) => void; onDelete?: (eventId: string) => void }) {
  const emptyDraft = { name: "Planlı bakım", start: dateAfterDays(1), end: dateAfterDays(1) };
  const [editingId, setEditingId] = useState<string | undefined>(initialEvent?.id);
  const [draft, setDraft] = useState(initialEvent ? { name: initialEvent.name, start: serialToInputDate(initialEvent.start), end: serialToInputDate(initialEvent.end) } : emptyDraft);
  const start = inputDateToSerial(draft.start);
  const end = inputDateToSerial(draft.end);
  const valid = Boolean(draft.name.trim() && start && end && end >= start);
  const maintenanceEvents = [...events].filter((event) => event.kind === "maintenance").sort((left, right) => left.start - right.start);
  function edit(event: MachineCalendarEvent) { setEditingId(event.id); setDraft({ name: event.name, start: serialToInputDate(event.start), end: serialToInputDate(event.end) }); }
  function reset() { setEditingId(undefined); setDraft(emptyDraft); }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog shift-manager-dialog" role="dialog" aria-modal="true" aria-label={`${machine.id} planlı bakım yönetimi`}><div className="operational-dialog-head"><span className="dialog-icon maintenance"><Wrench size={20} /></span><div><span>TEZGAH TAKVİMİ</span><h2>{machine.id} için planlı bakım</h2><p>Yeni bakım ekleyin veya mevcut bakımın tarihlerini revize edin.</p></div><button className="delete-button" onClick={onClose} aria-label="Planlı bakım penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Bakım açıklaması"><input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></Field><div className="dialog-date-range"><Field label="Başlangıç"><input type="date" value={draft.start} onChange={(event) => setDraft({ ...draft, start: event.target.value, end: event.target.value > draft.end ? event.target.value : draft.end })} /></Field><Field label="Bitiş"><input type="date" min={draft.start} value={draft.end} onChange={(event) => setDraft({ ...draft, end: event.target.value })} /></Field></div><div className="calendar-impact-note maintenance"><strong>{editingId ? "Bakım tarihleri revize ediliyor" : valid ? `${Math.floor(end - start) + 1} takvim günü duruş` : "Tarih aralığını kontrol edin"}</strong><span>Kaydettiğinizde Gantt ve kapasite hesabı yeni tarihlere göre güncellenir.</span></div><div className="drawer-actions">{editingId && <button className="secondary" onClick={reset}>Yeni bakım</button>}<button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(draft.name.trim(), start, end, editingId)}>{editingId ? "Revizyonu kaydet" : "Bakımı takvime ekle"}</button></div></div>{maintenanceEvents.length > 0 && <div className="shift-manager-records"><div><span>MEVCUT BAKIMLAR</span><small>{maintenanceEvents.length} kayıt</small></div>{maintenanceEvents.map((event) => <article key={event.id} className={editingId === event.id ? "editing" : ""}><span><strong>{event.name}</strong><small>{formatExcelDate(event.start)}{event.end !== event.start ? ` – ${formatExcelDate(event.end)}` : ""}</small></span><button onClick={() => edit(event)}><PencilSimple size={13} /> Tarihi revize et</button>{onDelete && <button className="delete-button" onClick={() => { onDelete(event.id); if (editingId === event.id) reset(); }} aria-label={`${event.name} bakım kaydını sil`}><Trash size={14} /></button>}</article>)}</div>}</section></div>;
}

export function ShiftOptions() { return <>{[0, 1, 2, 3].map((value) => <option key={value} value={value}>{value === 0 ? "0 · Üretim yok" : `${value} vardiya`}</option>)}</>; }

frontend/features/planning/machines/Mach.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessPlacementReview, placementDate, type PlacementPreview } from "@/features/planning/shared/ProcessPlacementReview";

import { ProcessIcon } from "@/components/ProcessIcon";

import { ProductionProcessTabs } from "@/components/ProductionProcessWorkspace";
import { MachineMaintenanceDialog, MachineShiftDialog, ShiftOptions } from "@/features/planning/machines/CalendarDialogs";
import {
  BatchQuantityDialog,
  CompleteJobDialog,
  CompleteProcessCurrentJobDialog,
  CompleteQueuedProcessOperationDialog,
  CurrentJobEditor,
  ProcessCurrentJobEditor,
  ProcessCurrentJobSwitcher,
} from "@/features/planning/machines/ProductionDialogs";
import { Field } from "@/features/planning/shared/controls";
import { formatHours, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import {
  actualProcessResources,
  clampShiftCount,
  normalizeMachineId,
  productionProcessLabel,
  queuePosition,
} from "@/features/planning/shared/production";
import { type PlanningOperations } from "@/features/planning/shared/types";
import { buildOvertimeEntries } from "@/lib/capacity-analytics";
import { factoryDateInput, factoryNowSerial } from "@/lib/factory-time";
import { buildMachineDiagnostics } from "@/lib/machine-diagnostics";
import { analyzeMachineDeletion, deleteMachineDefinition } from "@/lib/machine-management";
import { formatInteger as formatNumber } from "@/lib/number-format";
import {
  formatExcelDate,
  isMachineEligibleForProduct,
  productSetupFamily,
  removeMachineShiftOverrides,
  replaceMachineShiftOverrides,
  type Machine,
  type Order,
  type PlannedBatch,
  type PlanningSeed,
  type Product,
  type ScenarioResult,
  type ShiftCount,
} from "@/lib/planning";
import { processLabel, type DownstreamProcess, type ProcessKind, type ProcessResource } from "@/lib/process-master-data";
import {
  buildDownstreamProcessPlan,
  processJobStartAvailability,
  previewProcessQueuePlacement, processPlacementSignature, type ProcessQueuePlacementRequest,
  type ProcessCurrentJobInput,
  type ProcessOperation,
} from "@/lib/process-planning";
import { productSetupFamilyLabel, resolvedProductSetupFamily, type ProductSetupFamily } from "@/lib/setup-families";
import { type WipOperationInput } from "@/lib/wip-ledger";
import {
  Archive,
  ArrowCounterClockwise,
  CaretDown,
  CaretUp,
  CheckCircle,
  Clock,
  DotsSixVertical,
  Lock,
  LockOpen,
  MagnifyingGlass,
  PencilSimple,
  Play,
  Plus,
  Trash,
  Warning,
  Wrench,
  X,
} from "@phosphor-icons/react";
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

export function MachinesView({ seed, result, dirty, selectedMachineId, setSelectedMachineId, updateSeed, updateCalendar, onAddBatch, onMoveBatch, onRemoveBatch, onLockThrough, onUnlockQueue, onSaveWorkOrder, onUpdateBatchQuantity, onSaveCurrentJob, onCompleteCurrentJob, onStartProcessCurrentJob, onReplaceProcessCurrentJob, onSaveProcessCurrentJob, onCompleteProcessCurrentJob, onCompleteWipOperation, onPlaceProcessQueue, onReplanProcess }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; selectedMachineId: string; setSelectedMachineId: (id: string) => void; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; updateCalendar: (mutator: (seed: PlanningSeed) => void) => void; onAddBatch: (product: string, machine: string, quantity: number, position: number) => void; onPlaceProcessQueue: (request: ProcessQueuePlacementRequest, signature: string) => ProcessOperation; onReplanProcess: (process: DownstreamProcess) => boolean; onStartProcessCurrentJob: (operationId: string) => void; onReplaceProcessCurrentJob: (resourceId: string, operationId: string) => void; onSaveProcessCurrentJob: (resourceId: string, input: ProcessCurrentJobInput) => void; onCompleteProcessCurrentJob: (resourceId: string, completedAt: number, completedQuantity?: number, actualResourceId?: string) => void; onCompleteWipOperation: (input: WipOperationInput) => boolean } & PlanningOperations) {
  const machines = seed.machines;
  const products = seed.products;
  const batches = result.batches;
  const [activeProcess, setActiveProcess] = useState<ProcessKind>("turning");
  const [selectedProcessResources, setSelectedProcessResources] = useState<Partial<Record<ProcessKind, string>>>({});
  const selected = machines.find((machine) => machine.id === selectedMachineId) ?? machines[0];
  const downstreamResources = (seed.processMasterData?.resources ?? []).filter((resource) => resource.process === activeProcess);
  const activeResourceId = activeProcess === "turning" ? selected.id : selectedProcessResources[activeProcess] ?? downstreamResources[0]?.id ?? "";
  const selectedDownstreamResource = downstreamResources.find((resource) => resource.id === activeResourceId) ?? downstreamResources[0];
  const downstreamPlan = useMemo(() => buildDownstreamProcessPlan(seed, result), [result, seed]);
  const downstreamOperations = downstreamPlan.operations.filter((operation) => !operation.actual && operation.process === activeProcess);
  const selectedProcessCurrentJob = (seed.processCurrentJobs ?? []).find((job) => job.process === activeProcess && job.resourceId === activeResourceId);
  const selectedProcessSchedule = downstreamOperations.filter((operation) => !operation.current && operation.resourceId === activeResourceId).sort((left, right) => left.start - right.start || left.id.localeCompare(right.id));
  const [processNow, setProcessNow] = useState(factoryNowSerial);
  useEffect(() => { const timer = window.setInterval(() => setProcessNow(factoryNowSerial()), 30_000); return () => window.clearInterval(timer); }, []);
  const startAvailability = processJobStartAvailability(seed, downstreamPlan, activeResourceId, Math.max(processNow, factoryNowSerial()));
  const processStartCandidate = startAvailability.operation;
  const diagnostics = useMemo(() => buildMachineDiagnostics(seed, result, { dirty }), [dirty, result, seed]);
  const diagnostic = diagnostics[selected.id];
  const schedule = batches.filter((batch) => batch.status === "planned" && batch.machineId === selected.id).sort((left, right) => left.planColumn - right.planColumn);
  const activeOrdersByProduct = new Map(seed.orders.filter((order) => order.quantity > 0).map((order) => [order.product.toUpperCase(), order]));
  const calculatedOrdersByProduct = new Map(result.orders.map((order) => [order.product.toUpperCase(), order]));
  const compatibleProducts = products.filter((product) => (selected.rates[product.product.toUpperCase()] ?? 0) > 0 && isMachineEligibleForProduct(seed, selected.id, product.product));
  const availableProducts = compatibleProducts.filter((product) => activeOrdersByProduct.has(product.product.toUpperCase()));
  const compatibleWithoutOrderCount = compatibleProducts.length - availableProducts.length;
  const [manualDialogOpen, setManualDialogOpen] = useState(false);
  const [jobEditorOpen, setJobEditorOpen] = useState(false);
  const [completionOpen, setCompletionOpen] = useState(false);
  const [processJobEditorOpen, setProcessJobEditorOpen] = useState(false);
  const [processJobSwitcherOpen, setProcessJobSwitcherOpen] = useState(false);
  const [processCompletionOpen, setProcessCompletionOpen] = useState(false);
  const [queuedProcessCompletion, setQueuedProcessCompletion] = useState<ProcessOperation | null>(null);
  const [maintenanceDialogOpen, setMaintenanceDialogOpen] = useState(false);
  const [shiftDialogOpen, setShiftDialogOpen] = useState(false);
  const [catalogOpen, setCatalogOpen] = useState(false);
  const [processManualDialogOpen, setProcessManualDialogOpen] = useState(false);
  const [processMaintenanceDialogOpen, setProcessMaintenanceDialogOpen] = useState(false);
  const [processShiftDialogOpen, setProcessShiftDialogOpen] = useState(false);
  const [processCatalogOpen, setProcessCatalogOpen] = useState(false);
  const [editingQuantityBatch, setEditingQuantityBatch] = useState<PlannedBatch | null>(null);
  const [queueDrag, setQueueDrag] = useState<{ batchId: string; position: number; targetRowIndex: number; edge: "before" | "after" } | null>(null);
  const [processQueueDrag, setProcessQueueDrag] = useState<{ operationId: string; position: number; targetRowIndex: number; edge: "before" | "after" } | null>(null);
  const [processQueueFeedback, setProcessQueueFeedback] = useState<{ tone: "success" | "error"; message: string } | null>(null);
  const [pendingQueueMove, setPendingQueueMove] = useState<ProcessQueuePlacementRequest | null>(null);
  const [queueReviewError, setQueueReviewError] = useState("");
  const [lastAppliedQueueMove, setLastAppliedQueueMove] = useState<ProcessOperation | null>(null);
  const appliedQueueDestinationRef = useRef<string | null>(null);
  const processQueueListRef = useRef<HTMLDivElement | null>(null);
  const [processQueueQuery, setProcessQueueQuery] = useState("");
  useRaviScreenContext("machines", { activeProcess, activeResourceId, processQueueQuery,
    selectedMachine: activeProcess === "turning" ? selected : undefined,
    diagnostic: activeProcess === "turning" ? diagnostic : undefined,
    dialogs: { jobEditorOpen, completionOpen, maintenanceDialogOpen, shiftDialogOpen, processJobEditorOpen, processCompletionOpen },
    calculationSource: "buildMachineDiagnostics / buildDownstreamProcessPlan" });
  const [recentProcessOperationId, setRecentProcessOperationId] = useState("");
  const queueListRef = useRef<HTMLDivElement | null>(null);
  const queueRowPositionsRef = useRef<Map<string, number>>(new Map());
  const pendingMovedBatchRef = useRef<string | null>(null);
  const queueGestureRef = useRef<{ batchId: string; sourceIndex: number; startY: number; active: boolean } | null>(null);
  const queueDragRef = useRef<{ batchId: string; position: number; targetRowIndex: number; edge: "before" | "after" } | null>(null);
  const processQueueGestureRef = useRef<{ operationId: string; sourceIndex: number; startY: number; active: boolean } | null>(null);
  const processQueueDragRef = useRef<{ operationId: string; position: number; targetRowIndex: number; edge: "before" | "after" } | null>(null);
  const queueOrderKey = schedule.map((batch) => `${batch.id}:${batch.planColumn}`).join("|");
  const selectedShiftEvents = (seed.calendarEvents ?? []).filter((event) => event.machineId === selected.id && event.kind === "shift");
  const selectedOvertimeEntries = useMemo(() => {
    if (!selectedShiftEvents.length) return [];
    const start = Math.min(...selectedShiftEvents.map((event) => event.start));
    const end = Math.max(...selectedShiftEvents.map((event) => event.end));
    return buildOvertimeEntries(seed, start, end, selected.id);
  }, [seed, selected.id, selectedShiftEvents.map((event) => `${event.id}:${event.start}:${event.end}:${event.shiftCount}`).join("|")]);
  const selectedProcessCalendarEvents = (seed.calendarEvents ?? []).filter((event) => event.machineId === activeResourceId);
  const processManualCandidates = selectedDownstreamResource ? downstreamOperations.filter((operation) => {
    if (operation.current) return false;
    const product = seed.processMasterData?.products.find((item) => item.product === operation.product);
    const parameter = product?.processes.find((item) => item.process === operation.process);
    return Boolean(parameter?.resourcePriority.includes(selectedDownstreamResource.id) && (parameter.unitsPerShift[selectedDownstreamResource.id] ?? 0) > 0);
  }) : [];
  const processReplacementCandidates = processManualCandidates.filter((operation) => operation.source === "wip" && operation.wipLotId && operation.readyAt <= inputDateToSerial(factoryDateInput()) + 1);
  const normalizedProcessQueueQuery = processQueueQuery.trim().toLocaleUpperCase("tr-TR");
  const visibleProcessSchedule = selectedProcessSchedule.filter((operation) => !normalizedProcessQueueQuery || `${operation.workOrder} ${operation.product} ${operation.batchId}`.toLocaleUpperCase("tr-TR").includes(normalizedProcessQueueQuery));
  const downstreamMachineAdapter: Machine | undefined = selectedDownstreamResource ? (() => {
    const firstStart = selectedDownstreamResource.availableStart ?? selectedProcessCurrentJob?.start ?? selectedProcessSchedule[0]?.start ?? inputDateToSerial(factoryDateInput());
    const lastEnd = Math.max(firstStart, selectedProcessCurrentJob?.end ?? 0, ...selectedProcessSchedule.map((operation) => operation.end));
    return {
      id: selectedDownstreamResource.id,
      name: selectedDownstreamResource.name,
      active: selectedDownstreamResource.active,
      availableStart: firstStart,
      operationalAvailableStart: firstStart,
      planEnd: selectedDownstreamResource.planEnd ?? lastEnd,
      note: processLabel(activeProcess),
      shiftFactor: selectedDownstreamResource.defaultShifts,
      capacityFactor: 1,
      finishOffset: 0,
      rates: {},
      currentJob: {
        workOrder: selectedProcessCurrentJob?.workOrder ?? "",
        product: selectedProcessCurrentJob?.product ?? "",
        quantity: selectedProcessCurrentJob?.remainingQuantity ?? 0,
        originalQuantity: selectedProcessCurrentJob?.originalQuantity ?? 0,
        remainingQuantity: selectedProcessCurrentJob?.remainingQuantity ?? 0,
        start: selectedProcessCurrentJob?.start ?? firstStart,
        end: selectedProcessCurrentJob?.end ?? firstStart,
        dailyRate: (selectedProcessCurrentJob?.unitsPerShift ?? 0) * selectedDownstreamResource.defaultShifts,
        diameter: selectedProcessCurrentJob?.setupKey ?? "",
      },
    };
  })() : undefined;

  useLayoutEffect(() => {
    const rows = queueListRef.current?.querySelectorAll<HTMLElement>(".machine-queue-row[data-batch-id]");
    if (!rows) return;
    const nextPositions = new Map<string, number>();
    rows.forEach((row) => {
      const batchId = row.dataset.batchId;
      if (batchId) nextPositions.set(batchId, row.getBoundingClientRect().top);
    });
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!reduceMotion && queueRowPositionsRef.current.size) {
      rows.forEach((row) => {
        const batchId = row.dataset.batchId;
        if (!batchId) return;
        const previousTop = queueRowPositionsRef.current.get(batchId);
        const nextTop = nextPositions.get(batchId);
        const delta = previousTop == null || nextTop == null ? 0 : previousTop - nextTop;
        if (Math.abs(delta) > 1) {
          row.animate([{ transform: `translateY(${delta}px)` }, { transform: "translateY(0)" }], { duration: batchId === pendingMovedBatchRef.current ? 480 : 360, easing: "cubic-bezier(.2,.8,.2,1)" });
        }
        if (batchId === pendingMovedBatchRef.current) {
          row.animate([{ backgroundColor: "#dff3ec", boxShadow: "inset 3px 0 0 #087a78" }, { backgroundColor: "#eef8f4", boxShadow: "inset 3px 0 0 #087a78", offset: .55 }, { backgroundColor: "transparent", boxShadow: "inset 0 0 0 rgba(8,122,120,0)" }], { duration: 820, easing: "ease-out" });
        }
      });
    }
    queueRowPositionsRef.current = nextPositions;
    pendingMovedBatchRef.current = null;
  }, [queueOrderKey, selected.id]);

  function moveQueueBatch(batchId: string, machineId: string, position: number) {
    pendingMovedBatchRef.current = batchId;
    onMoveBatch(batchId, machineId, position);
    window.setTimeout(() => {
      if (pendingMovedBatchRef.current === batchId) pendingMovedBatchRef.current = null;
    }, 1000);
  }

  useEffect(() => {
    setManualDialogOpen(false);
    setJobEditorOpen(false);
    setCompletionOpen(false);
    setMaintenanceDialogOpen(false);
    setShiftDialogOpen(false);
    setEditingQuantityBatch(null);
    setQueueDrag(null);
    queueGestureRef.current = null;
    queueDragRef.current = null;
    queueRowPositionsRef.current = new Map();
    pendingMovedBatchRef.current = null;
  }, [selected.id]);

  useEffect(() => {
    setProcessQueueDrag(null);
    if (appliedQueueDestinationRef.current !== activeResourceId) {
      setProcessQueueFeedback(null);
      setRecentProcessOperationId("");
    }
    appliedQueueDestinationRef.current = null;
    setPendingQueueMove(null);
    setProcessJobEditorOpen(false);
    setProcessCompletionOpen(false);
    setQueuedProcessCompletion(null);
    setProcessManualDialogOpen(false);
    setProcessMaintenanceDialogOpen(false);
    setProcessShiftDialogOpen(false);
    setProcessCatalogOpen(false);
    processQueueGestureRef.current = null;
    processQueueDragRef.current = null;
  }, [activeProcess, activeResourceId]);

  function beginQueueDrag(event: React.PointerEvent<HTMLButtonElement>, batch: PlannedBatch, index: number) {
    if (event.button !== 0 || batch.locked) return;
    queueGestureRef.current = { batchId: batch.id, sourceIndex: index, startY: event.clientY, active: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continueQueueDrag(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = queueGestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.abs(event.clientY - gesture.startY) < 5) return;
    gesture.active = true;
    const targetRow = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>(".machine-queue-row[data-queue-index]");
    if (!targetRow) { processQueueDragRef.current = null; setProcessQueueDrag(null); return; }
    const targetRowIndex = Number(targetRow.dataset.queueIndex);
    if (!Number.isInteger(targetRowIndex)) { processQueueDragRef.current = null; setProcessQueueDrag(null); return; }
    const rect = targetRow.getBoundingClientRect();
    const edge = event.clientY < rect.top + rect.height / 2 ? "before" : "after";
    const rawInsertion = targetRowIndex + (edge === "after" ? 1 : 0);
    const position = Math.max(0, Math.min(schedule.length - 1, rawInsertion > gesture.sourceIndex ? rawInsertion - 1 : rawInsertion));
    const nextDrag = { batchId: gesture.batchId, position, targetRowIndex, edge } as const;
    queueDragRef.current = nextDrag;
    setQueueDrag(nextDrag);
  }

  function endQueueDrag(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = queueGestureRef.current;
    if (!gesture) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    const drop = queueDragRef.current;
    if (gesture.active && drop && drop.position !== gesture.sourceIndex) moveQueueBatch(gesture.batchId, selected.id, drop.position);
    queueGestureRef.current = null;
    queueDragRef.current = null;
    setQueueDrag(null);
  }

  const pendingQueuePreview = useMemo<PlacementPreview | null>(() => {
    if (!pendingQueueMove) return null;
    try { return { valid: true, preview: previewProcessQueuePlacement(seed, result, pendingQueueMove) }; }
    catch (error) { return { valid: false, reason: error instanceof Error ? error.message : "Kuyruk yerleşimi uygulanamaz." }; }
  }, [pendingQueueMove, seed, result]);
  const queueDragPreview = useMemo<PlacementPreview | null>(() => {
    if (!processQueueDrag || !selectedDownstreamResource) return null;
    try { return { valid: true, preview: previewProcessQueuePlacement(seed, result, { operationId: processQueueDrag.operationId, resourceId: selectedDownstreamResource.id, position: processQueueDrag.position }) }; }
    catch (error) { return { valid: false, reason: error instanceof Error ? error.message : "Bu sıra uygulanamaz." }; }
  }, [processQueueDrag, selectedDownstreamResource, seed, result]);
  useRaviScreenContext("machine-queue-placement", { pendingQueueMove, pendingQueuePreview: pendingQueuePreview?.valid ? {
    operation: pendingQueuePreview.preview.operation, requestedStart: pendingQueuePreview.preview.requestedStart,
    insertionIndex: pendingQueuePreview.preview.insertionIndex, adjustments: pendingQueuePreview.preview.adjustments,
    affectedOperations: pendingQueuePreview.preview.affectedOperations,
  } : pendingQueuePreview, processQueueDrag, queueDragReason: queueDragPreview?.valid ? queueDragPreview.preview.adjustments : queueDragPreview?.reason,
    processQueueFeedback, queueReviewError, dirty, processManualDialogOpen });
  useEffect(() => {
    if (!lastAppliedQueueMove) return;
    const operation = downstreamPlan.operations.find((item) => item.id === lastAppliedQueueMove.id);
    if (!operation || operation.start !== lastAppliedQueueMove.start || operation.end !== lastAppliedQueueMove.end || operation.resourceId !== lastAppliedQueueMove.resourceId) {
      setProcessQueueFeedback(null); setLastAppliedQueueMove(null); setRecentProcessOperationId("");
    }
  }, [downstreamPlan, lastAppliedQueueMove]);
  useEffect(() => {
    if (!recentProcessOperationId) return;
    const frame = requestAnimationFrame(() => processQueueListRef.current?.querySelector<HTMLElement>(".just-moved")?.scrollIntoView({ block: "center", behavior: "instant" }));
    const timer = window.setTimeout(() => setRecentProcessOperationId(""), 4500);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timer); };
  }, [recentProcessOperationId, lastAppliedQueueMove]);
  useEffect(() => {
    const cancel = (event: KeyboardEvent) => { if (event.key === "Escape") cancelProcessQueueDrag(); };
    window.addEventListener("keydown", cancel);
    return () => window.removeEventListener("keydown", cancel);
  }, []);

  function requestProcessQueueChange(request: ProcessQueuePlacementRequest) {
    try {
      const preview = previewProcessQueuePlacement(seed, result, request);
      if (preview.seed === seed) {
        setProcessQueueFeedback({ tone: "success", message: "İş zaten seçilen kuyruk sırasında; plan değişmedi." });
        setProcessManualDialogOpen(false);
        return;
      }
      setPendingQueueMove(request);
      setQueueReviewError("");
      setProcessQueueFeedback(null);
      setProcessManualDialogOpen(false);
    } catch (error) {
      const message = error instanceof Error ? error.message : "Kuyruk değişikliği uygulanamadı.";
      setProcessQueueFeedback({ tone: "error", message });
      // Keep the manual placement dialog open with an inline error.
      if (processManualDialogOpen) throw new Error(message);
    }
  }

  function applyReviewedQueueMove() {
    if (!pendingQueueMove || !pendingQueuePreview?.valid) return;
    try {
      const operation = onPlaceProcessQueue(pendingQueueMove, processPlacementSignature(pendingQueuePreview.preview));
      if (operation.resourceId !== activeResourceId) appliedQueueDestinationRef.current = operation.resourceId;
      setSelectedProcessResources((current) => ({ ...current, [operation.process]: operation.resourceId }));
      setProcessQueueQuery("");
      setRecentProcessOperationId(operation.id);
      setLastAppliedQueueMove(operation);
      setPendingQueueMove(null);
      setProcessQueueFeedback({ tone: "success", message: `${operation.workOrder || operation.product} · ${processLabel(operation.process)} · ${operation.resourceId} · ${pendingQueuePreview.preview.insertionIndex + 1}. sıra · ${placementDate(operation.start)} – ${placementDate(operation.end)}. Geri al ile geri alınabilir.` });
    } catch (error) { setQueueReviewError(error instanceof Error ? error.message : "Yerleşim uygulanamadı."); }
  }

  function moveProcessQueueOperation(operation: ProcessOperation, position: number) {
    requestProcessQueueChange({ operationId: operation.id, resourceId: operation.resourceId, position });
  }

  function transferProcessQueueOperation(operation: ProcessOperation, resourceId: string) {
    requestProcessQueueChange({ operationId: operation.id, resourceId, position: "end" });
  }

  function placeProcessOperationManually(operationId: string, position: number) {
    if (!selectedDownstreamResource) return;
    requestProcessQueueChange({ operationId, resourceId: selectedDownstreamResource.id, position });
  }

  function startSelectedProcessJob() {
    if (!processStartCandidate) {
      setProcessQueueFeedback({ tone: "error", message: startAvailability.reason });
      return;
    }
    try {
      onStartProcessCurrentJob(processStartCandidate.id);
      setProcessQueueFeedback({ tone: "success", message: `${processStartCandidate.product}, ${processStartCandidate.resourceId} üzerinde mevcut üretime alındı.` });
    } catch (error) {
      setProcessQueueFeedback({ tone: "error", message: error instanceof Error ? error.message : "İş mevcut üretime alınamadı." });
    }
  }

  function replaceSelectedProcessJob(operation: ProcessOperation) {
    if (!selectedDownstreamResource || !selectedProcessCurrentJob) return;
    try {
      onReplaceProcessCurrentJob(selectedDownstreamResource.id, operation.id);
      setProcessJobSwitcherOpen(false);
      setProcessQueueFeedback({ tone: "success", message: `${operation.workOrder || operation.product} mevcut üretime alındı; önceki iş kuyruğun ilk sırasına taşındı.` });
    } catch (error) {
      setProcessQueueFeedback({ tone: "error", message: error instanceof Error ? error.message : "Mevcut iş değiştirilemedi." });
      throw error;
    }
  }

  function resetSelectedProcessQueue() {
    if (activeProcess !== "turning" && onReplanProcess(activeProcess)) setProcessQueueFeedback({ tone: "success", message: `${processLabel(activeProcess)} otomatik planlandı; Torna ve çalışan işler korundu.` });
  }

  function beginProcessQueueDrag(event: React.PointerEvent<HTMLButtonElement>, operation: ProcessOperation, index: number) {
    if (event.button !== 0 || operation.actual || operation.current) return;
    processQueueDragRef.current = null;
    setProcessQueueDrag(null);
    processQueueGestureRef.current = { operationId: operation.id, sourceIndex: index, startY: event.clientY, active: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continueProcessQueueDrag(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = processQueueGestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.abs(event.clientY - gesture.startY) < 5) return;
    gesture.active = true;
    const targetRow = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>(".process-machine-queue-row[data-process-queue-index]");
    if (!targetRow) { processQueueDragRef.current = null; setProcessQueueDrag(null); return; }
    const targetRowIndex = Number(targetRow.dataset.processQueueIndex);
    if (!Number.isInteger(targetRowIndex)) { processQueueDragRef.current = null; setProcessQueueDrag(null); return; }
    const rect = targetRow.getBoundingClientRect();
    const edge = event.clientY < rect.top + rect.height / 2 ? "before" : "after";
    const rawInsertion = targetRowIndex + (edge === "after" ? 1 : 0);
    const position = Math.max(0, Math.min(selectedProcessSchedule.length - 1, rawInsertion > gesture.sourceIndex ? rawInsertion - 1 : rawInsertion));
    const nextDrag = { operationId: gesture.operationId, position, targetRowIndex, edge } as const;
    if (processQueueDragRef.current?.targetRowIndex === targetRowIndex && processQueueDragRef.current.edge === edge) return;
    processQueueDragRef.current = nextDrag;
    setProcessQueueDrag(nextDrag);
  }

  function cancelProcessQueueDrag() {
    processQueueGestureRef.current = null;
    processQueueDragRef.current = null;
    setProcessQueueDrag(null);
  }

  function endProcessQueueDrag(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = processQueueGestureRef.current;
    if (!gesture) return;
    if (gesture.active) {
      continueProcessQueueDrag(event);
      const drop = processQueueDragRef.current;
      const operation = selectedProcessSchedule.find((item) => item.id === gesture.operationId);
      if (!drop) setProcessQueueFeedback({ tone: "error", message: "Geçerli bir kuyruk satırına bırakın. Taşıma uygulanmadı." });
      else if (operation && drop.position !== gesture.sourceIndex) moveProcessQueueOperation(operation, drop.position);
    }
    cancelProcessQueueDrag();
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
  }

  return (
    <>
    {pendingQueueMove && <ProcessPlacementReview request={pendingQueueMove} preview={pendingQueuePreview} process={activeProcess} dirty={dirty} error={queueReviewError} onClose={() => setPendingQueueMove(null)} onApply={applyReviewedQueueMove} />}
    {processQueueDrag && <div role="status" className={`gantt-drag-preview process-move-notice ${queueDragPreview?.valid ? "valid" : "invalid"}`}><ProcessIcon process={activeProcess} /><div><strong>{queueDragPreview?.valid ? `${processQueueDrag.position + 1}. sıra · Bırakınca yerleşimi inceleyin` : "Bu sıraya taşınamaz"}</strong><span>{queueDragPreview?.valid ? `İstenen: ${placementDate(queueDragPreview.preview.requestedStart)} · Hesaplanan: ${placementDate(queueDragPreview.preview.operation.start)} – ${placementDate(queueDragPreview.preview.operation.end)} · ${queueDragPreview.preview.affectedOperations.length} diğer adım etkilenir. ${queueDragPreview.preview.adjustments.join(" ")}` : queueDragPreview?.reason}</span></div></div>}
