    </section>
    {activeProcess === "turning" ? <section className="split-surface">
      <div className="machine-list">{machines.map((machine) => <button key={machine.id} className={machine.id === selected.id ? "selected" : ""} onClick={() => setSelectedMachineId(machine.id)}><span className={`status ${machine.active ? "on" : "off"}`} /><span><strong>{machine.id}</strong><small>{machine.name}</small></span><em>{batches.filter((batch) => batch.status === "planned" && batch.machineId === machine.id).length}</em></button>)}</div>
      <div className="machine-detail">
        <div className="detail-heading"><div><span>{selected.name}</span><h2>{selected.id}</h2></div><div className="machine-heading-actions"><button className="secondary" onClick={() => setCatalogOpen(true)}><PencilSimple size={13} /> Tezgahları yönet</button><label className="switch-label"><input type="checkbox" checked={selected.active} onChange={(event) => updateSeed((draft) => { const machine = draft.machines.find((item) => item.id === selected.id); if (machine) machine.active = event.target.checked; })} /><span className="switch" /> Planlamada aktif</label></div></div>
        <div className="form-grid">
          <Field label="Müsait başlangıç"><input type="date" value={serialToInputDate(selected.operationalAvailableStart ?? selected.availableStart)} onChange={(event) => updateSeed((draft) => { const machine = draft.machines.find((item) => item.id === selected.id); if (machine) { const start = inputDateToSerial(event.target.value); machine.operationalAvailableStart = start; machine.availableStart = start; } })} /></Field>
          <Field label="Plan bitişi"><input type="date" value={serialToInputDate(selected.planEnd)} onChange={(event) => updateSeed((draft) => { const machine = draft.machines.find((item) => item.id === selected.id); if (machine) machine.planEnd = inputDateToSerial(event.target.value); })} /></Field>
          <Field label="Vardiya sayısı"><select value={selected.shiftFactor} onChange={(event) => updateSeed((draft) => { const machine = draft.machines.find((item) => item.id === selected.id); if (machine) machine.shiftFactor = Number(event.target.value); })}>{[0, 1, 2, 3].map((value) => <option key={value} value={value}>{value}</option>)}</select></Field>
        </div>
        <div className="machine-current-block"><div className="current-job"><div><span>MEVCUT ÜRETİM</span><strong>{selected.currentJob.product || "Mevcut ürün yok"}<small>{selected.currentJob.workOrder || "İş emri yok"}</small></strong></div><div><span>Orijinal</span><strong>{formatNumber(selected.currentJob.originalQuantity ?? selected.currentJob.quantity)}</strong></div><div><span>Kalan</span><strong>{formatNumber(selected.currentJob.remainingQuantity ?? selected.currentJob.quantity)}</strong></div><div><span>Bitiş</span><strong>{formatExcelDate(selected.currentJob.end)}</strong></div><div><span>Çap</span><strong>{selected.currentJob.diameter || "—"}</strong></div></div><div className="machine-current-actions"><button className="secondary" onClick={() => setJobEditorOpen(true)}><PencilSimple size={14} /> Mevcut işi düzenle</button><button className="secondary complete" disabled={!selected.currentJob.product} onClick={() => setCompletionOpen(true)}><ProcessIcon process={activeProcess} size={14} /> {processLabel(activeProcess)} prosesini bitir</button></div></div>
        <div className="machine-operation-bar"><div><span>TEZGAH İŞLEMLERİ</span><strong>Kuyruğu ve günlük kapasiteyi düzenleyin</strong></div><button className="primary" title={!availableProducts.length ? "Bu tezgahta üretilebilen aktif sipariş yok" : undefined} disabled={!selected.active || !availableProducts.length} onClick={() => setManualDialogOpen(true)}><Plus size={15} /> Manuel şarj</button><button className="secondary" onClick={() => setShiftDialogOpen(true)}><Clock size={15} /> Günlük vardiya</button><button className="secondary" onClick={() => setMaintenanceDialogOpen(true)}><Wrench size={15} /> Planlı bakım</button><small>{(seed.calendarEvents ?? []).filter((event) => event.machineId === selected.id).length} takvim kaydı</small></div>
        {selectedOvertimeEntries.length > 0 && <div className="machine-overtime-panel"><Clock size={17} weight="fill" /><div><strong>{selected.id} için {selectedOvertimeEntries.length} mesai günü</strong><span>{selectedOvertimeEntries.slice(0, 3).map((entry) => `${formatExcelDate(entry.serial, { day: "2-digit", month: "short" })} +${entry.extraShiftCount} vardiya`).join(" · ")}{selectedOvertimeEntries.length > 3 ? ` · +${selectedOvertimeEntries.length - 3} kayıt` : ""}</span></div><em>{formatNumber(selectedOvertimeEntries.reduce((sum, entry) => sum + entry.overtimeHours, 0))} ek saat</em></div>}
        {compatibleWithoutOrderCount > 0 && <div className="manual-order-note"><Warning size={14} /><span><strong>{compatibleWithoutOrderCount} uygun tip manuel listede gizli.</strong> Aktif siparişleri olmadığı için şarja eklenemezler; önce Siparişler sayfasında adet girin.</span></div>}
        {schedule.length === 0 && <div className={`machine-diagnostic-panel ${diagnostic.tone}`}><Warning size={17} weight={diagnostic.tone === "critical" ? "fill" : "regular"} /><div><strong>{diagnostic.title}</strong><span>{diagnostic.detail}</span></div></div>}
        <div className="queue-heading"><h3>Planlanan tezgah kuyruğu</h3><span><DotsSixVertical size={13} /> Sıra kolunu tutup işi yukarı veya aşağı sürükleyin</span></div>
        <div ref={queueListRef} className="queue-list">{schedule.length ? schedule.map((batch, index) => <MachineQueueRow key={batch.id} batch={batch} setupFamily={productSetupFamily(seed, batch.product)} index={index} count={schedule.length} eligibleMachines={machines.filter((machine) => machine.active && (machine.rates[batch.product.toUpperCase()] ?? 0) > 0 && isMachineEligibleForProduct(seed, machine.id, batch.product)).map((machine) => machine.id)} dragging={queueDrag?.batchId === batch.id} dropEdge={queueDrag?.targetRowIndex === index ? queueDrag.edge : null} onDragStart={(event) => beginQueueDrag(event, batch, index)} onDragMove={continueQueueDrag} onDragEnd={endQueueDrag} onMove={(position) => moveQueueBatch(batch.id, selected.id, position)} onTransfer={(machineId) => moveQueueBatch(batch.id, machineId, 99)} onEditQuantity={() => setEditingQuantityBatch(batch)} onRemove={() => onRemoveBatch(batch.id)} onLock={() => onLockThrough(batch)} onUnlock={() => onUnlockQueue(selected.id)} onSaveWorkOrder={(workOrder) => onSaveWorkOrder(batch, workOrder)} />) : <p className="empty-copy">Bu senaryoda tezgaha yerleşen yeni şarj yok.</p>}</div>
        <details className="machine-history"><summary>Üretim geçmişi ve planlama işlemleri</summary><div>{(seed.productionHistory ?? []).filter((entry) => entry.machineId === selected.id && entry.inventoryStatus !== "voided").slice(0, 5).map((entry) => <article key={entry.id}><Archive size={14} /><span><strong>{entry.product} · {productionProcessLabel(entry.process)}</strong><small><b className="tracking-number">{entry.workOrder || "İş emri yok"}</b> · {formatExcelDate(entry.completedAt)} · {formatNumber(entry.completedQuantity)} adet · {entry.inventoryStatus === "delivered" ? "teslim edildi" : entry.inventoryStatus === "scrapped" ? "ıskarta" : "yarı mamul"}</small></span></article>)}{(seed.planningEvents ?? []).filter((event) => event.machineId === selected.id).slice(0, 8).map((event) => <article key={event.id}><CheckCircle size={14} /><span><strong>{event.message}</strong><small>{new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short" }).format(new Date(event.createdAt))}</small></span></article>)}{!(seed.productionHistory ?? []).some((entry) => entry.machineId === selected.id && entry.inventoryStatus !== "voided") && !(seed.planningEvents ?? []).some((event) => event.machineId === selected.id) && <p className="empty-copy">Bu tezgah için henüz işlem kaydı yok.</p>}</div></details>
      </div>
      {jobEditorOpen && <CurrentJobEditor seed={seed} result={result} machine={selected} onClose={() => setJobEditorOpen(false)} onSave={(input, remainingAsOf) => { onSaveCurrentJob(selected.id, input, remainingAsOf); setJobEditorOpen(false); }} />}
      {completionOpen && <CompleteJobDialog machine={selected} nextBatch={schedule[0]} onClose={() => setCompletionOpen(false)} onConfirm={(completedAt, completedQuantity) => { onCompleteCurrentJob(selected.id, completedAt, completedQuantity); setCompletionOpen(false); }} />}
      {manualDialogOpen && <ManualBatchDialog machine={selected} products={availableProducts} orders={activeOrdersByProduct} calculatedOrders={calculatedOrdersByProduct} queueLength={schedule.length} onClose={() => setManualDialogOpen(false)} onSave={(product, quantity, position) => { onAddBatch(product, selected.id, quantity, position); setManualDialogOpen(false); }} />}
      {shiftDialogOpen && <MachineShiftDialog machine={selected} events={(seed.calendarEvents ?? []).filter((event) => event.machineId === selected.id && event.kind === "shift")} onClose={() => setShiftDialogOpen(false)} onSave={(name, start, end, shifts, editingId) => { updateCalendar((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); } replaceMachineShiftOverrides(draft, [selected.id], start, end, shifts, name); }); setShiftDialogOpen(false); }} onDelete={(eventId) => updateCalendar((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === eventId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); })} />}
      {maintenanceDialogOpen && <MachineMaintenanceDialog machine={selected} events={(seed.calendarEvents ?? []).filter((event) => event.machineId === selected.id && event.kind === "maintenance")} onClose={() => setMaintenanceDialogOpen(false)} onSave={(name, start, end, editingId) => { updateCalendar((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) Object.assign(existing, { name, start, end, shiftCount: 0 }); } else draft.calendarEvents = [...(draft.calendarEvents ?? []), { id: `bakim-${Date.now()}`, machineId: selected.id, kind: "maintenance", name, start, end, shiftCount: 0 }]; }); setMaintenanceDialogOpen(false); }} onDelete={(eventId) => updateCalendar((draft) => { draft.calendarEvents = (draft.calendarEvents ?? []).filter((event) => event.id !== eventId); })} />}
      {catalogOpen && <MachineCatalogDialog seed={seed} result={result} onClose={() => setCatalogOpen(false)} onRename={(machineId, name) => updateSeed((draft) => { const machine = draft.machines.find((item) => item.id === machineId); if (machine) machine.name = name; })} onAdd={(machine) => { updateSeed((draft) => { draft.machines.push(machine); }); setSelectedMachineId(machine.id); }} onDelete={(machineId, replacementId) => { updateSeed((draft) => { deleteMachineDefinition(draft, result, machineId, replacementId); }); setSelectedMachineId(replacementId || machines.find((machine) => machine.id !== machineId)?.id || ""); }} />}
      {editingQuantityBatch && <BatchQuantityDialog batch={editingQuantityBatch} setupFamily={productSetupFamily(seed, editingQuantityBatch.product)} onClose={() => setEditingQuantityBatch(null)} onSave={(quantity) => { onUpdateBatchQuantity(editingQuantityBatch, quantity); setEditingQuantityBatch(null); }} />}
    </section> : <section className="split-surface">
      <div className="machine-list">{downstreamResources.map((resource) => <button key={resource.id} className={resource.id === activeResourceId ? "selected" : ""} onClick={() => setSelectedProcessResources((current) => ({ ...current, [activeProcess]: resource.id }))}><span className={`status ${resource.active && resource.defaultShifts > 0 ? "on" : "off"}`} /><span><strong>{resource.id}</strong><small>{resource.name}</small></span><em>{downstreamOperations.filter((operation) => !operation.current && operation.resourceId === resource.id).length}</em></button>)}</div>
      <div className="machine-detail downstream-machine-detail">
        {selectedDownstreamResource ? <>
          <div className="detail-heading"><div><span>{selectedDownstreamResource.name}</span><h2>{selectedDownstreamResource.id}</h2></div><div className="machine-heading-actions"><button className="secondary" onClick={() => setProcessCatalogOpen(true)}><PencilSimple size={13} /> Tezgahları yönet</button><label className="switch-label"><input type="checkbox" checked={selectedDownstreamResource.active} onChange={(event) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === selectedDownstreamResource.id); if (resource) resource.active = event.target.checked; })} /><span className="switch" /> Planlamada aktif</label></div></div>
          <div className="form-grid downstream-resource-settings"><Field label="Müsait başlangıç"><input type="date" value={serialToInputDate(selectedDownstreamResource.availableStart ?? downstreamMachineAdapter!.availableStart)} onChange={(event) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === selectedDownstreamResource.id); if (resource) { const start = inputDateToSerial(event.target.value); resource.availableStart = start; if (!resource.planEnd || resource.planEnd < start) resource.planEnd = start; } })} /></Field><Field label="Plan bitişi"><input type="date" min={serialToInputDate(selectedDownstreamResource.availableStart ?? downstreamMachineAdapter!.availableStart)} value={serialToInputDate(selectedDownstreamResource.planEnd ?? downstreamMachineAdapter!.planEnd)} onChange={(event) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === selectedDownstreamResource.id); if (resource) resource.planEnd = Math.max(resource.availableStart ?? 0, inputDateToSerial(event.target.value)); })} /></Field><Field label="Vardiya sayısı"><select value={selectedDownstreamResource.defaultShifts} onChange={(event) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === selectedDownstreamResource.id); if (resource) resource.defaultShifts = clampShiftCount(Number(event.target.value)); })}>{[0, 1, 2, 3].map((value) => <option key={value} value={value}>{value}</option>)}</select></Field></div>
          <div className="machine-current-block downstream-current-block"><div className="current-job"><div><span>MEVCUT ÜRETİM</span><strong>{selectedProcessCurrentJob?.product || "Mevcut ürün yok"}<small>{selectedProcessCurrentJob?.workOrder || "İş emri yok"}</small></strong></div><div><span>Orijinal</span><strong>{formatNumber(selectedProcessCurrentJob?.originalQuantity ?? 0)}</strong></div><div><span>Kalan</span><strong>{formatNumber(selectedProcessCurrentJob?.remainingQuantity ?? 0)}</strong></div><div><span>Bitiş</span><strong>{selectedProcessCurrentJob ? formatExcelDate(selectedProcessCurrentJob.end) : "—"}</strong></div><div><span>{activeProcess === "drilling" ? "Matkap" : "Setup"}</span><strong>{selectedProcessCurrentJob?.setupKey || "—"}</strong></div></div><div className="machine-current-actions"><button className="secondary" disabled={!selectedProcessCurrentJob && !processStartCandidate} title={!selectedProcessCurrentJob && !processStartCandidate ? startAvailability.reason : undefined} onClick={() => selectedProcessCurrentJob ? setProcessJobEditorOpen(true) : startSelectedProcessJob()}>{selectedProcessCurrentJob ? <PencilSimple size={14} /> : <Play size={14} weight="fill" />} {selectedProcessCurrentJob ? "Adedi düzenle" : "Sıradaki işi üretime al"}</button>{selectedProcessCurrentJob && <button className="secondary" disabled={!processReplacementCandidates.length} title={!processReplacementCandidates.length ? "Bu proseste üretime hazır başka şarj yok" : "Şarj numarasıyla mevcut işi değiştir"} onClick={() => setProcessJobSwitcherOpen(true)}><ArrowCounterClockwise size={14} /> Mevcut işi değiştir</button>}<button className="secondary complete" disabled={!selectedProcessCurrentJob} onClick={() => setProcessCompletionOpen(true)}><ProcessIcon process={activeProcess} size={14} /> {processLabel(activeProcess)} prosesini bitir</button></div></div>
          {!selectedProcessCurrentJob && <p className="process-start-help" role="status">{processStartCandidate ? `Sıradaki hazır iş: ${processStartCandidate.workOrder || processStartCandidate.product} · ${processStartCandidate.product}` : startAvailability.reason}</p>}
          <div className="downstream-queue-summary"><span><small>Planlı iş</small><strong>{selectedProcessSchedule.length}</strong></span><span><small>Toplam miktar</small><strong>{formatNumber(selectedProcessSchedule.reduce((sum, operation) => sum + operation.quantity, 0))}</strong></span><span><small>Son planlı bitiş</small><strong>{selectedProcessSchedule.length ? formatExcelDate(Math.max(...selectedProcessSchedule.map((operation) => operation.end))) : "—"}</strong></span><span><small>Manuel yerleşim</small><strong>{selectedProcessSchedule.filter((operation) => operation.manualOverride).length}</strong></span></div>
          {dirty && <div className="manual-order-note"><Warning size={14} /><span><strong>Torna planı değişti.</strong> Downstream kuyrukları son hesaplanan torna planını gösteriyor; plan yeniden çalıştırıldığında tarihler güncellenir.</span></div>}
          <div className="machine-operation-bar downstream-queue-actions"><div><span>TEZGAH İŞLEMLERİ</span><strong>Kuyruğu ve günlük kapasiteyi düzenleyin</strong></div><button className="primary" disabled={!selectedDownstreamResource.active || !processManualCandidates.length} title={!processManualCandidates.length ? "Bu tezgâha yerleştirilebilecek planlı proses işi yok" : undefined} onClick={() => setProcessManualDialogOpen(true)}><Plus size={15} /> Manuel şarj</button><button className="secondary" onClick={() => setProcessShiftDialogOpen(true)}><Clock size={15} /> Günlük vardiya</button><button className="secondary" onClick={() => setProcessMaintenanceDialogOpen(true)}><Wrench size={15} /> Planlı bakım</button><small>{selectedProcessCalendarEvents.length} takvim kaydı</small></div>
          <div className="process-automatic-reset"><span>Seçili proses otomatik planlanır; Torna ve çalışan işler korunur.</span><button className="secondary" onClick={resetSelectedProcessQueue}><ArrowCounterClockwise size={14} /> {processLabel(activeProcess)} otomatik plana dön</button></div>
          {processQueueFeedback && <div className={`process-queue-feedback ${processQueueFeedback.tone}`} role={processQueueFeedback.tone === "error" ? "alert" : "status"}>{processQueueFeedback.tone === "error" ? <Warning size={15} weight="fill" /> : <CheckCircle size={15} weight="fill" />}<span>{processQueueFeedback.message}</span><button onClick={() => setProcessQueueFeedback(null)} aria-label="Kuyruk bildirimini kapat"><X size={12} /></button></div>}
          <div className="queue-heading process-queue-heading"><h3>Planlanan tezgah kuyruğu</h3><label className="process-queue-search"><MagnifyingGlass size={14} /><input value={processQueueQuery} onChange={(event) => setProcessQueueQuery(event.target.value)} placeholder="Şarj no veya ürün ara" /></label><span><DotsSixVertical size={13} /> Sıra kolunu tutup işi yukarı veya aşağı sürükleyin</span></div>
          <div ref={processQueueListRef} className="queue-list process-queue-list">{visibleProcessSchedule.length ? visibleProcessSchedule.map((operation) => {
            const index = selectedProcessSchedule.findIndex((item) => item.id === operation.id);
            const masterProduct = seed.processMasterData?.products.find((product) => product.product === operation.product);
            const parameter = masterProduct?.processes.find((item) => item.process === operation.process);
            const eligibleResources = downstreamResources.filter((resource) => resource.active && resource.defaultShifts > 0 && parameter?.resourcePriority.includes(resource.id) && (parameter.unitsPerShift[resource.id] ?? 0) > 0);
            const wipLot = operation.wipLotId ? (seed.wipLots ?? []).find((lot) => lot.id === operation.wipLotId) : undefined;
            const canComplete = Boolean(wipLot && wipLot.nextProcess === operation.process && wipLot.availableQuantity > 0);
            return <ProcessMachineQueueRow key={operation.id} operation={operation} index={index} count={selectedProcessSchedule.length} resources={eligibleResources} canComplete={canComplete} dragging={processQueueDrag?.operationId === operation.id} dropEdge={processQueueDrag?.targetRowIndex === index ? processQueueDrag.edge : null} recent={recentProcessOperationId === operation.id} onDragStart={(event) => beginProcessQueueDrag(event, operation, index)} onDragMove={continueProcessQueueDrag} onDragEnd={endProcessQueueDrag} onDragCancel={cancelProcessQueueDrag} onMove={(position) => moveProcessQueueOperation(operation, position)} onTransfer={(resourceId) => transferProcessQueueOperation(operation, resourceId)} onComplete={() => setQueuedProcessCompletion(operation)} />;
          }) : <p className="empty-copy">{selectedProcessSchedule.length ? "Bu aramayla eşleşen şarj bulunamadı." : `Bu iş merkezine yerleşen planlı ${processLabel(activeProcess).toLocaleLowerCase("tr-TR")} işi yok.`}</p>}</div>
          <details className="machine-history"><summary>Üretim geçmişi ve planlama işlemleri</summary><div>{(seed.wipMovements ?? []).filter((movement) => movement.resourceId === selectedDownstreamResource.id).slice(-5).reverse().map((movement) => <article key={movement.id}><ProcessIcon process={movement.process ?? activeProcess} size={14} /><span><strong>{movement.process ? processLabel(movement.process) : processLabel(activeProcess)} · {formatNumber(movement.quantity)} adet</strong><small>{formatExcelDate(movement.occurredAt)} · {movement.kind === "process-completed" ? "operasyon tamamlandı" : "yarı mamül hareketi"}</small></span></article>)}{(seed.planningEvents ?? []).filter((event) => event.machineId === selectedDownstreamResource.id).slice(0, 8).map((event) => <article key={event.id}><CheckCircle size={14} /><span><strong>{event.message}</strong><small>{new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short" }).format(new Date(event.createdAt))}</small></span></article>)}{!(seed.wipMovements ?? []).some((movement) => movement.resourceId === selectedDownstreamResource.id) && !(seed.planningEvents ?? []).some((event) => event.machineId === selectedDownstreamResource.id) && <p className="empty-copy">Bu iş merkezi için henüz işlem kaydı yok.</p>}</div></details>
        </> : <p className="empty-copy">Bu proses için tanımlı tezgah yok.</p>}
      </div>
      {processJobEditorOpen && selectedProcessCurrentJob && <ProcessCurrentJobEditor job={selectedProcessCurrentJob} onClose={() => setProcessJobEditorOpen(false)} onSave={(input) => { onSaveProcessCurrentJob(selectedProcessCurrentJob.resourceId, input); setProcessJobEditorOpen(false); }} />}
      {processJobSwitcherOpen && selectedDownstreamResource && selectedProcessCurrentJob && <ProcessCurrentJobSwitcher resource={selectedDownstreamResource} currentJob={selectedProcessCurrentJob} operations={processReplacementCandidates} onClose={() => setProcessJobSwitcherOpen(false)} onSelect={replaceSelectedProcessJob} />}
      {processCompletionOpen && selectedProcessCurrentJob && (() => {
        const lot = (seed.wipLots ?? []).find((item) => item.id === selectedProcessCurrentJob.wipLotId);
        const resources = actualProcessResources(seed, selectedProcessCurrentJob.process, selectedProcessCurrentJob.product);
        return lot ? <CompleteProcessCurrentJobDialog job={selectedProcessCurrentJob} lot={lot} resources={resources} nextOperation={selectedProcessSchedule.find((operation) => operation.source === "wip")} onClose={() => setProcessCompletionOpen(false)} onConfirm={(completedAt, completedQuantity, actualResourceId) => { onCompleteProcessCurrentJob(selectedProcessCurrentJob.resourceId, completedAt, completedQuantity, actualResourceId); setProcessCompletionOpen(false); }} /> : null;
      })()}
      {queuedProcessCompletion && queuedProcessCompletion.wipLotId && (() => {
        const lot = (seed.wipLots ?? []).find((item) => item.id === queuedProcessCompletion.wipLotId);
        const resources = actualProcessResources(seed, queuedProcessCompletion.process as DownstreamProcess, queuedProcessCompletion.product);
        return lot ? <CompleteQueuedProcessOperationDialog operation={queuedProcessCompletion} lot={lot} resources={resources} onClose={() => setQueuedProcessCompletion(null)} onConfirm={(input) => { const completed = onCompleteWipOperation(input); if (completed) setQueuedProcessCompletion(null); return completed; }} /> : null;
      })()}
      {processManualDialogOpen && selectedDownstreamResource && <ProcessManualBatchDialog resource={selectedDownstreamResource} operations={processManualCandidates} queueLength={selectedProcessSchedule.length} onClose={() => setProcessManualDialogOpen(false)} onSave={placeProcessOperationManually} />}
      {processShiftDialogOpen && downstreamMachineAdapter && <MachineShiftDialog machine={downstreamMachineAdapter} events={selectedProcessCalendarEvents.filter((event) => event.kind === "shift")} onClose={() => setProcessShiftDialogOpen(false)} onSave={(name, start, end, shifts, editingId) => { updateCalendar((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); } replaceMachineShiftOverrides(draft, [selectedDownstreamResource!.id], start, end, shifts, name); }); setProcessShiftDialogOpen(false); }} onDelete={(eventId) => updateCalendar((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === eventId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); })} />}
      {processMaintenanceDialogOpen && downstreamMachineAdapter && <MachineMaintenanceDialog machine={downstreamMachineAdapter} events={selectedProcessCalendarEvents.filter((event) => event.kind === "maintenance")} onClose={() => setProcessMaintenanceDialogOpen(false)} onSave={(name, start, end, editingId) => { updateCalendar((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) Object.assign(existing, { name, start, end, shiftCount: 0 }); } else draft.calendarEvents = [...(draft.calendarEvents ?? []), { id: `bakim-${Date.now()}`, machineId: selectedDownstreamResource!.id, kind: "maintenance", name, start, end, shiftCount: 0 }]; }); setProcessMaintenanceDialogOpen(false); }} onDelete={(eventId) => updateCalendar((draft) => { draft.calendarEvents = (draft.calendarEvents ?? []).filter((event) => event.id !== eventId); })} />}
      {processCatalogOpen && <ProcessResourceCatalogDialog process={activeProcess as DownstreamProcess} resources={downstreamResources} onClose={() => setProcessCatalogOpen(false)} onSave={(resourceId, name, active, defaultShifts) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === resourceId); if (resource) Object.assign(resource, { name, active, defaultShifts }); })} />}
    </section>}
    </>
  );
}

function MachineCatalogDialog({ seed, result, onClose, onRename, onAdd, onDelete }: { seed: PlanningSeed; result: ScenarioResult; onClose: () => void; onRename: (machineId: string, name: string) => void; onAdd: (machine: Machine) => void; onDelete: (machineId: string, replacementId?: string) => void }) {
  const machines = seed.machines;
  const [names, setNames] = useState<Record<string, string>>(() => Object.fromEntries(machines.map((machine) => [machine.id, machine.name])));
  const nextNumber = Math.max(0, ...machines.map((machine) => Number(machine.id.match(/\d+/)?.[0] ?? 0))) + 1;
  const [newMachine, setNewMachine] = useState({ id: `C-${String(nextNumber).padStart(2, "0")}`, name: "" });
  const [error, setError] = useState("");
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [replacementId, setReplacementId] = useState("");
  const deletion = deletingId ? analyzeMachineDeletion(seed, result, deletingId) : null;

  function saveName(machine: Machine) {
    const name = names[machine.id]?.trim();
    if (!name) return setError(`${machine.id} için tezgah adı zorunludur.`);
    onRename(machine.id, name);
    setError("");
  }

  function addMachine() {
    const id = normalizeMachineId(newMachine.id);
    const name = newMachine.name.trim();
    if (!id) return setError("Tezgah kodunu C-18 biçiminde girin.");
    if (machines.some((machine) => machine.id === id)) return setError(`${id} zaten tanımlı.`);
    if (!name) return setError("Yeni tezgahın adını girin.");
    const start = inputDateToSerial(factoryDateInput());
    onAdd({ id, name, active: false, availableStart: start, planEnd: start + 30, note: "", shiftFactor: 0, capacityFactor: 1, finishOffset: 0, rates: {}, currentJob: { workOrder: "", product: "", quantity: 0, originalQuantity: 0, remainingQuantity: 0, start, end: 0, dailyRate: 0, diameter: "" } });
    setError("");
    onClose();
  }

  function requestDelete(machineId: string) {
    setDeletingId(machineId);
    setReplacementId("");
    setError("");
  }

  function confirmDelete() {
    if (!deletingId || !deletion || deletion.blocked || (deletion.requiresReplacement && !replacementId)) return;
    try {
      onDelete(deletingId, replacementId || undefined);
      setDeletingId(null);
      setReplacementId("");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Tezgah silinemedi.");
    }
  }

  return <div className="confirmation-backdrop" role="presentation"><section className="machine-catalog-dialog" role="dialog" aria-modal="true" aria-label="Tezgahları yönet"><div className="operational-dialog-head"><span className="dialog-icon shift"><ProcessIcon process="turning" size={19} /></span><div><span>TEZGAH ANA VERİSİ</span><h2>Tezgahları yönet</h2><p>Adları güncelleyin, yeni tezgah ekleyin veya bağımlılıkları güvenle aktararak silin.</p></div><button className="delete-button" onClick={onClose} aria-label="Tezgah yönetimini kapat"><X size={16} /></button></div><div className="machine-catalog-list">{machines.map((machine) => { const changed = (names[machine.id] ?? "").trim() !== machine.name; return <div key={machine.id}><strong>{machine.id}</strong><input value={names[machine.id] ?? ""} onChange={(event) => setNames((current) => ({ ...current, [machine.id]: event.target.value }))} aria-label={`${machine.id} tezgah adı`} /><button disabled={!changed || !(names[machine.id] ?? "").trim()} onClick={() => saveName(machine)}>Kaydet</button><button className="delete-button machine-catalog-delete" onClick={() => requestDelete(machine.id)} aria-label={`${machine.id} tezgahını sil`}><Trash size={14} /></button></div>; })}</div>{deletion && <section className={`machine-delete-panel ${deletion.blocked ? "blocked" : ""}`}><div><span>TEZGAH SİLME KONTROLÜ</span><h3>{deletion.machineId} silinsin mi?</h3></div>{deletion.blocked ? <div className="machine-delete-blocker"><Warning size={18} weight="fill" /><span><strong>Tezgah şu anda silinemez.</strong><small>{deletion.currentJobProduct ? `Mevcut üretim: ${deletion.currentJobProduct}. ` : ""}{deletion.plannedBatches.length ? `${deletion.plannedBatches.length} planlı şarj önce tamamlanmalı veya başka tezgaha taşınmalı.` : "Mevcut iş tamamlanmalı."}</small></span></div> : <><div className="machine-delete-impact"><span><b>{deletion.parameterProducts.length}</b><small>ürün parametresi</small></span><span><b>{deletion.savedBatchCount}</b><small>kayıtlı plan işi</small></span><span><b>{deletion.calendarEventCount}</b><small>takvim kaydı silinir</small></span></div>{deletion.requiresReplacement && <Field label="Parametreleri aktar"><select value={replacementId} onChange={(event) => setReplacementId(event.target.value)}><option value="">Alternatif tezgah seçin</option>{machines.filter((machine) => machine.id !== deletion.machineId).map((machine) => <option key={machine.id} value={machine.id}>{machine.id} · {machine.name}</option>)}</select></Field>}<p>{deletion.requiresReplacement ? "Ürün öncelikleri, uygunluk kayıtları ve eksik üretim hızları seçilen tezgaha aktarılır. Mevcut hedef hızlar ezilmez." : "Bu tezgaha bağlı aktif iş veya ürün parametresi bulunmuyor."}</p></>}<div className="drawer-actions"><button className="secondary" onClick={() => { setDeletingId(null); setReplacementId(""); }}>Vazgeç</button><button className="danger-outline" disabled={deletion.blocked || (deletion.requiresReplacement && !replacementId)} onClick={confirmDelete}><Trash size={14} /> Tezgahı sil</button></div></section>}<div className="machine-catalog-add"><div><span>YENİ TEZGAH</span><p>Yeni tezgah pasif ve 0 vardiya ile eklenir. Hız ve ürün öncelikleri daha sonra Tip_Parametreleri üzerinden tanımlanır.</p></div><Field label="Tezgah kodu"><input value={newMachine.id} onChange={(event) => setNewMachine({ ...newMachine, id: event.target.value })} /></Field><Field label="Tezgah adı"><input value={newMachine.name} onChange={(event) => setNewMachine({ ...newMachine, name: event.target.value })} placeholder="Makine / model" /></Field><button className="primary" onClick={addMachine}><Plus size={14} /> Tezgah ekle</button></div>{error && <p className="form-error catalog-error">{error}</p>}</section></div>;
}

function ManualBatchDialog({ machine, products, orders, calculatedOrders, queueLength, onClose, onSave }: { machine: Machine; products: Product[]; orders: Map<string, Order>; calculatedOrders: Map<string, ScenarioResult["orders"][number]>; queueLength: number; onClose: () => void; onSave: (product: string, quantity: number, position: number) => void }) {
  const first = products[0];
  const [product, setProduct] = useState(first?.product ?? "");
  const [quantity, setQuantity] = useState(first?.batchSize ?? 0);
  const [position, setPosition] = useState(queueLength);
  const selectedProduct = products.find((item) => item.product === product);
  const selectedOrder = orders.get(product.toUpperCase());
  const calculatedOrder = calculatedOrders.get(product.toUpperCase());
  const plannedQuantity = calculatedOrder?.planned ?? 0;
  const remainingQuantity = Math.max(0, (selectedOrder?.quantity ?? 0) - plannedQuantity);
  const batchSize = selectedProduct?.batchSize ?? 0;
  const chargeCount = batchSize > 0 ? quantity / batchSize : 0;
  const validQuantity = batchSize > 0 && quantity > 0 && Number.isInteger(chargeCount);
  const valid = Boolean(product && validQuantity);
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog" role="dialog" aria-modal="true" aria-label={`${machine.id} manuel şarj ekleme`}><div className="operational-dialog-head"><span className="dialog-icon manual"><Plus size={20} /></span><div><span>MANUEL PLANLAMA</span><h2>{machine.id} kuyruğuna şarj ekle</h2><p>Yalnızca aktif siparişi olan, bu tezgahta üretilebilen ve hızı tanımlı ürünler gösterilir.</p></div><button className="delete-button" onClick={onClose} aria-label="Manuel şarj penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Ürün"><select value={product} onChange={(event) => { const next = products.find((item) => item.product === event.target.value); setProduct(event.target.value); setQuantity(next?.batchSize ?? 0); }}>{products.map((item) => <option key={item.product} value={item.product}>{item.product} · {productSetupFamilyLabel(resolvedProductSetupFamily(item.product, item.setupFamily))} · {item.diameter}</option>)}</select></Field><Field label={`Miktar · ${formatNumber(batchSize)} katları`}><input type="number" min={batchSize || 1} step={batchSize || 1} value={quantity} onChange={(event) => setQuantity(Number(event.target.value))} /></Field><Field label="Kuyruk sırası"><select value={position} onChange={(event) => setPosition(Number(event.target.value))}>{Array.from({ length: queueLength + 1 }, (_, index) => <option key={index} value={index}>{index + 1}. sıra</option>)}</select></Field><div className="manual-batch-preview four"><span><small>Sipariş</small><strong>{formatNumber(selectedOrder?.quantity ?? 0)}</strong></span><span><small>Şimdi planlı</small><strong>{formatNumber(plannedQuantity)}</strong></span><span><small>Kalan ihtiyaç</small><strong>{formatNumber(remainingQuantity)}</strong></span><span><small>Standart şarj</small><strong>{formatNumber(batchSize)}</strong></span></div>{validQuantity && <div className="calendar-impact-note"><strong>{formatNumber(chargeCount)} tam şarj eklenecek</strong><span>{formatNumber(chargeCount)} × {formatNumber(batchSize)} = {formatNumber(quantity)} adet. Manuel miktar standart şarjın tam katı olarak korunur.</span></div>}{quantity > 0 && !validQuantity && <p className="form-error">Miktar {formatNumber(batchSize)} adetlik standart şarjın tam katı olmalıdır.</p>}{remainingQuantity === 0 && <div className="calendar-impact-note"><strong>Sipariş mevcut planda karşılanmış</strong><span>Yeni şarj eklerseniz siparişin üzerinde üretim oluşabilir.</span></div>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(product, quantity, position)}>Şarjı kuyruğa ekle</button></div></div></section></div>;
}

function ProcessManualBatchDialog({ resource, operations, queueLength, onClose, onSave }: { resource: ProcessResource; operations: ProcessOperation[]; queueLength: number; onClose: () => void; onSave: (operationId: string, position: number) => void }) {
  const first = [...operations].sort((left, right) => left.readyAt - right.readyAt || left.id.localeCompare(right.id))[0];
  const [operationId, setOperationId] = useState(first?.id ?? "");
  const selected = operations.find((operation) => operation.id === operationId) ?? first;
  const positionCount = Math.max(1, queueLength + (selected?.resourceId === resource.id ? 0 : 1));
  const [position, setPosition] = useState(positionCount - 1);
  const [error, setError] = useState("");
  useRaviScreenContext("machine-manual-queue-placement", { resourceId: resource.id, operationId: selected?.id, position: Math.min(position, positionCount - 1), positionBase: 0, readyAt: selected?.readyAt, error });
  function review() {
    if (!selected) return;
    try { setError(""); onSave(selected.id, Math.min(position, positionCount - 1)); }
    catch (caught) { setError(caught instanceof Error ? caught.message : "Yerleşim uygulanamaz."); }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog" role="dialog" aria-modal="true" aria-label={`${resource.id} manuel proses şarjı ekleme`}><div className="operational-dialog-head"><span className="dialog-icon manual"><Plus size={20} /></span><div><span>MANUEL PLANLAMA</span><h2>{resource.id} kuyruğuna şarj ekle</h2><p>İzlenebilirliği korumak için planlı bir proses işi seçilir; miktar çoğaltılmadan bu tezgâhın kuyruğuna yerleştirilir.</p></div><button className="delete-button" onClick={onClose} aria-label="Manuel şarj penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Planlı proses işi"><select aria-label="Planlı proses işi" value={selected?.id ?? ""} onChange={(event) => { const next = operations.find((operation) => operation.id === event.target.value); setError(""); setOperationId(event.target.value); setPosition(Math.max(0, queueLength + (next?.resourceId === resource.id ? 0 : 1) - 1)); }}>{[...operations].sort((left, right) => left.readyAt - right.readyAt || left.id.localeCompare(right.id)).map((operation) => <option key={operation.id} value={operation.id}>{operation.product} · {formatNumber(operation.quantity)} adet · {operation.resourceId} · {operation.workOrder || "iş emri yok"}</option>)}</select></Field><Field label="Kuyruk sırası"><select aria-label="Kuyruk sırası" value={Math.min(position, positionCount - 1)} onChange={(event) => { setError(""); setPosition(Number(event.target.value)); }}>{Array.from({ length: positionCount }, (_, index) => <option key={index} value={index}>{index + 1}. sıra</option>)}</select></Field>{selected && <div className="manual-batch-preview four"><span><small>Ürün</small><strong>{selected.product}</strong></span><span><small>Miktar</small><strong>{formatNumber(selected.quantity)}</strong></span><span><small>Mevcut tezgâh</small><strong>{selected.resourceId}</strong></span><span><small>Hazır olma</small><strong>{formatExcelDate(selected.readyAt)}</strong></span></div>}<div className="calendar-impact-note"><strong>{selected?.resourceId === resource.id ? "Kuyruk sırası değiştirilecek" : `${selected?.resourceId ?? "—"} → ${resource.id} transferi`}</strong><span>Ürünün proses rotası, miktarı ve önceki operasyon bağı korunur; yalnızca uygun tezgâh ve sıra tercihi kaydedilir.</span></div>{error && <p className="form-error" role="alert">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!selected} onClick={review}><Plus size={14} /> Yerleşimi incele</button></div></div></section></div>;
}

function ProcessResourceCatalogDialog({ process, resources, onClose, onSave }: { process: DownstreamProcess; resources: ProcessResource[]; onClose: () => void; onSave: (resourceId: string, name: string, active: boolean, defaultShifts: ShiftCount) => void }) {
  const [drafts, setDrafts] = useState<Record<string, { name: string; active: boolean; defaultShifts: ShiftCount }>>(() => Object.fromEntries(resources.map((resource) => [resource.id, { name: resource.name, active: resource.active, defaultShifts: resource.defaultShifts }])));
  const [savedId, setSavedId] = useState("");
  return <div className="confirmation-backdrop" role="presentation"><section className="machine-catalog-dialog process-resource-catalog-dialog" role="dialog" aria-modal="true" aria-label={`${processLabel(process)} tezgahlarını yönet`}><div className="operational-dialog-head"><span className="dialog-icon shift"><ProcessIcon process={process} size={19} /></span><div><span>TEZGAH ANA VERİSİ</span><h2>{processLabel(process)} tezgahlarını yönet</h2><p>Tezgâh adını, planlama durumunu ve normal vardiya kapasitesini tek yerden güncelleyin.</p></div><button className="delete-button" onClick={onClose} aria-label="Tezgah yönetimini kapat"><X size={16} /></button></div><div className="process-resource-catalog-list"><div className="process-resource-catalog-head"><span>Tezgah</span><span>Tam adı</span><span>Durum</span><span>Normal vardiya</span><span /></div>{resources.map((resource) => { const draft = drafts[resource.id]; const changed = Boolean(draft && (draft.name.trim() !== resource.name || draft.active !== resource.active || draft.defaultShifts !== resource.defaultShifts)); return <div key={resource.id}><strong>{resource.id}</strong><input value={draft?.name ?? ""} onChange={(event) => setDrafts((current) => ({ ...current, [resource.id]: { ...current[resource.id], name: event.target.value } }))} aria-label={`${resource.id} tezgah adı`} /><label className="switch-label compact"><input type="checkbox" checked={draft?.active ?? false} onChange={(event) => setDrafts((current) => ({ ...current, [resource.id]: { ...current[resource.id], active: event.target.checked } }))} /><span className="switch" /> {draft?.active ? "Aktif" : "Pasif"}</label><select value={draft?.defaultShifts ?? 0} onChange={(event) => setDrafts((current) => ({ ...current, [resource.id]: { ...current[resource.id], defaultShifts: clampShiftCount(Number(event.target.value)) } }))} aria-label={`${resource.id} normal vardiya`}><ShiftOptions /></select><button disabled={!changed || !draft?.name.trim()} onClick={() => { if (!draft) return; onSave(resource.id, draft.name.trim(), draft.active, draft.defaultShifts); setSavedId(resource.id); window.setTimeout(() => setSavedId((current) => current === resource.id ? "" : current), 1200); }}>{savedId === resource.id ? "Kaydedildi" : "Kaydet"}</button></div>; })}</div><div className="process-resource-catalog-note"><CheckCircle size={15} weight="fill" /><span><strong>Değişiklikler planı yeniden hesaplar.</strong><small>Yeni tezgâh veya ürün hızı tanımı Parametreler sayfasından eklenir; burası günlük operasyon yönetimi içindir.</small></span></div></section></div>;
}

function MachineQueueRow({ batch, setupFamily, index, count, eligibleMachines, dragging, dropEdge, onDragStart, onDragMove, onDragEnd, onMove, onTransfer, onEditQuantity, onRemove, onLock, onUnlock, onSaveWorkOrder }: { batch: PlannedBatch; setupFamily?: ProductSetupFamily; index: number; count: number; eligibleMachines: string[]; dragging: boolean; dropEdge: "before" | "after" | null; onDragStart: (event: React.PointerEvent<HTMLButtonElement>) => void; onDragMove: (event: React.PointerEvent<HTMLButtonElement>) => void; onDragEnd: (event: React.PointerEvent<HTMLButtonElement>) => void; onMove: (position: number) => void; onTransfer: (machineId: string) => void; onEditQuantity: () => void; onRemove: () => void; onLock: () => void; onUnlock: () => void; onSaveWorkOrder: (workOrder: string) => void }) {
  const [workOrder, setWorkOrder] = useState(batch.workOrder ?? "");
  const [targetMachine, setTargetMachine] = useState(batch.machineId);
  useEffect(() => setWorkOrder(batch.workOrder ?? ""), [batch.id, batch.workOrder]);
  useEffect(() => setTargetMachine(batch.machineId), [batch.id, batch.machineId]);
  return <div data-queue-index={index} data-batch-id={batch.id} className={`machine-queue-row ${batch.locked ? "locked" : ""} ${dragging ? "dragging" : ""} ${dropEdge ? `drop-${dropEdge}` : ""}`}>{batch.locked ? <span className="queue-index"><Lock size={12} weight="fill" /></span> : <button className="queue-drag-handle" onPointerDown={onDragStart} onPointerMove={onDragMove} onPointerUp={onDragEnd} onPointerCancel={onDragEnd} aria-label={`${batch.product} işini sürükleyerek sırala`} title="Tut ve sırayı değiştir"><DotsSixVertical size={13} /><b>{queuePosition(batch.planColumn)}</b></button>}<strong>{batch.product}<small>{productSetupFamilyLabel(setupFamily)} · {batch.diameter} · {formatNumber(batch.quantity)} adet · setup {formatHours(batch.setupHours)} · {formatExcelDate(batch.start)} → {formatExcelDate(batch.end)}</small></strong><label className="queue-work-order"><span>İş emri / izlenebilirlik</span><span><input value={workOrder} onChange={(event) => setWorkOrder(event.target.value)} placeholder="320-…" /><button disabled={workOrder.trim() === (batch.workOrder ?? "")} onClick={() => onSaveWorkOrder(workOrder)}>Kaydet</button></span></label><label className="queue-transfer"><span>Uygun tezgaha taşı</span><span><select disabled={batch.locked} value={targetMachine} onChange={(event) => setTargetMachine(event.target.value)}>{eligibleMachines.map((machineId) => <option key={machineId} value={machineId}>{machineId}</option>)}</select><button disabled={batch.locked || targetMachine === batch.machineId} onClick={() => onTransfer(targetMachine)}>Taşı</button></span></label><div className="queue-row-actions"><button disabled={batch.locked || index === 0} onClick={() => onMove(index - 1)} aria-label={`${batch.product} yukarı taşı`}><CaretUp size={13} /></button><button disabled={batch.locked || index === count - 1} onClick={() => onMove(index + 1)} aria-label={`${batch.product} aşağı taşı`}><CaretDown size={13} /></button><button disabled={batch.locked} onClick={onEditQuantity} aria-label={`${batch.product} adedini düzenle`} title="Adedi düzenle"><PencilSimple size={13} /></button>{batch.locked ? <button onClick={onUnlock} aria-label="Kuyruk kilidini kaldır"><LockOpen size={13} /></button> : <button onClick={onLock} aria-label={`${batch.product} sırasına kadar kilitle`}><Lock size={13} /></button>}<button disabled={batch.locked} className="remove" onClick={onRemove} aria-label={`${batch.product} plandan çıkar`}><Trash size={13} /></button></div></div>;
}

function ProcessMachineQueueRow({ operation, index, count, resources, canComplete, dragging, dropEdge, recent, onDragStart, onDragMove, onDragEnd, onDragCancel, onMove, onTransfer, onComplete }: {
  operation: ProcessOperation;
  index: number;
  count: number;
  resources: ProcessResource[];
  canComplete: boolean;
  dragging: boolean;
  dropEdge: "before" | "after" | null;
  recent: boolean;
  onDragStart: (event: React.PointerEvent<HTMLButtonElement>) => void;
  onDragMove: (event: React.PointerEvent<HTMLButtonElement>) => void;
  onDragEnd: (event: React.PointerEvent<HTMLButtonElement>) => void;
  onDragCancel: () => void;
  onMove: (position: number) => void;
  onTransfer: (resourceId: string) => void;
  onComplete: () => void;
}) {
  const [targetResource, setTargetResource] = useState(operation.resourceId);
  useEffect(() => setTargetResource(operation.resourceId), [operation.id, operation.resourceId]);
  const family = operation.family === "piston" ? "Piston" : "Center Pin";
  return <div data-process-queue-index={index} data-operation-id={operation.id} className={`machine-queue-row process-machine-queue-row ${dragging ? "dragging" : ""} ${dropEdge ? `drop-${dropEdge}` : ""} ${recent ? "just-moved" : ""}`}>
    <button className="queue-drag-handle" onPointerDown={onDragStart} onPointerMove={onDragMove} onPointerUp={onDragEnd} onPointerCancel={onDragCancel} onLostPointerCapture={onDragCancel} aria-label={`${operation.workOrder || operation.product} işini sürükleyerek sırala`} title="Tut ve sırayı değiştir"><DotsSixVertical size={13} /><b>{index + 1}</b></button>
    <strong><b className="process-queue-charge">{operation.workOrder || "Şarj no yok"}</b>{operation.product}<small>{family} · {formatNumber(operation.quantity)} adet · setup {formatHours(operation.setupHours)} · {formatExcelDate(operation.start)} → {formatExcelDate(operation.end)}</small></strong>
    <label className="queue-work-order"><span>İş emri / izlenebilirlik</span><span className="process-queue-work-order"><b>{operation.workOrder || "İş emri yok"}</b><em>{operation.source === "wip" ? "Yarı mamül" : operation.source === "current-turning" ? "Tornada çalışan" : "Torna planı"}</em></span></label>
    <label className="queue-transfer"><span>Uygun iş merkezine taşı</span><span><select value={targetResource} onChange={(event) => setTargetResource(event.target.value)}>{resources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select><button disabled={targetResource === operation.resourceId} onClick={() => onTransfer(targetResource)}>Taşı</button></span></label>
    <div className="queue-row-actions process-queue-row-actions"><button disabled={index === 0} onClick={() => onMove(index - 1)} aria-label={`${operation.workOrder || operation.product} yukarı taşı`}><CaretUp size={13} /></button><button disabled={index === count - 1} onClick={() => onMove(index + 1)} aria-label={`${operation.workOrder || operation.product} aşağı taşı`}><CaretDown size={13} /></button><button className="complete-queued-process" disabled={!canComplete} onClick={onComplete} aria-label={`${operation.workOrder || operation.product} · ${processLabel(operation.process)} prosesini bitir`} title={canComplete ? `${processLabel(operation.process)} prosesini sırayı değiştirmeden bitir` : "Yalnız üretime hazır yarı mamül işler tamamlanabilir"}><ProcessIcon process={operation.process} size={13} /></button></div>
  </div>;
}

frontend/features/planning/machines/Prod.source:
"use client";

import { ProcessIcon } from "@/components/ProcessIcon";

import { Field } from "@/features/planning/shared/controls";
import { inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { factoryDateInput } from "@/lib/factory-time";
import { formatInteger as formatNumber } from "@/lib/number-format";
import {
  type CurrentJobInput,
  formatExcelDate,
  isMachineEligibleForProduct,
  type Machine,
  type PlannedBatch,
  type PlanningSeed,
  type ProcessCurrentJob,
  productSetupFamily,
  type ScenarioResult,
  updateMachineCurrentJob,
  type WipLot,
} from "@/lib/planning";
import { type DownstreamProcess, processLabel, type ProcessResource } from "@/lib/process-master-data";
import { type ProcessCurrentJobInput, type ProcessOperation } from "@/lib/process-planning";
import { productSetupFamilyLabel } from "@/lib/setup-families";
import { type WipOperationInput, wipOperationReadyAt } from "@/lib/wip-ledger";
import { ArrowCounterClockwise, MagnifyingGlass, Play, X } from "@phosphor-icons/react";
import { useState } from "react";
import { type ProductSetupFamily } from "@/lib/setup-families";
import { Minus, PencilSimple, Plus } from "@phosphor-icons/react";
import { signedNumber } from "../shared/format";
import { queuePosition } from "../shared/production";

export function CurrentJobEditor({ seed, result, machine, onClose, onSave }: { seed: PlanningSeed; result: ScenarioResult; machine: Machine; onClose: () => void; onSave: (input: CurrentJobInput, remainingAsOf: number) => void }) {
  const eligibleProducts = Array.from(new Set([machine.currentJob.product, ...seed.products.filter((product) => isMachineEligibleForProduct(seed, machine.id, product.product)).map((product) => product.product)].filter(Boolean))).sort((left, right) => left.localeCompare(right));
  const initialProduct = machine.currentJob.product || eligibleProducts[0] || "";
  const [draft, setDraft] = useState({ workOrder: machine.currentJob.workOrder ?? "", product: initialProduct, shiftRate: machine.rates[initialProduct.toUpperCase()] ?? 0, originalQuantity: machine.currentJob.originalQuantity ?? machine.currentJob.quantity, remainingQuantity: machine.currentJob.remainingQuantity ?? machine.currentJob.quantity, start: serialToInputDate(machine.currentJob.start), remainingAsOf: factoryDateInput() });
  const [error, setError] = useState("");
  let previewEnd = 0;
  let previewRate = 0;
  let previewError = "";
  try {
    const preview = updateMachineCurrentJob(seed, result, machine.id, { workOrder: draft.workOrder, product: draft.product, shiftRate: Number(draft.shiftRate), originalQuantity: Number(draft.originalQuantity), remainingQuantity: Number(draft.remainingQuantity), start: inputDateToSerial(draft.start) }, inputDateToSerial(draft.remainingAsOf));
    const previewMachine = preview.seed.machines.find((item) => item.id === machine.id);
    previewEnd = previewMachine?.currentJob.end ?? 0;
    previewRate = previewMachine?.currentJob.dailyRate ?? 0;
  } catch (reason) {
    previewEnd = 0;
    previewError = reason instanceof Error ? reason.message : "Mevcut iş plan üzerindeki etkisiyle hesaplanamadı.";
  }

  function submit() {
    try {
      onSave({ workOrder: draft.workOrder, product: draft.product, shiftRate: Number(draft.shiftRate), originalQuantity: Number(draft.originalQuantity), remainingQuantity: Number(draft.remainingQuantity), start: inputDateToSerial(draft.start) }, inputDateToSerial(draft.remainingAsOf));
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Mevcut iş kaydedilemedi.");
    }
  }

  return <div className="revision-backdrop" role="presentation"><aside className="current-job-drawer" role="dialog" aria-modal="true" aria-label={`${machine.id} mevcut işi`}><div className="revision-head"><div><span>MEVCUT ÜRETİM</span><h2>{machine.id} · {machine.name}</h2><p>Uyumlu ürünler hız kaydı olmasa da gösterilir. Eksik hızı bu iş için güvenle tamamlayabilirsiniz.</p></div><button className="delete-button" onClick={onClose} aria-label="Mevcut iş düzenleyicisini kapat"><X size={16} /></button></div><div className="current-job-form"><Field label="Ürün"><select value={draft.product} onChange={(event) => { const product = event.target.value; setDraft({ ...draft, product, shiftRate: machine.rates[product.toUpperCase()] ?? 0 }); }}>{eligibleProducts.map((product) => <option key={product} value={product}>{product} · {productSetupFamilyLabel(productSetupFamily(seed, product))}{(machine.rates[product.toUpperCase()] ?? 0) > 0 ? "" : " · hız girilmeli"}</option>)}</select></Field><Field label="Vardiya başına üretim hızı"><input type="number" min="0.01" step="0.01" value={draft.shiftRate || ""} onChange={(event) => setDraft({ ...draft, shiftRate: Number(event.target.value) })} placeholder="Örn. 273" /></Field><Field label="İş emri / izlenebilirlik"><input value={draft.workOrder} onChange={(event) => setDraft({ ...draft, workOrder: event.target.value })} placeholder="320-…" /></Field><Field label="Orijinal miktar"><input type="number" min="1" value={draft.originalQuantity} onChange={(event) => setDraft({ ...draft, originalQuantity: Number(event.target.value) })} /></Field><Field label="Kalan miktar"><input type="number" min="0" max={draft.originalQuantity} value={draft.remainingQuantity} onChange={(event) => setDraft({ ...draft, remainingQuantity: Number(event.target.value) })} /></Field><Field label="Üretim başlangıcı"><input type="date" value={draft.start} onChange={(event) => setDraft({ ...draft, start: event.target.value })} /></Field><Field label="Kalan miktar tarihi"><input type="date" value={draft.remainingAsOf} onChange={(event) => setDraft({ ...draft, remainingAsOf: event.target.value })} /></Field><div className="current-job-preview"><span><small>Hesaplanan hız</small><strong>{previewRate ? `${formatNumber(previewRate)} / gün` : "—"}</strong></span><span><small>Tahmini bitiş</small><strong>{previewEnd ? formatExcelDate(previewEnd) : "Plan etkisi kontrol ediliyor"}</strong></span><p>Girilen hız ürün × tezgah hız tablosuna vardiya başına değer olarak kaydedilir. Pazar, tatil ve vardiya istisnaları bitiş hesabına dahildir.</p></div>{(error || previewError) && <p className="form-error">{error || previewError}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!previewEnd || Boolean(previewError)} onClick={submit}>Mevcut işi kaydet</button></div></div></aside></div>;
}

export function CompleteJobDialog({ machine, nextBatch, onClose, onConfirm }: { machine: Machine; nextBatch?: PlannedBatch; onClose: () => void; onConfirm: (completedAt: number, completedQuantity: number) => void }) {
  const [completedDate, setCompletedDate] = useState(factoryDateInput());
  const [completedQuantity, setCompletedQuantity] = useState(machine.currentJob.originalQuantity ?? machine.currentJob.quantity);
  const [error, setError] = useState("");
  function confirm() {
    try {
      if (!completedDate) throw new Error("Tamamlanma tarihi zorunludur.");
      if (!Number.isInteger(completedQuantity) || completedQuantity <= 0) throw new Error("Fiili tamamlanan adet sıfırdan büyük tam sayı olmalıdır.");
      onConfirm(inputDateToSerial(completedDate), completedQuantity);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "İş tamamlanamadı.");
    }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label={`${machine.id} işi tamamlama onayı`}><ProcessIcon process="turning" size={24} /><span>TORNA TAMAMLAMA</span><h2>{machine.currentJob.product} işi tamamlandı mı?</h2><p><b className="tracking-number">{machine.currentJob.workOrder || "İş emri yok"}</b> kaydı üretim arşivine alınacak.</p><Field label="Fiili tamamlanan adet"><input type="number" min="1" step="1" value={completedQuantity || ""} onChange={(event) => setCompletedQuantity(Number(event.target.value))} /></Field><Field label="Gerçek tamamlanma tarihi"><input type="date" value={completedDate} onChange={(event) => setCompletedDate(event.target.value)} /></Field><div className="completion-next"><small>Sıradaki iş</small><strong>{nextBatch ? `${nextBatch.product} · ${formatNumber(nextBatch.quantity)} adet` : "Kuyrukta yeni iş yok"}</strong><span>{nextBatch ? "Onaydan sonra otomatik olarak mevcut üretime geçer." : "Tezgah boş duruma geçer."}</span></div>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={confirm}><ProcessIcon process="turning" size={15} /> Torna prosesini bitir</button></div></section></div>;
}

export function ProcessCurrentJobEditor({ job, onClose, onSave }: { job: ProcessCurrentJob; onClose: () => void; onSave: (input: ProcessCurrentJobInput) => void }) {
  const [draft, setDraft] = useState({ originalQuantity: job.originalQuantity, remainingQuantity: job.remainingQuantity });
  const [error, setError] = useState("");
  function submit() {
    try {
      onSave({ originalQuantity: Number(draft.originalQuantity), remainingQuantity: Number(draft.remainingQuantity) });
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Mevcut iş kaydedilemedi.");
    }
  }
  return <div className="revision-backdrop" role="presentation"><aside className="current-job-drawer" role="dialog" aria-modal="true" aria-label={`${job.resourceId} mevcut işi`}><div className="revision-head"><div><span>MEVCUT ÜRETİM</span><h2>{job.resourceId} · {job.resourceName}</h2><p>{processLabel(job.process)} sonrasında ürün ve şarj kimliği sabittir; yalnızca adet bilgisi düzeltilebilir.</p></div><button className="delete-button" onClick={onClose} aria-label="Mevcut iş düzenleyicisini kapat"><X size={16} /></button></div><div className="current-job-form"><Field label="Ürün"><input value={job.product} disabled /></Field><Field label="Şarj / iş emri"><input value={job.workOrder || "İş emri yok"} disabled /></Field><Field label="Üretim başlangıcı"><input value={formatExcelDate(job.start)} disabled /></Field><Field label="Orijinal miktar"><input type="number" min="1" step="1" value={draft.originalQuantity} onChange={(event) => setDraft({ ...draft, originalQuantity: Number(event.target.value) })} /></Field><Field label="Kalan miktar"><input type="number" min="1" max={draft.originalQuantity} step="1" value={draft.remainingQuantity} onChange={(event) => setDraft({ ...draft, remainingQuantity: Number(event.target.value) })} /></Field><div className="current-job-preview"><span><small>Vardiya kapasitesi</small><strong>{formatNumber(job.unitsPerShift)} adet</strong></span><span><small>Mevcut tahmini bitiş</small><strong>{formatExcelDate(job.end)}</strong></span><p>Kalan adet kaydedildiğinde setup, vardiya, tatil ve bakım takvimi kullanılarak bitiş yeniden hesaplanır.</p></div>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={submit}>Adedi kaydet</button></div></div></aside></div>;
}

export function ProcessCurrentJobSwitcher({ resource, currentJob, operations, onClose, onSelect }: { resource: ProcessResource; currentJob: ProcessCurrentJob; operations: ProcessOperation[]; onClose: () => void; onSelect: (operation: ProcessOperation) => void }) {
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState("");
  const [error, setError] = useState("");
  const normalizedQuery = query.trim().toLocaleUpperCase("tr-TR");
  const visible = operations
    .filter((operation) => !normalizedQuery || `${operation.workOrder} ${operation.product} ${operation.batchId}`.toLocaleUpperCase("tr-TR").includes(normalizedQuery))
    .sort((left, right) => left.readyAt - right.readyAt || left.workOrder.localeCompare(right.workOrder));
  const selected = operations.find((operation) => operation.id === selectedId);
  function submit() {
    if (!selected) return;
    try {
      setError("");
      onSelect(selected);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Mevcut iş değiştirilemedi.");
    }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog process-current-switcher" role="dialog" aria-modal="true" aria-label={`${resource.id} mevcut işi değiştir`}><div className="operational-dialog-head"><span className="dialog-icon shift"><ArrowCounterClockwise size={20} /></span><div><span>KONTROLLÜ İŞ DEĞİŞİMİ</span><h2>{resource.id} mevcut işi değiştir</h2><p>Yeni şarj mevcut üretime alınır; <b>{currentJob.workOrder || currentJob.product}</b> tamamlanmadan kuyruğun ilk sırasına geri döner.</p></div><button className="delete-button" onClick={onClose} aria-label="Mevcut iş değiştirme penceresini kapat"><X size={16} /></button></div><div className="process-switcher-body"><label className="process-queue-search wide"><MagnifyingGlass size={15} /><input autoFocus value={query} onChange={(event) => { setQuery(event.target.value); setError(""); }} placeholder="Şarj no yazın (ör. 320-2600623)" /></label><div className="process-switcher-list">{visible.map((operation) => <button key={operation.id} className={selectedId === operation.id ? "selected" : ""} onClick={() => { setSelectedId(operation.id); setError(""); }}><span><strong>{operation.workOrder || "İş emri yok"}</strong><small>{operation.product} · {formatNumber(operation.quantity)} adet</small></span><em>{formatExcelDate(operation.readyAt)} hazır</em></button>)}{!visible.length && <p className="empty-copy">Bu şarj numarasıyla üretime hazır iş bulunamadı.</p>}</div><div className="calendar-impact-note"><strong>Eski iş kaybolmaz</strong><span>Mevcut şarj tamamlanmış sayılmaz; aynı tezgâhın sıradaki işi olarak korunur.</span></div>{error && <p className="form-error" role="alert">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!selected} onClick={submit}><Play size={14} weight="fill" /> Seçili şarjı mevcut yap</button></div></div></section></div>;
}

export function CompleteProcessCurrentJobDialog({ job, lot, resources, nextOperation, onClose, onConfirm }: { job: ProcessCurrentJob; lot: WipLot; resources: ProcessResource[]; nextOperation?: ProcessOperation; onClose: () => void; onConfirm: (completedAt: number, completedQuantity: number, actualResourceId: string) => void }) {
  const today = inputDateToSerial(factoryDateInput());
  const realReadyAt = wipOperationReadyAt(lot);
  const defaultDate = serialToInputDate(Math.max(realReadyAt, Math.min(today, job.end)));
  const [completedDate, setCompletedDate] = useState(defaultDate);
  const [completedQuantity, setCompletedQuantity] = useState(job.originalQuantity);
  const [actualResourceId, setActualResourceId] = useState(resources.some((resource) => resource.id === job.resourceId) ? job.resourceId : resources[0]?.id ?? "");
  const [error, setError] = useState("");
  function confirm() {
    try {
      if (!completedDate) throw new Error("Tamamlanma tarihi zorunludur.");
      if (!actualResourceId) throw new Error("Fiili iş merkezi seçilmelidir.");
      if (!Number.isInteger(completedQuantity) || completedQuantity <= 0) throw new Error("Fiili tamamlanan adet sıfırdan büyük tam sayı olmalıdır.");
      onConfirm(inputDateToSerial(completedDate) + (job.end - Math.floor(job.end)), completedQuantity, actualResourceId);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "İş tamamlanamadı.");
    }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label={`${job.resourceId} işi tamamlama onayı`}><ProcessIcon process={job.process} size={24} /><span>{processLabel(job.process).toLocaleUpperCase("tr-TR")} GEÇİŞİ</span><h2>{job.product} işi tamamlandı mı?</h2><p><b className="tracking-number">{job.workOrder || "İş emri yok"}</b> kaydı tamamlanacak ve yarı mamül ürün rotasındaki sonraki operasyona gönderilecek.</p><Field label="Fiili tamamlanan adet"><input type="number" min="1" max={job.originalQuantity} step="1" value={completedQuantity || ""} onChange={(event) => setCompletedQuantity(Number(event.target.value))} /></Field><Field label="Fiili iş merkezi"><select value={actualResourceId} onChange={(event) => setActualResourceId(event.target.value)}>{resources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select></Field><Field label="Gerçek tamamlanma tarihi"><input type="date" min={serialToInputDate(realReadyAt)} max={factoryDateInput()} value={completedDate} onChange={(event) => setCompletedDate(event.target.value)} /><small>Plan tarihi değil, sahada gerçekleşen tarih girilir.</small></Field><div className="completion-next"><small>Sıradaki hazır iş</small><strong>{nextOperation ? `${nextOperation.product} · ${formatNumber(nextOperation.quantity)} adet` : "Hazır yarı mamül yok"}</strong><span>{nextOperation ? "Uygunsa onaydan sonra mevcut üretime geçirilir." : "İş merkezi boş mevcut iş durumuna geçer."}</span></div>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={confirm}><ProcessIcon process={job.process} size={15} /> {processLabel(job.process)} prosesini bitir</button></div></section></div>;
}

export function CompleteQueuedProcessOperationDialog({ operation, lot, resources, onClose, onConfirm }: { operation: ProcessOperation; lot: WipLot; resources: ProcessResource[]; onClose: () => void; onConfirm: (input: WipOperationInput) => boolean }) {
  const today = inputDateToSerial(factoryDateInput());
  const realReadyAt = wipOperationReadyAt(lot);
  const [completedDate, setCompletedDate] = useState(serialToInputDate(Math.max(realReadyAt, Math.min(today, operation.end))));
  const [completedQuantity, setCompletedQuantity] = useState(lot.availableQuantity);
  const [actualResourceId, setActualResourceId] = useState(resources.some((resource) => resource.id === operation.resourceId) ? operation.resourceId : resources[0]?.id ?? "");
  const [error, setError] = useState("");
  function confirm() {
    try {
      if (!completedDate) throw new Error("Tamamlanma tarihi zorunludur.");
      const actualResource = resources.find((resource) => resource.id === actualResourceId);
      if (!actualResource) throw new Error("Fiili iş merkezi seçilmelidir.");
      if (!Number.isInteger(completedQuantity) || completedQuantity <= 0 || completedQuantity > lot.availableQuantity) throw new Error("Fiili adet açık yarı mamül miktarını aşmayan pozitif tam sayı olmalıdır.");
      const completedAt = inputDateToSerial(completedDate) + (operation.end - Math.floor(operation.end));
      if (completedAt < realReadyAt) throw new Error(`Bu proses en erken ${formatExcelDate(realReadyAt)} tarihinde tamamlanabilir.`);
      const completed = onConfirm({
        lotId: lot.id,
        process: operation.process as DownstreamProcess,
        resourceId: actualResource.id,
        resourceName: actualResource.name,
        quantity: completedQuantity,
        startedAt: Math.max(realReadyAt, Math.min(operation.start, completedAt)),
        completedAt,
        plannedStart: operation.start,
        plannedEnd: operation.end,
      });
      if (!completed) throw new Error("İş tamamlanamadı; ekrandaki uyarıyı kontrol edin.");
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "İş tamamlanamadı.");
    }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label={`${operation.workOrder || operation.product} kuyruk işini tamamlama onayı`}><ProcessIcon process={operation.process} size={24} /><span>{processLabel(operation.process).toLocaleUpperCase("tr-TR")} TAMAMLAMA</span><h2>{operation.workOrder || operation.product}</h2><p>Şarjı kuyruğun başına taşımadan {processLabel(operation.process).toLocaleLowerCase("tr-TR")} tamamlanmış olarak kaydedilecek ve sonraki operasyona gönderilecek.</p><Field label="Fiili tamamlanan adet"><input type="number" min="1" max={lot.availableQuantity} step="1" value={completedQuantity || ""} onChange={(event) => setCompletedQuantity(Number(event.target.value))} /></Field><Field label="Fiili iş merkezi"><select value={actualResourceId} onChange={(event) => setActualResourceId(event.target.value)}>{resources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select></Field><Field label="Gerçek tamamlanma tarihi"><input type="date" min={serialToInputDate(realReadyAt)} max={factoryDateInput()} value={completedDate} onChange={(event) => setCompletedDate(event.target.value)} /><small>Geçmiş bir tarih seçebilirsiniz; alt sınır şarjın gerçek hazır olma tarihidir.</small></Field><div className="completion-next"><small>Planlanan iş merkezi</small><strong>{operation.resourceId} · {operation.resourceName}</strong><span>Fiili kayıt seçtiğiniz iş merkezine yazılır. Mevcut çalışan iş değişmez.</span></div>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={confirm}><ProcessIcon process={operation.process} size={15} /> {processLabel(operation.process)} prosesini bitir</button></div></section></div>;
}
export function BatchQuantityDialog({ batch, setupFamily, onClose, onSave }: { batch: PlannedBatch; setupFamily?: ProductSetupFamily; onClose: () => void; onSave: (quantity: number) => void }) {
  const batchSize = batch.batchSize;
  const [quantity, setQuantity] = useState(batch.quantity);
  const freeQuantity = setupFamily === "center-pin";
  const chargeCount = batchSize > 0 ? quantity / batchSize : 0;
  const validQuantity = Number.isInteger(quantity) && quantity > 0 && (freeQuantity || (batchSize > 0 && Number.isInteger(chargeCount)));
  const valid = validQuantity && quantity !== batch.quantity;
  const difference = quantity - batch.quantity;
  const changeStep = freeQuantity ? 1 : batchSize;
  const changeQuantity = (delta: number) => setQuantity(Math.max(freeQuantity ? 1 : batchSize, quantity + delta * changeStep));
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog quantity-dialog" role="dialog" aria-modal="true" aria-label={`${batch.product} planlanan adedi düzenle`}>
    <div className="operational-dialog-head"><span className="dialog-icon quantity"><PencilSimple size={20} /></span><div><span>PLANLANAN ŞARJ</span><h2>Üretim adedini düzenle</h2><p>{batch.product} · {batch.machineId} kuyruğunda {queuePosition(batch.planColumn)}. sıra</p></div><button className="delete-button" onClick={onClose} aria-label="Adet düzenlemeyi kapat"><X size={16} /></button></div>
    <div className="quantity-current"><span><small>Mevcut adet</small><strong>{formatNumber(batch.quantity)}</strong></span><span><small>Ürün ailesi</small><strong>{productSetupFamilyLabel(setupFamily)}</strong></span><span><small>{freeQuantity ? "Miktar kuralı" : "Standart şarj"}</small><strong>{freeQuantity ? "Serbest adet" : formatNumber(batchSize)}</strong></span></div>
    <div className="quantity-editor"><button onClick={() => changeQuantity(-1)} disabled={quantity <= (freeQuantity ? 1 : batchSize)}><Minus size={15} /> {freeQuantity ? "1 adet" : "1 şarj"}</button><label><span>Yeni üretim adedi</span><input type="number" min={freeQuantity ? 1 : batchSize} step={freeQuantity ? 1 : batchSize} value={quantity} onChange={(event) => setQuantity(Number(event.target.value))} /></label><button onClick={() => changeQuantity(1)}><Plus size={15} /> {freeQuantity ? "1 adet" : "1 şarj"}</button></div>
    {validQuantity ? <div className={`quantity-preview ${freeQuantity ? "free-quantity" : ""}`}><div><strong>{freeQuantity ? "Center pim için serbest miktar" : `${formatNumber(chargeCount)} tam şarj`}</strong><span>{freeQuantity ? "1980 veya başka bir standart şarj katı aranmaz." : `${formatNumber(chargeCount)} × ${formatNumber(batchSize)} = ${formatNumber(quantity)} adet`}</span></div><em className={difference > 0 ? "increase" : difference < 0 ? "decrease" : ""}>{difference === 0 ? "Değişiklik yok" : `${signedNumber(difference)} adet`}</em></div> : <p className="form-error quantity-error">{freeQuantity ? "Miktar sıfırdan büyük bir tam sayı olmalıdır." : `Miktar ${formatNumber(batchSize)} adetlik standart şarjın tam katı olmalıdır.`}</p>}
    <div className="calendar-impact-note"><strong>Sonraki işler yeniden hesaplanacak</strong><span>Bu şarjın üretim süresi, arkasındaki işlerin tarihleri ve sipariş karşılama durumu güncellenecek. İşlem geri alınabilir.</span></div>
    <div className="drawer-actions quantity-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(quantity)}>Adedi güncelle</button></div>
  </section></div>;
}

frontend/features/planning/orders/Orders.source:
"use client";

import { DeliverySummary, type DeliverySummaryProps } from "@/features/planning/shared/DeliverySummary";
import { buildDeliveryReport, type DeliveryReportRow } from "@/lib/delivery-report";
import { useRaviScreenContext } from "@/features/ravi/context";

import { createEmptyResult } from "@/features/planning/session/planning-state";
import { Field, OrderStatusBadge, SetupFamilyBadge } from "@/features/planning/shared/controls";
import { dateAfterDays, formatInputDate, inputDateToSerial, signedNumber } from "@/features/planning/shared/format";
import { useApiFetch } from "@/lib/api";
import {
  customerOrderOverrideFor,
  removeCustomerOrderOverride,
  upsertCustomerOrderOverride,
  validateCustomerOrderInput,
} from "@/lib/customer-order-overrides";
import { createOrderImportMetadata, orderImportMetadataForSeed } from "@/lib/delivery-deduction";
import {
  type DeliveryPlanRange,
  buildDeliveryPlanPayload,
  deliveryPlanRangeWeekCount,
  deliveryPlanSuggestedRange,
} from "@/lib/delivery-plan";
import { buildDeliveryReadinessEvents, buildOrderDeliveryResults } from "@/lib/delivery-readiness";
import { type DemandImportVersion, isDemandImportVersion } from "@/lib/demand-import-history";
import { compareCustomerDemandImport, protectedBatchesForDemandReimport } from "@/lib/demand-reimport";
import { factoryDateInput } from "@/lib/factory-time";
import { formatInteger as formatNumber } from "@/lib/number-format";
import {
  type OrderTemplateRow,
  TIPLER_ORDER_TEMPLATE,
  applyDueDateToAllOrders,
  ordersFromImportedRows,
  upsertManualOrder,
} from "@/lib/order-entry";
import { addUnconfiguredProductType, productParametersReady } from "@/lib/parameters";
import {
  type DeliveryMilestone,
  type Order,
  type OrderRevision,
  type OrderRevisionRequest,
  type PlanningSeed,
  type RevisionPreview,
  type ScenarioResult,
  type ScenarioStrategy,
  formatExcelDate,
  orderDeliveryMilestones,
  previewOrderRevision,
  productSetupFamily,
} from "@/lib/planning";
import { type ProductSetupFamily, productSetupFamilyLabel } from "@/lib/setup-families";
import { type ConfirmedOverviewPreview, buildWeeklyPlanningState, previewFromDataset } from "@/lib/weekly-demand";
import {
  Archive,
  ArrowCounterClockwise,
  CalendarBlank,
  ChartBar,
  Clock,
  FileXls,
  Lightbulb,
  MagnifyingGlass,
  PencilSimple,
  Plus,
  Question,
  Trash,
  UploadSimple,
  Warning,
  X,
} from "@phosphor-icons/react";
import { useEffect, useMemo, useState } from "react";

type SimpleOrderImportPreview = {
  format?: "simple-orders";
  fileName: string;
  rows: OrderTemplateRow[];
  summary: { productCount: number; orderCount: number; totalQuantity: number; ignoredBlankRows: number };
};

type OrderImportPreview = SimpleOrderImportPreview | ConfirmedOverviewPreview;

function OrderColumnHeader({ id, label, description, numeric = false }: { id: string; label: string; description: string; numeric?: boolean }) {
  const tooltipId = `order-column-tooltip-${id}`;
  return (
    <th className={numeric ? "numeric" : undefined}>
      <span className="order-column-heading">
        <span>{label}</span>
        <button type="button" className="order-column-help" aria-label={`${label} sütunu açıklaması`} aria-describedby={tooltipId}>
          <Question size={11} weight="bold" aria-hidden="true" />
          <span id={tooltipId} role="tooltip">{description}</span>
        </button>
      </span>
    </th>
  );
}

export function OrdersView({ report, reportRange, onReportRangeChange, seed, result, dirty, activeScenarioName, revisions, focusOrderId, onApprove, strategy, updateSeed, onApplyCustomerImport, onOpenAdvice, onOpenManualBatch }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; activeScenarioName: string; revisions: OrderRevision[]; focusOrderId: string | null; onApprove: (revision: OrderRevision) => Promise<void>; strategy: ScenarioStrategy; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; onApplyCustomerImport: (preview: ConfirmedOverviewPreview) => void; onOpenAdvice: (orderId: string) => void; onOpenManualBatch: (product: string) => void } & Omit<DeliverySummaryProps, "hasPlan">) {
  const apiFetch = useApiFetch();
  const [query, setQuery] = useState("");
  const [familyFilter, setFamilyFilter] = useState<ProductSetupFamily | "">("");
  const [filter, setFilter] = useState<"all" | "active" | "shortage" | "due-risk" | "over" | "no-order" | "missing-parameters">("all");
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);
  const [confirmation, setConfirmation] = useState<"clear" | null>(null);
  const [bulkDueDate, setBulkDueDate] = useState("");
  const [bulkDueConfirmationOpen, setBulkDueConfirmationOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  const [uploadedPreview, setUploadedPreview] = useState<OrderImportPreview | null>(null);
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState("");
  const [exportRangeOpen, setExportRangeOpen] = useState(false);
  const [importHistoryOpen, setImportHistoryOpen] = useState(false);
  const [importHistory, setImportHistory] = useState<DemandImportVersion[]>([]);
  const [importHistoryLoading, setImportHistoryLoading] = useState(false);
  const [importHistoryError, setImportHistoryError] = useState("");
  const [newOrderTypeOpen, setNewOrderTypeOpen] = useState(false);
  const exportRange = reportRange;
  const setExportRange = onReportRangeChange;
  const reportRows = new Map(report.rows.map((row) => [row.product, row]));
  const deliveryEvents = useMemo(() => buildDeliveryReadinessEvents(seed, result), [result, seed]);
  const deliveryResults = useMemo(() => buildOrderDeliveryResults(seed, result, deliveryEvents), [result, seed, deliveryEvents]);
  const orders = seed.orders;

  const selectedOrder = orders.find((order) => order.id === selectedOrderId) ?? null;
  const resultMap = new Map(deliveryResults.map((order) => [order.id, order]));
  const orderMap = new Map(orders.map((order) => [order.product.toUpperCase(), order]));
  const baseCatalog = seed.orderCatalog?.length ? seed.orderCatalog : TIPLER_ORDER_TEMPLATE.map((row) => row.product);
  const templateProducts = new Set(baseCatalog.map((product) => product.toUpperCase()));
  const catalog = [...new Set([...baseCatalog, ...orders.map((order) => order.product.toUpperCase()), ...report.rows.map((row) => row.product)])];
  const parameterProducts = new Set(seed.products.filter((product) => productParametersReady(seed, product.product)).map((product) => product.product.toUpperCase()));
  const customerDemand = seed.customerDemand;
  const orderImport = orderImportMetadataForSeed(seed);
  const activePlanRun = result.planRun ?? seed.activePlanRun;
  const baseWeek = customerDemand?.weeks.find((week) => week.id === activePlanRun?.scope.startWeekId);
  const baseWeekLabel = baseWeek
    ? `W${String(baseWeek.isoWeek).padStart(2, "0")}`
    : activePlanRun?.scope.startWeekId?.match(/W(\d{1,2})/i)?.[1]
      ? `W${activePlanRun.scope.startWeekId.match(/W(\d{1,2})/i)![1].padStart(2, "0")}`
      : "—";
  useRaviScreenContext("orders", {
    query, familyFilter, filter, selectedOrder,
    selectedOrderResult: selectedOrder ? resultMap.get(selectedOrder.id) : null,
    totals: report, reportRange,
    visibleCalculationSource: "Teslimat Planı Excel: Sipariş Adeti, Teslimat Adeti, Plan Adet, Fark",
    matchingOrders: deliveryResults.filter((order) => !query || order.product.toLocaleLowerCase("tr-TR").includes(query.toLocaleLowerCase("tr-TR"))).slice(0, 8),
    matchingOrdersNote: "Arama eşleşmeleri; aile/durum filtresi bu örnek listeye uygulanmaz, tüm liste değildir.",
    exportRange, dialogs: { exportRangeOpen, importHistoryOpen, newOrderTypeOpen, revision: Boolean(selectedOrder), importPreview: Boolean(uploadedPreview) },
  });
  const completionByProduct = new Map<string, number>();
  const firstDeliveryByProduct = new Map<string, number>();

  for (const { product, readyAt } of deliveryEvents) {
    completionByProduct.set(product, Math.max(completionByProduct.get(product) ?? 0, readyAt));
    firstDeliveryByProduct.set(product, Math.min(firstDeliveryByProduct.get(product) ?? Infinity, readyAt));
  }
  useEffect(() => {
    const focused = orders.find((order) => order.id === focusOrderId);
    if (focused) setQuery(focused.product);
  }, [focusOrderId, orders]);
  const hasCurrentPlan = result.state === "planned" && !dirty;
  const hasCurrentProduction = seed.machines.some((machine) => Boolean(machine.currentJob.product) && machine.currentJob.quantity > 0)
    || (seed.productionHistory ?? []).some((entry) => (entry.inventoryStatus ?? "semi-finished") === "semi-finished" && entry.completedQuantity > 0);
  const canExportDeliveryPlan = hasCurrentPlan || hasCurrentProduction || seed.orders.length > 0
    || Boolean(customerDemand?.products.length)
    || (seed.productionHistory ?? []).some((entry) => entry.inventoryStatus === "delivered" && entry.completedQuantity > 0);
  const matchesFilter = (product: string, value: typeof filter) => {
    const order = orderMap.get(product.toUpperCase());
    const calculated = order ? resultMap.get(order.id) : undefined;
    const row = reportRows.get(product.toUpperCase());
    if (value === "active") return Boolean(row && row.demand > 0);
    if (value === "shortage") return Boolean(row && row.difference < 0);
    if (value === "due-risk") return Boolean(row && row.difference < 0);
    if (value === "over") return Boolean(row && row.difference > 0);
    if (value === "no-order") return !row || row.demand === 0;
    if (value === "missing-parameters") return !parameterProducts.has(product.toUpperCase());
    return true;
  };
  const filterOptions: { value: typeof filter; label: string }[] = [
    { value: "all", label: "Tümü" }, { value: "active", label: "Aktif sipariş" }, { value: "shortage", label: "Eksik üretim" },
    { value: "due-risk", label: "Termin riski" }, { value: "over", label: "Fazla üretim" },
    { value: "missing-parameters", label: "Parametre eksik" }, { value: "no-order", label: "Sipariş yok" },
  ];
  const visibleProducts = catalog.filter((product) => {
    const family = productSetupFamily(seed, product);
    const searchable = `${product} ${productSetupFamilyLabel(family)}`.toLocaleLowerCase("tr-TR");
    return searchable.includes(query.trim().toLocaleLowerCase("tr-TR")) && (!familyFilter || family === familyFilter) && matchesFilter(product, filter);
  });

  function saveOrder(product: string, quantity: number, dueDate: string) {
    updateSeed((draft) => {
      if (!draft.customerDemand) {
        draft.orders = upsertManualOrder(draft.orders, product, quantity, dueDate, catalog);
        if (draft.orderImport) draft.orderImportGrossOrders = draft.orders.map((order) => ({ ...order, deliveryMilestones: order.deliveryMilestones?.map((milestone) => ({ ...milestone })) }));
        return;
      }
      draft.customerOrderOverrides = upsertCustomerOrderOverride(
        draft.customerOrderOverrides,
        { product, quantity, dueDate },
      );
      const state = buildWeeklyPlanningState(
        previewFromDataset(draft.customerDemand),
        draft.orders,
        draft.customerDemand.activeScope,
        draft.customerOrderOverrides,
        { includePriorBacklog: draft.activePlanRun?.includePriorBacklog ?? true },
      );
      draft.orders = state.orders;
      draft.orderCatalog = state.orderCatalog;
      draft.openingStock = {};
      draft.customerDemand = state.dataset;
    });
  }

  function resetCustomerOrder(product: string) {
    updateSeed((draft) => {
      if (!draft.customerDemand) return;
      draft.customerOrderOverrides = removeCustomerOrderOverride(draft.customerOrderOverrides, product);
      const state = buildWeeklyPlanningState(
        previewFromDataset(draft.customerDemand),
        draft.orders,
        draft.customerDemand.activeScope,
        draft.customerOrderOverrides,
        { includePriorBacklog: draft.activePlanRun?.includePriorBacklog ?? true },
      );
      draft.orders = state.orders;
      draft.orderCatalog = state.orderCatalog;
      draft.openingStock = {};
      draft.customerDemand = state.dataset;
    });
  }

  function addOrderType(product: string, setupFamily: ProductSetupFamily, quantity: number, dueDate: string) {
    const normalized = product.trim().toUpperCase();
    if (catalog.some((item) => item.toUpperCase() === normalized)) throw new Error(`${normalized} zaten tip listesinde.`);
    updateSeed((draft) => {
      addUnconfiguredProductType(draft, normalized, setupFamily);
      const nextCatalog = [...new Set([...(draft.orderCatalog ?? catalog), normalized])];
      draft.orderCatalog = nextCatalog;
      if (!draft.customerDemand) {
        draft.orders = upsertManualOrder(draft.orders, normalized, quantity, dueDate, nextCatalog);
        if (draft.orderImport) draft.orderImportGrossOrders = draft.orders.map((order) => ({ ...order, deliveryMilestones: order.deliveryMilestones?.map((milestone) => ({ ...milestone })) }));
        return;
      }
      draft.customerOrderOverrides = upsertCustomerOrderOverride(
        draft.customerOrderOverrides,
        { product: normalized, quantity, dueDate },
      );
      const state = buildWeeklyPlanningState(
        previewFromDataset(draft.customerDemand),
        draft.orders,
        draft.customerDemand.activeScope,
        draft.customerOrderOverrides,
        { includePriorBacklog: draft.activePlanRun?.includePriorBacklog ?? true },
      );
      draft.orders = state.orders;
      draft.orderCatalog = state.orderCatalog;
      draft.openingStock = {};
      draft.customerDemand = state.dataset;
    });
    setQuery(normalized);
    setFamilyFilter(setupFamily);
    setFilter("all");
  }

  function confirmListAction() {
    if (confirmation === "clear") updateSeed((draft) => { draft.orders = []; draft.customerDemand = undefined; draft.orderImport = undefined; draft.orderImportGrossOrders = undefined; draft.customerOrderOverrides = []; draft.openingStock = {}; });
    setSelectedOrderId(null);
    setConfirmation(null);
  }

  function applyBulkDueDate() {
    if (customerDemand) return;
    updateSeed((draft) => { draft.orders = applyDueDateToAllOrders(draft.orders, bulkDueDate); if (draft.orderImport) draft.orderImportGrossOrders = draft.orders.map((order) => ({ ...order, deliveryMilestones: order.deliveryMilestones?.map((milestone) => ({ ...milestone })) })); });
    setBulkDueConfirmationOpen(false);
  }

  async function previewUploadedExcel(file: File) {
    setUploading(true);
    setUploadError("");
    try {
      const form = new FormData();
      form.append("file", file);
      const response = await apiFetch("/order-imports/preview", { method: "POST", body: form });
      const payload = await response.json() as OrderImportPreview | { detail?: string };
      if (!response.ok) throw new Error("detail" in payload && payload.detail ? payload.detail : "Excel dosyası doğrulanamadı.");
      setUploadedPreview(payload as OrderImportPreview);
    } catch (reason) {
      setUploadError(reason instanceof Error ? reason.message : "Excel dosyası doğrulanamadı.");
    } finally {
      setUploading(false);
    }
  }

  async function openImportHistory() {
    setImportHistoryOpen(true);
    setImportHistoryLoading(true);
    setImportHistoryError("");
    try {
      const response = await apiFetch("/order-imports/history");
      const payload = await response.json() as unknown;
      if (!response.ok || !Array.isArray(payload)) throw new Error("İçe aktarma geçmişi alınamadı.");
      setImportHistory(payload.filter(isDemandImportVersion));
    } catch (reason) {
      setImportHistoryError(reason instanceof Error ? reason.message : "İçe aktarma geçmişi alınamadı.");
    } finally {
      setImportHistoryLoading(false);
    }
  }

  function applyUploadedExcel() {
    if (!uploadedPreview) return;
    if (uploadedPreview.format === "confirmed-overview") {
      onApplyCustomerImport(uploadedPreview);
      setSelectedOrderId(null);
      setUploadedPreview(null);
      return;
    }
    updateSeed((draft) => {
      draft.orderCatalog = uploadedPreview.rows.map((row) => row.product);
      draft.orderCatalogName = uploadedPreview.fileName;
      draft.orderImport = createOrderImportMetadata(uploadedPreview.fileName);
      draft.orders = ordersFromImportedRows(draft.orders, uploadedPreview.rows);
      draft.orderImportGrossOrders = draft.orders.map((order) => ({ ...order, deliveryMilestones: order.deliveryMilestones?.map((milestone) => ({ ...milestone })) }));
      draft.customerDemand = undefined;
      draft.customerOrderOverrides = [];
      draft.openingStock = {};
    });
    setSelectedOrderId(null);
    setUploadedPreview(null);
  }

  async function exportDeliveryPlan() {
    setExporting(true);
    setExportError("");
    try {
      if (!canExportDeliveryPlan) throw new Error("Teslimat planına aktarılacak sipariş, teslimat veya üretim bulunamadı.");
      const payload = report.payload;
      if (!payload) throw new Error(report.error);
      const response = await apiFetch("/delivery-plan/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
      if (!response.ok) {
        const body = await response.json().catch(() => ({})) as { detail?: string };
        throw new Error(body.detail || "Teslimat planı oluşturulamadı.");
      }
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? `Teslimat_Plani_${payload.startDate}_${payload.endDate}.xlsx`;
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
      setExportRangeOpen(false);
    } catch (reason) {
      setExportError(reason instanceof Error ? reason.message : "Teslimat planı oluşturulamadı.");
    } finally {
      setExporting(false);
    }
  }

  return (
    <>
      <section className="data-surface">
      <div className="surface-toolbar order-entry-toolbar">
        <div className="order-context-summary">
          <div className="order-context-line source">
            <span><small>Kullanılan sipariş şablonu</small><strong>{orderImport?.sourceFile ?? seed.orderCatalogName ?? "Manuel sipariş girişi"}</strong></span>
            <span><small>Yükleme tarihi</small><strong>{orderImport?.importedAt ? formatInputDate(factoryDateInput(orderImport.importedAt)) : "—"}</strong></span>
            <span><small>Planlama yapılan tarih</small><strong>{activePlanRun?.createdAt ? formatInputDate(factoryDateInput(activePlanRun.createdAt)) : result.state === "planned" ? formatInputDate(factoryDateInput(result.createdAt)) : "—"}</strong></span>
            <span><small>Planda baz alınan hafta</small><strong>{baseWeekLabel}</strong></span>
            <span><small>Kayıt adı</small><strong>{activeScenarioName || "Kaydedilmemiş plan"}</strong></span>
          </div>

        </div>
        <div className="order-toolbar-actions">
          <button className="primary new-order-type-action" onClick={() => setNewOrderTypeOpen(true)}><Plus size={15} /> Tip ekle</button>
          <button id="ravi-delivery-export" className="secondary delivery-export-action" disabled={!canExportDeliveryPlan || exporting} onClick={() => { setExportError(""); setExportRangeOpen(true); }} title={canExportDeliveryPlan ? "Mevcut ve planlı üretimi tarih aralığına göre indir" : "Aktarılacak üretim bulunamadı"}><FileXls size={15} /> {exporting ? "Excel hazırlanıyor…" : "Teslimat planını indir"}</button>
          <label id="ravi-order-import" tabIndex={-1} className={`secondary order-file-action ${uploading ? "loading" : ""}`}><UploadSimple size={15} />{uploading ? "Excel okunuyor…" : "Müşteri Excel’ini yükle"}<input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" disabled={uploading} onChange={(event) => { const file = event.target.files?.[0]; if (file) void previewUploadedExcel(file); event.currentTarget.value = ""; }} /></label>
          <button className="secondary import-history-action" onClick={() => void openImportHistory()}><ArrowCounterClockwise size={14} /> Excel geçmişi</button>
          <button className="danger-outline" disabled={!orders.length} onClick={() => setConfirmation("clear")}><Trash size={14} /> Tüm siparişleri temizle</button>
          <label className={`parameter-diameter-filter order-family-filter ${familyFilter ? "active" : ""}`}><span>Ürün ailesi</span><select value={familyFilter} onChange={(event) => setFamilyFilter(event.target.value as ProductSetupFamily | "")} aria-label="Ürün ailesine göre filtrele"><option value="">Tüm aileler</option><option value="piston">Piston</option><option value="center-pin">Center Pin</option></select></label>
          <div className="search"><MagnifyingGlass size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Tip ara" /></div>
        </div>
      </div>
      <DeliverySummary report={report} reportRange={reportRange} onReportRangeChange={onReportRangeChange} dirty={dirty} hasPlan={result.state === "planned"} />
      <div className="order-filter-rail"><span>Göster</span>{filterOptions.map((option) => <button key={option.value} className={filter === option.value ? "active" : ""} onClick={() => setFilter(option.value)}>{option.label}<small>{catalog.filter((product) => matchesFilter(product, option.value)).length}</small></button>)}<em>{visibleProducts.length} satır</em></div>
      {!customerDemand && <div className="bulk-due-date-rail"><CalendarBlank size={17} /><div><strong>Genel termin tarihi</strong><span>Tüm aktif siparişlere aynı tarihi verin; daha erken terminleri daha sonra sipariş satırından veya detayından ayrı düzenleyebilirsiniz.</span></div><label><span>Termin</span><input type="date" value={bulkDueDate} onChange={(event) => setBulkDueDate(event.target.value)} aria-label="Genel termin tarihi" /></label><button className="primary" disabled={!bulkDueDate || !orders.length} onClick={() => setBulkDueConfirmationOpen(true)}>Tüm siparişlere uygula</button></div>}
      {uploadError && <div className="order-upload-feedback error"><Warning size={16} weight="fill" /><div><strong>Excel yüklenemedi</strong><span>{uploadError}</span></div><button onClick={() => setUploadError("")} aria-label="Excel yükleme hatasını kapat"><X size={13} /></button></div>}
      {exportError && <div className="order-upload-feedback error"><Warning size={16} weight="fill" /><div><strong>Excel oluşturulamadı</strong><span>{exportError}</span></div><button onClick={() => setExportError("")} aria-label="Excel dışa aktarma hatasını kapat"><X size={13} /></button></div>}
      {revisions.length > 0 && <div className="revision-strip"><strong>Son revizyonlar</strong>{revisions.slice(0, 4).map((revision) => <span key={revision.id}><b>{revision.product}</b> {formatNumber(revision.original.quantity)} → {formatNumber(revision.requested.quantity)} · {formatInputDate(revision.approvedAt.slice(0, 10))}</span>)}</div>}
      <div className="table-scroll orders-table order-entry-table"><table><thead><tr>
        <OrderColumnHeader id="sequence" label="Sıra" description="Tipin müşteri Excel’indeki veya sipariş kataloğundaki sırasıdır." />
        <OrderColumnHeader id="product" label="Tip no" description="Excel’deki Material değerinden gelir; elle eklenen tiplerde kullanıcının girdiği R90… kodudur." />
        <OrderColumnHeader id="report-demand" label="Sipariş adedi" description="Teslimat Planı Excel’indeki Sipariş Adeti: seçili bitiş haftasının müşteri ihtiyacı." numeric />
        <OrderColumnHeader id="quantity" label="Planlama ihtiyacı" description="Düzenlenebilir üretim hedefi. Kümülatif ihtiyaç ve teslimat düşümü nedeniyle Excel teslimat raporundaki Sipariş adedinden farklı olabilir; bu alan rapor toplamını değiştirmek için kullanılmaz." />
        <OrderColumnHeader id="due-date" label="Termin" description="Excel siparişinde talep bulunan son ISO haftasının Cumartesi günüdür. Kullanıcı düzeltmesi varsa seçilen tarih kullanılır." />
        <OrderColumnHeader id="first-delivery" label="İlk teslimat tarihi" description="Bu tip için delme, çapak alma, GKM ve korunan +1 iş günlük tampon tamamlandığında oluşan ilk teslimata hazır tarihtir." />
        <OrderColumnHeader id="estimated-completion" label="Son teslimat tarihi" description="Bu tipe ait son şarjın hesaplanan proses rotası ve korunan +1 iş günlük tampon sonundaki tarihtir." />
        <OrderColumnHeader id="production-coverage" label="Üretim kapsamı" description="Mevcut üretim ile yeni planlanan şarj adetlerinin toplamıdır." numeric />
        <OrderColumnHeader id="delivered" label="Teslim edilen adet" description="Excel Teslimat Adeti: sipariş sonrası gerçekleşen teslimatlar." numeric />
        <OrderColumnHeader id="remaining" label="Dönem içinde planlanan adet" description="Seçili rapor dönemi içindeki Excel Plan Adet. Devreden tekrar eklenmez." numeric />
        <OrderColumnHeader id="delivery-total" label="Planlanan teslimat adedi" description="Dönem içi gerçekleşen teslimatlar + kalan plan; Excel toplamı ile aynı." numeric />
        <OrderColumnHeader id="total-variance" label="Fark (seçili dönem)" description="Excel Fark: sipariş sonrası teslim edilen + dönem içi plan − Sipariş Adeti. Artı fazla, eksi eksik." numeric />
        <OrderColumnHeader id="machines" label="Atanan tezgahlar" description="Bu sipariş için mevcut veya planlı üretim bulunan tezgahları gösterir." />
        <OrderColumnHeader id="status" label="Durum" description="Parametre eksikliği, toplam eksik veya fazla üretim ve termin riskinden hesaplanır." />
        <OrderColumnHeader id="actions" label="İşlem" description="Siparişi kaydetme, Excel değerine dönme, manuel şarj ve detay işlemlerini içerir." />
      </tr></thead><tbody>
        {visibleProducts.map((product) => {
          const order = orderMap.get(product);
          const customerOverride = customerOrderOverrideFor(seed.customerOrderOverrides, product);
          const source = customerOverride ? "override" : customerDemand ? "excel" : "manual";
          return <OrderEntryRow key={product} index={catalog.indexOf(product)} product={product} setupFamily={productSetupFamily(seed, product)} order={order} parameterReady={parameterProducts.has(product)} reportRow={reportRows.get(product)} calculated={order ? resultMap.get(order.id) : undefined} estimatedCompletion={completionByProduct.get(product) ?? 0} firstDelivery={firstDeliveryByProduct.get(product) ?? 0} hasPlan={result.state === "planned" && !dirty} focused={Boolean(order && focusOrderId === order.id)} source={source} onSave={(quantity, dueDate) => saveOrder(product, quantity, dueDate)} onReset={customerOverride ? () => resetCustomerOrder(product) : undefined} onDetails={order && !customerDemand ? () => setSelectedOrderId(order.id) : undefined} onOpenAdvice={order ? () => onOpenAdvice(order.id) : undefined} onManualCharge={order ? () => onOpenManualBatch(product) : undefined} />;
        })}
      </tbody></table></div>
      </section>
      {selectedOrder && <RevisionEditor key={selectedOrder.id} seed={seed} order={selectedOrder} result={result} strategy={strategy} onClose={() => setSelectedOrderId(null)} onApprove={async (revision) => { await onApprove(revision); setSelectedOrderId(null); }} />}
      {confirmation && <OrderListConfirmationDialog activeOrderCount={orders.length} onClose={() => setConfirmation(null)} onConfirm={confirmListAction} />}
      {bulkDueConfirmationOpen && <BulkDueDateConfirmationDialog dueDate={bulkDueDate} activeOrderCount={orders.length} onClose={() => setBulkDueConfirmationOpen(false)} onConfirm={applyBulkDueDate} />}
      {uploadedPreview && <UploadedOrderConfirmationDialog preview={uploadedPreview} seed={seed} result={result} missingParameterProducts={uploadedPreview.rows.filter((row) => !parameterProducts.has(row.product))} onClose={() => setUploadedPreview(null)} onConfirm={applyUploadedExcel} />}
      {exportRangeOpen && <DeliveryPlanExportDialog range={exportRange} orderDate={customerDemand?.snapshotDate ?? ""} sourceFile={customerDemand?.sourceFile ?? orderImport?.sourceFile ?? ""} activePlanScope={hasCurrentPlan && Boolean(result.planRun || seed.activePlanRun)} exporting={exporting} error={exportError} onChange={(range) => { setExportRange(range); setExportError(""); }} onClose={() => { if (!exporting) setExportRangeOpen(false); }} onConfirm={() => void exportDeliveryPlan()} />}
      {importHistoryOpen && <DemandImportHistoryDialog versions={importHistory} currentImportedAt={customerDemand?.importedAt ?? ""} loading={importHistoryLoading} error={importHistoryError} onClose={() => setImportHistoryOpen(false)} onRestore={(version) => { onApplyCustomerImport(previewFromDataset(version.dataset)); setImportHistoryOpen(false); }} />}
      {newOrderTypeOpen && <NewOrderTypeDialog existingProducts={catalog} onClose={() => setNewOrderTypeOpen(false)} onSave={(product, setupFamily, quantity, dueDate) => { addOrderType(product, setupFamily, quantity, dueDate); setNewOrderTypeOpen(false); }} />}
    </>
  );
}

function DeliveryPlanExportDialog({ range, orderDate, sourceFile, activePlanScope, exporting, error, onChange, onClose, onConfirm }: { range: DeliveryPlanRange; orderDate: string; sourceFile: string; activePlanScope: boolean; exporting: boolean; error: string; onChange: (range: DeliveryPlanRange) => void; onClose: () => void; onConfirm: () => void }) {
  let rangeError = "";
  let weekCount = 0;
  try {
    weekCount = deliveryPlanRangeWeekCount(range);
  } catch (reason) {
    rangeError = reason instanceof Error ? reason.message : "Tarih aralığı geçerli değil.";
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog delivery-export-dialog" role="dialog" aria-modal="true" aria-label="Teslimat planı tarih aralığı">
    <FileXls size={25} /><span>TESLİMAT PLANI EXCEL</span><h2>Zaman aralığını seçin</h2>
    <p>{activePlanScope ? "Tarihleri aktif plan kapsamından aldık. Bu Excel için farklı bir dönem seçebilirsiniz." : "Sipariş, gerçekleşen teslimat ve planı incelemek istediğiniz dönemi seçin."}</p>
    <p><strong>{sourceFile || "Manuel siparişler"}</strong><br />{orderDate ? `Müşteri sipariş tarihi: ${formatInputDate(orderDate)}` : "Müşteri sipariş tarihi belirtilmedi; gerçekleşen teslimatlar öncesi/sonrası olarak ayrılmayacak."}</p>
    <div className="delivery-export-range"><Field label="Başlangıç"><input type="date" value={range.startDate} onChange={(event) => onChange({ ...range, startDate: event.target.value })} /></Field><Field label="Bitiş"><input type="date" min={range.startDate} value={range.endDate} onChange={(event) => onChange({ ...range, endDate: event.target.value })} /></Field></div>
    <div className={`delivery-export-summary ${rangeError ? "invalid" : ""}`}><CalendarBlank size={17} /><div><strong>{rangeError || `${weekCount} takvim haftası Excel’e aktarılacak`}</strong><span>{orderDate ? "Sipariş adedi, bitiş haftasının müşteri ihtiyacıdır. Sipariş tarihindeki teslimatlar sipariş sonrası sayılır. Dönem içi toplam, seçilen tarihlerdeki tüm gerçekleşen teslimatları içerir." : "Sipariş adedine teslimatlar eklenmez. Dönem içi toplam, seçilen tarihlerdeki tüm gerçekleşen teslimatları içerir."}</span></div></div>
    {error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" disabled={exporting} onClick={onClose}>Vazgeç</button><button className="primary" disabled={Boolean(rangeError) || exporting} onClick={onConfirm}><FileXls size={15} /> {exporting ? "Excel hazırlanıyor…" : "Excel’i indir"}</button></div>
  </section></div>;
}

function DemandImportHistoryDialog({ versions, currentImportedAt, loading, error, onClose, onRestore }: { versions: DemandImportVersion[]; currentImportedAt: string; loading: boolean; error: string; onClose: () => void; onRestore: (version: DemandImportVersion) => void }) {
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog import-history-dialog" role="dialog" aria-modal="true" aria-label="Müşteri Excel geçmişi">
    <div className="operational-dialog-head"><span className="dialog-icon shift"><ArrowCounterClockwise size={20} /></span><div><span>EXCEL SÜRÜMLERİ</span><h2>İçe aktarma geçmişi</h2><p>Uygulanan müşteri dosyaları sunucuda saklanır. Eski bir sürümü seçerseniz kilitli ve manuel işler yine korunur.</p></div><button className="delete-button" onClick={onClose} aria-label="Excel geçmişini kapat"><X size={16} /></button></div>
    <div className="import-history-body">
      {loading ? <div className="import-history-empty"><Clock size={22} /><strong>Geçmiş yükleniyor…</strong></div>
        : error ? <p className="form-error">{error}</p>
          : versions.length ? <div className="import-history-list">{versions.map((version) => {
            const current = version.importedAt === currentImportedAt;
            return <article key={version.id} className={current ? "current" : ""}><span className="import-history-date"><strong>{new Intl.DateTimeFormat("tr-TR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(version.importedAt))}</strong><small>{current ? "Aktif sürüm" : `Dosya tarihi ${formatInputDate(version.snapshotDate)}`}</small></span><span><strong>{version.sourceFile}</strong><small>{version.summary.firstWeek}–{version.summary.lastWeek} · {version.summary.weekCount} hafta</small></span><span className="numeric"><strong>{formatNumber(version.summary.totalDemand)}</strong><small>{version.summary.productCount} ürün · net ihtiyaç</small></span><button className="secondary" disabled={current} onClick={() => onRestore(version)}>{current ? "Kullanılıyor" : "Bu sürüme dön"}</button></article>;
          })}</div>
            : <div className="import-history-empty"><Archive size={24} /><strong>Henüz kayıtlı Excel sürümü yok</strong><span>Bir sonraki müşteri Excel’i uygulandığında mevcut ve yeni sürüm burada saklanacak.</span></div>}
    </div>
    <div className="drawer-actions"><button className="secondary" onClick={onClose}>Kapat</button></div>
  </section></div>;
}

function BulkDueDateConfirmationDialog({ dueDate, activeOrderCount, onClose, onConfirm }: { dueDate: string; activeOrderCount: number; onClose: () => void; onConfirm: () => void }) {
  return <div className="confirmation-backdrop" role="presentation"><section className="reset-dialog order-list-dialog load bulk-due-dialog" role="dialog" aria-modal="true" aria-label="Genel termin tarihini uygulama onayı"><CalendarBlank size={25} /><span>TOPLU TERMİN GÜNCELLEMESİ</span><h2>{activeOrderCount} siparişin termini değişsin mi?</h2><p>Tüm aktif siparişlerin termin tarihi <b>{formatInputDate(dueDate)}</b> olacak. Sipariş adetleri, parçalı teslimatlar ve diğer bilgiler korunur.</p><div className="reset-impact"><strong>Sonradan değiştirilebilir</strong><span>Daha erken teslim edilecek siparişleri satırdaki termin alanından veya “Detay” ekranından tek tek güncelleyebilirsiniz.</span></div><div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={onConfirm}><CalendarBlank size={15} /> Evet, tümüne uygula</button></div></section></div>;
}

function OrderEntryRow({ reportRow, index, product, setupFamily, order, parameterReady, calculated, estimatedCompletion, firstDelivery, hasPlan, focused, source, onSave, onReset, onDetails, onOpenAdvice, onManualCharge }: { reportRow?: DeliveryReportRow; index: number; product: string; setupFamily?: ProductSetupFamily; order?: Order; parameterReady: boolean; calculated?: ScenarioResult["orders"][number]; estimatedCompletion: number; firstDelivery: number; hasPlan: boolean; focused: boolean; source: "excel" | "override" | "manual"; onSave: (quantity: number, dueDate: string) => void; onReset?: () => void; onDetails?: () => void; onOpenAdvice?: () => void; onManualCharge?: () => void }) {
  const [quantity, setQuantity] = useState(order ? String(order.quantity) : "");
  const [dueDate, setDueDate] = useState(order?.dueDate ?? "");
  useEffect(() => { setQuantity(order ? String(order.quantity) : ""); setDueDate(order?.dueDate ?? ""); }, [order?.id, order?.quantity, order?.dueDate]);
  const parsedQuantity = Math.trunc(Number(quantity) || 0);
  const invalid = Boolean(quantity && (!Number.isFinite(Number(quantity)) || Number(quantity) < 0 || !Number.isInteger(Number(quantity))));
  const changed = parsedQuantity !== (order?.quantity ?? 0) || dueDate !== (order?.dueDate ?? "");
  const difference = reportRow?.difference ?? 0;
  const hasRisk = hasPlan && Boolean(order) && (difference < 0 || (reportRow != null && reportRow.difference < 0));
  const dueSerial = inputDateToSerial(dueDate);
  const late = Boolean(dueSerial && Math.floor(estimatedCompletion) > Math.floor(dueSerial));
  const actionable = changed && !invalid && (parsedQuantity === 0 || Boolean(dueDate)) && (parsedQuantity > 0 || Boolean(order) || source === "override");
  const submit = () => { if (actionable) onSave(parsedQuantity, dueDate); };
  return <tr className={`${focused ? "focused-row" : ""} ${order ? "active-order-row" : "empty-order-row"}`}>
    <td className="muted">{index + 1}</td>
    <td><strong>{product}</strong><SetupFamilyBadge family={setupFamily} /><small className={`stacked-note order-source ${source}`}>{source === "excel" ? "Excel haftaları" : source === "override" ? "Kullanıcı düzeltmesi" : "Manuel sipariş"}</small>{order?.allowPartial && source === "excel" && <small className="stacked-note">Haftalık teslimatlar tanımlı</small>}</td>
    <td className="numeric">{reportRow ? formatNumber(reportRow.demand) : "—"}</td>
    <td><input className={`order-entry-input quantity ${invalid ? "invalid" : ""}`} type="number" min="0" step="1" inputMode="numeric" value={quantity} placeholder="0" onChange={(event) => setQuantity(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") submit(); }} aria-label={`${product} sipariş adeti`} /></td>
    <td><div className="order-date-input"><input className="order-entry-input date" type="date" value={dueDate} onInput={(event) => setDueDate(event.currentTarget.value)} onChange={(event) => setDueDate(event.target.value)} aria-label={`${product} termin tarihi`} /><small>{source === "excel" ? "Son talep haftasının Cumartesisi" : source === "override" ? "Kullanıcı termini" : "Manuel termin"}</small></div></td>
    <td>{hasPlan && firstDelivery ? <><strong>{formatExcelDate(firstDelivery)}</strong><small className="stacked-note">İlk teslimata hazır</small></> : "—"}</td>
    <td className={late ? "delivery-late" : ""}>{hasPlan && estimatedCompletion ? <><strong>{formatExcelDate(estimatedCompletion)}</strong><small className="stacked-note">{dueSerial ? late ? "Termin sonrası" : "Termin içinde" : "Termin yok"}</small></> : "—"}</td>
    <td className="numeric">{hasPlan && order ? <><strong>{formatNumber(calculated?.planned ?? 0)}</strong><small className="stacked-note">{formatNumber(calculated?.existingProduction ?? 0)} mevcut · {formatNumber(calculated?.newlyPlanned ?? 0)} yeni</small></> : "—"}</td>
    <td className="numeric">{reportRow ? formatNumber(reportRow.delivered) : "—"}</td>
    <td className="numeric">{reportRow ? formatNumber(reportRow.remaining) : "—"}</td>
    <td className="numeric">{reportRow ? formatNumber(reportRow.total) : "—"}</td>
    <td className={`numeric variance ${difference < 0 ? "negative" : "positive"}`}>{reportRow ? signedNumber(difference) : "—"}</td>
    <td>{hasPlan && order ? calculated?.assignedMachines.join(", ") || "—" : "—"}</td>
    <td>{!parameterReady ? <span className="badge short">Parametre eksik</span> : order ? hasRisk && onOpenAdvice ? <button className="order-advice-status" onClick={onOpenAdvice} title="Bu sipariş için tezgah, şarj ve mesai tavsiyelerini aç"><OrderStatusBadge difference={difference} onTimeDifference={reportRow?.difference ?? null} hasDueDate={Boolean(dueDate)} empty={!hasPlan} /><Lightbulb size={13} weight="fill" /></button> : <OrderStatusBadge difference={difference} onTimeDifference={reportRow?.difference ?? null} hasDueDate={Boolean(dueDate)} empty={!hasPlan} /> : <span className="badge empty">Sipariş yok</span>}</td>
    <td><div className="order-row-actions"><button className={`order-save-action ${parsedQuantity === 0 && order ? "remove" : ""}`} disabled={!actionable} onClick={submit}>{parsedQuantity === 0 && order ? "Kaldır" : order ? "Kaydet" : "Ekle"}</button>{onReset && <button className="order-reset-action" onClick={onReset}><ArrowCounterClockwise size={12} /> Excel’e dön</button>}{onManualCharge && <button className="order-manual-action" disabled={!hasPlan || !parameterReady} onClick={onManualCharge}><Plus size={13} /> Şarj</button>}{onDetails && <button className="order-detail-action" onClick={onDetails}><PencilSimple size={13} /> Detay</button>}</div></td>
  </tr>;
}

function NewOrderTypeDialog({ existingProducts, onClose, onSave }: { existingProducts: string[]; onClose: () => void; onSave: (product: string, setupFamily: ProductSetupFamily, quantity: number, dueDate: string) => void }) {
  const [product, setProduct] = useState("R90");
  const [setupFamily, setSetupFamily] = useState<ProductSetupFamily | "">("");
  const [quantity, setQuantity] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [error, setError] = useState("");
  const normalizedProduct = product.trim().toUpperCase();
  const parsedQuantity = Number(quantity);
  const validation = validateCustomerOrderInput(
    { product: normalizedProduct, quantity: parsedQuantity, dueDate },
    { requireR90: true },
  );
  if (normalizedProduct && existingProducts.some((item) => item.toUpperCase() === normalizedProduct)) {
    validation.unshift(`${normalizedProduct} zaten tip listesinde.`);
  }
  if (!setupFamily) validation.unshift("Ürün ailesini piston veya Center Pin olarak seçin.");
  const validationMessage = error || (quantity || dueDate ? validation[0] : "");

  function submit() {
    if (validation.length) {
      setError(validation[0]);
      return;
    }
    try {
      onSave(normalizedProduct, setupFamily as ProductSetupFamily, parsedQuantity, dueDate);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Tip eklenemedi.");
    }
  }

  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog new-order-type-dialog" role="dialog" aria-modal="true" aria-label="Siparişlere yeni tip ekle">
    <div className="operational-dialog-head"><span className="dialog-icon manual"><Plus size={20} /></span><div><span>SİPARİŞ TİPİ</span><h2>Yeni tip ve sipariş ekle</h2><p>Tip, sipariş listesine hemen eklenir. Üretim bilgilerini daha sonra Parametreler ekranında tamamlayabilirsiniz.</p></div><button className="delete-button" onClick={onClose} aria-label="Yeni sipariş tipi penceresini kapat"><X size={16} /></button></div>
    <div className="new-order-type-form">
      <Field label="Tip numarası"><input value={product} onChange={(event) => { setProduct(event.target.value.toUpperCase()); setError(""); }} placeholder="R902745180" autoFocus /></Field>
      <Field label="Ürün ailesi"><select value={setupFamily} onChange={(event) => { setSetupFamily(event.target.value as ProductSetupFamily | ""); setError(""); }}><option value="">Aile seçin</option><option value="piston">Piston</option><option value="center-pin">Center Pin</option></select></Field>
      <Field label="Sipariş adedi"><input type="number" min="1" step="1" inputMode="numeric" value={quantity} onChange={(event) => { setQuantity(event.target.value); setError(""); }} placeholder="Örn. 1920" /></Field>
      <Field label="Termin"><input type="date" value={dueDate} onInput={(event) => { setDueDate(event.currentTarget.value); setError(""); }} onChange={(event) => { setDueDate(event.target.value); setError(""); }} /></Field>
    </div>
    <div className="new-order-parameter-note"><Warning size={17} weight="fill" /><div><strong>Ürün ailesi hemen kaydedilir</strong><span>Aile setup hesabında kullanılır. Tezgah, hız, çap ve şarj büyüklüğü Parametreler’de tamamlanana kadar sipariş plana yerleşmez.</span></div></div>
    {validationMessage && <p className="form-error">{validationMessage}</p>}
    <div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={validation.length > 0} onClick={submit}><Plus size={14} /> Tipi ve siparişi ekle</button></div>
  </section></div>;
}

function OrderListConfirmationDialog({ activeOrderCount, onClose, onConfirm }: { activeOrderCount: number; onClose: () => void; onConfirm: () => void }) {
  return <div className="confirmation-backdrop" role="presentation"><section className="reset-dialog order-list-dialog clear" role="dialog" aria-modal="true" aria-label="Tüm siparişleri temizleme onayı"><Warning size={25} weight="fill" /><span>SİPARİŞLER TEMİZLENECEK</span><h2>{activeOrderCount} sipariş kaldırılsın mı?</h2><p>Ürün ve tezgah parametreleri korunur. Yalnızca aktif sipariş listesi boşaltılır ve mevcut plan geçersiz olur.</p><div className="reset-impact"><strong>Korunacaklar</strong><span>Tip listesi · üretim parametreleri · tezgah ayarları · geri bildirimler</span></div><div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="danger-confirm" onClick={onConfirm}><Trash size={15} /> Evet, siparişleri temizle</button></div></section></div>;
}

function UploadedOrderConfirmationDialog({ preview, seed, result, missingParameterProducts, onClose, onConfirm }: { preview: OrderImportPreview; seed: PlanningSeed; result: ScenarioResult; missingParameterProducts: OrderTemplateRow[]; onClose: () => void; onConfirm: () => void }) {
  const activeMissing = missingParameterProducts.filter((row) => row.quantity > 0);
  const confirmed = preview.format === "confirmed-overview";
  const comparison = confirmed ? compareCustomerDemandImport(seed.customerDemand, preview) : null;
  const repeatImport = Boolean(comparison?.repeatImport);
  const protectedBatches = confirmed ? protectedBatchesForDemandReimport(result) : [];
  const currentJobCount = seed.machines.filter((machine) => machine.currentJob.product && machine.currentJob.quantity > 0).length;
  const afterFirstWeekRequirement = confirmed ? Math.max(0, preview.summary.lastWeekRequirement - preview.summary.firstWeekRequirement) : 0;
  const firstWeekLabel = confirmed ? preview.weeks[0]?.label ?? "İlk CW" : "";
  const lastWeekLabel = confirmed ? preview.weeks.at(-1)?.label ?? "Son CW" : "";
  return (
    <div className="confirmation-backdrop" role="presentation">
      <section className="reset-dialog order-list-dialog upload" role="dialog" aria-modal="true" aria-label="Yüklenen Excel siparişlerini onayla">
        <FileXls size={25} />
        <span>{repeatImport ? "MÜŞTERİ TALEBİ DEĞİŞİKLİK ANALİZİ" : confirmed ? "CONFIRMED OVERVIEW DOĞRULANDI" : "EXCEL DOĞRULANDI"}</span>
        <h2>{preview.fileName}</h2>
        <p>
          {repeatImport
            ? "Yeni müşteri ihtiyacı mevcut veriyle karşılaştırıldı. Onaydan önce değişen net üretim ihtiyacı ve korunacak üretim aşağıda gösteriliyor."
            : confirmed
              ? `${preview.sheetName} sayfasındaki negatif bakiyeler net kümülatif üretim ihtiyacına çevrildi. Pozitif bakiye stok fazlasıdır ve üretim ihtiyacı oluşturmaz.`
              : "Dosya yapısı uygun. Onaydan sonra mevcut sipariş listesi ve ekrandaki tip sırası bu dosyayla değiştirilecek."}
        </p>
        <div className="order-import-metrics">
          <span><small>Tip</small><strong>{preview.summary.productCount}</strong>{confirmed && <em><code>Material</code> kayıtları</em>}</span>
          <span><small>{confirmed ? "ISO hafta" : "Dolu sipariş"}</small><strong>{confirmed ? preview.summary.weekCount : preview.summary.orderCount}</strong>{confirmed && <em>{firstWeekLabel}–{lastWeekLabel}</em>}</span>
          <span><small>{confirmed ? `${firstWeekLabel} ihtiyacı` : "Toplam sipariş"}</small><strong>{formatNumber(confirmed ? preview.summary.firstWeekRequirement : preview.summary.totalQuantity)}</strong>{confirmed && <em>İlk kümülatif hedef</em>}</span>
          <span><small>{confirmed ? `${lastWeekLabel} ihtiyacı` : "Boş satır"}</small><strong>{formatNumber(confirmed ? preview.summary.lastWeekRequirement : preview.summary.ignoredBlankRows)}</strong>{confirmed && <em>Son kümülatif hedef</em>}</span>
        </div>
        {confirmed && (
          <div className="order-import-week-range">
            <CalendarBlank size={16} />
            <div>
              <strong>{preview.weeks[0]?.label} → {preview.weeks.at(-1)?.label}</strong>
              <span>{formatInputDate(preview.weeks[0]?.weekStart ?? "")} – {formatInputDate(preview.weeks.at(-1)?.weekEnd ?? "")} · termin günü Cumartesi</span>
              <small>İlk haftadan sonra eklenen net ihtiyaç: <b>{formatNumber(afterFirstWeekRequirement)} adet</b>.</small>
            </div>
          </div>
        )}
        {confirmed && (
          <details className="order-import-calculation" open>
            <summary><Question size={14} /> Bu sayılar nasıl hesaplandı?</summary>
            <div className="order-import-calculation-body">
              <div className="order-import-equation" aria-label={`${firstWeekLabel} ihtiyacı ${formatNumber(preview.summary.firstWeekRequirement)} artı sonraki haftalarda eklenen ${formatNumber(afterFirstWeekRequirement)}, ${lastWeekLabel} kümülatif ihtiyacı ${formatNumber(preview.summary.lastWeekRequirement)}`}>
                <span><small>{firstWeekLabel} ihtiyacı</small><strong>{formatNumber(preview.summary.firstWeekRequirement)}</strong></span>
                <b>+</b>
                <span><small>Sonraki haftalarda eklenen</small><strong>{formatNumber(afterFirstWeekRequirement)}</strong></span>
                <b>=</b>
                <span className="total"><small>{lastWeekLabel} kümülatif</small><strong>{formatNumber(preview.summary.lastWeekRequirement)}</strong></span>
              </div>
              <div className="order-import-formulas">
                <p><b>Ürün bazında ihtiyaç</b><code>MAX(0, −CW bakiyesi)</code><span>Negatif değer üretilecek adettir. Pozitif değer müşterideki stok fazlasıdır ve o ürün için ihtiyaç sıfırdır.</span></p>
                <p><b>Haftanın toplamı</b><code>Σ ürünlerin kümülatif ihtiyacı</code><span>Hesap her <code>Material</code> için ayrı yapılır; bir ürünün stok fazlası başka ürünün eksiğini kapatmaz.</span></p>
                <p><b>Gantt’a eklenecek miktar</b><code>Bu hedef − önceki efektif hedef</code><span>Yalnız artış kadar yeni üretim açılır. Daha sonraki bir bakiye, geçmiş bir termin için doğmuş ihtiyacı silemez.</span></p>
                <p><b>İlk hafta öncesi</b><code>MAX(0, −&lt; CW bakiyesi)</code><span><code>Available quantity</code> bakiyelerin içinde zaten hesaba katılmıştır; ikinci kez eklenmez veya düşülmez. İlk hafta öncesi net ihtiyaç: <b>{formatNumber(preview.summary.priorDemand)}</b>.</span></p>
              </div>
            </div>
          </details>
        )}
        {repeatImport && comparison && (
          <div className="demand-reimport-analysis">
            <div><span>DEĞİŞİKLİKLER</span><strong>{comparison.changedWeekCount} hafta · {comparison.changedProductCount} tip güncellendi</strong></div>
            <dl>
              <div><dt>Net ihtiyaç farkı</dt><dd className={comparison.requirementDelta > 0 ? "increase" : comparison.requirementDelta < 0 ? "decrease" : ""}>{signedNumber(comparison.requirementDelta)}</dd></div>
              <div><dt>Yeni / kaldırılan hafta</dt><dd>+{comparison.addedWeekCount} / −{comparison.removedWeekCount}</dd></div>
              <div><dt>Yeni / kaldırılan tip</dt><dd>+{comparison.addedProductCount} / −{comparison.removedProductCount}</dd></div>
              <div><dt>İlk hafta öncesi farkı</dt><dd>{signedNumber(comparison.baselineRequirementDelta)}</dd></div>
            </dl>
          </div>
        )}
        {missingParameterProducts.length > 0 && (
          <div className={`order-import-warning ${activeMissing.length ? "critical" : ""}`}>
            <Warning size={16} weight="fill" />
            <div>
              <strong>{missingParameterProducts.length} tipte üretim parametresi yok</strong>
              <span>{activeMissing.length ? `${activeMissing.length} tanesinde sipariş adeti sıfırdan büyük; bu siparişler parametre girilene kadar planlanamaz.` : "Bu tiplerin sipariş adeti sıfır; listeye alınacak ancak şimdilik planı etkilemeyecek."}</span>
              <small>{missingParameterProducts.slice(0, 6).map((row) => row.product).join(", ")}{missingParameterProducts.length > 6 ? ` ve ${missingParameterProducts.length - 6} tip daha` : ""}</small>
            </div>
          </div>
        )}
        <div className="reset-impact">
          <strong>Veri güvenliği</strong>
          <span>
            {repeatImport
              ? `${currentJobCount} mevcut çalışan iş aynen korunacak. ${protectedBatches.length} kilitli, manuel veya iş emri verilmiş şarj sabitlenerek korunacak; yalnızca serbest optimize şarjları yeni net ihtiyaca göre yeniden hesaplanacak. Mevcut planlama hafta aralıkları yeni dosyada bulunduğu ölçüde korunacak.`
              : confirmed
                ? "Henüz hiçbir kayıt değişmedi. Ham Excel bakiyeleri ve bunlardan türetilen net kümülatif ihtiyaçlar kaynak veri olarak saklanacak. Available quantity bakiyelerde zaten bulunduğu için ikinci kez hesaba uygulanmayacak."
                : "Henüz hiçbir sipariş değiştirilmedi. Eşleşen tiplerin termin ve parçalı teslimat bilgileri korunacak."}
          </span>
        </div>
        <div className="drawer-actions">
          <button className="secondary" onClick={onClose}>Vazgeç</button>
          <button className="primary" onClick={onConfirm}><FileXls size={15} /> {repeatImport ? "Değişiklikleri uzlaştır" : "Bu Excel’i uygula"}</button>
        </div>
      </section>
    </div>
  );
}

function RevisionEditor({ seed, order, result, strategy, onClose, onApprove }: { seed: PlanningSeed; order: Order; result: ScenarioResult; strategy: ScenarioStrategy; onClose: () => void; onApprove: (revision: OrderRevision) => Promise<void> }) {
  const [draft, setDraft] = useState({ quantity: order.quantity, dueDate: order.dueDate, allowPartial: order.allowPartial, deliveryMilestones: orderDeliveryMilestones(order), reason: "", freezeDate: dateAfterDays(7) });
  const [preview, setPreview] = useState<RevisionPreview | null>(null);
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const change = (patch: Partial<typeof draft>) => { setDraft((current) => ({ ...current, ...patch })); setPreview(null); setError(""); };
  const activeMilestones = draft.allowPartial ? draft.deliveryMilestones : [];
  const request = (): OrderRevisionRequest => ({ orderId: order.id, quantity: Math.max(0, draft.quantity), dueDate: draft.dueDate, allowPartial: draft.allowPartial, deliveryMilestones: activeMilestones, partialDeliveryQuantity: activeMilestones[0]?.quantity ?? 0, partialDeliveryDate: activeMilestones[0]?.date ?? "", reason: draft.reason, freezeThrough: inputDateToSerial(draft.freezeDate) });
  const updateMilestone = (id: string, patch: Partial<DeliveryMilestone>) => change({ deliveryMilestones: draft.deliveryMilestones.map((milestone) => milestone.id === id ? { ...milestone, ...patch } : milestone) });
  const addMilestone = () => change({ deliveryMilestones: [...draft.deliveryMilestones, { id: crypto.randomUUID(), quantity: 0, date: "" }] });
  const removeMilestone = (id: string) => change({ deliveryMilestones: draft.deliveryMilestones.filter((milestone) => milestone.id !== id) });

  function calculateImpact() {
    try {
      if (result.state !== "planned") throw new Error("Revizyon öncesinde mevcut plan çalıştırılmış olmalıdır.");
      setPreview(previewOrderRevision(seed, result, request(), strategy));
      setError("");
    } catch (reason) {
      setPreview(null);
      setError(reason instanceof Error ? reason.message : "Etki analizi oluşturulamadı.");
    }
  }

  async function approve() {
    if (!preview) return;
    setSaving(true);
    try {
      const timestamp = new Date().toISOString();
      await onApprove({ id: crypto.randomUUID(), orderId: order.id, product: order.product, status: "approved", createdAt: timestamp, approvedAt: timestamp, original: { quantity: order.quantity, dueDate: order.dueDate, allowPartial: order.allowPartial, partialDeliveryQuantity: order.partialDeliveryQuantity, partialDeliveryDate: order.partialDeliveryDate, deliveryMilestones: orderDeliveryMilestones(order) }, requested: request(), impact: preview.impact, seed: preview.seed, result: preview.result });
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Revizyon onaylanamadı.");
    } finally {
      setSaving(false);
    }
  }

  return <div className="revision-backdrop" role="presentation"><aside className="revision-drawer" role="dialog" aria-modal="true" aria-label={`${order.product} sipariş revizyonu`}><div className="revision-head"><div><span>SİPARİŞ DEĞİŞİKLİĞİ</span><h2>{order.product}</h2><p>Önce etkiyi hesaplayın, ardından revize planı onaylayın.</p></div><button className="delete-button" onClick={onClose} aria-label="Revizyon penceresini kapat">×</button></div><div className="revision-form"><Field label="Yeni sipariş adedi"><input type="number" min="0" value={draft.quantity} onChange={(event) => change({ quantity: Number(event.target.value) })} /></Field><Field label="Nihai termin"><input type="date" value={draft.dueDate} onChange={(event) => change({ dueDate: event.target.value })} /></Field><Field label="Dondurma tarihi"><input type="date" value={draft.freezeDate} onChange={(event) => change({ freezeDate: event.target.value })} /></Field><label className="partial-toggle"><input type="checkbox" checked={draft.allowPartial} onChange={(event) => change({ allowPartial: event.target.checked, deliveryMilestones: event.target.checked && draft.deliveryMilestones.length === 0 ? [{ id: crypto.randomUUID(), quantity: 0, date: "" }] : draft.deliveryMilestones })} /><span><strong>Parçalı teslimat</strong><small>Birden fazla kümülatif teslimat hedefi tanımlayın</small></span></label>{draft.allowPartial && <div className="delivery-milestones"><div className="delivery-milestone-head"><div><strong>Ara teslimatlar</strong><span>Her satırdaki adet, o tarihe kadar teslim edilecek toplam miktardır.</span></div><button type="button" onClick={addMilestone}><Plus size={13} /> Teslimat ekle</button></div>{draft.deliveryMilestones.map((milestone, index) => <div className="delivery-milestone-row" key={milestone.id}><span>{index + 1}</span><Field label="Bu tarihe kadar toplam"><input type="number" min="1" max={Math.max(1, draft.quantity - 1)} value={milestone.quantity || ""} onChange={(event) => updateMilestone(milestone.id, { quantity: Number(event.target.value) })} /></Field><Field label="Teslim tarihi"><input type="date" value={milestone.date} onChange={(event) => updateMilestone(milestone.id, { date: event.target.value })} /></Field><button className="delete-button" type="button" onClick={() => removeMilestone(milestone.id)} aria-label={`${index + 1}. ara teslimatı sil`}><Trash size={14} /></button></div>)}</div>}<label className="revision-reason">Değişiklik nedeni<textarea value={draft.reason} onChange={(event) => change({ reason: event.target.value })} placeholder="Müşteri miktar veya termin değişikliği…" /></label><div className="freeze-note"><strong>Dondurulan alan</strong><span>{draft.freezeDate} tarihine kadar başlayan planlı şarjlar ve halen çalışan işler taşınmaz.</span></div><button className="wide-secondary" onClick={calculateImpact}><ChartBar size={15} /> Etkiyi hesapla</button>{error && <p className="form-error">{error}</p>}</div>{preview && <div className="impact-preview"><div className="impact-heading"><span>ETKİ ÖNİZLEMESİ</span><strong>{preview.impact.frozenBatchCount} şarj korunuyor</strong></div><div className="impact-metrics"><div><span>Eklenen</span><strong>+{preview.impact.addedBatchCount}</strong></div><div><span>Çıkarılan</span><strong>−{preview.impact.removedBatchCount}</strong></div><div><span>Plan farkı</span><strong>{signedNumber(preview.impact.plannedDelta)}</strong></div><div><span>Etkilenen</span><strong>{preview.impact.affectedMachines.join(", ") || "Yok"}</strong></div></div>{(preview.impact.deliveryChecks ?? []).map((check, index, checks) => <div key={check.id} className={`delivery-check ${check.feasible ? "feasible" : "risk"}`}><strong>{check.feasible ? "Teslimat karşılanıyor" : "Teslimat riski var"} · {index === checks.length - 1 && check.id === "final" ? "Nihai termin" : `${index + 1}. ara teslimat`}</strong><span>{formatInputDate(check.date)} tarihine kadar toplam {formatNumber(check.required)} gerekli; planlanan hazır miktar {formatNumber(check.available)}.</span></div>)}{!preview.impact.deliveryChecks?.length && preview.impact.deliveryFeasible !== null && <div className={`delivery-check ${preview.impact.deliveryFeasible ? "feasible" : "risk"}`}><strong>{preview.impact.deliveryFeasible ? "Teslimat karşılanıyor" : "Teslimat riski var"}</strong><span>{formatInputDate(preview.impact.deliveryDate)} tarihine kadar {formatNumber(preview.impact.deliveryRequired)} gerekli; planlanan hazır miktar {formatNumber(preview.impact.availableByDeliveryDate)}.</span></div>}<button className="primary approve-revision" disabled={saving} onClick={approve}>{saving ? "Kaydediliyor…" : "Revizyonu onayla ve yayınla"}</button></div>}</aside></div>;
}

frontend/features/planning/parameters/Pa.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessParametersEditor } from "@/components/ProcessParametersEditor";
import { ProductionProcessTabs } from "@/components/ProductionProcessWorkspace";
import { DataPackageActions } from "@/features/planning/shared/DataPackageActions";
import { Field } from "@/features/planning/shared/controls";
import { applyParameterPackage, parameterPackage } from "@/lib/data-packages";
import { formatInteger as formatNumber } from "@/lib/number-format";
import {
  addProductType,
  applyProductParameterDraft,
  type NewProductTypeDraft,
  type NewProductTypeValidation,
  parameterDiameterOptions,
  parameterFamilyOptions,
  productMatchesParameterFilters,
  productParameterDraft,
  type ProductParameterDraft,
  validateNewProductTypeDraft,
  validateProductParameterDraft,
} from "@/lib/parameters";
import { diameterNumeric, type PlanningSeed, type Product } from "@/lib/planning";
import { type DownstreamProcess, type ProcessKind } from "@/lib/process-master-data";
import { type ProductSetupFamily, productSetupFamilyLabel } from "@/lib/setup-families";
import { CaretDown, CaretUp, CheckCircle, DotsSixVertical, MagnifyingGlass, Plus, Warning, X } from "@phosphor-icons/react";
import { useLayoutEffect, useRef, useState } from "react";

export function ParametersView({ seed, updateSeed }: { seed: PlanningSeed; updateSeed: (mutator: (seed: PlanningSeed) => void) => void }) {
  const [activeProcess, setActiveProcess] = useState<ProcessKind>("turning");
  const [query, setQuery] = useState("");
  const [diameterFilter, setDiameterFilter] = useState("");
  const [familyFilter, setFamilyFilter] = useState<ProductSetupFamily | "">("");
  const [newProductOpen, setNewProductOpen] = useState(false);
  const [createdProduct, setCreatedProduct] = useState("");
  useRaviScreenContext("parameters", { activeProcess, query, diameterFilter, familyFilter, newProductOpen });
  const diameterOptions = parameterDiameterOptions(seed.products);
  const familyOptions = parameterFamilyOptions(seed.products);
  const activeDiameterFilter = diameterOptions.some((option) => option.value === diameterFilter) ? diameterFilter : "";
  const activeFamilyFilter = familyOptions.some((option) => option.value === familyFilter) ? familyFilter : "";
  const visibleProductCodes = new Set(seed.products.filter((product) => productMatchesParameterFilters(product, query, activeDiameterFilter, activeFamilyFilter)).map((product) => product.product));
  const visibleProductCount = visibleProductCodes.size;
  const filtersActive = Boolean(query.trim() || activeDiameterFilter || activeFamilyFilter);
  const activeDiameterLabel = diameterOptions.find((option) => option.value === activeDiameterFilter)?.label;
  return (
    <>
    <section className="production-process-switcher"><ProductionProcessTabs seed={seed} value={activeProcess} onChange={setActiveProcess} /></section>
    {activeProcess === "turning" ? <>
    <section className="data-surface">
      <div className="turning-parameter-heading"><span>TORNA PARAMETRELERİ</span><strong>Ürün, tezgah uygunluğu, şarj ve üretim hızı</strong><small>Tezgah kodlarının altında tam tezgah adları gösterilir.</small></div>
      <div className="surface-toolbar parameter-toolbar"><div><strong>{filtersActive ? `${visibleProductCount} / ${seed.products.length}` : seed.products.length} ürün parametresi</strong><span>{activeFamilyFilter ? `${productSetupFamilyLabel(activeFamilyFilter)} ailesindeki tipler gösteriliyor.` : activeDiameterLabel ? `${activeDiameterLabel} hammadde çapındaki tipler gösteriliyor.` : "Değişiklikler yalnızca “Kaydet” ile uygulanır. Eksik veya tanımsız tezgah kodları mevcut veriyi silmez."}</span></div><div className="data-toolbar-actions"><button className="primary new-product-action" onClick={() => setNewProductOpen(true)}><Plus size={15} /> Yeni tip</button><DataPackageActions scope="parameters" data={parameterPackage(seed)} onImport={(data) => updateSeed((draft) => applyParameterPackage(draft, data))} /><label className={`parameter-diameter-filter ${activeFamilyFilter ? "active" : ""}`}><span>Ürün ailesi</span><select aria-label="Ürün ailesine göre filtrele" value={activeFamilyFilter} onChange={(event) => setFamilyFilter(event.target.value as ProductSetupFamily | "")}><option value="">Tüm aileler</option>{familyOptions.map((option) => <option key={option.value} value={option.value}>{option.label} · {option.productCount} tip</option>)}</select></label><label className={`parameter-diameter-filter ${activeDiameterFilter ? "active" : ""}`}><span>Hammadde çapı</span><select aria-label="Hammadde çapına göre filtrele" value={activeDiameterFilter} onChange={(event) => setDiameterFilter(event.target.value)}><option value="">Tüm çaplar</option>{diameterOptions.map((option) => <option key={option.value} value={option.value}>{option.label} · {option.productCount} tip</option>)}</select></label><div className="search"><MagnifyingGlass size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ürün ara" /></div></div></div>
      {createdProduct && <div className="parameter-created-note" role="status"><CheckCircle size={17} weight="fill" /><div><strong>{createdProduct} kullanıma hazır</strong><span>Tip, sipariş listesine ve planlama motoruna eklendi. Sipariş adedini girdikten sonra planı yeniden çalıştırabilirsiniz.</span></div><button onClick={() => setCreatedProduct("")} aria-label="Yeni tip bildirimini kapat"><X size={13} /></button></div>}
      <div className="table-scroll"><table><thead><tr><th>Ürün</th><th>Ürün ailesi</th><th>Tezgah önceliği ve günlük üretim</th><th className="numeric">Şarj büyüklüğü</th><th className="numeric">Varsayılan günlük üretim</th><th>Çap</th><th>Kaynak</th><th>Durum</th></tr></thead><tbody>
        {seed.products.map((product) => <ParameterRow key={product.product} hidden={!visibleProductCodes.has(product.product)} seed={seed} product={product} onSave={(validation) => updateSeed((draft) => applyProductParameterDraft(draft, product.product, validation))} />)}
        {visibleProductCount === 0 && <tr className="parameter-empty-row"><td colSpan={8}><strong>Eşleşen tip bulunamadı</strong><span>Ürün aramasını, aile veya hammadde çapı filtresini değiştirin.</span><button onClick={() => { setQuery(""); setFamilyFilter(""); setDiameterFilter(""); }}>Filtreleri temizle</button></td></tr>}
      </tbody></table></div>
    </section>
    {newProductOpen && <NewProductTypeDialog seed={seed} onClose={() => setNewProductOpen(false)} onSave={(validation) => {
      updateSeed((draft) => { addProductType(draft, validation); });
      setQuery(validation.product);
      setFamilyFilter(validation.setupFamily ?? "");
      setDiameterFilter(String(diameterNumeric(validation.diameter)));
      setCreatedProduct(validation.product);
      setNewProductOpen(false);
    }} />}
    </> : <ProcessParametersEditor key={activeProcess} seed={seed} updateSeed={updateSeed} process={activeProcess as DownstreamProcess} />}
    </>
  );
}

function NewProductTypeDialog({ seed, onClose, onSave }: { seed: PlanningSeed; onClose: () => void; onSave: (validation: NewProductTypeValidation) => void }) {
  const [draft, setDraft] = useState<NewProductTypeDraft>({ product: "", setupFamily: "", machines: [], machineDailyRates: {}, batchSize: "", diameter: "" });
  const [attempted, setAttempted] = useState(false);
  const validation = validateNewProductTypeDraft(seed, draft);
  const activeMachines = seed.machines.filter((machine) => machine.active);
  const availableMachines = activeMachines.filter((machine) => !draft.machines.includes(machine.id));

  function change(patch: Partial<NewProductTypeDraft>) {
    setDraft((current) => ({ ...current, ...patch }));
  }

  function addMachine(machineId: string) {
    if (draft.machines.includes(machineId)) return;
    change({ machines: [...draft.machines, machineId], machineDailyRates: { ...draft.machineDailyRates, [machineId]: "" } });
  }

  function removeMachine(machineId: string) {
    const machineDailyRates = { ...draft.machineDailyRates };
    delete machineDailyRates[machineId];
    change({ machines: draft.machines.filter((item) => item !== machineId), machineDailyRates });
  }

  function moveMachine(index: number, direction: -1 | 1) {
    const target = index + direction;
    if (target < 0 || target >= draft.machines.length) return;
    const machines = [...draft.machines];
    [machines[index], machines[target]] = [machines[target], machines[index]];
    change({ machines });
  }

  function save() {
    setAttempted(true);
    if (validation.errors.length) return;
    onSave(validation);
  }

  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog new-product-dialog" role="dialog" aria-modal="true" aria-label="Yeni tip ekle"><div className="operational-dialog-head"><span className="dialog-icon manual"><Plus size={20} /></span><div><span>ÜRÜN ANA VERİSİ</span><h2>Yeni tip tanımla</h2><p>Tipi bir kez tanımlayın; sipariş, manuel şarj ve senaryo planlamasında doğrudan kullanın.</p></div><button className="delete-button" onClick={onClose} aria-label="Yeni tip penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form">
    <div className="new-product-basics"><Field label="Tip numarası"><input value={draft.product} onChange={(event) => change({ product: event.target.value.toUpperCase() })} placeholder="Örn. R902745180" autoFocus /></Field><Field label="Ürün ailesi"><select value={draft.setupFamily} onChange={(event) => change({ setupFamily: event.target.value as ProductSetupFamily | "" })}><option value="">Aile seçin</option><option value="piston">Piston</option><option value="center-pin">Center Pin</option></select></Field><Field label="Hammadde çapı"><input value={draft.diameter} onChange={(event) => change({ diameter: event.target.value })} placeholder="Örn. Ø 23" /></Field><Field label="Standart şarj büyüklüğü"><input type="number" min="1" step="1" value={draft.batchSize} onChange={(event) => change({ batchSize: event.target.value })} placeholder="Örn. 1920" /></Field></div>
    <div className="new-product-machine-section"><div><span>TEZGAH ÖNCELİĞİ VE HIZ</span><small>İlk sıradaki tezgah ana tercihtir. Üretim adedi, tezgahın üç vardiyadaki günlük kapasitesidir.</small></div>{draft.machines.length ? <div className="new-product-machine-list">{draft.machines.map((machineId, index) => <article key={machineId}><span className="new-product-rank">{index + 1}</span><div><strong>{machineId}</strong><small>{seed.machines.find((machine) => machine.id === machineId)?.name ?? "Tanımsız tezgah"}</small></div><label><span>Günlük üretim</span><input type="number" min="0.01" step="0.01" value={draft.machineDailyRates[machineId] ?? ""} onChange={(event) => change({ machineDailyRates: { ...draft.machineDailyRates, [machineId]: event.target.value } })} placeholder="Adet" /></label><div className="new-product-machine-actions"><button disabled={index === 0} onClick={() => moveMachine(index, -1)} aria-label={`${machineId} önceliğini yükselt`}><CaretUp size={12} /></button><button disabled={index === draft.machines.length - 1} onClick={() => moveMachine(index, 1)} aria-label={`${machineId} önceliğini düşür`}><CaretDown size={12} /></button><button className="remove" onClick={() => removeMachine(machineId)} aria-label={`${machineId} seçimini kaldır`}><X size={12} /></button></div></article>)}</div> : <div className="new-product-empty"><strong>Henüz tezgah seçilmedi</strong><span>Planlamaya açmak için en az bir aktif tezgah ekleyin.</span></div>}<div className="new-product-machine-picker">{availableMachines.map((machine) => <button key={machine.id} onClick={() => addMachine(machine.id)}><Plus size={11} /> {machine.id}<small>{machine.name}</small></button>)}</div></div>
    {attempted && validation.errors.length > 0 && <div className="new-product-validation" role="alert"><Warning size={17} weight="fill" /><div><strong>Tip kaydedilemedi</strong>{validation.errors.map((error) => <span key={error}>{error}</span>)}</div></div>}
    {!validation.errors.length && <div className="calendar-impact-note"><strong>{validation.product || "Yeni tip"} planlamaya hazır</strong><span>{productSetupFamilyLabel(validation.setupFamily)} · {validation.machines.length} tezgah · {formatNumber(validation.batchSize)} adet/şarj · ana tezgah {validation.machines[0]}</span></div>}
    <div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={save}>Tipi oluştur</button></div>
  </div></section></div>;
}

function ParameterRow({ seed, product, hidden, onSave }: { seed: PlanningSeed; product: Product; hidden?: boolean; onSave: (validation: ReturnType<typeof validateProductParameterDraft>) => void }) {
  const initial = productParameterDraft(seed, product);
  const [draft, setDraft] = useState<ProductParameterDraft>(initial);
  const [saved, setSaved] = useState(false);
  const [editingRateMachineId, setEditingRateMachineId] = useState<string | null>(null);
  const [editingDefaultRate, setEditingDefaultRate] = useState(false);
  const [priorityDrag, setPriorityDrag] = useState<{ machineId: string; targetIndex: number; edge: "before" | "after" } | null>(null);
  const priorityListRef = useRef<HTMLDivElement | null>(null);
  const priorityPositionsRef = useRef<Map<string, number>>(new Map());
  const priorityMovedRef = useRef<string | null>(null);
  const priorityGestureRef = useRef<{ machineId: string; sourceIndex: number; startY: number; active: boolean } | null>(null);
  const priorityDropRef = useRef<number | null>(null);
  const priorityOrderKey = draft.machines.join("|");

  useLayoutEffect(() => {
    const rows = priorityListRef.current?.querySelectorAll<HTMLElement>(".machine-priority-item[data-machine-id]");
    if (!rows) return;
    const nextPositions = new Map<string, number>();
    rows.forEach((row) => {
      const machineId = row.dataset.machineId;
      if (machineId) nextPositions.set(machineId, row.getBoundingClientRect().top);
    });
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!reduceMotion && priorityPositionsRef.current.size) {
      rows.forEach((row) => {
        const machineId = row.dataset.machineId;
        if (!machineId) return;
        const previousTop = priorityPositionsRef.current.get(machineId);
        const nextTop = nextPositions.get(machineId);
        const delta = previousTop == null || nextTop == null ? 0 : previousTop - nextTop;
        if (Math.abs(delta) > 1) {
          row.animate([{ transform: `translateY(${delta}px)` }, { transform: "translateY(0)" }], { duration: machineId === priorityMovedRef.current ? 420 : 320, easing: "cubic-bezier(.2,.8,.2,1)" });
        }
        if (machineId === priorityMovedRef.current) {
          row.animate([{ backgroundColor: "#dff3ec", boxShadow: "inset 3px 0 0 #087a78" }, { backgroundColor: "#eef8f4", boxShadow: "inset 3px 0 0 #087a78", offset: .55 }, { backgroundColor: "transparent", boxShadow: "inset 0 0 0 rgba(8,122,120,0)" }], { duration: 760, easing: "ease-out" });
        }
      });
    }
    priorityPositionsRef.current = nextPositions;
    priorityMovedRef.current = null;
  }, [priorityOrderKey]);

  function beginPriorityDrag(event: React.PointerEvent<HTMLSpanElement>, machineId: string, index: number) {
    if (event.button !== 0) return;
    priorityGestureRef.current = { machineId, sourceIndex: index, startY: event.clientY, active: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continuePriorityDrag(event: React.PointerEvent<HTMLSpanElement>) {
    const gesture = priorityGestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.abs(event.clientY - gesture.startY) < 5) return;
    gesture.active = true;
    const row = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>(".machine-priority-item[data-priority-index]");
    if (!row || row.closest(".machine-priority-list") !== priorityListRef.current) return;
    const targetIndex = Number(row.dataset.priorityIndex);
    if (!Number.isInteger(targetIndex)) return;
    const rect = row.getBoundingClientRect();
    const edge = event.clientY < rect.top + rect.height / 2 ? "before" : "after";
    const rawInsertion = targetIndex + (edge === "after" ? 1 : 0);
    priorityDropRef.current = Math.max(0, Math.min(draft.machines.length - 1, rawInsertion > gesture.sourceIndex ? rawInsertion - 1 : rawInsertion));
    setPriorityDrag({ machineId: gesture.machineId, targetIndex, edge });
  }

  function endPriorityDrag(event: React.PointerEvent<HTMLSpanElement>) {
    const gesture = priorityGestureRef.current;
    if (!gesture) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    const drop = priorityDropRef.current;
    if (gesture.active && drop != null && drop !== gesture.sourceIndex) {
      const machines = [...draft.machines];
      const [moved] = machines.splice(gesture.sourceIndex, 1);
      machines.splice(drop, 0, moved);
      priorityMovedRef.current = moved;
      change({ machines });
    }
    priorityGestureRef.current = null;
    priorityDropRef.current = null;
    setPriorityDrag(null);
  }
  const validation = validateProductParameterDraft(seed, product, draft);
  const machineInvalid = draft.machines.length === 0 || draft.machines.some((machine) => !seed.machines.some((known) => known.id === machine));
  const batchNumber = Number(draft.batchSize);
  const batchInvalid = !Number.isInteger(batchNumber) || batchNumber <= 0;
  const defaultRateNumber = Number(draft.defaultDailyRate);
  const defaultRateInvalid = !Number.isFinite(defaultRateNumber) || defaultRateNumber <= 0;
  const diameterInvalid = diameterNumeric(draft.diameter.trim()) <= 0;
  const rateSignature = (value: ProductParameterDraft) => value.machines.map((machineId) => `${machineId}:${value.machineDailyRates[machineId] ?? ""}`).join("|");
  const changed = draft.machines.join("|") !== initial.machines.join("|") || rateSignature(draft) !== rateSignature(initial) || draft.defaultDailyRate !== initial.defaultDailyRate || draft.batchSize !== initial.batchSize || draft.diameter.trim() !== initial.diameter.trim() || draft.setupFamily !== initial.setupFamily;
  const message = validation.errors[0] ?? (changed ? validation.warnings[0] : undefined);

  function change(patch: Partial<ProductParameterDraft>) {
    setDraft((current) => ({ ...current, ...patch }));
    setSaved(false);
  }

  function save() {
    if (!changed || validation.errors.length) return;
    onSave(validation);
    setDraft({ machines: [...validation.machines], machineDailyRates: Object.fromEntries(validation.machines.map((machineId) => [machineId, String(validation.machineDailyRates[machineId])])), defaultDailyRate: String(validation.defaultDailyRate), batchSize: String(validation.batchSize), diameter: validation.diameter, setupFamily: validation.setupFamily });
    setEditingRateMachineId(null);
    setEditingDefaultRate(false);
    setSaved(true);
  }

  function addMachine(machineId: string) {
    if (draft.machines.includes(machineId)) return;
    change({ machines: [...draft.machines, machineId], machineDailyRates: { ...draft.machineDailyRates, [machineId]: draft.defaultDailyRate } });
  }

  function removeMachine(machineId: string) {
    change({ machines: draft.machines.filter((item) => item !== machineId) });
    if (editingRateMachineId === machineId) setEditingRateMachineId(null);
  }

  function moveMachine(index: number, direction: -1 | 1) {
    const target = index + direction;
    if (target < 0 || target >= draft.machines.length) return;
    const machines = [...draft.machines];
    [machines[index], machines[target]] = [machines[target], machines[index]];
    priorityMovedRef.current = machines[target];
    change({ machines });
  }

  return <>
    <tr hidden={hidden} className={validation.errors.length && changed ? "parameter-row invalid" : "parameter-row"}>
      <td><strong>{product.product}</strong></td>
      <td><select className="product-family-select" aria-label={`${product.product} ürün ailesi`} value={draft.setupFamily ?? ""} onChange={(event) => change({ setupFamily: event.target.value as ProductSetupFamily | "" })}><option value="">Seçin</option><option value="piston">Piston</option><option value="center-pin">Center Pin</option></select></td>
      <td className={`machine-priority-cell ${machineInvalid && changed ? "invalid" : ""}`}><div ref={priorityListRef} className="machine-priority-list">{draft.machines.map((machineId, index) => <div key={machineId} data-machine-id={machineId} data-priority-index={index} className={`machine-priority-item ${priorityDrag?.machineId === machineId ? "dragging" : ""} ${priorityDrag && priorityDrag.targetIndex === index && priorityDrag.machineId !== machineId ? `drop-${priorityDrag.edge}` : ""}`}><span className="priority-drag-handle" title="Tutup sürükleyerek sıralayın" onPointerDown={(event) => beginPriorityDrag(event, machineId, index)} onPointerMove={continuePriorityDrag} onPointerUp={endPriorityDrag} onPointerCancel={endPriorityDrag}><DotsSixVertical size={10} /><b>{index + 1}</b></span><div className="machine-priority-identity"><strong>{machineId}</strong><small>{seed.machines.find((machine) => machine.id === machineId)?.name ?? "Tanımsız tezgah"}</small></div><small className="machine-priority-role">{index === 0 ? "Ana tezgah" : `${index + 1}. tercih`}</small><div className={`machine-daily-rate ${editingRateMachineId === machineId ? "editing" : ""}`}><small>Günlük üretim</small>{editingRateMachineId === machineId ? <span><input type="number" min="0.01" step="0.01" value={draft.machineDailyRates[machineId] ?? ""} onChange={(event) => change({ machineDailyRates: { ...draft.machineDailyRates, [machineId]: event.target.value } })} autoFocus /><button disabled={validation.errors.length > 0} onClick={() => { if (changed) save(); else setEditingRateMachineId(null); }}>{changed ? "Kaydet" : "Kapat"}</button></span> : <span><b>{formatNumber(Number(draft.machineDailyRates[machineId]) || 0)}</b><em>adet</em><button onClick={() => setEditingRateMachineId(machineId)}>Değiştir</button></span>}</div><button disabled={index === 0} onClick={() => moveMachine(index, -1)} aria-label={`${machineId} önceliğini yükselt`}><CaretUp size={11} /></button><button disabled={index === draft.machines.length - 1} onClick={() => moveMachine(index, 1)} aria-label={`${machineId} önceliğini düşür`}><CaretDown size={11} /></button><button className="remove" onClick={() => removeMachine(machineId)} aria-label={`${machineId} seçimini kaldır`}><X size={11} /></button></div>)}</div><details className="machine-priority-picker"><summary><Plus size={12} /> Tezgah seç</summary><div><p>Seçim sırası planlama önceliğidir. Yeni tezgah ürünün varsayılan günlük üretim adediyle eklenir.</p><div className="machine-option-grid">{seed.machines.map((machine) => { const rank = draft.machines.indexOf(machine.id); return <button key={machine.id} className={rank >= 0 ? "selected" : ""} disabled={rank >= 0} onClick={() => addMachine(machine.id)}><span>{rank >= 0 ? rank + 1 : "+"}</span><b><strong>{machine.id}</strong><small>{machine.name}</small></b></button>; })}</div></div></details></td>
      <td className="numeric"><input aria-label={`${product.product} şarj büyüklüğü`} className={`cell-input numeric ${batchInvalid && changed ? "invalid" : ""}`} inputMode="numeric" value={draft.batchSize} onChange={(event) => change({ batchSize: event.target.value })} /></td>
      <td className={`numeric default-daily-rate-cell ${defaultRateInvalid && changed ? "invalid" : ""}`}><div className={`default-daily-rate ${editingDefaultRate ? "editing" : ""}`}>{editingDefaultRate ? <><input aria-label={`${product.product} varsayılan günlük üretim`} type="number" min="0.01" step="0.01" value={draft.defaultDailyRate} onChange={(event) => change({ defaultDailyRate: event.target.value })} autoFocus /><button disabled={validation.errors.length > 0} onClick={() => { if (changed) save(); else setEditingDefaultRate(false); }}>{changed ? "Kaydet" : "Kapat"}</button></> : <><strong>{formatNumber(defaultRateNumber || 0)}</strong><span>adet</span><button onClick={() => setEditingDefaultRate(true)}>Değiştir</button></>}</div></td>
      <td><input aria-label={`${product.product} çap`} className={`cell-input compact ${diameterInvalid && changed ? "invalid" : ""}`} value={draft.diameter} onChange={(event) => change({ diameter: event.target.value })} /></td>
      <td className="muted source-cell">{product.source}</td>
      <td><button className="parameter-save" disabled={!changed || validation.errors.length > 0} onClick={save}>{saved ? "Kaydedildi" : changed ? "Kaydet" : "Güncel"}</button></td>
    </tr>
    {(message || saved) && <tr hidden={hidden} className="parameter-feedback-row"><td colSpan={8}><span className={validation.errors.length ? "error" : saved ? "success" : "warning"}>{validation.errors.length ? "Kaydedilmedi" : saved ? "Kalıcı olarak kaydedildi" : "Kontrol edin"}</span>{message ?? "Parametreler planlama motoruna uygulandı."}</td></tr>}
  </>;
}

frontend/features/planning/scenarios/Sce.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { Field } from "@/features/planning/shared/controls";
import { DataPackageActions } from "@/features/planning/shared/DataPackageActions";
import { formatFactoryDateTime, signedNumber } from "@/features/planning/shared/format";
import { type PlanningStateRevision, type ScenarioLoadReport } from "@/features/planning/shared/types";
import { scenarioPackage } from "@/lib/data-packages";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { buildOperationalMetrics } from "@/lib/operational-metrics";
import { planRunMetadataLabel } from "@/lib/plan-run";
import { type StoredScenario, formatExcelDate } from "@/lib/planning";
import { type StoredScenarioSummary } from "@/lib/scenario-list";
import { ArrowClockwise, ChartBar, FloppyDisk, Lock, PencilSimple, Trash, Warning, X } from "@phosphor-icons/react";
import { useState } from "react";

export function ScenariosView({ scenarios, loadedScenarios, total, loading, error, planningHistory, onFetchScenario, onLoad, onLoadMore, onRetry, onRestoreRevision, onDelete, onUpdate, onImport }: { scenarios: StoredScenarioSummary[]; loadedScenarios: StoredScenario[]; total: number; loading: boolean; error: string; planningHistory: PlanningStateRevision[]; onFetchScenario: (id: string) => Promise<StoredScenario>; onLoad: (scenario: StoredScenario) => void; onLoadMore: () => void | Promise<void>; onRetry: () => void | Promise<void>; onRestoreRevision: (revision: PlanningStateRevision) => void; onDelete: (id: string) => Promise<void>; onUpdate: (scenario: StoredScenario) => Promise<void>; onImport: (data: unknown) => Promise<void> }) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [editingScenario, setEditingScenario] = useState<StoredScenario | null>(null);
  const [detailLoadingIds, setDetailLoadingIds] = useState<string[]>([]);
  const [detailError, setDetailError] = useState("");
  const selected = selectedIds.map((id) => loadedScenarios.find((scenario) => scenario.id === id)).filter((scenario): scenario is StoredScenario => Boolean(scenario));
  const first = selected[0];
  const second = selected[1];
  const firstOperational = first ? buildOperationalMetrics(first.seed, first.result) : null;
  const secondOperational = second ? buildOperationalMetrics(second.seed, second.result) : null;

  useRaviScreenContext("scenarios", { selectedIds, total, loading, error,
    selected: selected.map((scenario) => ({ id: scenario.id, name: scenario.name, summary: scenario.result.summary })),
    firstOperational, secondOperational, editingScenarioId: editingScenario?.id });

  async function requireScenario(id: string): Promise<StoredScenario> {
    const loaded = loadedScenarios.find((scenario) => scenario.id === id);
    if (loaded) return loaded;
    setDetailLoadingIds((current) => [...new Set([...current, id])]);
    setDetailError("");
    try {
      return await onFetchScenario(id);
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : "Senaryo ayrıntısı yüklenemedi.";
      setDetailError(message);
      throw caught;
    } finally {
      setDetailLoadingIds((current) => current.filter((item) => item !== id));
    }
  }

  async function toggle(id: string) {
    if (selectedIds.includes(id)) {
      setSelectedIds((current) => current.filter((item) => item !== id));
      return;
    }
    setSelectedIds((current) => [...current.slice(-1), id]);
    try {
      await requireScenario(id);
    } catch {
      setSelectedIds((current) => current.filter((item) => item !== id));
    }
  }

  async function loadSelected(id: string) {
    try {
      onLoad(await requireScenario(id));
    } catch {
      // The inline error keeps the list usable and offers an immediate retry.
    }
  }

  async function editSelected(id: string) {
    try {
      setEditingScenario(await requireScenario(id));
    } catch {
      // The inline error keeps the list usable and offers an immediate retry.
    }
  }

  const metricRows = first && second ? [
    ["Talep", first.result.summary.demand, second.result.summary.demand, "neutral"],
    ["Planlanan", first.result.summary.planned, second.result.summary.planned, "higher"],
    ["Net eksik", Math.max(0, first.result.summary.demand - first.result.summary.planned), Math.max(0, second.result.summary.demand - second.result.summary.planned), "lower"],
    ["Brüt eksik", first.result.summary.shortage, second.result.summary.shortage, "lower"],
    ["Fazla üretim", first.result.summary.overproduction, second.result.summary.overproduction, "lower"],
    ["Yeni şarj", first.result.summary.plannedBatchCount, second.result.summary.plannedBatchCount, "neutral"],
    ["Planlanamayan", first.result.summary.unplannedBatchCount, second.result.summary.unplannedBatchCount, "lower"],
    ["Setup saati", first.result.summary.totalSetupHours ?? 0, second.result.summary.totalSetupHours ?? 0, "lower"],
    ["Kullanılan tezgah", first.result.summary.machinesUsed ?? 0, second.result.summary.machinesUsed ?? 0, "neutral"],
    ["Planlanan mesai saati", firstOperational?.plannedOvertimeHours ?? 0, secondOperational?.plannedOvertimeHours ?? 0, "neutral"],
    ["Bakıma ayrılan saat", firstOperational?.maintenanceHours ?? 0, secondOperational?.maintenanceHours ?? 0, "neutral"],
    ["Fasona planlanan adet", firstOperational?.outsourcedQuantity ?? 0, secondOperational?.outsourcedQuantity ?? 0, "neutral"],
  ] as Array<[string, number, number, "higher" | "lower" | "neutral"]> : [];

  const machineRows = first && second ? first.seed.machines.map((machine) => {
    const a = first.result.batches.filter((batch) => batch.status === "planned" && batch.machineId === machine.id);
    const b = second.result.batches.filter((batch) => batch.status === "planned" && batch.machineId === machine.id);
    return { id: machine.id, aCount: a.length, bCount: b.length, aQuantity: a.reduce((sum, batch) => sum + batch.quantity, 0), bQuantity: b.reduce((sum, batch) => sum + batch.quantity, 0) };
  }).filter((row) => row.aCount || row.bCount) : [];

  const orderRows = first && second ? first.result.orders.map((order) => {
    const other = second.result.orders.find((item) => item.id === order.id);
    return { product: order.product, a: order, b: other };
  }).filter((row) => row.b && (row.a.planned !== row.b.planned || row.a.assignedMachines.join() !== row.b.assignedMachines.join())) : [];

  return (
    <section className="scenario-layout">
      <div className="scenario-list-panel">
        <div className="panel-title scenario-panel-title"><ChartBar size={18} /><div><h2>Kayıtlı senaryolar</h2><p>{total ? `${scenarios.length} / ${total} senaryo gösteriliyor. ` : ""}Karşılaştırmak ve Excel'e indirmek için en fazla iki senaryo seçin.</p></div><DataPackageActions scope="scenarios" data={scenarioPackage(selected)} onImport={onImport} exportDisabled={!selected.length || selected.length !== selectedIds.length} exportLabel={detailLoadingIds.length ? "Senaryo açılıyor…" : selected.length ? `Seçilenleri indir (${selected.length})` : "Önce senaryo seçin"} /></div>
        {detailError && <div className="scenario-list-error" role="alert"><Warning size={14} weight="fill" /><span>{detailError}</span><button onClick={() => setDetailError("")}>Kapat</button></div>}
        {loading && !scenarios.length ? <div className="scenario-list-loading" role="status"><ArrowClockwise size={20} /><strong>Senaryolar getiriliyor</strong><span>Önce liste bilgileri yükleniyor; plan ayrıntıları yalnızca gerektiğinde açılacak.</span></div> : error && !scenarios.length ? <div className="scenario-list-loading error" role="alert"><Warning size={20} weight="fill" /><strong>Senaryo listesi açılamadı</strong><span>{error}</span><button className="secondary" onClick={() => void onRetry()}>Tekrar dene</button></div> : scenarios.length ? <><div className="scenario-list">{scenarios.map((scenario) => { const detailLoading = detailLoadingIds.includes(scenario.id); return <article key={scenario.id} className={selectedIds.includes(scenario.id) ? "selected" : ""}><label><input type="checkbox" checked={selectedIds.includes(scenario.id)} disabled={detailLoading} onChange={() => void toggle(scenario.id)} /><span><strong>{scenario.name}</strong>{scenario.notes && <em>{scenario.notes}</em>}<small>{new Intl.DateTimeFormat("tr-TR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(scenario.createdAt))} · {scenario.plannedBatchCount} şarj</small>{scenario.planRun && <small className="scenario-plan-run">{planRunMetadataLabel(scenario.planRun)}</small>}</span></label><div><button className="secondary compact-button" disabled={detailLoading} onClick={() => void loadSelected(scenario.id)}>{detailLoading ? "Açılıyor…" : "Yükle"}</button><button className="edit-button" disabled={detailLoading} onClick={() => void editSelected(scenario.id)} aria-label={`${scenario.name} bilgilerini düzenle`}><PencilSimple size={14} /></button><button className="delete-button" disabled={detailLoading} onClick={() => { setSelectedIds((current) => current.filter((id) => id !== scenario.id)); void onDelete(scenario.id).catch((caught) => setDetailError(caught instanceof Error ? caught.message : "Senaryo silinemedi.")); }} aria-label={`${scenario.name} senaryosunu sil`}><Trash size={15} /></button></div></article>; })}</div>{error && <div className="scenario-list-error" role="alert"><Warning size={14} weight="fill" /><span>{error}</span><button onClick={() => void onRetry()}>Yenile</button></div>}{scenarios.length < total && <button className="scenario-load-more" disabled={loading} onClick={() => void onLoadMore()}>{loading ? "Sonraki senaryolar getiriliyor…" : `Daha fazla göster · ${total - scenarios.length} kayıt kaldı`}</button>}</> : <div className="scenario-empty"><FloppyDisk size={25} /><strong>Henüz kayıtlı senaryo yok</strong><span>Planı çalıştırdıktan sonra “Senaryoyu Kaydet” düğmesini kullanın.</span></div>}
        <div className="version-history-panel"><div><strong>Versiyon geçmişi</strong><small>Canlı yarı mamül, teslimat ve mevcut işler dahil son 20 değişiklik.</small></div>{planningHistory.slice(0, 8).map((revision, index) => <article key={revision.id}><span><b>{formatFactoryDateTime(revision.createdAt)}</b><small>{revision.createdBy?.name ? `${revision.createdBy.name} · ` : ""}{(revision.seed.wipLots ?? []).filter((lot) => lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped").length} açık yarı mamül</small></span><button className="secondary compact-button" disabled={index === 0} onClick={() => onRestoreRevision(revision)}>{index === 0 ? "Güncel" : "Geri yükle"}</button></article>)}</div>
      </div>
      <div className="comparison-panel">
        {first && second ? <>
          <div className="comparison-heading"><div><span>SENARYO KARŞILAŞTIRMA</span><h2>{first.name}<br /><em>ve</em> {second.name}</h2>{(first.notes || second.notes) && <small>{first.notes && `${scenarioColumnName(first)}: ${first.notes}`}{first.notes && second.notes ? " · " : ""}{second.notes && `${scenarioColumnName(second)}: ${second.notes}`}</small>}</div><p>{scenarioColumnName(first)} bitiş: {formatExcelDate(first.result.summary.completion)}<br />{scenarioColumnName(second)} bitiş: {formatExcelDate(second.result.summary.completion)}<br />Fark = ikinci senaryo − ilk senaryo</p></div>
          <div className="comparison-grid"><div className="comparison-card"><h3>Temel sonuçlar</h3><table><thead><tr><th>Ölçüt</th><th className="numeric">{scenarioColumnName(first)}</th><th className="numeric">{scenarioColumnName(second)}</th><th className="numeric">Fark</th></tr></thead><tbody>{metricRows.map(([label, a, b, direction]) => { const delta = b - a; const favorable = direction === "higher" ? delta > 0 : direction === "lower" ? delta < 0 : false; const unfavorable = direction === "higher" ? delta < 0 : direction === "lower" ? delta > 0 : false; return <tr key={label}><td>{label}</td><td className="numeric">{formatNumber(a)}</td><td className="numeric">{formatNumber(b)}</td><td className={`numeric variance ${favorable ? "positive" : unfavorable ? "negative" : ""}`}>{signedNumber(delta)}</td></tr>; })}</tbody></table></div>
          <div className="comparison-card"><h3>Tezgah yükü</h3><table><thead><tr><th>Tezgah</th><th className="numeric">{scenarioColumnName(first)} şarj</th><th className="numeric">{scenarioColumnName(second)} şarj</th><th className="numeric">Miktar farkı</th></tr></thead><tbody>{machineRows.map((row) => <tr key={row.id}><td><strong>{row.id}</strong></td><td className="numeric">{row.aCount}</td><td className="numeric">{row.bCount}</td><td className="numeric">{signedNumber(row.bQuantity - row.aQuantity)}</td></tr>)}</tbody></table></div></div>
          <div className="comparison-card order-comparison"><h3>Değişen sipariş atamaları</h3>{orderRows.length ? <table><thead><tr><th>Ürün</th><th>{scenarioColumnName(first)} plan / tezgah</th><th>{scenarioColumnName(second)} plan / tezgah</th><th className="numeric">Plan farkı</th></tr></thead><tbody>{orderRows.map((row) => <tr key={row.product}><td><strong>{row.product}</strong></td><td>{formatNumber(row.a.planned)} · {row.a.assignedMachines.join(", ") || "—"}</td><td>{formatNumber(row.b?.planned ?? 0)} · {row.b?.assignedMachines.join(", ") || "—"}</td><td className="numeric">{signedNumber((row.b?.planned ?? 0) - row.a.planned)}</td></tr>)}</tbody></table> : <p className="empty-copy">Sipariş planı ve tezgah atamaları aynı.</p>}</div>
        </> : <div className="comparison-empty">{selectedIds.length && detailLoadingIds.length ? <ArrowClockwise size={30} /> : <ChartBar size={30} />}<strong>{selectedIds.length && detailLoadingIds.length ? "Senaryo ayrıntıları açılıyor" : "İki senaryo seçin"}</strong><span>{selectedIds.length && detailLoadingIds.length ? "Büyük plan gövdeleri yalnızca seçtiğiniz kayıtlar için yükleniyor." : "Talep, eksik/fazla üretim, şarj sayısı, tezgah yükü ve sipariş atamalarını yan yana göreceksiniz."}</span></div>}
      </div>
      {editingScenario && <ScenarioEditDialog scenario={editingScenario} onClose={() => setEditingScenario(null)} onSave={async (updated) => { await onUpdate(updated); setEditingScenario(null); }} />}
    </section>
  );
}

export function ScenarioSaveDialog({ sequence, onClose, onSave }: { sequence: number; onClose: () => void; onSave: (name: string, notes: string) => Promise<void> }) {
  const [name, setName] = useState(`Senaryo ${sequence}`);
  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function submit() {
    if (!name.trim()) return;
    setSaving(true);
    setError("");
    try { await onSave(name, notes); }
    catch (caught) { setError(caught instanceof Error ? caught.message : "Senaryo kaydedilemedi."); setSaving(false); }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog scenario-edit-dialog" role="dialog" aria-modal="true" aria-label="Senaryoyu kaydet"><div className="operational-dialog-head"><span className="dialog-icon shift"><FloppyDisk size={20} /></span><div><span>SENARYO KAYDI</span><h2>Planı anlamlı bir adla saklayın</h2><p>Karşılaştırma ekranında bu ad ve açıklama gösterilecek.</p></div><button className="delete-button" onClick={onClose} aria-label="Senaryo kaydını kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Senaryo adı"><input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder={`Senaryo ${sequence}`} /></Field><Field label="Açıklama"><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Örn. Ağustos planı · 2 vardiya · bakım dahil" /></Field>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!name.trim() || saving} onClick={() => void submit()}>{saving ? "Kaydediliyor…" : "Senaryoyu kaydet"}</button></div></div></section></div>;
}

export function ScenarioLoadReportDialog({ report, onClose }: { report: ScenarioLoadReport; onClose: () => void }) {
  const visible = report.overflows.slice(0, 12);
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog scenario-load-report-dialog" role="dialog" aria-modal="true" aria-label={`${report.scenarioName} plan penceresi uyarısı`}><div className="operational-dialog-head"><span className="dialog-icon maintenance"><Warning size={20} weight="fill" /></span><div><span>SENARYO GÜNCEL DURUMA UYARLANDI</span><h2>Plan yüklendi; bazı işler hedef tarihi aşıyor</h2><p>Canlı üretim korunarak kayıtlı tezgah ve kuyruk sırası yeniden hesaplandı. Kilitler korundu ve yüklemeyi engellemedi.</p></div><button className="delete-button" onClick={onClose} aria-label="Senaryo yükleme raporunu kapat"><X size={16} /></button></div><div className="scenario-load-report-summary"><strong>{report.overflows.length} iş</strong><span>kayıtlı plan penceresinin dışında tamamlanıyor</span></div><div className="scenario-load-overflow-list">{visible.map((item) => <article key={item.batchId}><div><strong>{item.machineId} · {item.product}</strong><span>{item.workOrder || item.batchId} · {item.queuePosition}. sıra</span></div><em className={item.locked ? "locked" : "unlocked"}>{item.locked ? <Lock size={11} weight="fill" /> : null}{item.locked ? "Kilitli" : "Kilitli değil"}</em><p><span>Hesaplanan</span><b>{formatExcelDate(item.start)} – {formatExcelDate(item.end)}</b><span>Plan penceresi</span><b>{formatExcelDate(item.windowStart)} – {formatExcelDate(item.windowEnd)}</b></p></article>)}</div>{report.overflows.length > visible.length && <p className="scenario-load-report-more">Ayrıca {report.overflows.length - visible.length} iş daha plan penceresini aşıyor.</p>}<div className="scenario-load-report-note"><strong>Bu bir yükleme hatası değildir.</strong><span>Planın kayıtlı hedef tarihe sığması gerekiyorsa kapasiteyi, kuyruk sırasını veya kilitli işleri gözden geçirin.</span></div><div className="drawer-actions"><button className="primary" onClick={onClose}>Planı görüntüle</button></div></section></div>;
}

function ScenarioEditDialog({ scenario, onClose, onSave }: { scenario: StoredScenario; onClose: () => void; onSave: (scenario: StoredScenario) => Promise<void> }) {
  const [name, setName] = useState(scenario.name);
  const [notes, setNotes] = useState(scenario.notes ?? "");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function submit() {
    if (!name.trim()) return;
    setSaving(true);
    setError("");
    try { await onSave({ ...scenario, name: name.trim(), notes: notes.trim() }); }
    catch (caught) { setError(caught instanceof Error ? caught.message : "Senaryo bilgileri kaydedilemedi."); setSaving(false); }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog scenario-edit-dialog" role="dialog" aria-modal="true" aria-label={`${scenario.name} bilgilerini düzenle`}><div className="operational-dialog-head"><span className="dialog-icon shift"><PencilSimple size={20} /></span><div><span>SENARYO BİLGİSİ</span><h2>Ad ve açıklamayı düzenle</h2><p>Plan verileri değişmez; yalnızca senaryonun tanımı güncellenir.</p></div><button className="delete-button" onClick={onClose} aria-label="Senaryo düzenlemeyi kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Senaryo adı"><input autoFocus value={name} onChange={(event) => setName(event.target.value)} /></Field><Field label="Açıklama"><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Örn. Ağustos planı" /></Field>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!name.trim() || saving} onClick={() => void submit()}>{saving ? "Kaydediliyor…" : "Değişikliği kaydet"}</button></div></div></section></div>;
}

export function nextScenarioNumber(scenarios: Array<Pick<StoredScenario, "name">>): number {
  return Math.max(0, ...scenarios.map((scenario) => Number(scenario.name.match(/senaryo\s+(\d+)/i)?.[1] ?? 0))) + 1;
}

function scenarioColumnName(scenario: StoredScenario): string {
  return scenario.name.split("·")[0].trim() || scenario.name;
}

