"use client";

import { useEffect, useId, useRef, useState } from "react";
import { ArrowDown, ArrowRight, ArrowUp } from "@phosphor-icons/react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { ProcessIcon } from "@/components/ProcessIcon";
import { processLabel, type ProcessKind } from "@/lib/process-master-data";
import { excelSerialToDate } from "@/lib/planning";
import type { ProcessGanttPlacementPreview } from "@/lib/process-planning";

export type PlacementPreview = { valid: true; preview: ProcessGanttPlacementPreview } | { valid: false; reason: string };

export function ProcessPlacementReview({ request, preview, process, dirty, error, onClose, onApply }: {
  request: { requestedStart?: number; resourceId: string };
  preview: PlacementPreview | null;
  process: ProcessKind;
  dirty: boolean;
  error: string;
  onClose: () => void;
  onApply: () => void;
}) {
  const impactListId = useId();
  const impactListRef = useRef<HTMLDivElement | null>(null);
  const impactContentRef = useRef<HTMLDivElement | null>(null);
  const [impactScroll, setImpactScroll] = useState({ overflow: false, moreBelow: false });
  useEffect(() => {
    const list = impactListRef.current;
    const content = impactContentRef.current;
    if (!list || !content) { setImpactScroll({ overflow: false, moreBelow: false }); return; }
    const update = () => {
      const overflow = list.scrollHeight > list.clientHeight + 2;
      const moreBelow = overflow && list.scrollTop + list.clientHeight < list.scrollHeight - 2;
      setImpactScroll((previous) => previous.overflow === overflow && previous.moreBelow === moreBelow ? previous : { overflow, moreBelow });
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(list);
    observer.observe(content);
    list.addEventListener("scroll", update, { passive: true });
    return () => { observer.disconnect(); list.removeEventListener("scroll", update); };
  }, [preview]);
  useRaviScreenContext("placement-review-scroll", { impactCount: preview?.valid ? preview.preview.affectedOperations.length : 0, ...impactScroll });
  function scrollImpacts() {
    const list = impactListRef.current;
    if (!list) return;
    const behavior = window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth";
    if (impactScroll.moreBelow) list.scrollBy({ top: Math.max(100, list.clientHeight * 0.8), behavior });
    else list.scrollTo({ top: 0, behavior });
  }
  const cancelRef = useRef<HTMLButtonElement | null>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    cancelRef.current?.focus();
    return () => { if (previous?.isConnected) previous.focus({ preventScroll: true }); };
  }, []);
  return <div className="confirmation-backdrop"><section className="process-placement-dialog" role="dialog" aria-modal="true" aria-label="Proses yerleşimini incele" onKeyDown={(event) => {
        if (event.key === "Escape") { event.stopPropagation(); onClose(); return; }
        if (event.key !== "Tab") return;
        const buttons = Array.from(event.currentTarget.querySelectorAll<HTMLElement>("button:not(:disabled), [tabindex=\"0\"]"));
        const first = buttons[0], last = buttons.at(-1);
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
      }}><ProcessIcon process={process} size={25} /><h2>Proses yerleşimini incele</h2>
        {dirty && <p className="form-error">Plan girdileri değişmiş. Önizleme mevcut Torna planına göre hesaplanır; taşıma bu uyarıyı kaldırmaz.</p>}
        {preview?.valid ? <>
          <p><strong>{preview.preview.operation.workOrder || preview.preview.operation.product}</strong> · {processLabel(process)} · {request.resourceId} · {preview.preview.insertionIndex + 1}. sıra</p>
          <dl><div><dt>İstenen başlangıç</dt><dd>{placementDate(preview.preview.requestedStart)}</dd></div><div><dt>Hesaplanan başlangıç</dt><dd>{placementDate(preview.preview.operation.start)}</dd></div><div><dt>Hesaplanan bitiş</dt><dd>{placementDate(preview.preview.operation.end)}</dd></div></dl>
          {preview.preview.adjustments.map((reason) => <p className="placement-adjustment" key={reason}>{reason}</p>)}
          <p>{preview.preview.affectedOperations.length} diğer proses adımının tarihi/iş merkezi değişir.</p>
          {!!preview.preview.affectedOperations.length && <div className="placement-impact-browser"><div className={`placement-impact-viewport ${impactScroll.moreBelow ? "has-more-below" : ""}`}><div id={impactListId} ref={impactListRef} className="placement-impact-list" tabIndex={0} role="region" aria-label="Etkilenen proses adımları"><div ref={impactContentRef}>{preview.preview.affectedOperations.map(({ before, after }) => <article key={before.id}>
            <strong className="placement-impact-title"><ProcessIcon process={after.process} size={15} /> {after.workOrder || after.product} · {processLabel(after.process)}</strong>
            <div className="placement-comparison">
              <section className="placement-version placement-version-before" aria-label="Önce · Mevcut plan">
                <header><span className="placement-version-label">Önce</span><span>Mevcut plan</span></header>
                <dl className="placement-version-details">
                  <div><dt>Tezgâh</dt><dd>{before.resourceId}</dd></div>
                  <div><dt>Başlangıç</dt><dd>{placementDate(before.start)}</dd></div>
                  <div><dt>Bitiş</dt><dd>{placementDate(before.end)}</dd></div>
                </dl>
              </section>
              <ArrowRight className="placement-comparison-arrow" size={18} aria-hidden="true" />
              <section className="placement-version placement-version-after" aria-label="Sonra · Yeni plan">
                <header><span className="placement-version-label">Sonra</span><span>Yeni plan</span></header>
                <dl className="placement-version-details">
                  <div><dt>Tezgâh</dt><dd className={before.resourceId !== after.resourceId ? "placement-value-changed" : undefined}>{after.resourceId}{before.resourceId !== after.resourceId && <small className="placement-resource-change">Değişti</small>}</dd></div>
                  <div><dt>Başlangıç</dt><dd className={Math.abs(before.start - after.start) > 1e-8 ? "placement-value-changed" : undefined}>{placementDate(after.start)}</dd></div>
                  <div><dt>Bitiş</dt><dd className={Math.abs(before.end - after.end) > 1e-8 ? "placement-value-changed" : undefined}>{placementDate(after.end)}</dd></div>
                </dl>
              </section>
            </div>
          </article>)}</div></div></div>
            {impactScroll.overflow && <div className="placement-scroll-guide">
              <span>{impactScroll.moreBelow ? "Diğer adımlar aşağıda" : "Listenin sonu"} · Toplam {preview.preview.affectedOperations.length} adım</span>
              <button type="button" aria-controls={impactListId} onClick={scrollImpacts}>
                {impactScroll.moreBelow ? <>Devamını gör <ArrowDown size={15} aria-hidden="true" /></> : <>Başa dön <ArrowUp size={15} aria-hidden="true" /></>}
              </button>
            </div>}
          </div>}
        </> : <p role="alert" className="form-error">{preview?.reason}</p>}
        {error && <p role="alert" className="form-error">{error}</p>}
        <div className="drawer-actions"><button ref={cancelRef} className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!preview?.valid} onClick={onApply}>Yerleşimi uygula</button></div>
      </section></div>;
}

export function placementDate(serial: number): string { return new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "UTC" }).format(new Date(Math.round(excelSerialToDate(serial).getTime() / 1000) * 1000)); }

