"use client";

import { useEffect, useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { AppUpdates } from "@/components/AppUpdates";
import { formatFactoryDateTime } from "@/features/planning/shared/format";
import { type View } from "@/features/planning/shared/types";
import { AuthAvatar } from "@/lib/api";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { type ProductionPullStatus, productionSyncAction, type ProductionSyncInfo } from "@/lib/production-sync";
import { Archive, ArrowClockwise, Lightbulb, X } from "@phosphor-icons/react";

export function Header({ isAdmin, view, setView, notice, adviceCount, onOpenAdvice, onOpenArchive, productionSyncInfo, productionPullStatus, onPullProduction }: { isAdmin: boolean; view: View; setView: (view: View) => void; notice: string; adviceCount: number; onOpenAdvice: () => void; onOpenArchive: () => void; productionSyncInfo: ProductionSyncInfo | null; productionPullStatus: ProductionPullStatus; onPullProduction: () => void }) {
  const [visibleNotice, setVisibleNotice] = useState("");
  useEffect(() => {
    setVisibleNotice(notice);
    if (!notice) return;
    const timer = window.setTimeout(() => setVisibleNotice(""), 8000);
    return () => window.clearTimeout(timer);
  }, [notice]);
  useRaviScreenContext("header-status", { notice: visibleNotice });
  const items: Array<[View, string]> = [
    ["planning", "Planlama"],
    ["processes", "Şarj Yolculuğu"],
    ["control", "Genel Bakış"],
    ["orders", "Siparişler"],
    ["machines", "Tezgahlar"],
    ["parameters", "Parametreler"],
    ["settings", "Ayarlar"],
    ["scenarios", "Senaryolar"],
    ["feedback", "Geri Bildirimler"],
  ].filter(([id]) => isAdmin || id !== "settings") as Array<[View, string]>;
  const productionAction = productionSyncAction(productionSyncInfo, productionPullStatus);
  return (
    <>
    <header className="topbar">
      <button className="brand" onClick={() => setView("planning")} aria-label="Selsa Planlama ana sayfa"><span className="selsa-logo-frame"><img src="/selsa-logo.gif" alt="Selsa" /></span><span>Planlama</span></button>
      <nav aria-label="Primary navigation">
        {items.map(([id, label]) => <button key={id} className={`nav-item ${view === id ? "active" : ""}`} onClick={() => setView(id)}>{label}</button>)}
      </nav>
      <div className="top-actions"><button className={`advice-launch ${adviceCount ? "active" : ""}`} onClick={onOpenAdvice} title="Planlama tavsiyelerini aç"><Lightbulb size={14} weight={adviceCount ? "fill" : "regular"} /><span>Tavsiyeler</span><b>{formatNumber(adviceCount)}</b></button><button className="archive-global-launch" onClick={onOpenArchive} title="Üretim arşivini her ekrandan aç"><Archive size={14} /><span>Üretim arşivi</span></button>{isAdmin && productionAction.visible && <button className={`sync-action production-pull ${productionPullStatus}`} disabled={productionAction.disabled} onClick={onPullProduction} title={productionSyncInfo?.enabled ? "Üretimdeki son verileri staging’e kopyala; üretim hiçbir şekilde değiştirilmez" : "Staging üretim bağlantısı yapılandırılmamış"}><ArrowClockwise size={14} /><span>{productionAction.label}<small>{productionSyncInfo?.enabled && productionSyncInfo.lastSync ? `Son kopya: ${formatFactoryDateTime(productionSyncInfo.lastSync.importedAt)}` : productionAction.detail}</small></span></button>}<AppUpdates canManage={isAdmin} /><span id="feedback-header-action" className="feedback-header-slot" /><AuthAvatar /></div>
    </header>
    {visibleNotice && <div className="planning-status-toast" role="status"><span>{visibleNotice}</span><button onClick={() => setVisibleNotice("")} aria-label="Durum mesajını kapat"><X size={15} /></button></div>}
    </>
  );
}

export function pageTitle(view: View) {
  return ({ planning: "Tezgah planı", processes: "Şarj yolculuğu", control: "Üretim genel bakış", orders: "02_Siparisler", machines: "Tezgah programları", parameters: "Tip_Parametreleri", settings: "Üretim takvimi ve ayarlar", scenarios: "Senaryo karşılaştırma", feedback: "Geri bildirimler" })[view];
}

