import { excelSerialToDate, type PlanningSeed, type ScenarioResult } from "./planning";
import { factoryDateInput } from "./factory-time";
import { buildDeliveryReadinessEvents } from "./delivery-readiness";
import { effectiveDeliveryTimestamp } from "./delivery-deduction";
import { activeWipLots } from "./wip-ledger";
import { resolvedProductSetupFamily } from "./setup-families";

export type DeliveryPlanColumnKind = "actual" | "actual-before-order" | "actual-after-order" | "carryover" | "plan";

export type DeliveryPlanPayload = {
  startDate: string;
  endDate: string;
  category: string;
  orderDate: string;
  sourceFile: string;
  demandSource: "customer-snapshot" | "imported-orders" | "manual-orders";
  weeks: { label: string; kind: DeliveryPlanColumnKind }[];
  rows: { product: string; family: string; orderQuantity: number; weeklyQuantities: number[] }[];
};

export type DeliveryPlanRange = { startDate: string; endDate: string };

const DAY_MS = 86_400_000;
const MAX_DELIVERY_PLAN_WEEKS = 53;

function serialToIsoDate(serial: number): string {
  return excelSerialToDate(Math.floor(serial)).toISOString().slice(0, 10);
}

function isoDateToSerial(value: string): number {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return Number.NaN;
  const timestamp = Date.parse(`${value}T00:00:00Z`);
  if (!Number.isFinite(timestamp) || new Date(timestamp).toISOString().slice(0, 10) !== value) return Number.NaN;
  return (timestamp - Date.UTC(1899, 11, 30)) / DAY_MS;
}

function isoWeek(serial: number): number {
  const date = excelSerialToDate(Math.floor(serial));
  const day = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date.getTime() - yearStart.getTime()) / DAY_MS) + 1) / 7);
}

function weekStart(serial: number): number {
  const date = excelSerialToDate(Math.floor(serial));
  const day = date.getUTCDay() || 7;
  return Math.floor(serial) - day + 1;
}

export function deliveryPlanDefaultRange(today = factoryDateInput()): DeliveryPlanRange {
  const todaySerial = isoDateToSerial(today);
  const start = weekStart(todaySerial);
  return { startDate: serialToIsoDate(start), endDate: serialToIsoDate(start + 41) };
}

function scheduledCompletionEvents(seed: PlanningSeed, result: ScenarioResult) {
  return buildDeliveryReadinessEvents(seed, result);
}

function rangeIncludingCurrentWeek(range: DeliveryPlanRange, today: string): DeliveryPlanRange {
  const currentWeekStart = weekStart(isoDateToSerial(today));
  const start = Math.min(isoDateToSerial(range.startDate), currentWeekStart);
  const end = Math.max(isoDateToSerial(range.endDate), currentWeekStart + 6);
  return { startDate: serialToIsoDate(start), endDate: serialToIsoDate(end) };
}

export function deliveryPlanSuggestedRange(seed: PlanningSeed, result: ScenarioResult, today = factoryDateInput()): DeliveryPlanRange {
  const activeScope = result.planRun?.scope ?? seed.activePlanRun?.scope;
  if (activeScope?.startDate && activeScope.endDate) {
    return rangeIncludingCurrentWeek({ startDate: activeScope.startDate, endDate: activeScope.endDate }, today);
  }
  const completions = scheduledCompletionEvents(seed, result).filter((completion) => completion.readyAt > 0);
  if (!completions.length) return deliveryPlanDefaultRange(today);
  const start = weekStart(Math.min(...completions.map((completion) => completion.readyAt)));
  const end = weekStart(Math.max(...completions.map((completion) => completion.readyAt))) + 6;
  return rangeIncludingCurrentWeek({ startDate: serialToIsoDate(start), endDate: serialToIsoDate(end) }, today);
}

export function deliveryPlanRangeWeekCount(range: DeliveryPlanRange): number {
  const start = isoDateToSerial(range.startDate);
  const end = isoDateToSerial(range.endDate);
  if (!Number.isFinite(start) || !Number.isFinite(end)) throw new Error("Başlangıç ve bitiş tarihini seçin.");
  if (end < start) throw new Error("Bitiş tarihi başlangıç tarihinden önce olamaz.");
  const weekCount = Math.floor((weekStart(end) - weekStart(start)) / 7) + 1;
  if (weekCount > MAX_DELIVERY_PLAN_WEEKS) throw new Error(`Teslimat planı en fazla ${MAX_DELIVERY_PLAN_WEEKS} takvim haftasını kapsayabilir.`);
  return weekCount;
}

export function buildDeliveryPlanPayload(seed: PlanningSeed, result: ScenarioResult, range: DeliveryPlanRange = deliveryPlanDefaultRange(), today = factoryDateInput()): DeliveryPlanPayload {
  const start = isoDateToSerial(range.startDate);
  const end = isoDateToSerial(range.endDate);
  const weekCount = deliveryPlanRangeWeekCount(range);
  const firstWeek = weekStart(start);
  const currentWeekStart = weekStart(isoDateToSerial(today));
  const customerDemand = seed.customerDemand;
  const orderDate = customerDemand?.snapshotDate ?? "";
  const cutoff = customerDemand ? isoDateToSerial(orderDate) : Number.NaN;
  if (customerDemand && !Number.isFinite(cutoff)) throw new Error("Müşteri dosyasının sipariş tarihi geçerli değil. Dosyayı yeniden yükleyin.");
  const calendarWeeks = Array.from({ length: weekCount }, (_, index) => ({ start: firstWeek + index * 7, label: `KW${isoWeek(firstWeek + index * 7)}` }));
  const carryoverLots = activeWipLots(seed);
  const carryoverByProduct = new Map<string, number>();
  for (const lot of carryoverLots) {
    const product = lot.product.trim().toUpperCase();
    carryoverByProduct.set(product, (carryoverByProduct.get(product) ?? 0) + Math.max(0, Math.trunc(lot.availableQuantity)));
  }
  const completions = scheduledCompletionEvents(seed, result)
    .filter((completion) => completion.readyAt >= start && completion.readyAt < end + 1);
  const seenDeliveries = new Set<string>();
  const delivered = (seed.productionHistory ?? []).flatMap((entry) => {
    if (entry.inventoryStatus !== "delivered" || entry.completedQuantity <= 0) return [];
    if (seenDeliveries.has(entry.id)) return [];
    seenDeliveries.add(entry.id);
    const timestamp = effectiveDeliveryTimestamp(entry);
    const deliveredAt = timestamp ? isoDateToSerial(factoryDateInput(timestamp)) : Number.NaN;
    if (!Number.isFinite(deliveredAt) || deliveredAt < start || deliveredAt >= end + 1) return [];
    return [{ id: entry.id, product: entry.product.trim().toUpperCase(), quantity: Math.max(0, Math.trunc(entry.completedQuantity)), deliveredAt }];
  });
  const weeks = calendarWeeks.flatMap((week): Array<{ start: number; label: string; kind: DeliveryPlanColumnKind }> => {
    const columns: Array<{ start: number; label: string; kind: DeliveryPlanColumnKind }> = [];
    const hasActual = delivered.some((entry) => weekStart(entry.deliveredAt) === week.start);
    if (customerDemand) {
      if (week.start <= weekStart(cutoff)) columns.push({ ...week, label: `${week.label}\nSipariş öncesi\nGerçekleşen`, kind: "actual-before-order" });
      if (week.start >= weekStart(cutoff) && (week.start <= currentWeekStart || hasActual)) columns.push({ ...week, label: `${week.label}\nSipariş sonrası\nGerçekleşen`, kind: "actual-after-order" });
    } else if (week.start <= currentWeekStart || hasActual) {
      columns.push({ ...week, label: `${week.label}\nGerçekleşen`, kind: "actual" });
    }
    if (week.start === currentWeekStart) columns.push({ ...week, label: `${week.label}'e\nDevreden`, kind: "carryover" });
    if (week.start >= currentWeekStart || completions.some((entry) => weekStart(entry.readyAt) === week.start)) columns.push({ ...week, label: `${week.label}\nPlan`, kind: "plan" });
    return columns;
  });
  // Sipariş toplamı, seçilen bitiş gününde kesilmez. Excel'de son sütun olarak
  // gösterilen takvim haftasının müşteri taleplerinin tamamını kapsar.
  const orderHorizonEnd = weekStart(end) + 6;
  const orderQuantityByProduct = new Map<string, number>();
  const familyByProduct = new Map<string, string>();
  if (customerDemand) {
    const selectedWeek = customerDemand.weeks.find((week) => isoDateToSerial(week.weekStart) === weekStart(end));
    if (!selectedWeek) throw new Error("Seçilen bitiş haftası müşteri dosyasında yok. Dosyadaki haftalardan birini seçin veya güncel dosyayı yükleyin.");
    for (const item of customerDemand.products) {
      const product = item.product.trim().toUpperCase();
      const point = item.weeklyDemands.find((week) => week.weekId === selectedWeek.id);
      if (!point || !Number.isFinite(point.balance)) throw new Error(`${product} için seçilen haftanın müşteri ihtiyacı bulunamadı.`);
      const quantity = Math.max(0, Math.trunc(-point.balance));
      if (quantity > 0) orderQuantityByProduct.set(product, quantity);
      familyByProduct.set(product, item.family.trim().toUpperCase());
    }
  } else for (const order of (seed.orderImportGrossOrders?.length ? seed.orderImportGrossOrders : seed.orders).filter((item) => {
    if (item.quantity <= 0) return false;
    const dueAt = isoDateToSerial(item.dueDate);
    return !Number.isFinite(dueAt) || dueAt < orderHorizonEnd + 1;
  })) {
    const product = order.product.trim().toUpperCase();
    orderQuantityByProduct.set(product, (orderQuantityByProduct.get(product) ?? 0) + Math.max(0, Math.trunc(order.quantity)));
  }
  const products = [...new Set([
    ...orderQuantityByProduct.keys(),
    ...delivered.map((entry) => entry.product),
    ...carryoverByProduct.keys(),
    ...completions.map((completion) => completion.product),
  ])];

  return {
    startDate: range.startDate,
    endDate: range.endDate,
    category: "Üretim",
    orderDate,
    sourceFile: customerDemand?.sourceFile ?? seed.orderImport?.sourceFile ?? "",
    demandSource: customerDemand ? "customer-snapshot" : seed.orderImport ? "imported-orders" : "manual-orders",
    weeks: weeks.map(({ label, kind }) => ({ label, kind })),
    rows: products.map((product) => ({
      product,
      family: familyByProduct.get(product) || (() => {
        const family = resolvedProductSetupFamily(product, seed.products?.find((item) => item.product === product)?.setupFamily);
        return family === "piston" ? "PISTON" : family === "center-pin" ? "CENTER PIN" : "";
      })(),
      orderQuantity: orderQuantityByProduct.get(product) ?? 0,
      weeklyQuantities: weeks.map((week) => {
        if (week.kind === "carryover") return carryoverByProduct.get(product) ?? 0;
        if (week.kind === "actual" || week.kind === "actual-before-order" || week.kind === "actual-after-order") return delivered
          .filter((entry) => week.kind === "actual" || (week.kind === "actual-before-order" ? entry.deliveredAt < cutoff : entry.deliveredAt >= cutoff))
          .filter((entry) => entry.product === product && entry.deliveredAt >= Math.max(start, week.start) && entry.deliveredAt < Math.min(end + 1, week.start + 7))
          .reduce((sum, entry) => sum + entry.quantity, 0);
        return completions
          .filter((completion) => completion.product === product && completion.readyAt >= Math.max(start, week.start) && completion.readyAt < Math.min(end + 1, week.start + 7))
          .reduce((sum, completion) => sum + Math.max(0, Math.trunc(completion.quantity)), 0);
      }),
    })),
  };
}

