import { formatExcelDate, isMachineEligibleForProduct, machineCapacityHoursBetween, orderDeliveryMilestones, productionQuantityByDate, type Order, type PlannedBatch, type PlanningSeed, type ScenarioResult } from "./planning";

export type AuditSeverity = "critical" | "warning" | "info";
export type AuditTarget = { view: "planning" | "orders" | "machines" | "parameters" | "settings"; orderId?: string; machineId?: string; batchId?: string };
export type AuditFinding = {
  id: string;
  severity: AuditSeverity;
  category: "plan" | "delivery" | "machine" | "data";
  title: string;
  detail: string;
  target?: AuditTarget;
};

export type PlanAudit = {
  findings: AuditFinding[];
  criticalCount: number;
  warningCount: number;
  infoCount: number;
  rulesChecked: number;
  checkedAt: string;
};

function dateToSerial(value: string): number {
  return value ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0;
}

function orderForProduct(orders: Order[], product: string): Order | undefined {
  return orders.find((order) => order.product.toUpperCase() === product.toUpperCase());
}

function finding(id: string, severity: AuditSeverity, category: AuditFinding["category"], title: string, detail: string, target?: AuditTarget): AuditFinding {
  return { id, severity, category, title, detail, target };
}

export function buildPlanAudit(seed: PlanningSeed, result: ScenarioResult, options: { dirty?: boolean } = {}): PlanAudit {
  const findings: AuditFinding[] = [];
  const activePlan = seed.activePlanRun;
  const resultPlan = result.planRun;

  if (activePlan && resultPlan) {
    const activeKey = `${activePlan.planId ?? activePlan.createdAt}:${activePlan.version ?? 1}`;
    const resultKey = `${resultPlan.planId ?? resultPlan.createdAt}:${resultPlan.version ?? 1}`;
    if (activeKey !== resultKey) {
      findings.push(finding("plan-version-mismatch", "critical", "plan", "Ana plan ile tezgâh planı farklı versiyonda", `Ana plan ${activeKey}; Gantt sonucu ${resultKey}. Tarihler kullanılmadan önce plan yeniden çalıştırılmalı.`, { view: "planning" }));
    }
  }

  for (const item of activePlan?.deliveryDeduction?.items ?? []) {
    if (item.status === "unmatched") {
      findings.push(finding(`delivery-unmatched-${item.entryId}`, "critical", "data", `${item.product} teslimatı Excel ile eşleşmedi`, `${item.workOrder || "İş emri bulunmuyor"} · ${item.quantity.toLocaleString("tr-TR")} adet ihtiyaçtan düşülmedi.`, { view: "planning" }));
    } else if (item.excessQuantity > 0) {
      findings.push(finding(`delivery-excess-${item.entryId}`, "warning", "delivery", `${item.product} teslimatı ihtiyacı aşıyor`, `${item.excessQuantity.toLocaleString("tr-TR")} adet fazla teslimat sıfırın altına düşürülmeden dışarıda bırakıldı.`, { view: "planning" }));
    }
  }

  if (options.dirty) {
    findings.push(finding("stale-plan", "critical", "plan", "Plan güncel değil", "Sipariş, tezgah veya parametre girdileri değişti. Kontrol sonuçlarını kullanmadan önce planı yeniden çalıştırın.", { view: "planning" }));
  }

  if (result.state === "empty") {
    findings.push(finding("plan-empty", "critical", "plan", "Plan henüz çalıştırılmadı", "Sipariş ve tezgah uygunluk kontrollerinin tamamlanması için Planı Çalıştır düğmesini kullanın.", { view: "planning" }));
  }

  const incompletePartials = seed.orders.filter((order) => {
    if (!order.allowPartial) return false;
    const milestones = orderDeliveryMilestones(order);
    return milestones.length === 0 || milestones.some((milestone, index) => milestone.quantity <= (milestones[index - 1]?.quantity ?? 0) || milestone.quantity > order.quantity || !milestone.date || Boolean(order.dueDate && milestone.date > order.dueDate));
  });
  for (const order of incompletePartials) {
    findings.push(finding(`partial-data-${order.id}`, "critical", "data", `${order.product} parçalı teslimat bilgisi eksik`, "Ara teslim adedi, tarihi ve toplam siparişle ilişkisi tamamlanmadan teslimat kontrolü yapılamaz.", { view: "orders", orderId: order.id }));
  }

  const ordersWithoutDueDate = seed.orders.filter((order) => !order.dueDate);
  if (ordersWithoutDueDate.length) {
    findings.push(finding("missing-due-dates", "info", "data", `${ordersWithoutDueDate.length} siparişte termin bulunmuyor`, "Bu siparişler miktar açısından planlanır; ancak termin riski hesaplanamaz.", { view: "orders", orderId: ordersWithoutDueDate[0]?.id }));
  }

  for (const machine of seed.machines) {
    const original = machine.currentJob.originalQuantity ?? machine.currentJob.quantity;
    const remaining = machine.currentJob.remainingQuantity ?? machine.currentJob.quantity;
    if (remaining < 0 || remaining > original) {
      findings.push(finding(`current-quantity-${machine.id}`, "critical", "data", `${machine.id} kalan miktarı geçersiz`, `Kalan miktar ${remaining.toLocaleString("tr-TR")}; orijinal miktar ${original.toLocaleString("tr-TR")}.`, { view: "machines", machineId: machine.id }));
    }
    if (machine.currentJob.product && (!Number.isFinite(machine.currentJob.start) || !Number.isFinite(machine.currentJob.end) || machine.currentJob.end < machine.currentJob.start)) {
      findings.push(finding(`current-date-${machine.id}`, "critical", "machine", `${machine.id} mevcut iş tarihi geçersiz`, `Başlangıç ${formatExcelDate(machine.currentJob.start)}, bitiş ${formatExcelDate(machine.currentJob.end)}.`, { view: "machines", machineId: machine.id }));
    }
    const operationalStart = machine.operationalAvailableStart ?? machine.availableStart;
    if (!Number.isFinite(operationalStart) || !Number.isFinite(machine.availableStart) || !Number.isFinite(machine.planEnd) || machine.availableStart > machine.planEnd) {
      findings.push(finding(`machine-window-${machine.id}`, "critical", "machine", `${machine.id} planlama penceresi geçersiz`, `Operasyon başlangıcı ${formatExcelDate(operationalStart)}, etkin başlangıç ${formatExcelDate(machine.availableStart)}, plan sonu ${formatExcelDate(machine.planEnd)}.`, { view: "machines", machineId: machine.id }));
    }
  }

  if (activePlan?.scope.kind === "customer-weeks") {
    const scopeEnd = dateToSerial(activePlan.scope.endDate);
    const expectedPlanEnd = scopeEnd + (activePlan.optimizationGoal === "coarse" ? 0 : 28);
    for (const machine of seed.machines.filter((item) => item.active)) {
      if (Math.abs(machine.planEnd - expectedPlanEnd) > 1e-8) {
        findings.push(finding(`scope-window-${machine.id}`, "warning", "machine", `${machine.id} plan sonu ana planla uyuşmuyor`, `Ana planın beklenen sonu ${formatExcelDate(expectedPlanEnd)}; tezgâh penceresi ${formatExcelDate(machine.planEnd)}.`, { view: "machines", machineId: machine.id }));
      }
    }
  }

  if (result.state === "planned") {
    const unplannedByProduct = new Map<string, PlannedBatch[]>();
    for (const batch of result.batches.filter((item) => item.status === "unplanned")) {
      unplannedByProduct.set(batch.product, [...(unplannedByProduct.get(batch.product) ?? []), batch]);
    }
    for (const [product, batches] of unplannedByProduct) {
      const order = orderForProduct(seed.orders, product);
      const batchLabel = batches.length > 1 ? `${batches.length} şarj` : "şarj";
      findings.push(finding(`unplanned-${product}`, "critical", "plan", `${product} için ${batchLabel} planlanamadı`, batches[0].reason || batches[0].explanation, { view: "orders", orderId: order?.id }));
    }

    for (const order of result.orders) {
      if (order.difference < 0) {
        findings.push(finding(`shortage-${order.id}`, "critical", "plan", `${order.product} siparişinde ${Math.abs(order.difference).toLocaleString("tr-TR")} adet eksik`, `${order.quantity.toLocaleString("tr-TR")} adet talebe karşı ${order.planned.toLocaleString("tr-TR")} adet planlandı.`, { view: "orders", orderId: order.id }));
      } else if (order.difference > 0) {
        findings.push(finding(`over-${order.id}`, "warning", "plan", `${order.product} için ${order.difference.toLocaleString("tr-TR")} adet fazla üretim`, "Fark şarj yuvarlamasından kaynaklanabilir; planlama yöneticisi tarafından teyit edilmelidir.", { view: "orders", orderId: order.id }));
      }

      if (order.dueDate) {
        const dueSerial = dateToSerial(order.dueDate);
        const cumulativeRequired = seed.orders
          .filter((item) => item.product.toUpperCase() === order.product.toUpperCase() && item.dueDate && item.dueDate <= order.dueDate)
          .reduce((sum, item) => sum + item.quantity, 0);
        const available = productionQuantityByDate(seed, result.batches, order.product, dueSerial);
        if (available < cumulativeRequired) {
          findings.push(finding(`due-${order.id}`, "critical", "delivery", `${order.product} termin riski`, `${order.dueDate} tarihine kadar ${cumulativeRequired.toLocaleString("tr-TR")} adet gerekli; tamamlanması beklenen miktar ${available.toLocaleString("tr-TR")}.`, { view: "orders", orderId: order.id }));
        }
      }

      for (const milestone of orderDeliveryMilestones(order)) {
        const available = productionQuantityByDate(seed, result.batches, order.product, dateToSerial(milestone.date));
        if (available < milestone.quantity) {
          findings.push(finding(`partial-risk-${order.id}-${milestone.id}`, "critical", "delivery", `${order.product} ara teslim riski`, `${milestone.date} tarihine kadar toplam ${milestone.quantity.toLocaleString("tr-TR")} adet gerekli; tamamlanması beklenen miktar ${available.toLocaleString("tr-TR")}.`, { view: "orders", orderId: order.id }));
        }
      }
    }

    const plannedBatches = result.batches.filter((batch) => batch.status === "planned");
    for (const batch of plannedBatches) {
      const machine = seed.machines.find((item) => item.id === batch.machineId);
      if (!machine?.active) {
        findings.push(finding(`inactive-${batch.id}`, "critical", "machine", `${batch.machineId} pasif olduğu halde işi var`, `${batch.product} şarjı pasif veya bulunamayan bir tezgaha atanmış.`, { view: "machines", machineId: batch.machineId, batchId: batch.id }));
        continue;
      }
      if (!isMachineEligibleForProduct(seed, batch.machineId, batch.product)) {
        findings.push(finding(`assignment-${batch.id}`, "critical", "machine", `${batch.product} × ${batch.machineId} kural çakışması`, "Atama mevcut ürün–tezgah kısıtlarıyla uyumlu değil.", { view: "machines", machineId: batch.machineId, batchId: batch.id }));
      }
      if ((machine.rates[batch.product.toUpperCase()] ?? 0) <= 0 || batch.dailyRate <= 0) {
        findings.push(finding(`speed-${batch.id}`, "critical", "data", `${batch.product} × ${batch.machineId} hızı eksik`, "Bu atama için üretim hızı tanımlanmadığından süre hesabına güvenilemez.", { view: "machines", machineId: batch.machineId, batchId: batch.id }));
      }
      if (batch.start < machine.availableStart - 1e-8 || batch.end >= Math.floor(machine.planEnd) + 1) {
        findings.push(finding(`window-${batch.id}`, "critical", "machine", `${batch.machineId} planlama penceresi aşıldı`, `${batch.product} şarjının başlangıç veya bitiş tarihi tezgahın izin verilen plan aralığının dışında.`, { view: "machines", machineId: batch.machineId, batchId: batch.id }));
      }
      if (batch.planColumn < 13) {
        findings.push(finding(`queue-position-${batch.id}`, "critical", "machine", `${batch.machineId} kuyruk sırası geçersiz`, `${batch.product} için hesaplanan sıra 1'den küçük.`, { view: "machines", machineId: batch.machineId, batchId: batch.id }));
      }
    }

    for (const machine of seed.machines) {
      const queue = plannedBatches.filter((batch) => batch.machineId === machine.id).sort((left, right) => left.planColumn - right.planColumn);
      let previousEnd = Math.max(machine.availableStart, machine.currentJob.end);
      for (const batch of queue) {
        if (batch.start < previousEnd - 1e-8) {
          findings.push(finding(`overlap-${batch.id}`, "critical", "machine", `${machine.id} kuyruğunda tarih çakışması`, `${batch.product}, önceki iş bitmeden başlıyor (${formatExcelDate(batch.start)} < ${formatExcelDate(previousEnd)}).`, { view: "machines", machineId: machine.id, batchId: batch.id }));
        } else {
          const unexplainedIdleHours = machineCapacityHoursBetween(seed, machine, previousEnd, batch.start);
          if (unexplainedIdleHours > 0.01) {
            findings.push(finding(`working-gap-${batch.id}`, "warning", "machine", `${machine.id} kuyruğunda açıklanamayan boşluk`, `${batch.product} öncesinde ${unexplainedIdleHours.toLocaleString("tr-TR", { maximumFractionDigits: 1 })} çalışılabilir saat boş bırakılmış (${formatExcelDate(previousEnd)} → ${formatExcelDate(batch.start)}).`, { view: "machines", machineId: machine.id, batchId: batch.id }));
          }
        }
        previousEnd = Math.max(previousEnd, batch.end);
      }
      const firstUnlocked = queue.findIndex((batch) => !batch.locked);
      if (firstUnlocked >= 0 && queue.slice(firstUnlocked).some((batch) => batch.locked)) {
        findings.push(finding(`lock-prefix-${machine.id}`, "critical", "machine", `${machine.id} kilit sırası kesintili`, "Kilitli işler tezgah kuyruğunun başında kesintisiz bir sıra oluşturmalıdır.", { view: "machines", machineId: machine.id }));
      }
    }
  }

  const severityOrder: Record<AuditSeverity, number> = { critical: 0, warning: 1, info: 2 };
  findings.sort((left, right) => severityOrder[left.severity] - severityOrder[right.severity] || left.title.localeCompare(right.title, "tr"));
  return {
    findings,
    criticalCount: findings.filter((item) => item.severity === "critical").length,
    warningCount: findings.filter((item) => item.severity === "warning").length,
    infoCount: findings.filter((item) => item.severity === "info").length,
    rulesChecked: 18,
    checkedAt: new Date().toISOString(),
  };
}

