import type { PlanningSeed } from "./planning";

export type PlanningStateRecord = {
  seed: PlanningSeed;
  updatedAt: string;
};

function timestamp(value: string | undefined): number {
  const parsed = value ? Date.parse(value) : Number.NaN;
  return Number.isFinite(parsed) ? parsed : 0;
}

export function newestPlanningState(
  local: PlanningStateRecord | null,
  remote: PlanningStateRecord | null,
): PlanningStateRecord | null {
  if (!local) return remote;
  if (!remote) return local;
  return timestamp(local.updatedAt) > timestamp(remote.updatedAt) ? local : remote;
}

