import foundation from "../data/product-weights.json";

export type ProductWeight = { product: string; productName: string; materialCode: string; materialName: string; grams: number | null; sourceRow?: number };
export function initialProductWeights(): ProductWeight[] {
  return structuredClone(foundation.rows);
}
export function validateProductWeights(value: unknown): ProductWeight[] {
  if (!Array.isArray(value) || value.length > 5000) throw new Error("Ürün ağırlıkları listesi geçersiz.");
  const codes = new Set<string>();
  for (const row of value) {
    if (!row || typeof row.product !== "string" || !row.product.trim() || row.product !== row.product.trim().toUpperCase()
      || codes.has(row.product) || ["productName", "materialCode", "materialName"].some((key) => typeof row[key] !== "string")
      || (row.grams !== null && (typeof row.grams !== "number" || !Number.isFinite(row.grams) || row.grams <= 0))) {
      throw new Error("Ürün kodları benzersiz, ağırlıklar sıfırdan büyük olmalıdır. Bilinmeyen ağırlığı boş bırakın.");
    }
    codes.add(row.product);
  }
  return structuredClone(value);
}

frontend/lib/production-archive-safety.t.source:
import type { PlanningSeed } from "./planning";

function copy<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

/** Saved scenarios are planning alternatives, not production backups. */
export function scenarioSeedWithoutProductionArchive(seed: PlanningSeed): PlanningSeed {
  const scenario = copy(seed);
  scenario.productionHistory = [];
  return scenario;
}

/** Apply old planning inputs without replacing the live production archive. */
export function mergeWithLiveProductionArchive(candidate: PlanningSeed, live: PlanningSeed): PlanningSeed {
  const merged = copy(candidate);
  merged.productionHistory = copy(live.productionHistory ?? []);
  return merged;
}

export function productionArchiveChanged(left: PlanningSeed, right: PlanningSeed): boolean {
  return JSON.stringify(left.productionHistory ?? []) !== JSON.stringify(right.productionHistory ?? []);
}

