import type { PlanningSeed } from "@/lib/planning";
import { processLabel, type ProcessKind } from "@/lib/process-master-data";

export const PRODUCTION_PROCESS_TABS: ReadonlyArray<{ id: ProcessKind; label: string }> = ([
  "turning",
  "drilling",
  "deburring",
  "gkm",
] as const).map((id) => ({ id, label: processLabel(id) }));

export type ProductionResourceOption = {
  id: string;
  name: string;
  active: boolean;
  meta: string;
};

export function productionResourceOptions(
  seed: PlanningSeed,
  process: ProcessKind,
  plannedBatchCounts: Readonly<Record<string, number>> = {},
): ProductionResourceOption[] {
  if (process === "turning") {
    return seed.machines.map((machine) => ({
      id: machine.id,
      name: machine.name,
      active: machine.active,
      meta: `${plannedBatchCounts[machine.id] ?? 0} planlı şarj`,
    }));
  }

  return (seed.processMasterData?.resources ?? [])
    .filter((resource) => resource.process === process)
    .map((resource) => ({
      id: resource.id,
      name: resource.name,
      active: resource.active && resource.defaultShifts > 0,
      meta: `${resource.defaultShifts} vardiya`,
    }));
}

export function productionProcessResourceCount(seed: PlanningSeed, process: ProcessKind): number {
  return process === "turning"
    ? seed.machines.length
    : (seed.processMasterData?.resources ?? []).filter((resource) => resource.process === process).length;
}

