export type ProductionSyncRecord = {
  sourceUpdatedAt: string;
  importedAt: string;
  sourceUrl: string;
};

export type ProductionSyncInfo = {
  appEnv: string;
  enabled: boolean;
  lastSync: ProductionSyncRecord | null;
};

export type ProductionPullStatus = "idle" | "pulling" | "error";

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object";
}

function parseSyncRecord(value: unknown): ProductionSyncRecord | null {
  if (!isRecord(value)) return null;
  if (typeof value.sourceUpdatedAt !== "string" || typeof value.importedAt !== "string" || typeof value.sourceUrl !== "string") return null;
  return {
    sourceUpdatedAt: value.sourceUpdatedAt,
    importedAt: value.importedAt,
    sourceUrl: value.sourceUrl,
  };
}

export function parseProductionSyncInfo(value: unknown): ProductionSyncInfo | null {
  if (!isRecord(value) || typeof value.appEnv !== "string" || typeof value.enabled !== "boolean") return null;
  if (value.lastSync !== null && value.lastSync !== undefined && !parseSyncRecord(value.lastSync)) return null;
  return {
    appEnv: value.appEnv.toLowerCase(),
    enabled: value.enabled,
    lastSync: value.lastSync == null ? null : parseSyncRecord(value.lastSync),
  };
}

export function productionSyncAction(info: ProductionSyncInfo | null, status: ProductionPullStatus) {
  if (!info || info.appEnv !== "staging") {
    return { visible: false, disabled: true, label: "", detail: "" };
  }
  if (!info.enabled) {
    return { visible: true, disabled: true, label: "Prod bağlantısı eksik", detail: "Staging ayarları tamamlanmalı" };
  }
  if (status === "pulling") {
    return { visible: true, disabled: true, label: "Prod’dan alınıyor", detail: "Üretim yalnızca okunuyor" };
  }
  return {
    visible: true,
    disabled: false,
    label: status === "error" ? "Tekrar dene" : "Prod’dan güncelle",
    detail: info.lastSync ? "Son üretim kopyası" : "Üretim kaynak · staging yenilenir",
  };
}

