export type SettingsCalendarEntry = {
  id: string;
  title: string;
  kind: "holiday" | "maintenance" | "overtime" | "shift-change";
  start: number;
  end: number;
  shifts: number;
  resource?: string;
  process?: string;
  completed?: boolean;
};

const EXCEL_EPOCH = Date.UTC(1899, 11, 30);
export const calendarDateSerial = (date: string) => (Date.parse(`${date}T00:00:00Z`) - EXCEL_EPOCH) / 86_400_000;
export const calendarSerialDate = (serial: number) => new Date(EXCEL_EPOCH + Math.floor(serial) * 86_400_000).toISOString().slice(0, 10);

export function settingsMonthDays(month: string): string[] {
  const first = calendarDateSerial(`${month}-01`);
  const date = new Date(`${month}-01T00:00:00Z`);
  const weekday = (date.getUTCDay() + 6) % 7;
  const daysInMonth = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0)).getUTCDate();
  const length = Math.ceil((weekday + daysInMonth) / 7) * 7;
  return Array.from({ length }, (_, index) => calendarSerialDate(first - weekday + index));
}

export function settingsEntriesOnDate(entries: SettingsCalendarEntry[], date: string): SettingsCalendarEntry[] {
  const day = calendarDateSerial(date);
  return entries.filter((entry) => Math.floor(entry.start) <= day && Math.floor(entry.end) >= day)
    .sort((a, b) => Number(Boolean(a.completed)) - Number(Boolean(b.completed)) || a.kind.localeCompare(b.kind) || (a.resource ?? "").localeCompare(b.resource ?? "") || a.id.localeCompare(b.id));
}

export function shiftCalendarMonth(month: string, offset: number): string {
  const date = new Date(`${month}-01T00:00:00Z`);
  date.setUTCMonth(date.getUTCMonth() + offset);
  return date.toISOString().slice(0, 7);
}

