import catalogJson from "../data/product-setup-families.json";

export type ProductSetupFamily = "center-pin" | "piston";

export const PRODUCT_SETUP_FAMILIES: readonly ProductSetupFamily[] = ["piston", "center-pin"];

const FAMILY_VALUES = new Set<ProductSetupFamily>(["center-pin", "piston"]);
const catalog = catalogJson as Record<ProductSetupFamily, string[]>;
const familyByProduct = new Map<string, ProductSetupFamily>();

for (const family of ["center-pin", "piston"] as const) {
  for (const rawProduct of catalog[family]) {
    const product = rawProduct.trim().toUpperCase();
    const existing = familyByProduct.get(product);
    if (existing && existing !== family) throw new Error(`${product} hem ${existing} hem ${family} setup ailesinde tanımlı.`);
    familyByProduct.set(product, family);
  }
}

export function normalizeProductSetupFamily(value: unknown): ProductSetupFamily | undefined {
  return typeof value === "string" && FAMILY_VALUES.has(value as ProductSetupFamily)
    ? value as ProductSetupFamily
    : undefined;
}

export function catalogProductSetupFamily(productCode: string): ProductSetupFamily | undefined {
  return familyByProduct.get(productCode.trim().toUpperCase());
}

export function resolvedProductSetupFamily(productCode: string, storedFamily?: unknown): ProductSetupFamily | undefined {
  return normalizeProductSetupFamily(storedFamily) ?? catalogProductSetupFamily(productCode);
}

export function productSetupFamilyLabel(family: ProductSetupFamily | undefined): string {
  return family === "piston" ? "Piston" : family === "center-pin" ? "Center Pin" : "Aile tanımsız";
}

export function productSetupFamilyDescription(family: ProductSetupFamily | undefined): string {
  if (!family) return "Ürün ailesi henüz tanımlanmadı; setup sınıfı hesaplanamaz.";
  return family === "piston"
    ? "Center Pin ürününe geçişte 5 saat setup uygulanır."
    : "Piston ürününe geçişte 5 saat setup uygulanır.";
}

export function productSetupFamilyCatalog(): Readonly<Record<ProductSetupFamily, readonly string[]>> {
  return catalog;
}

frontend/lib/weekly-demand.ts.source:
import type {
  ConfirmedDemandProduct,
  CustomerOrderOverride,
  CustomerDemandDataset,
  DeliveryMilestone,
  Order,
  WeeklyDemandScope,
} from "./planning";
import { applyCustomerOrderOverrides } from "./customer-order-overrides";

export type ConfirmedOverviewPreview = {
  format: "confirmed-overview";
  calculationModel: "net-shortage-v1";
  fileName: string;
  sheetName: "3. Overview (confirmed)";
  snapshotDate: string;
  baselineLabel: string;
  baselineDueDate: string;
  weeks: CustomerDemandDataset["weeks"];
  products: ConfirmedDemandProduct[];
  rows: Array<{ product: string; quantity: number }>;
  summary: {
    productCount: number;
    orderCount: number;
    totalQuantity: number;
    openingStock: number;
    priorDemand: number;
    firstWeekRequirement: number;
    lastWeekRequirement: number;
    weekCount: number;
    firstWeek: string;
    lastWeek: string;
    ignoredBlankRows: number;
  };
};

export const NET_SHORTAGE_CALCULATION_MODEL = "net-shortage-v1" as const;

export type WeeklyPlanningState = {
  dataset: CustomerDemandDataset;
  orders: Order[];
  orderCatalog: string[];
  planEndDate: string;
  summary: {
    orderCount: number;
    totalDemand: number;
    priorBacklog: number;
    selectedDemand: number;
    includedPriorBacklog: boolean;
  };
};

export type WeeklyPlanningOptions = {
  includePriorBacklog?: boolean;
};

export type WeeklyScopeDemandSummary = {
  priorBacklog: number;
  selectedDemand: number;
};

export type PlanningMonthRange = {
  startMonth: string;
  endMonth: string;
};

export type PlanningWeekRange = {
  startWeekId: string;
  endWeekId: string;
};

export type ResolvedPlanningWeekRange = PlanningWeekRange & {
  startIndex: number;
  endIndex: number;
  label: string;
  startDate: string;
  endDate: string;
};

function planningWeekLabel(week: CustomerDemandDataset["weeks"][number]): string {
  return `W${String(week.isoWeek).padStart(2, "0")}.${week.isoYear}`;
}

export function planningWeekRangesForScope(scope: WeeklyDemandScope): PlanningWeekRange[] {
  return [{ startWeekId: scope.startWeekId, endWeekId: scope.endWeekId }];
}

export function resolvePlanningWeekRanges(
  weeks: CustomerDemandDataset["weeks"],
  ranges: PlanningWeekRange[],
): ResolvedPlanningWeekRange[] {
  if (!ranges.length) throw new Error("En az bir planlama hafta aralığı ekleyin.");
  let previousEndIndex = -1;
  return ranges.map((range, index) => {
    const startIndex = weeks.findIndex((week) => week.id === range.startWeekId);
    const endIndex = weeks.findIndex((week) => week.id === range.endWeekId);
    if (startIndex < 0 || endIndex < 0) throw new Error(`${index + 1}. aralıktaki başlangıç ve bitiş haftasını seçin.`);
    if (startIndex > endIndex) throw new Error(`${index + 1}. aralığın başlangıç haftası bitiş haftasından sonra olamaz.`);
    if (index > 0 && startIndex <= previousEndIndex) throw new Error(`${index + 1}. aralık önceki aralıkla çakışıyor veya geriye gidiyor.`);
    if (index > 0 && startIndex !== previousEndIndex + 1) throw new Error(`${index + 1}. aralık önceki aralığın hemen arkasından başlamalıdır.`);
    previousEndIndex = endIndex;
    const firstWeek = weeks[startIndex];
    const lastWeek = weeks[endIndex];
    return {
      ...range,
      startIndex,
      endIndex,
      label: `${planningWeekLabel(firstWeek)}–${planningWeekLabel(lastWeek)}`,
      startDate: firstWeek.weekStart,
      endDate: lastWeek.weekEnd,
    };
  });
}

export function weekScopeForPlanningWeekRanges(
  weeks: CustomerDemandDataset["weeks"],
  ranges: PlanningWeekRange[],
): WeeklyDemandScope {
  const resolved = resolvePlanningWeekRanges(weeks, ranges);
  return {
    startWeekId: resolved[0].startWeekId,
    endWeekId: resolved.at(-1)!.endWeekId,
  };
}

function validMonthId(value: string): boolean {
  return /^\d{4}-(0[1-9]|1[0-2])$/.test(value);
}

export function planningMonthRangeForScope(
  weeks: CustomerDemandDataset["weeks"],
  scope: WeeklyDemandScope,
): PlanningMonthRange {
  const start = weeks.find((week) => week.id === scope.startWeekId);
  const end = weeks.find((week) => week.id === scope.endWeekId);
  return {
    startMonth: start?.weekEnd.slice(0, 7) ?? "",
    endMonth: end?.weekEnd.slice(0, 7) ?? "",
  };
}

export function weekScopeForPlanningMonthRange(
  weeks: CustomerDemandDataset["weeks"],
  range: PlanningMonthRange,
): WeeklyDemandScope {
  if (!validMonthId(range.startMonth) || !validMonthId(range.endMonth)) {
    throw new Error("Planlama başlangıç ve bitiş ayı zorunludur.");
  }
  if (range.startMonth > range.endMonth) {
    throw new Error("Planlama başlangıç ayı bitiş ayından sonra olamaz.");
  }
  const selected = weeks.filter((week) => {
    const deliveryMonth = week.weekEnd.slice(0, 7);
    return deliveryMonth >= range.startMonth && deliveryMonth <= range.endMonth;
  });
  if (!selected.length) {
    throw new Error("Seçilen ay aralığında Cumartesi termini bulunan müşteri haftası yok.");
  }
  return {
    startWeekId: selected[0].id,
    endWeekId: selected.at(-1)!.id,
  };
}

function isoDateToUtc(value: string): Date {
  const date = new Date(`${value}T00:00:00Z`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || !Number.isFinite(date.getTime())) {
    throw new Error(`Geçersiz ISO tarih: ${value}`);
  }
  return date;
}

function addUtcDays(value: string, days: number): string {
  const date = isoDateToUtc(value);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

export function normalizeCustomerDemandDataset(dataset: CustomerDemandDataset): CustomerDemandDataset {
  const weeks = dataset.weeks.map((week) => ({
    ...week,
    weekEnd: addUtcDays(week.weekStart, 5),
  }));
  const baselineDueDate = weeks[0] ? addUtcDays(weeks[0].weekStart, -2) : dataset.baselineDueDate;
  const normalizedWeeks = new Map(weeks.map((week) => [week.id, week]));
  const products = dataset.products.map((product) => {
    let cumulativeQuantity = Math.max(0, -Number(product.baselineBalance || 0));
    const priorDemand = cumulativeQuantity;
    const weeklyDemands = product.weeklyDemands.map((week) => {
      const normalizedWeek = normalizedWeeks.get(week.weekId);
      const requiredQuantity = Math.max(0, -Number(week.balance || 0));
      const nextCumulativeQuantity = Math.max(cumulativeQuantity, requiredQuantity);
      const quantity = nextCumulativeQuantity - cumulativeQuantity;
      cumulativeQuantity = nextCumulativeQuantity;
      return {
        ...week,
        weekStart: normalizedWeek?.weekStart ?? week.weekStart,
        weekEnd: normalizedWeek?.weekEnd ?? addUtcDays(week.weekStart, 5),
        quantity,
        cumulativeQuantity,
        requiredQuantity,
      };
    });
    return {
      ...product,
      baselineDueDate,
      priorDemand,
      weeklyDemands,
      totalDemand: cumulativeQuantity,
    };
  });
  const weeksWithQuantity = weeks.map((week) => ({
    ...week,
    quantity: products.reduce(
      (sum, product) => sum + (product.weeklyDemands.find((point) => point.weekId === week.id)?.quantity ?? 0),
      0,
    ),
  }));
  return {
    ...dataset,
    calculationModel: NET_SHORTAGE_CALCULATION_MODEL,
    baselineDueDate,
    weeks: weeksWithQuantity,
    products,
  };
}

function normalizedScope(preview: ConfirmedOverviewPreview, scope?: WeeklyDemandScope): WeeklyDemandScope {
  if (!preview.weeks.length) throw new Error("Excel dosyasında planlanabilir ISO hafta bulunamadı.");
  const next = scope ?? { startWeekId: preview.weeks[0].id, endWeekId: preview.weeks.at(-1)!.id };
  const startIndex = preview.weeks.findIndex((week) => week.id === next.startWeekId);
  const endIndex = preview.weeks.findIndex((week) => week.id === next.endWeekId);
  if (startIndex < 0 || endIndex < 0) throw new Error("Seçilen ISO hafta kapsamı müşteri dosyasında bulunamadı.");
  if (startIndex > endIndex) throw new Error("Planlama başlangıç haftası bitiş haftasından sonra olamaz.");
  return next;
}

function orderForProduct(
  product: ConfirmedDemandProduct,
  productIndex: number,
  startIndex: number,
  endIndex: number,
  previous?: Order,
  includePriorBacklog = true,
): Order | undefined {
  const cumulativeDemandBeforeScope = startIndex === 0
    ? product.priorDemand
    : product.weeklyDemands[startIndex - 1]?.cumulativeQuantity ?? product.priorDemand;
  const selectedWeeks = product.weeklyDemands.slice(startIndex, endIndex + 1);
  const deliveryPoints: DeliveryMilestone[] = [];
  let cumulative = 0;

  if (includePriorBacklog && cumulativeDemandBeforeScope > 0) {
    cumulative += cumulativeDemandBeforeScope;
    deliveryPoints.push({
      id: `${product.product}-scope-backlog`,
      quantity: cumulative,
      date: addUtcDays(selectedWeeks[0].weekStart, -2),
    });
  }
  for (const week of selectedWeeks) {
    if (week.quantity <= 0) continue;
    cumulative += week.quantity;
    deliveryPoints.push({
      id: `${product.product}-${week.weekId}`,
      quantity: cumulative,
      date: week.weekEnd,
    });
  }
  if (cumulative <= 0) return undefined;

  const finalPoint = deliveryPoints.at(-1)!;
  const milestones = deliveryPoints.slice(0, -1);
  return {
    id: `confirmed-${product.product}`,
    sourceRow: productIndex + 2,
    product: product.product,
    periodId: finalPoint.date.slice(0, 7),
    quantity: cumulative,
    savedPlanned: previous?.savedPlanned ?? 0,
    savedDifference: previous?.savedDifference ?? 0,
    savedMachines: previous?.savedMachines ?? [],
    dueDate: finalPoint.date,
    allowPartial: milestones.length > 0,
    partialDeliveryQuantity: milestones[0]?.quantity ?? 0,
    partialDeliveryDate: milestones[0]?.date ?? "",
    deliveryMilestones: milestones,
  };
}

export function weeklyScopeDemandSummary(
  preview: ConfirmedOverviewPreview,
  requestedScope?: WeeklyDemandScope,
): WeeklyScopeDemandSummary {
  const scope = normalizedScope(preview, requestedScope);
  const startIndex = preview.weeks.findIndex((week) => week.id === scope.startWeekId);
  const endIndex = preview.weeks.findIndex((week) => week.id === scope.endWeekId);
  return preview.products.reduce<WeeklyScopeDemandSummary>((summary, product) => {
    const priorBacklog = startIndex === 0
      ? product.priorDemand
      : product.weeklyDemands[startIndex - 1]?.cumulativeQuantity ?? product.priorDemand;
    const selectedDemand = product.weeklyDemands
      .slice(startIndex, endIndex + 1)
      .reduce((sum, week) => sum + Math.max(0, week.quantity), 0);
    return {
      priorBacklog: summary.priorBacklog + Math.max(0, priorBacklog),
      selectedDemand: summary.selectedDemand + selectedDemand,
    };
  }, { priorBacklog: 0, selectedDemand: 0 });
}

export function buildWeeklyPlanningState(
  preview: ConfirmedOverviewPreview,
  existingOrders: Order[] = [],
  requestedScope?: WeeklyDemandScope,
  customerOrderOverrides: CustomerOrderOverride[] = [],
  options: WeeklyPlanningOptions = {},
): WeeklyPlanningState {
  if (preview.format !== "confirmed-overview") throw new Error("Müşteri sipariş dosyası '3. Overview (confirmed)' formatında değil.");
  if (preview.calculationModel !== NET_SHORTAGE_CALCULATION_MODEL) throw new Error("Müşteri talebi net ihtiyaç modeliyle hesaplanmamış. Excel’i yeniden doğrulayın.");
  const scope = normalizedScope(preview, requestedScope);
  const startIndex = preview.weeks.findIndex((week) => week.id === scope.startWeekId);
  const endIndex = preview.weeks.findIndex((week) => week.id === scope.endWeekId);
  const includePriorBacklog = options.includePriorBacklog ?? true;
  const demandSummary = weeklyScopeDemandSummary(preview, scope);
  const existingByProduct = new Map(existingOrders.map((order) => [order.product.toUpperCase(), order]));
  const baseOrders: Order[] = [];

  preview.products.forEach((product, index) => {
    if (product.weeklyDemands.length !== preview.weeks.length) {
      throw new Error(`${product.product} için haftalık bakiye sayısı dosya başlıklarıyla eşleşmiyor.`);
    }
    const order = orderForProduct(
      product,
      index,
      startIndex,
      endIndex,
      existingByProduct.get(product.product.toUpperCase()),
      includePriorBacklog,
    );
    if (order) baseOrders.push(order);
  });
  const orderCatalog = [...new Set([
    ...preview.products.map((product) => product.product),
    ...customerOrderOverrides.map((override) => override.product.trim().toUpperCase()),
  ].filter(Boolean))];
  const orders = applyCustomerOrderOverrides(baseOrders, customerOrderOverrides, orderCatalog, existingOrders);

  const selectedEnd = preview.weeks[endIndex].weekEnd;
  const dataset: CustomerDemandDataset = {
    format: "confirmed-overview",
    calculationModel: NET_SHORTAGE_CALCULATION_MODEL,
    sourceFile: preview.fileName,
    sheetName: preview.sheetName,
    snapshotDate: preview.snapshotDate,
    baselineLabel: preview.baselineLabel,
    baselineDueDate: preview.baselineDueDate,
    weeks: preview.weeks,
    products: preview.products,
    activeScope: scope,
    importedAt: new Date().toISOString(),
  };
  const totalDemand = orders.reduce((sum, order) => sum + order.quantity, 0);

  return {
    dataset,
    orders,
    orderCatalog,
    planEndDate: addUtcDays(selectedEnd, 28),
    summary: {
      orderCount: orders.length,
      totalDemand,
      priorBacklog: demandSummary.priorBacklog,
      selectedDemand: demandSummary.selectedDemand,
      includedPriorBacklog: includePriorBacklog,
    },
  };
}

export function previewFromDataset(dataset: CustomerDemandDataset): ConfirmedOverviewPreview {
  const normalized = normalizeCustomerDemandDataset(dataset);
  const totalQuantity = normalized.products.reduce((sum, product) => sum + product.totalDemand, 0);
  const firstWeekRequirement = normalized.products.reduce(
    (sum, product) => sum + (product.weeklyDemands[0]?.cumulativeQuantity ?? product.priorDemand),
    0,
  );
  return {
    format: "confirmed-overview",
    calculationModel: NET_SHORTAGE_CALCULATION_MODEL,
    fileName: normalized.sourceFile,
    sheetName: normalized.sheetName,
    snapshotDate: normalized.snapshotDate,
    baselineLabel: normalized.baselineLabel,
    baselineDueDate: normalized.baselineDueDate,
    weeks: normalized.weeks,
    products: normalized.products,
    rows: normalized.products.map((product) => ({ product: product.product, quantity: product.totalDemand })),
    summary: {
      productCount: normalized.products.length,
      orderCount: normalized.products.filter((product) => product.totalDemand > 0).length,
      totalQuantity,
      openingStock: normalized.products.reduce((sum, product) => sum + product.availableQuantity, 0),
      priorDemand: normalized.products.reduce((sum, product) => sum + product.priorDemand, 0),
      firstWeekRequirement,
      lastWeekRequirement: totalQuantity,
      weekCount: normalized.weeks.length,
      firstWeek: normalized.weeks[0]?.id ?? "",
      lastWeek: normalized.weeks.at(-1)?.id ?? "",
      ignoredBlankRows: 0,
    },
  };
}

